import { useState, useRef, useEffect } from "react";
import { CalendarDays, ChevronDown, ChevronLeft, ChevronRight } from "lucide-react";



export function ModernDatePicker({
  value,
  onChange,
}: {
  value: string;
  onChange: (value: string) => void;
}) {
  const initialDate = value
    ? new Date(`${value}T00:00:00`)
    : new Date();

  const [open, setOpen] = useState(false);
  const [viewDate, setViewDate] =
    useState(initialDate);

  const pickerRef =
    useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!open) return;

    function handleOutside(event: MouseEvent) {
      const target = event.target as Node | null;

      if (
        target &&
        pickerRef.current &&
        !pickerRef.current.contains(target)
      ) {
        setOpen(false);
      }
    }

    document.addEventListener(
      "mousedown",
      handleOutside,
    );

    return () => {
      document.removeEventListener(
        "mousedown",
        handleOutside,
      );
    };
  }, [open]);

  useEffect(() => {
    if (!value) return;

    const next = new Date(
      `${value}T00:00:00`,
    );

    if (!Number.isNaN(next.getTime())) {
      setViewDate(next);
    }
  }, [value]);

  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();

  const firstDay = new Date(
    year,
    month,
    1,
  ).getDay();

  const daysInMonth = new Date(
    year,
    month + 1,
    0,
  ).getDate();

  const startOffset =
    firstDay === 0 ? 6 : firstDay - 1;

  const cells = Array.from(
    {
      length:
        Math.ceil(
          (startOffset + daysInMonth) /
            7,
        ) * 7,
    },
    (_, index) => {
      const day =
        index - startOffset + 1;

      return day > 0 &&
        day <= daysInMonth
        ? day
        : null;
    },
  );

  const selectedDate = value
    ? new Date(`${value}T00:00:00`)
    : null;

  const formatValue = (date: Date) =>
    date.toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });

  const toInputDate = (date: Date) =>
    [
      date.getFullYear(),
      String(
        date.getMonth() + 1,
      ).padStart(2, "0"),
      String(
        date.getDate(),
      ).padStart(2, "0"),
    ].join("-");

  const selectDay = (day: number) => {
    const date = new Date(
      year,
      month,
      day,
    );

    onChange(toInputDate(date));
    setOpen(false);
  };

  const isSelected = (
    day: number,
  ) =>
    selectedDate?.getFullYear() ===
      year &&
    selectedDate?.getMonth() ===
      month &&
    selectedDate?.getDate() === day;

  const today = new Date();

  const isToday = (day: number) =>
    today.getFullYear() === year &&
    today.getMonth() === month &&
    today.getDate() === day;

  return (
    <div
      ref={pickerRef}
      className="relative min-w-0"
    >
      <button
        type="button"
        onClick={() =>
          setOpen((current) => !current)
        }
        className={`flex h-7 w-full items-center justify-between rounded-lg border px-2 transition-all duration-200 ${
          open
            ? "border-indigo-300 bg-white ring-2 ring-indigo-100"
            : "border-slate-200 bg-white hover:border-indigo-200 hover:bg-indigo-50/20"
        }`}
      >
        <div className="flex min-w-0 items-center gap-1.5">
          <div
            className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md transition ${
              open
                ? "bg-indigo-100 text-indigo-600"
                : "bg-slate-50 text-slate-400"
            }`}
          >
            <CalendarDays size={10} />
          </div>

          <span className="truncate !text-[9px] font-semibold text-slate-600">
            {selectedDate
              ? formatValue(selectedDate)
              : "Select date"}
          </span>
        </div>

        <ChevronDown
          size={10}
          className={`shrink-0 text-slate-400 transition-transform duration-200 ${
            open ? "rotate-180" : ""
          }`}
        />
      </button>

      {open && (
        <div className="absolute bottom-[calc(100%+7px)] right-0 z-[100] w-[244px] overflow-hidden rounded-xl border border-slate-200 bg-white p-2.5 shadow-[0_-14px_40px_rgba(15,23,42,0.14)]">
          <div className="mb-2 flex items-center justify-between px-0.5">
            <button
              type="button"
              onClick={() =>
                setViewDate(
                  new Date(
                    year,
                    month - 1,
                    1,
                  ),
                )
              }
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-100 text-slate-400 transition hover:border-indigo-100 hover:bg-indigo-50 hover:text-indigo-600"
            >
              <ChevronLeft size={13} />
            </button>

            <div className="text-center">
              <p className="!text-[11px] font-bold text-slate-700">
                {viewDate.toLocaleDateString(
                  "en-US",
                  { month: "long" },
                )}
              </p>

              <p className="!text-[8px] font-semibold text-slate-400">
                {year}
              </p>
            </div>

            <button
              type="button"
              onClick={() =>
                setViewDate(
                  new Date(
                    year,
                    month + 1,
                    1,
                  ),
                )
              }
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-100 text-slate-400 transition hover:border-indigo-100 hover:bg-indigo-50 hover:text-indigo-600"
            >
              <ChevronRight size={13} />
            </button>
          </div>

          <div className="mb-1 grid grid-cols-7">
            {[
              "Mo",
              "Tu",
              "We",
              "Th",
              "Fr",
              "Sa",
              "Su",
            ].map((day) => (
              <div
                key={day}
                className="flex h-6 items-center justify-center !text-[7px] font-bold uppercase tracking-wide text-slate-400"
              >
                {day}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-7 gap-[2px]">
            {cells.map(
              (day, index) => {
                if (!day) {
                  return (
                    <div
                      key={index}
                      className="h-7"
                    />
                  );
                }

                const active =
                  isSelected(day);

                const current =
                  isToday(day);

                return (
                  <button
                    key={index}
                    type="button"
                    onClick={() =>
                      selectDay(day)
                    }
                    className={`relative flex h-7 items-center justify-center rounded-lg !text-[9px] font-semibold transition-all ${
                      active
                        ? "bg-indigo-600 text-white shadow-sm hover:bg-indigo-500"
                        : current
                          ? "bg-indigo-50 text-indigo-700 ring-1 ring-inset ring-indigo-200"
                          : "text-slate-600 hover:bg-indigo-50 hover:text-indigo-700"
                    }`}
                  >
                    {day}

                    {current &&
                      !active && (
                        <span className="absolute bottom-1 h-[2px] w-[2px] rounded-full bg-indigo-500" />
                      )}
                  </button>
                );
              },
            )}
          </div>

          <div className="mt-2 flex items-center justify-between border-t border-slate-100 pt-2">
            <button
              type="button"
              onClick={() => {
                const now = new Date();
                setViewDate(now);
                onChange(toInputDate(now));
                setOpen(false);
              }}
              className="rounded-md px-2 py-1 !text-[8px] font-bold text-indigo-600 transition hover:bg-indigo-50"
            >
              Today
            </button>

            <button
              type="button"
              onClick={() => setOpen(false)}
              className="rounded-md px-2 py-1 !text-[8px] font-semibold text-slate-400 transition hover:bg-slate-50 hover:text-slate-600"
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { accountingDemographics } from "./config";
import { type Period, type SortKey } from "./types";


/* ========================================================================== */
/* DATA HELPERS                                                               */
/* ========================================================================== */

export function getInitials(
  name: string,
) {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map(
      (part) => part[0],
    )
    .join("")
    .toUpperCase();
}


export function getPatientMrn(
  surgery: unknown,
) {
  const record =
    surgery as {
      id?: string;
      mrn?: string;
      patientMrn?: string;
    };

  if (
    typeof record.mrn ===
    "string"
  ) {
    return record.mrn;
  }

  if (
    typeof record.patientMrn ===
    "string"
  ) {
    return record.patientMrn;
  }

  if (
    record.id &&
    accountingDemographics[
      record.id
    ]
  ) {
    return accountingDemographics[
      record.id
    ].mrn;
  }

  return record.id
    ? `MRN-${record.id}`
    : "MRN";
}


export function getPatientAge(
  surgery: unknown,
) {
  const record =
    surgery as {
      id?: string;
      age?: number;
      patientAge?: number;
    };

  const direct =
    record.age ??
    record.patientAge;

  if (
    typeof direct === "number" &&
    Number.isFinite(direct) &&
    direct > 0
  ) {
    return direct;
  }

  if (
    record.id &&
    accountingDemographics[
      record.id
    ]
  ) {
    return accountingDemographics[
      record.id
    ].age;
  }

  return "—";
}


export function getPatientGender(
  surgery: unknown,
) {
  const record =
    surgery as {
      id?: string;
      gender?: string;
      patientGender?: string;
      sex?: string;
    };

  const direct =
    record.gender ??
    record.patientGender ??
    record.sex;

  if (
    direct === "Male" ||
    direct === "Female"
  ) {
    return direct;
  }

  if (
    record.id &&
    accountingDemographics[
      record.id
    ]
  ) {
    return accountingDemographics[
      record.id
    ].gender;
  }

  return "Not specified";
}


export function getSurgeryProcedures(
  surgery: unknown,
): Array<{
  name: string;
  site?: string;
}> {
  const record =
    surgery as {
      procedure?: unknown;
      procedures?: unknown;
    };

  if (
    Array.isArray(
      record.procedures,
    )
  ) {
    const procedures =
      record.procedures
        .map((item) => {
          if (
            typeof item ===
            "string"
          ) {
            return {
              name: item,
            };
          }

          if (
            item &&
            typeof item ===
              "object"
          ) {
            const value =
              item as {
                name?: unknown;
                procedure?: unknown;
                site?: unknown;
              };

            const name =
              value.name ??
              value.procedure;

            if (
              typeof name ===
              "string"
            ) {
              return {
                name,
                site:
                  typeof value.site ===
                  "string"
                    ? value.site
                    : undefined,
              };
            }
          }

          return null;
        })
        .filter(
          (
            item,
          ): item is {
            name: string;
            site?: string;
          } => item !== null,
        );

    if (
      procedures.length > 0
    ) {
      return procedures;
    }
  }

  return [
    {
      name:
        typeof record.procedure ===
        "string"
          ? record.procedure
          : "Procedure",
    },
  ];
}


export function getReceiptNumber(
  surgery: any,
) {
  const value =
    surgery.receiptNumber ??
    surgery.receiptNo ??
    surgery.paymentReceiptNumber;

  if (
    typeof value === "string" &&
    value.trim()
  ) {
    return value;
  }

  return `RCT-${String(
    surgery.id ?? "0000",
  ).replace(/^SRG-/, "")}`;
}


export function getPaymentTimestamp(
  surgery: any,
) {
  const candidates = [
    surgery.paymentCompletedAt,
    surgery.paymentPaidAt,
    surgery.paidAt,
    surgery.paymentAt,
    surgery.cashierCompletedAt,
    surgery.updatedAt,
  ];

  for (const value of candidates) {
    if (!value) continue;

    const date =
      new Date(String(value));

    if (
      !Number.isNaN(
        date.getTime(),
      )
    ) {
      return date;
    }
  }

  return null;
}


export function getReceiptDate(
  surgery: any,
) {
  const date =
    getPaymentTimestamp(surgery);

  if (!date) {
    return "Not recorded";
  }

  return date.toLocaleDateString(
    "en-US",
    {
      month: "short",
      day: "numeric",
      year: "numeric",
    },
  );
}


export function getReceiptTime(
  surgery: any,
) {
  const date =
    getPaymentTimestamp(surgery);

  if (!date) {
    return "Not recorded";
  }

  return date.toLocaleTimeString(
    "en-US",
    {
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    },
  );
}


export function formatDateShort(
  value?: string,
) {
  if (!value) return "-";

  const date = new Date(
    `${value}T00:00:00`,
  );

  if (
    Number.isNaN(
      date.getTime(),
    )
  ) {
    return value;
  }

  return date.toLocaleDateString(
    "en-US",
    {
      month: "short",
      day: "numeric",
    },
  );
}


export function isDateInPeriod(
  value: string | undefined,
  selectedDate: string,
  period: Period,
) {
  if (
    !value ||
    !selectedDate
  ) {
    return true;
  }

  const surgeryDate =
    new Date(
      `${value}T00:00:00`,
    );

  const selected =
    new Date(
      `${selectedDate}T00:00:00`,
    );

  if (
    Number.isNaN(
      surgeryDate.getTime(),
    ) ||
    Number.isNaN(
      selected.getTime(),
    )
  ) {
    return true;
  }

  if (period === "Day") {
    return (
      surgeryDate.getFullYear() ===
        selected.getFullYear() &&
      surgeryDate.getMonth() ===
        selected.getMonth() &&
      surgeryDate.getDate() ===
        selected.getDate()
    );
  }

  if (period === "Week") {
    const day =
      selected.getDay();

    const diff =
      day === 0
        ? -6
        : 1 - day;

    const start =
      new Date(selected);

    start.setDate(
      selected.getDate() +
        diff,
    );
    start.setHours(
      0,
      0,
      0,
      0,
    );

    const end =
      new Date(start);

    end.setDate(
      start.getDate() + 6,
    );
    end.setHours(
      23,
      59,
      59,
      999,
    );

    return (
      surgeryDate >= start &&
      surgeryDate <= end
    );
  }

  return (
    surgeryDate.getFullYear() ===
      selected.getFullYear() &&
    surgeryDate.getMonth() ===
      selected.getMonth()
  );
}


export function getSortValue(
  surgery: any,
  key: SortKey,
) {
  switch (key) {
    case "patient":
      return surgery.patientName;

    case "case":
      return surgery.id;

    case "mrn":
      return getPatientMrn(
        surgery,
      );

    case "procedures":
      return getSurgeryProcedures(
        surgery,
      )
        .map(
          (item) =>
            item.name,
        )
        .join(" ");

    case "doctor":
      return surgery.doctor;

    case "date":
      return surgery.date;

    case "total":
      return surgery.cost;

    case "paid":
      return surgery.paidAmount;

    case "payment":
      return surgery.paymentStatus;

    case "status":
      return surgery.status;

    default:
      return "";
  }
}

import { useMemo, useState, useRef, useEffect } from "react";
import { CalendarDays, ChevronDown, ChevronLeft, ChevronRight } from "lucide-react";




export function DashboardDatePicker({
  value,
  onChange,
}: {
  value: string;
  onChange: (value: string) => void;
}) {
  const parsedValue = useMemo(() => {
    const parsed = new Date(`${value}T00:00:00`);
    return Number.isNaN(parsed.getTime()) ? new Date() : parsed;
  }, [value]);

  const [open, setOpen] = useState(false);
  const [viewDate, setViewDate] = useState(
    () =>
      new Date(
        parsedValue.getFullYear(),
        parsedValue.getMonth(),
        1,
      ),
  );

  const pickerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    setViewDate(
      new Date(
        parsedValue.getFullYear(),
        parsedValue.getMonth(),
        1,
      ),
    );
  }, [parsedValue]);

  useEffect(() => {
    if (!open) return;

    const handleOutside = (event: MouseEvent) => {
      if (
        pickerRef.current &&
        !pickerRef.current.contains(event.target as Node)
      ) {
        setOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutside);

    return () =>
      document.removeEventListener(
        "mousedown",
        handleOutside,
      );
  }, [open]);

  const toValue = (date: Date) =>
    [
      date.getFullYear(),
      String(date.getMonth() + 1).padStart(2, "0"),
      String(date.getDate()).padStart(2, "0"),
    ].join("-");

  const formatValue = (date: Date) =>
    date.toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });

  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();

  const firstDay = new Date(
    year,
    month,
    1,
  ).getDay();

  const offset =
    firstDay === 0 ? 6 : firstDay - 1;

  const daysInMonth = new Date(
    year,
    month + 1,
    0,
  ).getDate();

  const cells = Array.from(
    {
      length:
        Math.ceil(
          (offset + daysInMonth) / 7,
        ) * 7,
    },
    (_, index) => {
      const day = index - offset + 1;

      return day > 0 &&
        day <= daysInMonth
        ? day
        : null;
    },
  );

  const today = new Date();

  return (
    <div
      ref={pickerRef}
      className="relative min-w-0 flex-1"
    >
      <button
        type="button"
        onClick={() =>
          setOpen((current) => !current)
        }
        className={`flex h-8 w-full min-w-[158px] items-center justify-between rounded-lg border px-2.5 transition-all duration-200 ${
          open
            ? "border-violet-300 bg-white ring-2 ring-violet-100"
            : "border-slate-200 bg-white hover:border-violet-200 hover:bg-violet-50/20"
        }`}
      >
        <div className="flex min-w-0 items-center gap-2">
          <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-md bg-violet-50 text-violet-600">
            <CalendarDays size={10} />
          </span>

          <span className="truncate !text-[9px] font-semibold text-slate-600">
            {formatValue(parsedValue)}
          </span>
        </div>

        <ChevronDown
          size={10}
          className={`shrink-0 text-slate-400 transition ${
            open ? "rotate-180" : ""
          }`}
        />
      </button>

      {open && (
        <div className="absolute bottom-[calc(100%+7px)] right-0 z-[160] w-[250px] overflow-hidden rounded-xl border border-slate-200 bg-white p-2.5 shadow-[0_-14px_40px_rgba(15,23,42,0.15)]">
          <div className="mb-2 flex items-center justify-between">
            <button
              type="button"
              onClick={() =>
                setViewDate(
                  new Date(
                    year,
                    month - 1,
                    1,
                  ),
                )
              }
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-100 text-slate-400 transition hover:border-violet-100 hover:bg-violet-50 hover:text-violet-600"
              aria-label="Previous month"
            >
              <ChevronLeft size={12} />
            </button>

            <div className="text-center">
              <p className="!text-[10px] font-bold text-slate-700">
                {viewDate.toLocaleDateString(
                  "en-US",
                  {
                    month: "long",
                  },
                )}
              </p>

              <p className="mt-0.5 !text-[8px] font-semibold text-slate-400">
                {year}
              </p>
            </div>

            <button
              type="button"
              onClick={() =>
                setViewDate(
                  new Date(
                    year,
                    month + 1,
                    1,
                  ),
                )
              }
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-100 text-slate-400 transition hover:border-violet-100 hover:bg-violet-50 hover:text-violet-600"
              aria-label="Next month"
            >
              <ChevronRight size={12} />
            </button>
          </div>

          <div className="mb-1 grid grid-cols-7">
            {[
              "Mo",
              "Tu",
              "We",
              "Th",
              "Fr",
              "Sa",
              "Su",
            ].map((label) => (
              <div
                key={label}
                className="flex h-6 items-center justify-center !text-[7px] font-bold uppercase tracking-wide text-slate-400"
              >
                {label}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-7 gap-[2px]">
            {cells.map((day, index) => {
              if (!day) {
                return (
                  <div
                    key={index}
                    className="h-7"
                  />
                );
              }

              const date = new Date(
                year,
                month,
                day,
              );

              const key = toValue(date);

              const selected =
                key === value;

              const current =
                today.getFullYear() ===
                  year &&
                today.getMonth() ===
                  month &&
                today.getDate() === day;

              return (
                <button
                  key={key}
                  type="button"
                  onClick={() => {
                    onChange(key);
                    setOpen(false);
                  }}
                  className={`relative flex h-7 items-center justify-center rounded-lg !text-[9px] font-semibold transition-all ${
                    selected
                      ? "bg-violet-600 text-white shadow-sm hover:bg-violet-500"
                      : current
                        ? "bg-violet-50 text-violet-700 ring-1 ring-inset ring-violet-200"
                        : "text-slate-600 hover:bg-violet-50 hover:text-violet-700"
                  }`}
                >
                  {day}

                  {current &&
                    !selected && (
                      <span className="absolute bottom-1 h-[2px] w-[2px] rounded-full bg-violet-500" />
                    )}
                </button>
              );
            })}
          </div>

          <div className="mt-2 flex items-center justify-between border-t border-slate-100 pt-2">
            <button
              type="button"
              onClick={() => {
                const now = new Date();

                setViewDate(
                  new Date(
                    now.getFullYear(),
                    now.getMonth(),
                    1,
                  ),
                );

                onChange(toValue(now));
                setOpen(false);
              }}
              className="rounded-md px-2 py-1 !text-[8px] font-bold text-violet-600 transition hover:bg-violet-50"
            >
              Today
            </button>

            <button
              type="button"
              onClick={() => setOpen(false)}
              className="rounded-md px-2 py-1 !text-[8px] font-semibold text-slate-400 transition hover:bg-slate-50 hover:text-slate-600"
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export function ProcedureCell({
  surgery,
}: {
  surgery: any;
}) {
  const procedures =
    Array.isArray(surgery.procedures) &&
    surgery.procedures.length > 0
      ? surgery.procedures.map(
          (item: any) =>
            typeof item === "string"
              ? item
              : item?.name ?? "",
        )
      : [surgery.procedure];

  const first =
    procedures[0] || "—";

  const more =
    Math.max(
      0,
      procedures.length - 1,
    );

  return (
    <div data-cell-label="Procedure" className="group/procedure relative min-w-0">
      <div className="flex min-w-0 items-center gap-1.5">
        <span className="truncate text-[10.5px] font-medium text-slate-600">
          {first}
        </span>

        {more > 0 && (
          <span className="shrink-0 rounded-full bg-slate-100 px-1.5 py-0.5 text-[7px] font-bold text-slate-500">
            +{more}
          </span>
        )}
      </div>

      {procedures.length > 1 && (
        <div className="pointer-events-none invisible absolute left-0 top-[calc(100%+5px)] z-50 w-[235px] rounded-xl border border-slate-200 bg-white p-2.5 opacity-0 shadow-[0_12px_30px_rgba(15,23,42,0.16)] transition group-hover/procedure:visible group-hover/procedure:opacity-100">
          <p className="mb-1.5 text-[7.5px] font-semibold uppercase tracking-wide text-slate-400">
            Procedures
          </p>

          <div className="space-y-1">
            {procedures.map(
              (
                procedure: string,
                index: number,
              ) => (
                <div
                  key={`${procedure}-${index}`}
                  className="flex items-start gap-1.5 text-[10px] font-medium text-slate-600"
                >
                  <span className="mt-[5px] h-1.5 w-1.5 shrink-0 rounded-full bg-slate-300" />
                  <span>{procedure}</span>
                </div>
              ),
            )}
          </div>
        </div>
      )}
    </div>
  );
}

