import { useState, useRef, useEffect } from "react";
import { CalendarDays, ChevronDown, ChevronLeft, ChevronRight } from "lucide-react";




export function ModernPostOpDatePicker({
  value,
  onChange,
  min,
  tone = "cyan",
}: {
  value: string;
  onChange: (value: string) => void;
  min?: string;
  tone?: "cyan" | "violet" | "amber";
}) {
  const initialDate = value
    ? new Date(`${value}T00:00:00`)
    : new Date();

  const [open, setOpen] = useState(false);
  const [viewDate, setViewDate] =
    useState(initialDate);

  const pickerRef =
    useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!open) return;

    const handleMouseDown = (
      event: MouseEvent,
    ) => {
      const target =
        event.target as Node | null;

      if (
        target &&
        pickerRef.current &&
        !pickerRef.current.contains(target)
      ) {
        setOpen(false);
      }
    };

    document.addEventListener(
      "mousedown",
      handleMouseDown,
    );

    return () =>
      document.removeEventListener(
        "mousedown",
        handleMouseDown,
      );
  }, [open]);

  useEffect(() => {
    if (!value) return;

    const next = new Date(
      `${value}T00:00:00`,
    );

    if (!Number.isNaN(next.getTime())) {
      setViewDate(next);
    }
  }, [value]);

  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();

  const firstDay = new Date(
    year,
    month,
    1,
  ).getDay();

  const daysInMonth = new Date(
    year,
    month + 1,
    0,
  ).getDate();

  const startOffset =
    firstDay === 0
      ? 6
      : firstDay - 1;

  const cells = Array.from(
    {
      length:
        Math.ceil(
          (startOffset + daysInMonth) / 7,
        ) * 7,
    },
    (_, index) => {
      const day =
        index - startOffset + 1;

      return day > 0 &&
        day <= daysInMonth
        ? day
        : null;
    },
  );

  const selectedDate = value
    ? new Date(`${value}T00:00:00`)
    : null;

  const toDateValue = (date: Date) =>
    [
      date.getFullYear(),
      String(
        date.getMonth() + 1,
      ).padStart(2, "0"),
      String(
        date.getDate(),
      ).padStart(2, "0"),
    ].join("-");

  const isSelected = (day: number) =>
    selectedDate?.getFullYear() === year &&
    selectedDate?.getMonth() === month &&
    selectedDate?.getDate() === day;

  const today = new Date();

  const isToday = (day: number) =>
    today.getFullYear() === year &&
    today.getMonth() === month &&
    today.getDate() === day;

  const accent =
    tone === "violet"
      ? {
          border: "border-violet-300",
          ring: "ring-violet-100",
          iconBg: "bg-violet-100",
          iconText: "text-violet-600",
          hoverBorder: "hover:border-violet-200",
          hoverBg: "hover:bg-violet-50/20",
          selected: "bg-violet-600 text-white",
          today: "bg-violet-50 text-violet-700 ring-violet-200",
          hoverDay: "hover:bg-violet-50 hover:text-violet-700",
          action: "text-violet-600 hover:bg-violet-50",
        }
      : tone === "amber"
        ? {
            border: "border-amber-300",
            ring: "ring-amber-100",
            iconBg: "bg-amber-100",
            iconText: "text-amber-600",
            hoverBorder: "hover:border-amber-200",
            hoverBg: "hover:bg-amber-50/20",
            selected: "bg-amber-500 text-white",
            today: "bg-amber-50 text-amber-700 ring-amber-200",
            hoverDay: "hover:bg-amber-50 hover:text-amber-700",
            action: "text-amber-600 hover:bg-amber-50",
          }
        : {
            border: "border-cyan-300",
            ring: "ring-cyan-100",
            iconBg: "bg-cyan-100",
            iconText: "text-cyan-600",
            hoverBorder: "hover:border-cyan-200",
            hoverBg: "hover:bg-cyan-50/20",
            selected: "bg-cyan-600 text-white",
            today: "bg-cyan-50 text-cyan-700 ring-cyan-200",
            hoverDay: "hover:bg-cyan-50 hover:text-cyan-700",
            action: "text-cyan-600 hover:bg-cyan-50",
          };

  return (
    <div
      ref={pickerRef}
      className="relative min-w-0"
    >
      <button
        type="button"
        onClick={() =>
          setOpen((current) => !current)
        }
        className={`flex h-7 w-full items-center justify-between rounded-lg border px-2 transition-all duration-200 ${
          open
            ? `${accent.border} bg-white ring-2 ${accent.ring}`
            : `border-slate-200 bg-white ${accent.hoverBorder} ${accent.hoverBg}`
        }`}
      >
        <div className="flex min-w-0 items-center gap-1.5">
          <div
            className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md transition ${
              open
                ? `${accent.iconBg} ${accent.iconText}`
                : "bg-slate-50 text-slate-400"
            }`}
          >
            <CalendarDays size={10} />
          </div>

          <span className="truncate text-[9px] font-semibold text-slate-600">
            {selectedDate
              ? selectedDate.toLocaleDateString(
                  "en-US",
                  {
                    month: "short",
                    day: "numeric",
                    year: "numeric",
                  },
                )
              : "Select date"}
          </span>
        </div>

        <ChevronDown
          size={10}
          className={`text-slate-400 transition-transform ${
            open ? "rotate-180" : ""
          }`}
        />
      </button>

      {open && (
        <div
          className="fixed inset-0 z-[260] flex items-center justify-center bg-slate-900/10 p-4"
          onMouseDown={(event) => {
            if (
              event.target ===
              event.currentTarget
            ) {
              setOpen(false);
            }
          }}
        >
          <div className="w-[264px] max-w-[92vw] overflow-hidden rounded-xl border border-slate-200 bg-white p-2.5 shadow-[0_18px_48px_rgba(15,23,42,0.18)]">
          <div className="mb-2 flex items-center justify-between">
            <button
              type="button"
              onClick={() =>
                setViewDate(
                  new Date(
                    year,
                    month - 1,
                    1,
                  ),
                )
              }
              className={`flex h-7 w-7 items-center justify-center rounded-lg border border-slate-100 text-slate-400 transition ${accent.hoverDay}`}
            >
              <ChevronLeft size={13} />
            </button>

            <div className="text-center">
              <p className="text-[11px] font-bold text-slate-700">
                {viewDate.toLocaleDateString(
                  "en-US",
                  { month: "long" },
                )}
              </p>

              <p className="text-[8px] font-semibold text-slate-400">
                {year}
              </p>
            </div>

            <button
              type="button"
              onClick={() =>
                setViewDate(
                  new Date(
                    year,
                    month + 1,
                    1,
                  ),
                )
              }
              className={`flex h-7 w-7 items-center justify-center rounded-lg border border-slate-100 text-slate-400 transition ${accent.hoverDay}`}
            >
              <ChevronRight size={13} />
            </button>
          </div>

          <div className="mb-1 grid grid-cols-7">
            {[
              "Mo",
              "Tu",
              "We",
              "Th",
              "Fr",
              "Sa",
              "Su",
            ].map((day) => (
              <div
                key={day}
                className="flex h-6 items-center justify-center text-[7px] font-bold uppercase text-slate-400"
              >
                {day}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-7 gap-[2px]">
            {cells.map((day, index) => {
              if (!day) {
                return (
                  <div
                    key={index}
                    className="h-7"
                  />
                );
              }

              const selected =
                isSelected(day);

              const current =
                isToday(day);

              return (
                <button
                  key={index}
                  type="button"
                  disabled={
                    Boolean(min) &&
                    toDateValue(
                      new Date(
                        year,
                        month,
                        day,
                      ),
                    ) < (min ?? "")
                  }
                  onClick={() => {
                    const nextValue =
                      toDateValue(
                        new Date(
                          year,
                          month,
                          day,
                        ),
                      );

                    if (
                      min &&
                      nextValue < min
                    ) {
                      return;
                    }

                    onChange(nextValue);
                    setOpen(false);
                  }}
                  className={`relative flex h-7 items-center justify-center rounded-lg text-[9px] font-semibold transition disabled:cursor-not-allowed disabled:text-slate-300 disabled:hover:bg-transparent ${
                    selected
                      ? `${accent.selected} shadow-sm`
                      : current
                        ? `${accent.today} ring-1 ring-inset`
                        : `text-slate-600 ${accent.hoverDay}`
                  }`}
                >
                  {day}
                </button>
              );
            })}
          </div>

          <div className="mt-2 flex items-center justify-between border-t border-slate-100 pt-2">
            <button
              type="button"
              onClick={() => {
                const now = new Date();
                setViewDate(now);
                onChange(toDateValue(now));
                setOpen(false);
              }}
              className={`rounded-md px-2 py-1 text-[8px] font-bold transition ${accent.action}`}
            >
              Today
            </button>

            <button
              type="button"
              onClick={() =>
                setOpen(false)
              }
              className="rounded-md px-2 py-1 text-[8px] font-semibold text-slate-400 hover:bg-slate-50"
            >
              Close
            </button>
          </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { getProcedureNames } from "../utils";



export function ProcedureNames({
  surgery,
}: {
  surgery: any;
}) {
  const procedures =
    getProcedureNames(surgery);

  return (
    <div className="flex min-w-0 items-center overflow-hidden pr-3">
      {procedures.map(
        (
          procedure,
          index,
        ) => (
          <div
            key={`${procedure}-${index}`}
            className="flex min-w-0 items-center"
          >
            {index > 0 && (
              <span className="mx-2 shrink-0 text-[10px] text-slate-300">
                •
              </span>
            )}

            <span className="truncate text-[10px] font-medium text-slate-600">
              {procedure}
            </span>
          </div>
        ),
      )}
    </div>
  );
}

import { type PostOpVisit } from "../types";
import { useState, useMemo } from "react";
import { getDoctorAvailableVisitSlots, formatDateInput, formatVisitTime, formatShortDate, getDoctorVisitBookingCount, isDoctorBusyWithSurgeryAtSlot } from "../utils";
import { ClinicalAddForm } from "./ClinicalAddForm";
import { CalendarDays, ChevronDown, X } from "lucide-react";
import { RequiredLabel } from "./RequiredLabel";
import { ModernPostOpDatePicker } from "./ModernPostOpDatePicker";
import { POST_OP_VISIT_SLOTS } from "../config";
import { FormInput } from "./FormInput";



export function VisitForm({
  value,
  onChange,
  doctor,
  surgeries,
  existingVisits,
  onCancel,
  onSave,
}: {
  value: {
    date: string;
    time: string;
    progress: string;
    notes: string;
  };
  onChange: React.Dispatch<
    React.SetStateAction<{
      date: string;
      time: string;
      progress: string;
      notes: string;
    }>
  >;
  doctor: string;
  surgeries: any[];
  existingVisits: PostOpVisit[];
  onCancel: () => void;
  onSave: () => void;
}) {
  const [
    timeSlotsOpen,
    setTimeSlotsOpen,
  ] = useState(false);

  const availableSlots =
    useMemo(
      () =>
        value.date
          ? getDoctorAvailableVisitSlots(
              doctor,
              value.date,
              surgeries,
              existingVisits,
            )
          : [],
      [
        doctor,
        value.date,
        surgeries,
        existingVisits,
      ],
    );

  const dateUnavailable =
    Boolean(value.date) &&
    availableSlots.length === 0;

  return (
    <ClinicalAddForm
      eyebrow="New follow-up"
      title={`Post-Op Visit · ${doctor}`}
      icon={
        <CalendarDays size={12} />
      }
      tone="violet"
      onCancel={onCancel}
      onSave={onSave}
      saveLabel="Schedule Visit"
    >
      <div data-responsive-grid="2" className="grid grid-cols-[128px_1fr] gap-2">
        <div>
          <RequiredLabel>
            Visit date
          </RequiredLabel>

          <ModernPostOpDatePicker
            value={value.date}
            min={formatDateInput(
              new Date(),
            )}
            tone="violet"
            onChange={(date) =>
              onChange(
                (current) => ({
                  ...current,
                  date,
                  time: "",
                }),
              )
            }
          />
        </div>

        <div>
          <RequiredLabel>
            Available time with {doctor}
          </RequiredLabel>

          {!value.date ? (
            <div className="flex h-8 items-center rounded-lg border border-dashed border-slate-200 bg-slate-50/50 px-2.5 text-[9px] text-slate-400">
              Select a date first
            </div>
          ) : dateUnavailable ? (
            <div className="flex h-8 items-center rounded-lg border border-red-200 bg-red-50 px-2.5 text-[9px] font-semibold text-red-600">
              No available slots — choose another date
            </div>
          ) : (
            <>
              <button
                type="button"
                onClick={() =>
                  setTimeSlotsOpen(true)
                }
                className={`flex h-7 w-full items-center justify-between rounded-lg border px-2.5 !text-[11px] font-semibold transition ${
                  value.time
                    ? "border-violet-200 bg-violet-50 text-violet-700"
                    : "border-slate-200 bg-white text-slate-500 hover:border-violet-200"
                }`}
              >
                <span>
                  {value.time
                    ? formatVisitTime(
                        value.time,
                      )
                    : "Choose available time"}
                </span>

                <ChevronDown size={10} />
              </button>

              {timeSlotsOpen && (
                <div
                  className="fixed inset-0 z-[220] flex items-center justify-center bg-slate-900/10 p-4"
                  onClick={(event) => {
                    if (
                      event.target ===
                      event.currentTarget
                    ) {
                      setTimeSlotsOpen(
                        false,
                      );
                    }
                  }}
                >
                  <div className="w-[470px] max-w-[92vw] rounded-2xl border border-violet-100 bg-white p-3 shadow-[0_18px_48px_rgba(15,23,42,0.18)]">
                    <div className="mb-3 flex items-center justify-between">
                      <div>
                        <p className="text-[11px] font-bold text-slate-700">
                          Post-Op Time Slots
                        </p>

                        <p className="mt-0.5 text-[9px] text-slate-400">
                          {doctor} •{" "}
                          {formatShortDate(
                            value.date,
                          )}
                        </p>
                      </div>

                      <button
                        type="button"
                        onClick={() =>
                          setTimeSlotsOpen(
                            false,
                          )
                        }
                        className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400"
                      >
                        <X size={12} />
                      </button>
                    </div>

                    <div className="mb-2 rounded-lg border border-violet-100 bg-violet-50/40 px-2.5 py-2">
                      <p className="text-[9px] font-semibold text-violet-700">
                        Multiple Post-Op visits can be booked in the same time slot
                      </p>

                      <p className="mt-0.5 text-[8px] leading-3.5 text-slate-400">
                        The number shown is informational only. The doctor decides whether another visit can be added.
                      </p>
                    </div>

                    <div data-responsive-grid="3" className="grid grid-cols-3 gap-1.5">
                      {POST_OP_VISIT_SLOTS.map(
                        (slot) => {
                          const booked =
                            getDoctorVisitBookingCount(
                              doctor,
                              value.date,
                              slot,
                              surgeries,
                              existingVisits,
                            );

                          const blockedBySurgery =
                            isDoctorBusyWithSurgeryAtSlot(
                              doctor,
                              value.date,
                              slot,
                              surgeries,
                            );

                          return (
                            <button
                              key={slot}
                              type="button"
                              disabled={
                                blockedBySurgery
                              }
                              onClick={() => {
                                onChange(
                                  (current) => ({
                                    ...current,
                                    time: slot,
                                  }),
                                );

                                setTimeSlotsOpen(
                                  false,
                                );
                              }}
                              className={`relative min-h-[50px] rounded-lg border px-2 py-1.5 text-left transition ${
                                value.time ===
                                slot
                                  ? "border-violet-300 bg-violet-50 ring-1 ring-violet-100"
                                  : blockedBySurgery
                                    ? "cursor-not-allowed border-red-100 bg-red-50/40 opacity-60"
                                    : booked > 0
                                      ? "border-amber-200 bg-amber-50/50 hover:border-violet-200 hover:bg-violet-50/40"
                                      : "border-emerald-200 bg-emerald-50/40 hover:border-violet-200 hover:bg-violet-50/40"
                              }`}
                            >
                              <div className="flex items-center justify-between gap-1">
                                <span
                                  className={`text-[10px] font-bold ${
                                    value.time ===
                                    slot
                                      ? "text-violet-700"
                                      : "text-slate-700"
                                  }`}
                                >
                                  {formatVisitTime(
                                    slot,
                                  )}
                                </span>

                                <span
                                  className={`rounded-full px-1.5 py-0.5 text-[7px] font-bold ${
                                    blockedBySurgery
                                      ? "bg-red-100 text-red-700"
                                      : booked > 0
                                        ? "bg-amber-100 text-amber-700"
                                        : "bg-emerald-100 text-emerald-700"
                                  }`}
                                >
                                  {blockedBySurgery
                                    ? "Busy"
                                    : booked ===
                                        0
                                      ? "Free"
                                      : `${booked} booked`}
                                </span>
                              </div>

                              <p
                                className={`mt-1 text-[7.5px] font-semibold ${
                                  blockedBySurgery
                                    ? "text-red-500"
                                    : booked > 0
                                      ? "text-amber-600"
                                      : "text-emerald-600"
                                }`}
                              >
                                {blockedBySurgery
                                  ? "Doctor in surgery"
                                  : booked ===
                                      0
                                    ? "No visits booked"
                                    : booked ===
                                        1
                                      ? "1 visit already booked"
                                      : `${booked} visits already booked`}
                              </p>
                            </button>
                          );
                        },
                      )}
                    </div>
                  </div>
                </div>
              )}
            </>
          )}
        </div>
      </div>

      <div>
        <RequiredLabel>
          Visit purpose
        </RequiredLabel>

        <FormInput
          placeholder="e.g. Review healing and surgical progress"
          value={value.progress}
          onChange={(value) =>
            onChange(
              (current) => ({
                ...current,
                progress: value,
              }),
            )
          }
        />
      </div>

      <div>
        <RequiredLabel optional>
          Notes
        </RequiredLabel>

        <FormInput
          placeholder="Additional instructions"
          value={value.notes}
          onChange={(value) =>
            onChange(
              (current) => ({
                ...current,
                notes: value,
              }),
            )
          }
        />
      </div>
    </ClinicalAddForm>
  );
}

import { type Medication, type FollowUpOrder, type LifestyleHabitType, type Period, type LifestylePlan, type PostOpState, type PatientCondition, type PostOpProcedureItem, type PostOpVisit } from "./types";
import { lifestyleHabitTypes, EMPTY_STATE, EMPTY_LIFESTYLE, demoPostOpPatientAge, POST_OP_VISIT_SLOTS } from "./config";



export function getPatientPhoneForWhatsApp(
  surgery: any,
) {
  return String(
    surgery?.phone ??
      surgery?.patientPhone ??
      surgery?.mobile ??
      "",
  )
    .replace(/[^\d+]/g, "")
    .replace(/^\+/, "");
}


export function formatWhatsAppMedicationLines(
  medications: Medication[],
) {
  const activeMedications =
    medications.filter(
      (medication) =>
        medication.status === "Active",
    );

  if (!activeMedications.length) {
    return ["No active medications."];
  }

  return activeMedications.map(
    (medication, index) =>
      `${index + 1}. ${medication.name}\n   Dose: ${medication.dose}\n   Frequency: ${medication.frequency}\n   Duration: ${medication.duration}`,
  );
}


export function formatWhatsAppFollowUpLines(
  followUps: FollowUpOrder[],
) {
  const pendingFollowUps =
    followUps.filter(
      (order) =>
        order.status === "Requested" ||
        order.status === "Scheduled",
    );

  if (!pendingFollowUps.length) {
    return [
      "No requested or scheduled tests/imaging.",
    ];
  }

  return pendingFollowUps.map(
    (order, index) =>
      `${index + 1}. ${order.type}: ${order.name}\n   Due date: ${
        order.dueDate
          ? formatShortDate(order.dueDate)
          : "Not specified"
      }\n   Status: ${order.status}`,
  );
}


export function buildPostOpVisitWhatsAppMessage({
  action,
  patientName,
  doctor,
  date,
  time,
  previousDate,
  previousTime,
  medications,
  followUps,
}: {
  action: "booked" | "updated" | "cancelled";
  patientName: string;
  doctor: string;
  date: string;
  time: string;
  previousDate?: string;
  previousTime?: string;
  medications: Medication[];
  followUps: FollowUpOrder[];
}) {
  const formattedDate =
    date
      ? formatShortDate(date)
      : "";

  const formattedTime =
    time
      ? formatVisitTime(time)
      : "";

  const medicationLines =
    formatWhatsAppMedicationLines(
      medications,
    );

  const followUpLines =
    formatWhatsAppFollowUpLines(
      followUps,
    );

  const planDetails = [
    "",
    "------------------------------",
    "MEDICATIONS",
    "------------------------------",
    ...medicationLines,
    "",
    "------------------------------",
    "TESTS & IMAGING",
    "------------------------------",
    ...followUpLines,
  ];

  if (action === "booked") {
    return [
      `Hello ${patientName},`,
      "",
      "Your Post-Op follow-up visit has been booked.",
      "",
      `Doctor: ${doctor}`,
      `Date: ${formattedDate}`,
      `Time: ${formattedTime}`,
      ...planDetails,
      "",
      "Please contact the hospital if you need any assistance.",
    ].join("\n");
  }

  if (action === "updated") {
    return [
      `Hello ${patientName},`,
      "",
      "Your Post-Op follow-up visit has been updated.",
      "",
      previousDate || previousTime
        ? `Previous appointment: ${
            previousDate
              ? formatShortDate(previousDate)
              : ""
          }${
            previousDate && previousTime
              ? " at "
              : ""
          }${
            previousTime
              ? formatVisitTime(previousTime)
              : ""
          }`
        : "",
      `New date: ${formattedDate}`,
      `New time: ${formattedTime}`,
      `Doctor: ${doctor}`,
      ...planDetails,
      "",
      "Please contact the hospital if you need any assistance.",
    ]
      .filter(
        (line) =>
          line !== "",
      )
      .join("\n");
  }

  return [
    `Hello ${patientName},`,
    "",
    "Your Post-Op follow-up visit has been cancelled.",
    "",
    `Doctor: ${doctor}`,
    `Cancelled date: ${formattedDate}`,
    `Cancelled time: ${formattedTime}`,
    ...planDetails,
    "",
    "Please contact the hospital if you need to arrange another visit.",
  ].join("\n");
}


export function openPostOpWhatsApp(
  phone: string,
  message: string,
) {
  if (!phone) return false;

  const normalizedPhone =
    phone.replace(/\D/g, "");

  const params =
    new URLSearchParams();

  params.set(
    "text",
    message,
  );

  const url = `https://wa.me/${normalizedPhone}?${params.toString()}`;

  window.open(
    url,
    "_blank",
    "noopener,noreferrer",
  );

  return true;
}


export function getLifestylePlaceholder(
  type: LifestyleHabitType,
) {
  switch (type) {
    case "Walking":
      return "e.g. Walk 20–30 min twice daily";
    case "Exercise":
      return "e.g. Gentle stretching only";
    case "Nutrition":
      return "e.g. High-protein soft diet";
    case "Foods to Avoid":
      return "e.g. Avoid spicy or hard foods";
    case "Hydration":
      return "e.g. 2 L water daily";
    case "Sleep / Rest":
      return "e.g. Sleep with head elevated";
    case "Restriction":
      return "e.g. No lifting over 5 kg";
    default:
      return "Add patient-specific guidance";
  }
}


export function hasRichTextContent(
  html: string | undefined | null,
) {
  if (!html) return false;

  const text = html
    .replace(/<br\s*\/?>/gi, " ")
    .replace(/<\/p>/gi, " ")
    .replace(/<[^>]*>/g, "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .trim();

  return text.length > 0;
}


