export function getPostOpDateSortValue(
  surgery: any,
) {
  const value =
    surgery.surgeryDate ??
    surgery.scheduledDate ??
    surgery.date ??
    surgery.scheduledAt ??
    surgery.startDate ??
    surgery.surgeryStartedAt;

  return value
    ? String(value)
    : "";
}


export function formatPostOpSurgeryDate(
  surgery: any,
) {
  const raw =
    getPostOpDateSortValue(
      surgery,
    );

  if (!raw) return "—";

  const date =
    new Date(
      raw.length === 10
        ? `${raw}T00:00:00`
        : raw,
    );

  if (
    Number.isNaN(
      date.getTime(),
    )
  ) {
    return raw;
  }

  return date.toLocaleDateString(
    "en-US",
    {
      month: "short",
      day: "numeric",
      year: "numeric",
    },
  );
}


export function isPostOpDateInPeriod(
  surgery: any,
  selectedDate: string,
  period: Period,
) {
  const raw =
    getPostOpDateSortValue(
      surgery,
    );

  if (
    !raw ||
    !selectedDate
  ) {
    return true;
  }

  const surgeryDate =
    new Date(
      raw.length === 10
        ? `${raw}T00:00:00`
        : raw,
    );

  const selected =
    new Date(
      `${selectedDate}T00:00:00`,
    );

  if (
    Number.isNaN(
      surgeryDate.getTime(),
    ) ||
    Number.isNaN(
      selected.getTime(),
    )
  ) {
    return true;
  }

  if (period === "Day") {
    return (
      surgeryDate.getFullYear() ===
        selected.getFullYear() &&
      surgeryDate.getMonth() ===
        selected.getMonth() &&
      surgeryDate.getDate() ===
        selected.getDate()
    );
  }

  if (period === "Week") {
    const day =
      selected.getDay();

    const diff =
      day === 0
        ? -6
        : 1 - day;

    const start =
      new Date(selected);

    start.setDate(
      selected.getDate() +
        diff,
    );

    start.setHours(
      0,
      0,
      0,
      0,
    );

    const end =
      new Date(start);

    end.setDate(
      start.getDate() + 6,
    );

    end.setHours(
      23,
      59,
      59,
      999,
    );

    return (
      surgeryDate >= start &&
      surgeryDate <= end
    );
  }

  return (
    surgeryDate.getFullYear() ===
      selected.getFullYear() &&
    surgeryDate.getMonth() ===
      selected.getMonth()
  );
}


export function formatDischargeDateTime(
  value: string,
) {
  const date =
    new Date(value);

  if (
    Number.isNaN(
      date.getTime(),
    )
  ) {
    return "Date not recorded";
  }

  return date.toLocaleString(
    "en-US",
    {
      month: "short",
      day: "numeric",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    },
  );
}


export function normalizeLifestylePlan(
  value: unknown,
): LifestylePlan {
  if (Array.isArray(value)) {
    return value
      .filter(
        (item) =>
          item &&
          typeof item === "object" &&
          typeof item.instruction ===
            "string",
      )
      .map(
        (item: any, index) => ({
          id:
            typeof item.id === "string"
              ? item.id
              : `lifestyle-loaded-${index}`,
          type:
            lifestyleHabitTypes.includes(
              item.type,
            )
              ? item.type
              : ("Other" as LifestyleHabitType),
          instruction:
            item.instruction,
        }),
      );
  }

  if (
    value &&
    typeof value === "object"
  ) {
    const old =
      value as Record<
        string,
        unknown
      >;

    const migrated: LifestylePlan =
      [];

    const add = (
      type: LifestyleHabitType,
      key: string,
    ) => {
      const instruction =
        typeof old[key] === "string"
          ? old[key].trim()
          : "";

      if (!instruction) return;

      migrated.push({
        id: `lifestyle-migrated-${key}`,
        type,
        instruction,
      });
    };

    add(
      "Walking",
      "walkingMinutesPerDay",
    );
    add(
      "Exercise",
      "exercisePlan",
    );
    add(
      "Nutrition",
      "allowedFoods",
    );
    add(
      "Foods to Avoid",
      "avoidFoods",
    );
    add(
      "Hydration",
      "hydration",
    );
    add(
      "Sleep / Rest",
      "sleepRest",
    );
    add(
      "Restriction",
      "restrictions",
    );
    add(
      "Other",
      "notes",
    );

    return migrated;
  }

  return [];
}


export function persistPostOp(
  id: string,
  value: PostOpState,
) {
  localStorage.setItem(
    `post-op-${id}`,
    JSON.stringify(value),
  );
}


export function loadPostOp(
  id: string,
): PostOpState {
  const raw =
    localStorage.getItem(
      `post-op-${id}`,
    );

  if (!raw) {
    return {
      ...EMPTY_STATE,
      medications: [],
      followUps: [],
      lifestyle: [...EMPTY_LIFESTYLE],
      surgeonReport: "",
      visits: [],
    };
  }

  try {
    const parsed =
      JSON.parse(raw);

    return {
      condition:
        isCondition(
          parsed.condition,
        )
          ? parsed.condition
          : "Stable",
      painLevel:
        typeof parsed.painLevel ===
        "number"
          ? Math.max(
              0,
              Math.min(
                10,
                parsed.painLevel,
              ),
            )
          : 2,
      woundStatus:
        typeof parsed.woundStatus ===
        "string"
          ? parsed.woundStatus
          : "Healing normally",
      instructions:
        typeof parsed.instructions ===
        "string"
          ? parsed.instructions
          : "",
      medications:
        Array.isArray(
          parsed.medications,
        )
          ? parsed.medications.map(
              (item: any) => ({
                ...item,
                stopReason:
                  typeof item?.stopReason ===
                  "string"
                    ? item.stopReason
                    : "",
              }),
            )
          : [],
      followUps:
        Array.isArray(
          parsed.followUps,
        )
          ? parsed.followUps.map(
              (item: any) => ({
                ...item,
                result:
                  typeof item?.result ===
                  "string"
                    ? item.result
                    : "",
              }),
            )
          : [],
      lifestyle:
        normalizeLifestylePlan(
          parsed.lifestyle,
        ),
      surgeonReport:
        typeof parsed.surgeonReport === "string"
          ? parsed.surgeonReport
          : "",
      visits:
        Array.isArray(
          parsed.visits,
        )
          ? parsed.visits.map(
              (visit: any) => ({
                ...visit,
                time:
                  typeof visit?.time ===
                  "string"
                    ? visit.time
                    : "",
                result:
                  typeof visit?.result ===
                  "string"
                    ? visit.result
                    : "",
              }),
            )
          : [],
      /*
       * Discharge confirmation is intentionally reset on refresh.
       * The clinical plan stays saved, but the user must explicitly
       * re-confirm discharge readiness in the current page session.
       */
      dischargeChecklist: {
        medicationsReviewed: false,
        followUpsArranged: false,
        instructionsProvided: false,
      },
      discharged: false,
      dischargedAt: null,
    };
  } catch {
    return {
      ...EMPTY_STATE,
      medications: [],
      followUps: [],
      lifestyle: [...EMPTY_LIFESTYLE],
      surgeonReport: "",
      visits: [],
    };
  }
}


