export function isPostOpStateEmpty(
  state: PostOpState,
) {
  return (
    state.medications.length ===
      0 &&
    state.followUps.length === 0 &&
    state.lifestyle.length === 0 &&
    state.visits.length === 0
  );
}


export function isCondition(
  value: unknown,
): value is PatientCondition {
  return [
    "Improving",
    "Stable",
    "Needs Attention",
  ].includes(
    String(value),
  );
}


export function getPatientAge(
  surgery: any,
): number | string {
  const value =
    surgery.age ??
    surgery.patientAge;

  if (
    typeof value === "number" &&
    Number.isFinite(value) &&
    value > 0
  ) {
    return value;
  }

  return surgery.id
    ? demoPostOpPatientAge[
        surgery.id
      ] ?? "—"
    : "—";
}


export function getProcedureItems(
  surgery: any,
): PostOpProcedureItem[] {
  if (
    Array.isArray(
      surgery.procedures,
    )
  ) {
    const items =
      surgery.procedures
        .map((item: any) => {
          if (
            typeof item ===
            "string"
          ) {
            return {
              name: item,
            };
          }

          if (
            item &&
            typeof item ===
              "object"
          ) {
            const name =
              item.name ??
              item.procedure ??
              item.label ??
              item.operation;

            const site =
              item.site ??
              item.side ??
              item.location ??
              item.bodySite;

            if (
              typeof name ===
              "string"
            ) {
              return {
                name,
                site:
                  typeof site ===
                  "string"
                    ? site
                    : undefined,
              };
            }
          }

          return null;
        })
        .filter(
          (
            item: PostOpProcedureItem | null,
          ): item is PostOpProcedureItem =>
            item !== null,
        );

    if (items.length > 0) {
      return items;
    }
  }

  const fallbackSitesRaw =
    surgery.procedureSites ??
    surgery.sites ??
    surgery.procedureSide;

  const fallbackSites =
    Array.isArray(
      fallbackSitesRaw,
    )
      ? fallbackSitesRaw
          .map(
            (value: unknown) =>
              typeof value ===
              "string"
                ? value
                : "",
          )
          .filter(Boolean)
      : typeof fallbackSitesRaw ===
          "string"
        ? fallbackSitesRaw
            .split(",")
            .map(
              (value: string) =>
                value.trim(),
            )
            .filter(Boolean)
        : [];

  return [
    {
      name:
        surgery.procedure ||
        "Procedure",
      site: fallbackSites[0],
    },
  ];
}


export function getProcedureNames(
  surgery: any,
) {
  return getProcedureItems(
    surgery,
  ).map((item) => item.name);
}


export function stripHtml(
  value: string,
) {
  return value
    .replace(/<br\s*\/?>/gi, " ")
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .trim();
}


export function createId(
  prefix: string,
) {
  return `${prefix}-${Date.now()}-${Math.random()
    .toString(36)
    .slice(2, 7)}`;
}


export function formatShortDate(
  value: string,
) {
  if (!value) return "Not set";

  const date = new Date(
    `${value}T00:00:00`,
  );

  if (
    Number.isNaN(
      date.getTime(),
    )
  ) {
    return value;
  }

  return date.toLocaleDateString(
    "en-US",
    {
      month: "short",
      day: "numeric",
    },
  );
}


export function getNextVisitLabel(
  visits: PostOpVisit[],
) {
  const next =
    visits
      .filter(
        (visit) =>
          visit.status ===
          "Upcoming",
      )
      .sort((a, b) =>
        a.date.localeCompare(
          b.date,
        ),
      )[0];

  return next
    ? `${formatShortDate(
        next.date,
      )}${
        next.time
          ? ` • ${formatVisitTime(
              next.time,
            )}`
          : ""
      }`
    : "Not scheduled";
}


export function getDoctorVisitBookingCount(
  doctor: string,
  date: string,
  slot: string,
  surgeries: any[],
  existingVisits: PostOpVisit[],
) {
  if (!doctor || !date || !slot) return 0;

  const normalizedSlot =
    normalizeVisitTime(slot);

  const visitIds = new Set<string>();

  const addVisit = (visit: PostOpVisit) => {
    if (
      visit.date === date &&
      visit.status === "Upcoming" &&
      normalizeVisitTime(visit.time) === normalizedSlot
    ) {
      visitIds.add(visit.id);
    }
  };

  existingVisits.forEach(addVisit);

  surgeries.forEach((surgery) => {
    if (
      String(surgery.doctor ?? "").trim() !==
      doctor.trim()
    ) {
      return;
    }

    const state = loadPostOp(surgery.id);
    state.visits.forEach(addVisit);
  });

  return visitIds.size;
}


export function isDoctorBusyWithSurgeryAtSlot(
  doctor: string,
  date: string,
  slot: string,
  surgeries: any[],
) {
  const normalizedSlot =
    normalizeVisitTime(slot);

  return surgeries.some((surgery) => {
    if (
      String(surgery.doctor ?? "").trim() !==
      doctor.trim()
    ) {
      return false;
    }

    const rawDate =
      surgery.surgeryDate ??
      surgery.scheduledDate ??
      surgery.date ??
      surgery.scheduledAt;

    if (!rawDate) return false;

    const surgeryDate =
      String(rawDate).slice(0, 10);

    if (surgeryDate !== date) return false;

    const rawTime =
      surgery.time ??
      surgery.surgeryTime ??
      surgery.scheduledTime ??
      surgery.startTime ??
      (typeof surgery.scheduledAt === "string"
        ? surgery.scheduledAt.slice(11, 16)
        : "");

    return (
      normalizeVisitTime(rawTime) === normalizedSlot
    );
  });
}


export function getDoctorAvailableVisitSlots(
  doctor: string,
  date: string,
  surgeries: any[],
  _existingVisits: PostOpVisit[],
) {
  if (!doctor || !date) {
    return [];
  }

  const selectedDate = new Date(
    `${date}T00:00:00`,
  );

  if (
    Number.isNaN(selectedDate.getTime())
  ) {
    return [];
  }

  const today =
    formatDateInput(new Date());

  if (date < today) {
    return [];
  }

  // Demo clinic availability: Sunday unavailable.
  if (selectedDate.getDay() === 0) {
    return [];
  }

  const now = new Date();

  return POST_OP_VISIT_SLOTS.filter(
    (slot) => {
      if (
        isDoctorBusyWithSurgeryAtSlot(
          doctor,
          date,
          slot,
          surgeries,
        )
      ) {
        return false;
      }

      if (date === today) {
        const [hours, minutes] =
          slot.split(":").map(Number);

        const slotDate = new Date();
        slotDate.setHours(
          hours,
          minutes,
          0,
          0,
        );

        if (slotDate <= now) {
          return false;
        }
      }

      return true;
    },
  );
}


export function normalizeVisitTime(
  value: unknown,
) {
  if (
    typeof value !==
    "string"
  ) {
    return "";
  }

  const match =
    value
      .trim()
      .match(
        /^(\d{1,2}):(\d{2})/,
      );

  if (!match) {
    return "";
  }

  return `${String(
    Number(match[1]),
  ).padStart(2, "0")}:${String(
    Number(match[2]),
  ).padStart(2, "0")}`;
}


export function formatVisitTime(
  value: string,
) {
  const normalized =
    normalizeVisitTime(
      value,
    );

  if (!normalized) {
    return "—";
  }

  const [
    hours,
    minutes,
  ] = normalized
    .split(":")
    .map(Number);

  const date =
    new Date();

  date.setHours(
    hours,
    minutes,
    0,
    0,
  );

  return date.toLocaleTimeString(
    "en-US",
    {
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    },
  );
}


export function addDays(
  date: Date,
  days: number,
) {
  const copy =
    new Date(date);

  copy.setDate(
    copy.getDate() + days,
  );

  return copy;
}


export function formatDateInput(
  date: Date,
) {
  const year =
    date.getFullYear();

  const month =
    String(
      date.getMonth() + 1,
    ).padStart(2, "0");

  const day =
    String(
      date.getDate(),
    ).padStart(2, "0");

  return `${year}-${month}-${day}`;
}

