  );
}


export function loadPostOp(
  id: string,
): PostOpState {
  const raw =
    localStorage.getItem(
      `post-op-${id}`,
    );

  if (!raw) {
    return {
      ...EMPTY_STATE,
      medications: [],
      followUps: [],
      visits: [],
    };
  }

  try {
    const parsed =
      JSON.parse(raw);

    return {
      condition:
        isCondition(
          parsed.condition,
        )
          ? parsed.condition
          : "Stable",
      painLevel:
        typeof parsed.painLevel ===
        "number"
          ? Math.max(
              0,
              Math.min(
                10,
                parsed.painLevel,
              ),
            )
          : 2,
      woundStatus:
        typeof parsed.woundStatus ===
        "string"
          ? parsed.woundStatus
          : "Healing normally",
      instructions:
        typeof parsed.instructions ===
        "string"
          ? parsed.instructions
          : "",
      medications:
        Array.isArray(
          parsed.medications,
        )
          ? parsed.medications.map(
              (item: any) => ({
                ...item,
                stopReason:
                  typeof item?.stopReason ===
                  "string"
                    ? item.stopReason
                    : "",
              }),
            )
          : [],
      followUps:
        Array.isArray(
          parsed.followUps,
        )
          ? parsed.followUps.map(
              (item: any) => ({
                ...item,
                result:
                  typeof item?.result ===
                  "string"
                    ? item.result
                    : "",
              }),
            )
          : [],
      visits:
        Array.isArray(
          parsed.visits,
        )
          ? parsed.visits.map(
              (visit: any) => ({
                ...visit,
                time:
                  typeof visit?.time ===
                  "string"
                    ? visit.time
                    : "",
                result:
                  typeof visit?.result ===
                  "string"
                    ? visit.result
                    : "",
              }),
            )
          : [],
      /*
       * Discharge confirmation is intentionally reset on refresh.
       * The clinical plan stays saved, but the user must explicitly
       * re-confirm discharge readiness in the current page session.
       */
      dischargeChecklist: {
        medicationsReviewed: false,
        followUpsArranged: false,
        instructionsProvided: false,
      },
      discharged: false,
      dischargedAt: null,
    };
  } catch {
    return {
      ...EMPTY_STATE,
      medications: [],
      followUps: [],
      visits: [],
    };
  }
}


