export function getProcedureItems(
  surgery: any,
): PostOpProcedureItem[] {
  if (
    Array.isArray(
      surgery.procedures,
    )
  ) {
    const items =
      surgery.procedures
        .map((item: any) => {
          if (
            typeof item ===
            "string"
          ) {
            return {
              name: item,
            };
          }

          if (
            item &&
            typeof item ===
              "object"
          ) {
            const name =
              item.name ??
              item.procedure ??
              item.label ??
              item.operation;

            const site =
              item.site ??
              item.side ??
              item.location ??
              item.bodySite;

            if (
              typeof name ===
              "string"
            ) {
              return {
                name,
                site:
                  typeof site ===
                  "string"
                    ? site
                    : undefined,
              };
            }
          }

          return null;
        })
        .filter(
          (
            item: PostOpProcedureItem | null,
          ): item is PostOpProcedureItem =>
            item !== null,
        );

    if (items.length > 0) {
      return items;
    }
  }

  const fallbackSitesRaw =
    surgery.procedureSites ??
    surgery.sites ??
    surgery.procedureSide;

  const fallbackSites =
    Array.isArray(
      fallbackSitesRaw,
    )
      ? fallbackSitesRaw
          .map(
            (value: unknown) =>
              typeof value ===
              "string"
                ? value
                : "",
          )
          .filter(Boolean)
      : typeof fallbackSitesRaw ===
          "string"
        ? fallbackSitesRaw
            .split(",")
            .map(
              (value: string) =>
                value.trim(),
            )
            .filter(Boolean)
        : [];

  return [
    {
      name:
        surgery.procedure ||
        "Procedure",
      site: fallbackSites[0],
    },
  ];
}


export function getProcedureNames(
  surgery: any,
) {
