export function getProcedures(
  surgery: unknown,
): ProcedureItem[] {
  const meta = getMeta(surgery);

  const raw =
    meta.procedures ??
    meta.operations ??
    meta.procedureList;

  if (Array.isArray(raw)) {
    const result = raw
      .map((item) => {
        if (typeof item === "string") {
          return {
            name: item,
          };
        }

        if (
          typeof item === "object" &&
          item !== null
        ) {
          const object =
            item as Record<
              string,
              unknown
            >;

          const name =
            object.name ??
            object.procedure ??
            object.label ??
            object.operation ??
            object.type;

          const site =
            object.site ??
            object.side ??
            object.location ??
            object.bodySite;

          if (typeof name === "string") {
            return {
              name,
              site:
                typeof site === "string"
                  ? site
                  : undefined,
            };
          }
        }

        return null;
      })
      .filter(
        (
          item,
        ): item is ProcedureItem =>
          item !== null,
      );

    if (result.length > 0) {
      return result;
    }
  }

  const procedure =
    getProcedure(surgery);

  const sites = toStringArray(
    meta.procedureSites ??
      meta.sites ??
      meta.procedureSide,
  );

  if (sites.length > 0) {
    return [
      {
        name: procedure,
        site: sites[0],
      },
    ];
  }

  return [
    {
      name: procedure,
    },
  ];
}


