export function isDateInPeriod(
  surgery: any,
  selectedDate: string,
  period: Period,
) {
  const raw =
    getDateSortValue(surgery);

  if (!raw || !selectedDate) {
    return true;
  }

  const surgeryDate = new Date(
    raw.length === 10
      ? `${raw}T00:00:00`
      : raw,
  );

  const selected = new Date(
    `${selectedDate}T00:00:00`,
  );

  if (
    Number.isNaN(
      surgeryDate.getTime(),
    ) ||
    Number.isNaN(
      selected.getTime(),
    )
  ) {
    return true;
  }

  if (period === "Day") {
    return (
      surgeryDate.getFullYear() ===
        selected.getFullYear() &&
      surgeryDate.getMonth() ===
        selected.getMonth() &&
      surgeryDate.getDate() ===
        selected.getDate()
    );
  }

  if (period === "Week") {
    const day = selected.getDay();
    const diff =
      day === 0 ? -6 : 1 - day;

    const start = new Date(selected);
    start.setDate(
      selected.getDate() + diff,
    );
    start.setHours(0, 0, 0, 0);

    const end = new Date(start);
    end.setDate(
      start.getDate() + 6,
    );
    end.setHours(
      23,
      59,
      59,
      999,
    );

    return (
      surgeryDate >= start &&
      surgeryDate <= end
    );
  }

  return (
    surgeryDate.getFullYear() ===
      selected.getFullYear() &&
    surgeryDate.getMonth() ===
      selected.getMonth()
  );
}


export function getPreOpWorkflowStatus(
  surgery: any,
): PreOpWorkflowStatus {
  if (
    surgery.status === "Financially Cleared"
  ) {
    return "Awaiting Admit";
  }

  if (surgery.status === "Admitted") {
    return "Admitted";
  }

  /*
   * A patient is complete only after the shared surgery flow
   * has been moved to Ready by Confirm Pre-Op Ready.
   */
  if (
    surgery.status === "Ready" ||
    surgery.status === "In Progress" ||
    surgery.status === "Completed" ||
    surgery.status === "Recovery" ||
    surgery.status === "Discharged" ||
    surgery.preOpStatus === "Ready" ||
    surgery.preOpCompleted === true
  ) {
    return "Complete";
  }

  const id = String(
    surgery.id ?? "",
  );

  if (!id) {
    return "Not Started";
  }

  try {
    const progressRaw =
      localStorage.getItem(
        `pre-op-progress-${id}`,
      );

    const safetyRaw =
      localStorage.getItem(
        `pre-op-safety-${id}`,
      );

    const suppliesRaw =
      localStorage.getItem(
        `pre-op-supplies-${id}`,
      );

    let hasProgress = false;

    if (progressRaw) {
      const progress =
        JSON.parse(progressRaw);

      hasProgress =
        (Array.isArray(
          progress.completedTests,
        ) &&
          progress.completedTests
            .length > 0) ||
        (Array.isArray(
          progress.completedAssessment,
        ) &&
          progress.completedAssessment
            .length > 0) ||
        Boolean(
          progress.anesthesia,
        );
    }

    if (
      !hasProgress &&
      safetyRaw
    ) {
      const safety =
        JSON.parse(safetyRaw);

      hasProgress =
        safety.acknowledged === true ||
        (Array.isArray(
          safety.exceptions,
        ) &&
          safety.exceptions
            .length > 0);
    }

    if (
      !hasProgress &&
      suppliesRaw
    ) {
      const supplies =
        JSON.parse(suppliesRaw);

      hasProgress = [
        ...(Array.isArray(
          supplies.required,
        )
          ? supplies.required
          : []),
        ...(Array.isArray(
          supplies.additional,
        )
          ? supplies.additional
          : []),
      ].some(
        (item: any) =>
          item?.checked === true,
      );
    }

    return hasProgress
      ? "In Progress"
      : "Not Started";
  } catch {
    return "Not Started";
  }
}

import { useState, useRef, useMemo, useEffect } from "react";
import { CalendarDays, ChevronDown, ChevronLeft, ChevronRight } from "lucide-react";
import { formatSurgeryDate } from "../utils";




export function ReceptionDatePicker({
  value,
  onChange,
}: {
  value: string;
  onChange: (value: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const pickerRef = useRef<HTMLDivElement>(null);

  const parsedValue = useMemo(() => {
    const parsed = new Date(`${value}T00:00:00`);
    return Number.isNaN(parsed.getTime()) ? new Date() : parsed;
  }, [value]);

  const [viewDate, setViewDate] = useState(
    () =>
      new Date(
        parsedValue.getFullYear(),
        parsedValue.getMonth(),
        1,
      ),
  );

  useEffect(() => {
    setViewDate(
      new Date(
        parsedValue.getFullYear(),
        parsedValue.getMonth(),
        1,
      ),
    );
  }, [parsedValue]);

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        pickerRef.current &&
        !pickerRef.current.contains(event.target as Node)
      ) {
        setOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);
    return () =>
      document.removeEventListener(
        "mousedown",
        handleOutsideClick,
      );
  }, []);

  const formatInputDate = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  };

  const days = useMemo(() => {
    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();
    const firstDay = new Date(year, month, 1);
    const mondayOffset = (firstDay.getDay() + 6) % 7;
    const gridStart = new Date(year, month, 1 - mondayOffset);

    return Array.from({ length: 42 }, (_, index) => {
      const date = new Date(gridStart);
      date.setDate(gridStart.getDate() + index);
      return date;
    });
  }, [viewDate]);

  const todayKey = formatInputDate(new Date());
  const selectedKey = value;

  return (
    <div ref={pickerRef} className="relative min-w-0 flex-1">
      <button
        type="button"
        onClick={() => setOpen((current) => !current)}
        className={`flex h-8 w-full items-center justify-between gap-2 rounded-lg border bg-white px-2.5 text-left transition ${
          open
            ? "border-amber-300 ring-2 ring-amber-100"
            : "border-slate-200 hover:border-amber-200"
        }`}
      >
        <div className="flex min-w-0 items-center gap-2">
          <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-md bg-amber-50 text-amber-600">
            <CalendarDays size={11} />
          </span>

          <span className="truncate text-[10px] font-semibold text-slate-600">
            {formatSurgeryDate(value)}
          </span>
        </div>

        <ChevronDown
          size={10}
          className={`shrink-0 text-slate-400 transition ${
            open ? "rotate-180" : ""
          }`}
        />
      </button>

      {open && (
        <div className="absolute bottom-[calc(100%+7px)] right-0 z-[80] w-[244px] overflow-hidden rounded-xl border border-slate-200 bg-white p-2.5 shadow-[0_-14px_40px_rgba(15,23,42,0.14)]">
          <div className="mb-2 flex items-center justify-between">
            <button
              type="button"
              onClick={() =>
                setViewDate(
                  (current) =>
                    new Date(
                      current.getFullYear(),
                      current.getMonth() - 1,
                      1,
                    ),
                )
              }
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400 transition hover:border-amber-200 hover:bg-amber-50 hover:text-amber-700"
              aria-label="Previous month"
            >
              <ChevronLeft size={12} />
            </button>

            <div className="text-center">
              <p className="text-[10px] font-bold text-slate-700">
                {viewDate.toLocaleDateString("en-US", {
                  month: "long",
                  year: "numeric",
                })}
              </p>
            </div>

            <button
              type="button"
              onClick={() =>
                setViewDate(
                  (current) =>
                    new Date(
                      current.getFullYear(),
                      current.getMonth() + 1,
                      1,
                    ),
                )
              }
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400 transition hover:border-amber-200 hover:bg-amber-50 hover:text-amber-700"
              aria-label="Next month"
            >
              <ChevronRight size={12} />
            </button>
          </div>

          <div className="grid grid-cols-7 gap-0.5">
            {["M", "T", "W", "T", "F", "S", "S"].map(
              (day, index) => (
                <div
                  key={`${day}-${index}`}
                  className="flex h-5 items-center justify-center text-[7px] font-bold uppercase text-slate-400"
                >
                  {day}
                </div>
              ),
            )}

            {days.map((date) => {
              const key = formatInputDate(date);
              const isSelected = key === selectedKey;
              const isToday = key === todayKey;
              const isCurrentMonth =
                date.getMonth() === viewDate.getMonth();

              return (
                <button
                  key={key}
                  type="button"
                  onClick={() => {
                    onChange(key);
                    setOpen(false);
                  }}
                  className={`flex h-7 w-full items-center justify-center rounded-md text-[8.5px] font-semibold transition ${
                    isSelected
                      ? "bg-amber-500 text-white shadow-sm"
                      : isToday
                        ? "bg-amber-50 text-amber-700 ring-1 ring-inset ring-amber-200"
                        : isCurrentMonth
                          ? "text-slate-600 hover:bg-amber-50 hover:text-amber-700"
                          : "text-slate-300 hover:bg-slate-50"
                  }`}
                >
                  {date.getDate()}
                </button>
              );
            })}
          </div>

          <div className="mt-2 flex items-center justify-between border-t border-slate-100 pt-2">
            <button
              type="button"
              onClick={() => {
                const today = new Date();
                const key = formatInputDate(today);
                onChange(key);
                setViewDate(
                  new Date(
                    today.getFullYear(),
                    today.getMonth(),
                    1,
                  ),
                );
                setOpen(false);
              }}
              className="rounded-md px-2 py-1 text-[8px] font-bold text-amber-700 transition hover:bg-amber-50"
            >
              Today
            </button>

            <button
              type="button"
              onClick={() => setOpen(false)}
              className="rounded-md px-2 py-1 text-[8px] font-semibold text-slate-400 transition hover:bg-slate-50 hover:text-slate-600"
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { type ReceptionToastType, type Period, type PatientStatus, type AdmissionFormItem, type ConsentFormDetails, type ConsentAnswer, type ReceptionConsentApproval, type Patient, type CashierChargeRow } from "./types";
import { toast } from "sonner";
import { CheckCircle2, AlertTriangle, HeartPulse, X } from "lucide-react";
import { admissionFormItems } from "./config";


export function showReceptionToast(
  type: ReceptionToastType,
  title: string,
  message: string,
) {
  const isSuccess = type === "success";
  const isWarning = type === "warning";

  const borderClass = isSuccess
    ? "border-emerald-200"
    : isWarning
      ? "border-amber-200"
      : "border-red-200";

  const accentClass = isSuccess
    ? "bg-emerald-500"
    : isWarning
      ? "bg-amber-500"
      : "bg-red-500";

  const iconClass = isSuccess
    ? "bg-emerald-50 text-emerald-600"
    : isWarning
      ? "bg-amber-50 text-amber-600"
      : "bg-red-50 text-red-600";

  const titleClass = isSuccess
    ? "text-emerald-700"
    : isWarning
      ? "text-amber-700"
      : "text-red-700";

  toast.custom(
    (toastId) => (
      <div className="w-[410px] max-w-[calc(100vw-40px)]">
        <div
          className={`relative overflow-hidden rounded-xl border bg-white shadow-[0_18px_45px_rgba(15,23,42,0.18)] ${borderClass}`}
        >
          <span
            className={`absolute bottom-0 left-0 top-0 w-1 ${accentClass}`}
          />

          <div className="flex items-start gap-3 py-3.5 pl-4 pr-3.5">
            <div
              className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${iconClass}`}
            >
              {isSuccess ? (
                <CheckCircle2 size={17} />
              ) : isWarning ? (
                <AlertTriangle size={17} />
              ) : (
                <HeartPulse size={17} />
              )}
            </div>

            <div className="min-w-0 flex-1">
              <p className={`text-[12px] font-bold ${titleClass}`}>
                {title}
              </p>

              <p className="mt-0.5 whitespace-pre-line text-[9px] leading-4 text-slate-500">
                {message}
              </p>
            </div>

            <button
              type="button"
              onClick={() => toast.dismiss(toastId)}
              className="mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-slate-300 transition hover:bg-slate-50 hover:text-slate-500"
              aria-label="Dismiss notification"
            >
              <X size={13} />
            </button>
          </div>
        </div>
      </div>
    ),
    {
      duration: 5000,
      position: "bottom-right",
    },
  );
}


export function getInitials(name: string) {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("");
}


export function isDateInPeriod(
  surgeryDateValue: string,
  selectedDate: string,
  period: Period,
) {
  const surgeryDate = new Date(`${surgeryDateValue}T00:00:00`);
  const selected = new Date(`${selectedDate}T00:00:00`);

  if (
    Number.isNaN(surgeryDate.getTime()) ||
    Number.isNaN(selected.getTime())
  ) {
    return false;
  }

  if (period === "Day") {
    return surgeryDate.toDateString() === selected.toDateString();
  }

  if (period === "Week") {
    const day = selected.getDay();
    const start = new Date(selected);
    start.setDate(selected.getDate() - (day === 0 ? 6 : day - 1));
    start.setHours(0, 0, 0, 0);

    const end = new Date(start);
    end.setDate(start.getDate() + 6);
    end.setHours(23, 59, 59, 999);

    return surgeryDate >= start && surgeryDate <= end;
  }

  return (
    surgeryDate.getFullYear() === selected.getFullYear() &&
    surgeryDate.getMonth() === selected.getMonth()
  );
}


export function formatSurgeryDate(dateString: string) {
  const date = new Date(`${dateString}T00:00:00`);

  if (Number.isNaN(date.getTime())) return dateString;

  return date.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}



export function getSharedReceptionStatus(
  surgery: {
    status?: string;
    arrivedAt?: string;
    receptionCompletedAt?: string;
  },
): PatientStatus | null {
  /*
   * Only completed cross-page handoffs should override Reception's
   * local intermediate workflow state.
   *
   * IMPORTANT:
   * `arrivedAt` must NOT force "Reception In Progress" here because that
   * would overwrite local states such as "Ready for Admission".
   */
  if (
    surgery.receptionCompletedAt ||
    surgery.status === "Payment Pending" ||
    surgery.status === "Pre-Op" ||
    surgery.status === "Ready" ||
    surgery.status === "In Progress" ||
    surgery.status === "Completed" ||
    surgery.status === "Recovery" ||
    surgery.status === "Discharged"
  ) {
    return "Sent to Cashier";
  }

  return null;
}

export function createAdmissionFormsState(complete = false) {
