    ) as Record<string, string>,
    answers: Object.fromEntries(
      item.questions.map((question) => [
        question.id,
        "",
      ]),
    ) as Record<string, ConsentAnswer>,
  };
}


export function createConsentApproval(): ReceptionConsentApproval {
