    identificationNumber: "",
    approvalMethod: "",
  };
}


export function isConsentFormComplete(
  item: AdmissionFormItem,
  details: ConsentFormDetails,
) {
  return item.fields
    .filter((field) => field.required)
    .every((field) =>
      Boolean(
        details.values[field.id]?.trim(),
      ),
    );
}


export function firstMoneyValue(...values: unknown[]) {
  for (const value of values) {
    const numeric = Number(value);

    if (
      value !== null &&
      value !== undefined &&
      value !== "" &&
      Number.isFinite(numeric)
    ) {
      return numeric;
    }
  }

  return null;
}


export function getCashierChargeSummary(
  patient: Patient,
  surgery?: any,
) {
  const configuredLineItems: CashierChargeRow[] =
    Array.isArray(
      surgery?.cashierEstimate?.lineItems,
    )
      ? surgery.cashierEstimate.lineItems.map(
          (item: any, index: number) => {
            const label = String(
              item?.label ??
                "Hospital charge",
            );

            const matchingProcedure =
              patient.procedures.find(
                (procedure) =>
                  procedure.name === label,
              );

            return {
              id:
                String(
                  item?.id ??
                    `charge-${index}`,
                ),
              category: String(
                item?.category ??
                  "Hospital",
              ),
              label,
              site:
                typeof item?.site ===
                "string"
                  ? item.site
                  : matchingProcedure?.site,
              detail:
                typeof item?.detail ===
                "string"
                  ? item.detail
                  : undefined,
              amount: firstMoneyValue(
                item?.amount,
              ),
            };
          },
        )
      : [];

  const recordedTotal =
    firstMoneyValue(
      surgery?.cost,
      surgery?.totalAmount,
      surgery?.amount,
    ) ?? 0;

  let rows = configuredLineItems;

  // Backward-compatible fallback for records that do not yet have a
  // configured cashier estimate.
  if (rows.length === 0) {
    const procedureCosts =
      surgery?.procedureCosts &&
      typeof surgery.procedureCosts ===
        "object"
        ? surgery.procedureCosts
        : {};

    rows = patient.procedures.map(
      (procedure, index) => ({
        id: `procedure-${index}`,
        category: "Procedure",
        label: procedure.name,
        site: procedure.site,
        amount: firstMoneyValue(
          procedureCosts?.[
            procedure.name
          ],
          procedureCosts?.[index],
        ),
      }),
    );

    const known = rows.reduce(
      (sum, item) =>
        sum + (item.amount ?? 0),
      0,
    );

    if (
      recordedTotal > 0 &&
      recordedTotal > known
    ) {
      rows.push({
        id: "package-balance",
        category: "Package",
        label: "Remaining surgery package",
        detail:
          known > 0
            ? "Unallocated hospital estimate"
            : "Detailed pricing to be confirmed by Cashier",
        amount:
          recordedTotal - known,
      });
    }
  }

  const lineItemsTotal =
    rows.reduce(
      (sum, item) =>
        sum + (item.amount ?? 0),
      0,
    );

  const totalAmount =
    recordedTotal > 0
      ? recordedTotal
      : lineItemsTotal;

  const paidAmount =
    firstMoneyValue(
      surgery?.paidAmount,
    ) ?? 0;

  const insuranceCoverage =
    firstMoneyValue(
      surgery?.cashierEstimate
        ?.insuranceCoverage,
      surgery?.insuranceCoverage,
      surgery?.coverageAmount,
    );

  const discountAmount =
    firstMoneyValue(
      surgery?.cashierEstimate
        ?.discountAmount,
      surgery?.discountAmount,
    ) ?? 0;

  const patientResponsibility =
    Math.max(
      totalAmount -
        (insuranceCoverage ?? 0) -
        discountAmount,
      0,
    );

  const balance = Math.max(
    patientResponsibility -
      paidAmount,
    0,
  );

  return {
    rows,
    totalAmount,
    paidAmount,
    insuranceCoverage,
    discountAmount,
    patientResponsibility,
    balance,
  };
}


export function filteredIndexForPatient(
  patients: Patient[],
  id: string,
) {
  return Math.max(
    0,
    patients.findIndex(
      (patient) => patient.id === id,
    ),
  );
}

