import { useState, useRef, useEffect } from "react";
import { Calendar, ChevronDown, ChevronLeft, ChevronRight } from "lucide-react";




export function ModernRecoveryDatePicker({
  value,
  onChange,
}: {
  value: string;
  onChange: (value: string) => void;
}) {
  const initialDate = value
    ? new Date(`${value}T00:00:00`)
    : new Date();

  const [open, setOpen] = useState(false);
  const [viewDate, setViewDate] =
    useState(initialDate);

  const pickerRef =
    useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!open) return;

    const handleMouseDown = (
      event: MouseEvent,
    ) => {
      const target =
        event.target as Node | null;

      if (
        target &&
        pickerRef.current &&
        !pickerRef.current.contains(target)
      ) {
        setOpen(false);
      }
    };

    document.addEventListener(
      "mousedown",
      handleMouseDown,
    );

    return () =>
      document.removeEventListener(
        "mousedown",
        handleMouseDown,
      );
  }, [open]);

  useEffect(() => {
    if (!value) return;

    const next = new Date(
      `${value}T00:00:00`,
    );

    if (!Number.isNaN(next.getTime())) {
      setViewDate(next);
    }
  }, [value]);

  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();

  const firstDay = new Date(
    year,
    month,
    1,
  ).getDay();

  const daysInMonth = new Date(
    year,
    month + 1,
    0,
  ).getDate();

  const startOffset =
    firstDay === 0
      ? 6
      : firstDay - 1;

  const cells = Array.from(
    {
      length:
        Math.ceil(
          (startOffset + daysInMonth) / 7,
        ) * 7,
    },
    (_, index) => {
      const day =
        index - startOffset + 1;

      return day > 0 &&
        day <= daysInMonth
        ? day
        : null;
    },
  );

  const selectedDate = value
    ? new Date(`${value}T00:00:00`)
    : null;

  const toDateValue = (date: Date) =>
    [
      date.getFullYear(),
      String(
        date.getMonth() + 1,
      ).padStart(2, "0"),
      String(date.getDate()).padStart(
        2,
        "0",
      ),
    ].join("-");

  const isSelected = (day: number) =>
    selectedDate?.getFullYear() === year &&
    selectedDate?.getMonth() === month &&
    selectedDate?.getDate() === day;

  const today = new Date();

  const isToday = (day: number) =>
    today.getFullYear() === year &&
    today.getMonth() === month &&
    today.getDate() === day;

  return (
    <div
      ref={pickerRef}
      className="relative min-w-0"
    >
      <button
        type="button"
        onClick={() =>
          setOpen((current) => !current)
        }
        className={`flex h-7 w-full items-center justify-between rounded-lg border px-2 transition ${
          open
            ? "border-teal-300 bg-white ring-2 ring-teal-100"
            : "border-slate-200 bg-white hover:border-teal-200"
        }`}
      >
        <div className="flex min-w-0 items-center gap-1.5">
          <Calendar
            size={11}
            className={
              open
                ? "text-teal-600"
                : "text-slate-400"
            }
          />

          <span className="truncate text-[9px] font-semibold text-slate-600">
            {selectedDate
              ? selectedDate.toLocaleDateString(
                  "en-US",
                  {
                    month: "short",
                    day: "numeric",
                    year: "numeric",
                  },
                )
              : "Select date"}
          </span>
        </div>

        <ChevronDown
          size={10}
          className={`text-slate-400 transition-transform ${
            open ? "rotate-180" : ""
          }`}
        />
      </button>

      {open && (
        <div className="absolute bottom-[calc(100%+7px)] right-0 z-[100] w-[244px] overflow-hidden rounded-xl border border-slate-200 bg-white p-2.5 shadow-[0_-14px_40px_rgba(15,23,42,0.14)]">
          <div className="mb-2 flex items-center justify-between">
            <button
              type="button"
              onClick={() =>
                setViewDate(
                  new Date(
                    year,
                    month - 1,
                    1,
                  ),
                )
              }
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-100 text-slate-400 hover:bg-teal-50 hover:text-teal-600"
            >
              <ChevronLeft size={13} />
            </button>

            <div className="text-center">
              <p className="text-[11px] font-bold text-slate-700">
                {viewDate.toLocaleDateString(
                  "en-US",
                  { month: "long" },
                )}
              </p>
              <p className="text-[8px] font-semibold text-slate-400">
                {year}
              </p>
            </div>

            <button
              type="button"
              onClick={() =>
                setViewDate(
                  new Date(
                    year,
                    month + 1,
                    1,
                  ),
                )
              }
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-100 text-slate-400 hover:bg-teal-50 hover:text-teal-600"
            >
              <ChevronRight size={13} />
            </button>
          </div>

          <div className="mb-1 grid grid-cols-7">
            {[
              "Mo",
              "Tu",
              "We",
              "Th",
              "Fr",
              "Sa",
              "Su",
            ].map((day) => (
              <div
                key={day}
                className="flex h-6 items-center justify-center text-[7px] font-bold uppercase text-slate-400"
              >
                {day}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-7 gap-[2px]">
            {cells.map((day, index) => {
              if (!day) {
                return (
                  <div
                    key={index}
                    className="h-7"
                  />
                );
              }

              const selected =
                isSelected(day);
              const current =
                isToday(day);

              return (
                <button
                  key={index}
                  type="button"
                  onClick={() => {
                    onChange(
                      toDateValue(
                        new Date(
                          year,
                          month,
                          day,
                        ),
                      ),
                    );
                    setOpen(false);
                  }}
                  className={`relative flex h-7 items-center justify-center rounded-lg text-[9px] font-semibold transition ${
                    selected
                      ? "bg-teal-600 text-white shadow-sm"
                      : current
                        ? "bg-teal-50 text-teal-700 ring-1 ring-inset ring-teal-200"
                        : "text-slate-600 hover:bg-teal-50 hover:text-teal-700"
                  }`}
                >
                  {day}
                </button>
              );
            })}
          </div>

          <div className="mt-2 flex items-center justify-between border-t border-slate-100 pt-2">
            <button
              type="button"
              onClick={() => {
                const now = new Date();
                setViewDate(now);
                onChange(toDateValue(now));
                setOpen(false);
              }}
              className="rounded-md px-2 py-1 text-[8px] font-bold text-teal-600 hover:bg-teal-50"
            >
              Today
            </button>

            <button
              type="button"
              onClick={() => setOpen(false)}
              className="rounded-md px-2 py-1 text-[8px] font-semibold text-slate-400 hover:bg-slate-50"
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { demoPatientAge, demoPatientGender } from "./config";
import { type Period, type RecoveryStatus } from "./types";


export function getPatientAge(
  surgery: unknown,
): number | string {
  const record = surgery as {
    id?: string;
    age?: unknown;
    patientAge?: unknown;
  };

  const value =
    record.age ??
    record.patientAge;

  if (
    typeof value === "number" &&
    Number.isFinite(value) &&
    value > 0
  ) {
    return value;
  }

  return record.id
    ? demoPatientAge[record.id] ?? "—"
    : "—";
}


export function getPatientGender(
  surgery: unknown,
): string {
  const record = surgery as {
    id?: string;
    gender?: unknown;
    patientGender?: unknown;
    sex?: unknown;
  };

  const value =
    record.gender ??
    record.patientGender ??
    record.sex;

  if (
    typeof value === "string" &&
    value.trim()
  ) {
    return value;
  }

  return record.id
    ? demoPatientGender[record.id] ?? "Not specified"
    : "Not specified";
}


export function getSurgeryProcedures(
  surgery: unknown,
): Array<{
  name: string;
  site?: string;
}> {
  const record = surgery as {
    procedure?: unknown;
    procedures?: unknown;
  };

  if (Array.isArray(record.procedures)) {
    const result = record.procedures
      .map((item) => {
        if (typeof item === "string") {
          return {
            name: item,
          };
        }

        if (
          typeof item === "object" &&
          item !== null
        ) {
          const value = item as {
            name?: unknown;
            procedure?: unknown;
            label?: unknown;
            site?: unknown;
            location?: unknown;
          };

          const name =
            value.name ??
            value.procedure ??
            value.label;

          const site =
            value.site ??
            value.location;

          if (typeof name === "string") {
            return {
              name,
              site:
                typeof site === "string"
                  ? site
                  : undefined,
            };
          }
        }

        return null;
      })
      .filter(
        (
          item,
        ): item is {
          name: string;
          site?: string;
        } => item !== null,
      );

    if (result.length > 0) {
      return result;
    }
  }

  return [
    {
      name:
        typeof record.procedure === "string"
          ? record.procedure
          : "Procedure",
    },
  ];
}


export function getInitials(
  name: string,
) {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
}


export function hasRichTextContent(
  value: string,
) {
  const plainText = value
    .replace(/<br\s*\/?>/gi, " ")
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .trim();

  return plainText.length > 0;
}


export function getRecoveryDateSortValue(
  surgery: any,
) {
  const value =
    surgery.surgeryDate ??
    surgery.scheduledDate ??
    surgery.date ??
    surgery.scheduledAt ??
    surgery.startDate ??
    surgery.surgeryStartedAt;

  return value
    ? String(value)
    : "";
}


export function formatRecoverySurgeryDate(
  surgery: any,
) {
  const raw =
    getRecoveryDateSortValue(
      surgery,
    );

  if (!raw) return "—";

  const date = new Date(
    raw.length === 10
      ? `${raw}T00:00:00`
      : raw,
  );

  if (
    Number.isNaN(
      date.getTime(),
    )
  ) {
    return raw;
  }

  return date.toLocaleDateString(
    "en-US",
    {
      month: "short",
      day: "numeric",
      year: "numeric",
    },
  );
}


export function isRecoveryDateInPeriod(
  surgery: any,
  selectedDate: string,
  period: Period,
) {
  const raw =
    getRecoveryDateSortValue(
      surgery,
    );

  if (
    !raw ||
    !selectedDate
  ) {
    return true;
  }

  const surgeryDate =
    new Date(
      raw.length === 10
        ? `${raw}T00:00:00`
        : raw,
    );

  const selected =
    new Date(
      `${selectedDate}T00:00:00`,
    );

  if (
    Number.isNaN(
      surgeryDate.getTime(),
    ) ||
    Number.isNaN(
      selected.getTime(),
    )
  ) {
    return true;
  }

  if (period === "Day") {
    return (
      surgeryDate.getFullYear() ===
        selected.getFullYear() &&
      surgeryDate.getMonth() ===
        selected.getMonth() &&
      surgeryDate.getDate() ===
        selected.getDate()
    );
  }

  if (period === "Week") {
    const day =
      selected.getDay();

    const diff =
      day === 0
        ? -6
        : 1 - day;

    const start =
      new Date(selected);

    start.setDate(
      selected.getDate() +
        diff,
    );

    start.setHours(
      0,
      0,
      0,
      0,
    );

    const end =
      new Date(start);

    end.setDate(
      start.getDate() + 6,
    );

    end.setHours(
      23,
      59,
      59,
      999,
    );

    return (
      surgeryDate >= start &&
      surgeryDate <= end
    );
  }

  return (
    surgeryDate.getFullYear() ===
      selected.getFullYear() &&
    surgeryDate.getMonth() ===
      selected.getMonth()
  );
}


export function getSurgeryDurationSeconds(
  surgery: any,
) {
  const numeric =
    surgery.durationSeconds ??
    surgery.surgeryDurationSeconds;

  if (
    typeof numeric === "number" &&
    Number.isFinite(numeric)
  ) {
    return Math.max(
      0,
      numeric,
    );
  }

  const duration =
    surgery.duration ??
    surgery.surgeryDuration ??
    surgery.actualDuration;

  if (
    typeof duration === "number" &&
    Number.isFinite(duration)
  ) {
    /*
     * Existing stores often keep duration in seconds.
     * If the value looks like milliseconds, normalize it.
     */
    return duration > 86400
      ? Math.floor(
          duration / 1000,
        )
      : Math.floor(duration);
  }

  const startedAt =
    surgery.surgeryStartedAt ??
    surgery.startedAt ??
    surgery.actualStartAt;

  const completedAt =
    surgery.surgeryCompletedAt ??
    surgery.completedAt ??
    surgery.actualEndAt;

  if (
    startedAt &&
    completedAt
  ) {
    const start =
      new Date(startedAt)
        .getTime();

    const end =
      new Date(completedAt)
        .getTime();

    if (
      Number.isFinite(start) &&
      Number.isFinite(end) &&
      end >= start
    ) {
      return Math.floor(
        (end - start) /
          1000,
      );
    }
  }

  return 0;
}


export function formatSurgeryDuration(
  surgery: any,
) {
  const total =
    getSurgeryDurationSeconds(
      surgery,
    );

  if (!total) {
    return "—";
  }

  const hours =
    Math.floor(
      total / 3600,
    );

  const minutes =
    Math.floor(
      (total % 3600) /
        60,
    );

  const seconds =
    total % 60;

  return [
    hours > 0
      ? `${hours}h`
      : "",
    minutes > 0 ||
    hours > 0
      ? `${minutes}m`
      : "",
    `${seconds}s`,
  ]
    .filter(Boolean)
    .join(" ");
}


export function formatClock(
  value?: string,
) {
  if (!value) return "Not recorded";

  const date = new Date(value);

  if (
    Number.isNaN(date.getTime())
  ) {
    return "Not recorded";
  }

  return date.toLocaleTimeString(
    "en-US",
    {
      hour: "numeric",
      minute: "2-digit",
    },
  );
}


export function isRecoveryStatus(
  value: unknown,
): value is RecoveryStatus {
  return [
    "Not Started",
    "Monitoring",
    "Progressing",
    "Ready for Transfer",
  ].includes(String(value));
}

import { type SurgeryProcedure } from "./types";




/* ========================================================================== */
/* Helpers                                                                    */
/* ========================================================================== */





export function getSurgeryProcedures(
  surgery: any,
): SurgeryProcedure[] {
  if (Array.isArray(surgery.procedures)) {
    const procedures = surgery.procedures
      .map((item: any) => {
        if (typeof item === "string") {
          return {
            name: item,
            site: undefined,
          };
        }

        const name =
          item?.name ??
          item?.procedure ??
          item?.label ??
          "";

        const site =
          item?.site ??
          item?.side ??
          item?.location ??
          item?.bodySite;

        if (!name) return null;

        return {
          name: String(name),
          site:
            typeof site === "string" &&
            site.trim()
              ? site.trim()
              : undefined,
        };
      })
      .filter(
        (
          item: SurgeryProcedure | null,
        ): item is SurgeryProcedure =>
          item !== null,
      );

    if (procedures.length > 0) {
      return procedures;
    }
  }

  const fallbackName =
    surgery.procedure ??
    "Procedure not specified";

  const fallbackSite =
    surgery.procedureSite ??
    surgery.site ??
    surgery.side ??
    surgery.bodySite;

  return [
    {
      name: String(fallbackName),
      site:
        typeof fallbackSite === "string" &&
        fallbackSite.trim()
          ? fallbackSite.trim()
          : undefined,
    },
  ];
}




export function formatDuration(totalSeconds: number) {
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  return [hours, minutes, seconds]
    .map((value) => String(value).padStart(2, "0"))
    .join(":");
}


export function getSurgeryTimestamp(
  surgery: Record<string, unknown>,
  keys: string[],
) {
  for (const key of keys) {
    const value = surgery[key];

    if (value) {
      const date = new Date(String(value));

      if (!Number.isNaN(date.getTime())) {
        return date;
      }
    }
  }

  return null;
}


export function formatClinicalTime(value: Date | string | null) {
  if (!value) return "Not recorded";

  const date = value instanceof Date ? value : new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "Not recorded";
  }

  return new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  }).format(date);
}




export function formatCompletedDuration(surgery: {
  surgeryStartedAt?: string | null;
  surgeryCompletedAt?: string | null;
  durationMinutes?: number | null;
}) {
  if (surgery.surgeryStartedAt && surgery.surgeryCompletedAt) {
    const start = new Date(surgery.surgeryStartedAt).getTime();
    const end = new Date(surgery.surgeryCompletedAt).getTime();

    if (!Number.isNaN(start) && !Number.isNaN(end) && end >= start) {
      const seconds = Math.max(0, Math.floor((end - start) / 1000));
      return formatCompactDuration(seconds);
    }
  }

  if (
    typeof surgery.durationMinutes === "number" &&
    surgery.durationMinutes >= 0
  ) {
    return formatCompactDuration(Math.round(surgery.durationMinutes * 60));
  }

  return "Not available";
}


export function formatCompactDuration(totalSeconds: number) {
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  const parts: string[] = [];

  if (hours > 0) {
    parts.push(`${hours}h`);
  }

  if (minutes > 0 || hours > 0) {
    parts.push(`${minutes}m`);
  }

  parts.push(`${seconds}s`);

  return parts.join("");
}


export function getCurrentPhase(status: string) {
  switch (status) {
    case "Pre-Op":
      return "Pre-Operative";
    case "Ready":
      return "Ready for Surgery";
    case "In Progress":
      return "Surgery in Progress";
    case "Completed":
      return "Surgery Completed";
    case "Recovery":
      return "Recovery";
    case "Discharged":
      return "Discharged";
    default:
      return status;
  }
}

import { type Patient } from "../types";
import { getProcedurePricingRows } from "../utils";
import { CheckCircle2, Clock3, ShieldCheck, FileCheck2, Receipt, ArrowRight } from "lucide-react";



export function ReceptionCompletedPanel({
