import { type CalendarSurgery, type StatusBucket } from "../types";
import { useState, useRef, useEffect, useMemo } from "react";
import { surgeryCaseNumber, formatTime, getInitials } from "../utils";
import { CalendarDays, X, Search, Filter, ChevronDown, Stethoscope, Building2, ChevronRight, ChevronLeft } from "lucide-react";
import { STATUS_STYLES } from "../config";



/* ==========================================================================
   SURGERY PREVIEW PANEL
   ========================================================================== */

export function DaySurgeriesDrawer({
  date,
  surgeries,
  onClose,
  onOpenSurgery,
}: {
  date: Date;
  surgeries: CalendarSurgery[];
  onClose: () => void;
  onOpenSurgery: (
    id: string,
  ) => void;
}) {
  const PAGE_SIZE = 6;

  const [search, setSearch] =
    useState("");

  const [filterOpen, setFilterOpen] =
    useState(false);

  const [selectedDoctors, setSelectedDoctors] =
    useState<string[]>([]);

  const [selectedRooms, setSelectedRooms] =
    useState<string[]>([]);

  const [selectedStatuses, setSelectedStatuses] =
    useState<StatusBucket[]>([]);

  const [page, setPage] =
    useState(0);

  const filterRef =
    useRef<HTMLDivElement | null>(
      null,
    );

  useEffect(() => {
    setSearch("");
    setSelectedDoctors([]);
    setSelectedRooms([]);
    setSelectedStatuses([]);
    setPage(0);
    setFilterOpen(false);
  }, [date]);

  useEffect(() => {
    if (!filterOpen) return;

    function handleOutside(
      event: MouseEvent,
    ) {
      const target =
        event.target as Node | null;

      if (
        target &&
        filterRef.current &&
        !filterRef.current.contains(
          target,
        )
      ) {
        setFilterOpen(false);
      }
    }

    document.addEventListener(
      "mousedown",
      handleOutside,
    );

    return () => {
      document.removeEventListener(
        "mousedown",
        handleOutside,
      );
    };
  }, [filterOpen]);

  const doctors =
    useMemo(
      () =>
        Array.from(
          new Set(
            surgeries.map(
              (surgery) =>
                surgery.doctor,
            ),
          ),
        ).sort(),
      [surgeries],
    );

  const rooms =
    useMemo(
      () =>
        Array.from(
          new Set(
            surgeries.map(
              (surgery) =>
                surgery.displayRoom,
            ),
          ),
        ).sort(),
      [surgeries],
    );

  const filtered =
    useMemo(() => {
      const query =
        search
          .trim()
          .toLowerCase();

      return [...surgeries]
        .filter((surgery) => {
          const matchesSearch =
            !query ||
            surgery.patientName
              .toLowerCase()
              .includes(query) ||
            surgery.displayProcedure
              .toLowerCase()
              .includes(query) ||
            surgeryCaseNumber(
              surgery,
            )
              .toLowerCase()
              .includes(query) ||
            surgery.doctor
              .toLowerCase()
              .includes(query) ||
            surgery.displayRoom
              .toLowerCase()
              .includes(query);

          const matchesDoctor =
            selectedDoctors.length ===
              0 ||
            selectedDoctors.includes(
              surgery.doctor,
            );

          const matchesRoom =
            selectedRooms.length ===
              0 ||
            selectedRooms.includes(
              surgery.displayRoom,
            );

          const matchesStatus =
            selectedStatuses.length ===
              0 ||
            selectedStatuses.includes(
              surgery.bucket,
            );

          return (
            matchesSearch &&
            matchesDoctor &&
            matchesRoom &&
            matchesStatus
          );
        })
        .sort(
          (a, b) =>
            a.start.getTime() -
            b.start.getTime(),
        );
    }, [
      surgeries,
      search,
      selectedDoctors,
      selectedRooms,
      selectedStatuses,
    ]);

  const totalPages =
    Math.max(
      1,
      Math.ceil(
        filtered.length /
          PAGE_SIZE,
      ),
    );

  const visibleRows =
    filtered.slice(
      page * PAGE_SIZE,
      page * PAGE_SIZE +
        PAGE_SIZE,
    );

  const activeFilterCount =
    selectedDoctors.length +
    selectedRooms.length +
    selectedStatuses.length;

  useEffect(() => {
    setPage(0);
  }, [
    search,
    selectedDoctors,
    selectedRooms,
    selectedStatuses,
  ]);

  useEffect(() => {
    if (
      page >
      totalPages - 1
    ) {
      setPage(
        Math.max(
          0,
          totalPages - 1,
        ),
      );
    }
  }, [
    page,
    totalPages,
  ]);

  function toggleDoctor(
    doctor: string,
  ) {
    setSelectedDoctors(
      (current) =>
        current.includes(
          doctor,
