      (current) =>
        current.includes(
          status,
        )
          ? current.filter(
              (item) =>
                item !== status,
            )
          : [
              ...current,
              status,
            ],
    );
  }

  function clearFilters() {
    setSelectedDoctors([]);
    setSelectedRooms([]);
    setSelectedStatuses([]);
  }

  const pageIndexes =
    Array.from(
      {
        length: totalPages,
      },
      (_, index) => index,
    ).slice(
      Math.max(
        0,
        Math.min(
          page - 1,
          totalPages - 4,
        ),
      ),
      Math.max(
        0,
        Math.min(
          page - 1,
          totalPages - 4,
        ),
      ) + 4,
