                                className={`flex items-center gap-1.5 rounded-md border px-2 py-1 !text-[9px] font-semibold transition ${
                                  active
                                    ? `${style.bg} ${style.border} ${style.text}`
                                    : "border-slate-200 bg-white text-slate-500"
