                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>

          {(search ||
            activeFilterCount >
              0) && (
            <div className="mt-2 flex items-center justify-between">
              <p className="text-[8px] text-slate-400">
                Showing{" "}
                <span className="font-semibold text-slate-600">
                  {
                    filtered.length
                  }
                </span>{" "}
                of{" "}
                <span className="font-semibold text-slate-600">
                  {
                    surgeries.length
                  }
