                </span>
                <span className="text-right">
                  Status
                </span>
                <span />
              </div>

              <div className="min-h-0 flex-1 divide-y divide-slate-100 overflow-hidden rounded-xl border border-slate-100 bg-white">
                {visibleRows.map(
                  (surgery) => {
                    const style =
                      STATUS_STYLES[
