import { useState, useRef, useEffect } from "react";
import { CalendarDays, ChevronDown, ChevronLeft, ChevronRight } from "lucide-react";



export function ModernScheduleDatePicker({
  value,
  onChange,
}: {
  value: string;
  onChange: (value: string) => void;
}) {
  const initialDate = value
    ? new Date(`${value}T00:00:00`)
    : new Date();

  const [open, setOpen] =
    useState(false);

  const [viewDate, setViewDate] =
    useState(initialDate);

  const pickerRef =
    useRef<HTMLDivElement | null>(
      null,
    );

  useEffect(() => {
    if (!open) return;

    function handleOutside(
      event: MouseEvent,
    ) {
      const target =
        event.target as Node | null;

      if (
        target &&
        pickerRef.current &&
        !pickerRef.current.contains(
          target,
        )
      ) {
        setOpen(false);
      }
    }

    document.addEventListener(
      "mousedown",
      handleOutside,
    );

    return () => {
      document.removeEventListener(
        "mousedown",
        handleOutside,
      );
    };
  }, [open]);

  useEffect(() => {
    if (!value) return;

    const next =
      new Date(
        `${value}T00:00:00`,
      );

    if (
      !Number.isNaN(
        next.getTime(),
      )
    ) {
      setViewDate(next);
    }
  }, [value]);

  const year =
    viewDate.getFullYear();

  const month =
    viewDate.getMonth();

  const firstDay =
    new Date(
      year,
      month,
      1,
    ).getDay();

  const daysInMonth =
    new Date(
      year,
      month + 1,
      0,
    ).getDate();

  const startOffset =
    firstDay === 0
      ? 6
      : firstDay - 1;

  const cells =
    Array.from(
      {
        length:
          Math.ceil(
            (startOffset +
              daysInMonth) /
              7,
          ) * 7,
      },
      (_, index) => {
        const day =
          index -
          startOffset +
          1;

        return day > 0 &&
          day <=
            daysInMonth
          ? day
          : null;
      },
    );

  const selectedDate =
    value
      ? new Date(
          `${value}T00:00:00`,
        )
      : null;

  const formatValue = (
    date: Date,
  ) =>
    date.toLocaleDateString(
      "en-US",
      {
        month: "short",
        day: "numeric",
        year: "numeric",
      },
    );

  const toInputDate = (
    date: Date,
  ) =>
    [
      date.getFullYear(),
      String(
        date.getMonth() + 1,
      ).padStart(
        2,
        "0",
      ),
      String(
        date.getDate(),
      ).padStart(
        2,
        "0",
      ),
    ].join("-");

  const selectDay = (
    day: number,
  ) => {
    const date =
      new Date(
        year,
        month,
        day,
      );

    onChange(
      toInputDate(date),
    );

    setOpen(false);
  };

  const isSelected = (
    day: number,
  ) =>
    selectedDate?.getFullYear() ===
      year &&
    selectedDate?.getMonth() ===
      month &&
    selectedDate?.getDate() ===
      day;

  const today =
    new Date();

  const isCurrentDay = (
    day: number,
  ) =>
    today.getFullYear() ===
      year &&
    today.getMonth() ===
      month &&
    today.getDate() ===
      day;

  return (
    <div
      ref={pickerRef}
      className="relative min-w-0"
    >
      <button
        type="button"
        onClick={() =>
          setOpen(
            (current) =>
              !current,
          )
        }
        className={`flex h-7 min-w-[138px] items-center justify-between rounded-lg border px-2 transition-all duration-200 ${
          open
            ? "border-blue-300 bg-white ring-2 ring-blue-100"
            : "border-slate-200 bg-white hover:border-blue-200 hover:bg-blue-50/20"
        }`}
      >
        <div className="flex min-w-0 items-center gap-1.5">
          <div
            className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md transition ${
              open
                ? "bg-blue-100 text-blue-600"
                : "bg-slate-50 text-slate-400"
            }`}
          >
            <CalendarDays
              size={10}
            />
          </div>

          <span className="truncate !text-[9px] font-semibold text-slate-600">
            {selectedDate
              ? formatValue(
                  selectedDate,
                )
              : "Select date"}
          </span>
        </div>

        <ChevronDown
          size={10}
          className={`shrink-0 text-slate-400 transition-transform duration-200 ${
            open
              ? "rotate-180"
              : ""
          }`}
        />
      </button>

      {open && (
        <div className="absolute right-0 top-[calc(100%+7px)] z-[100] w-[244px] overflow-hidden rounded-xl border border-slate-200 bg-white p-2.5 shadow-[0_14px_40px_rgba(15,23,42,0.14)]">
          <div className="mb-2 flex items-center justify-between px-0.5">
            <button
              type="button"
              onClick={() =>
                setViewDate(
                  new Date(
                    year,
                    month - 1,
                    1,
                  ),
                )
              }
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-100 text-slate-400 transition hover:border-blue-100 hover:bg-blue-50 hover:text-blue-600"
            >
              <ChevronLeft
                size={13}
              />
            </button>

            <div className="text-center">
              <p className="!text-[11px] font-bold text-slate-700">
                {viewDate.toLocaleDateString(
                  "en-US",
                  {
                    month:
                      "long",
                  },
                )}
              </p>

              <p className="!text-[8px] font-semibold text-slate-400">
                {year}
              </p>
            </div>

            <button
              type="button"
              onClick={() =>
                setViewDate(
                  new Date(
                    year,
                    month + 1,
                    1,
                  ),
                )
              }
              className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-100 text-slate-400 transition hover:border-blue-100 hover:bg-blue-50 hover:text-blue-600"
            >
              <ChevronRight
                size={13}
              />
            </button>
          </div>

          <div className="mb-1 grid grid-cols-7">
            {[
              "Mo",
              "Tu",
              "We",
              "Th",
              "Fr",
              "Sa",
              "Su",
            ].map(
              (day) => (
                <div
                  key={day}
                  className="flex h-6 items-center justify-center !text-[7px] font-bold uppercase tracking-wide text-slate-400"
                >
                  {day}
                </div>
              ),
            )}
          </div>

          <div className="grid grid-cols-7 gap-[2px]">
            {cells.map(
              (
                day,
                index,
              ) => {
                if (!day) {
                  return (
                    <div
                      key={
                        index
                      }
                      className="h-7"
                    />
                  );
                }

                const active =
                  isSelected(
                    day,
                  );

                const current =
                  isCurrentDay(
                    day,
                  );

                return (
                  <button
                    key={
                      index
                    }
                    type="button"
                    onClick={() =>
                      selectDay(
                        day,
                      )
                    }
                    className={`relative flex h-7 items-center justify-center rounded-lg !text-[9px] font-semibold transition-all ${
                      active
                        ? "bg-blue-600 text-white shadow-sm hover:bg-blue-500"
                        : current
                          ? "bg-blue-50 text-blue-700 ring-1 ring-inset ring-blue-200"
                          : "text-slate-600 hover:bg-blue-50 hover:text-blue-700"
                    }`}
                  >
                    {day}

                    {current &&
                      !active && (
                        <span className="absolute bottom-1 h-[2px] w-[2px] rounded-full bg-blue-500" />
                      )}
                  </button>
                );
              },
            )}
          </div>

          <div className="mt-2 flex items-center justify-between border-t border-slate-100 pt-2">
            <button
              type="button"
              onClick={() => {
                const now =
                  new Date();

                setViewDate(
                  now,
                );

                onChange(
                  toInputDate(
                    now,
                  ),
                );

                setOpen(
                  false,
                );
              }}
              className="rounded-md px-2 py-1 !text-[8px] font-bold text-blue-600 transition hover:bg-blue-50"
            >
              Today
            </button>

            <button
              type="button"
              onClick={() =>
                setOpen(
                  false,
                )
              }
              className="rounded-md px-2 py-1 !text-[8px] font-semibold text-slate-400 transition hover:bg-slate-50 hover:text-slate-600"
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { type Surgery } from "../../../types/surgery";
import { type StatusBucket, type CalendarSurgery, type SurgeryTimeGroup } from "./types";


/* ==========================================================================
   DATA HELPERS
   ========================================================================== */

export function surgeryDate(
  surgery: Surgery,
) {
  const source =
    surgery as any;

  return String(
    source.date ??
      source.surgeryDate ??
      source.scheduledDate ??
      "",
  );
}


export function surgeryTime(
  surgery: Surgery,
) {
  const source =
    surgery as any;

  return String(
    source.time ??
      source.surgeryTime ??
      source.scheduledTime ??
      "",
  );
}


export function surgeryRoom(
  surgery: Surgery,
) {
  const source =
    surgery as any;

  return String(
    source.room ??
      source.opRoom ??
      source.operatingRoom ??
      "Unassigned",
  );
}


export function surgeryProcedure(
  surgery: Surgery,
) {
  const source =
    surgery as any;

  if (
    Array.isArray(
      source.procedures,
    )
  ) {
    return source.procedures
      .map(
        (item: any) =>
          typeof item ===
          "string"
            ? item
            : item?.name ??
              item?.procedure ??
              "",
      )
      .filter(Boolean)
      .join(" • ");
  }

  return String(
    source.procedure ??
      "Procedure not specified",
  );
}


export function surgeryCaseNumber(
  surgery: Surgery,
) {
  const source =
    surgery as any;

  return String(
    source.caseNumber ??
      source.caseNo ??
      source.id ??
      "",
  );
}


export function surgeryGender(
  surgery: Surgery,
) {
  const source =
    surgery as any;

  return String(
    source.gender ??
      source.patientGender ??
      "",
  );
}


export function combineDateTime(
  dateStr: string,
  timeStr?: string,
) {
  const [
    year,
    month,
    day,
  ] = dateStr
    .split("-")
    .map(Number);

  let hours = 0;
  let minutes = 0;

  if (timeStr) {
    const parts =
      timeStr
        .split(":")
        .map(Number);

    hours =
      parts[0] ?? 0;

    minutes =
      parts[1] ?? 0;
  }

  return new Date(
    year,
    (month ?? 1) - 1,
    day ?? 1,
    hours,
    minutes,
  );
}


export function addMinutes(
  date: Date,
  minutes: number,
) {
  return new Date(
    date.getTime() +
      minutes * 60000,
  );
}


export function addDays(
  date: Date,
  amount: number,
) {
  const next =
    new Date(date);

  next.setDate(
    next.getDate() +
      amount,
  );

  return next;
}


export function addMonths(
  date: Date,
  amount: number,
) {
  const next =
    new Date(date);

  next.setMonth(
    next.getMonth() +
      amount,
  );

  return next;
}


export function isSameDay(
  a: Date,
  b: Date,
) {
  return (
    a.getFullYear() ===
      b.getFullYear() &&
    a.getMonth() ===
      b.getMonth() &&
    a.getDate() ===
      b.getDate()
  );
}


export function isToday(
  date: Date,
) {
  return isSameDay(
    date,
    new Date(),
  );
}


export function dateKey(
  date: Date,
) {
  return `${date.getFullYear()}-${String(
    date.getMonth() + 1,
  ).padStart(2, "0")}-${String(
    date.getDate(),
  ).padStart(2, "0")}`;
}


export function getWeekStart(
  date: Date,
) {
  const start =
    new Date(date);

  const day =
    start.getDay();

  const diff =
    day === 0
      ? -6
      : 1 - day;

  start.setDate(
    start.getDate() +
      diff,
  );

  start.setHours(
    0,
    0,
    0,
    0,
  );

  return start;
}


export function getWeekDays(
  date: Date,
) {
  const start =
    getWeekStart(date);

  return Array.from(
    {
      length: 7,
    },
    (
      _,
      index,
    ) =>
      addDays(
        start,
        index,
      ),
  );
}


export function getMonthGrid(
  anchor: Date,
) {
  const year =
    anchor.getFullYear();

  const month =
    anchor.getMonth();

  const first =
    new Date(
      year,
      month,
      1,
    );

  const firstDay =
    first.getDay();

  const mondayOffset =
    firstDay === 0
      ? -6
      : 1 - firstDay;

  const gridStart =
    new Date(
      year,
      month,
      1 +
        mondayOffset,
    );

  return Array.from(
    {
      length: 42,
    },
    (
      _,
      index,
    ) =>
      addDays(
        gridStart,
        index,
      ),
  );
}


export function getDurationMinutes(
  surgery: Surgery,
) {
  const source =
    surgery as any;

  if (
    typeof source.durationSeconds ===
      "number" &&
    source.durationSeconds >
      0
  ) {
    return Math.max(
      30,
      Math.round(
        source.durationSeconds /
          60,
      ),
    );
  }

  if (
    typeof source.durationMinutes ===
      "number" &&
    source.durationMinutes >
      0
  ) {
    return Math.max(
      30,
      Math.round(
        source.durationMinutes,
      ),
    );
  }

  return 90;
}


export function getStatusBucket(
  status: unknown,
): StatusBucket {
  const value =
    String(status ?? "")
      .trim()
      .toLowerCase();

  if (
    value ===
      "in progress" ||
    value ===
      "in-progress"
  ) {
    return "in-progress";
  }

  if (
    value ===
      "completed" ||
    value ===
      "complete"
  ) {
    return "completed";
  }

  if (
    value ===
    "recovery"
  ) {
    return "recovery";
  }

  if (
    value ===
    "discharged"
  ) {
    return "discharged";
  }

  if (
    value ===
      "ready" ||
    value.includes(
      "ready",
    )
  ) {
    return "ready";
  }

  return "scheduled";
}


export function formatHourLabel(
  hour: number,
) {
  const date =
    new Date();

  date.setHours(
    hour,
    0,
    0,
    0,
  );

  return date.toLocaleTimeString(
    "en-US",
    {
      hour: "numeric",
    },
  );
}


export function formatTime(
  date: Date,
) {
  return date.toLocaleTimeString(
    "en-US",
    {
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    },
  );
}


export function formatCompactDate(
  date: Date,
) {
  return date.toLocaleDateString(
    "en-US",
    {
      month: "short",
      day: "numeric",
    },
  );
}


export function getInitials(
  name: string,
) {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map(
      (part) =>
        part[0],
    )
    .join("")
    .toUpperCase();
}


export function overlaps(
  aStart: Date,
  aEnd: Date,
  bStart: Date,
  bEnd: Date,
) {
  return (
    aStart < bEnd &&
    bStart < aEnd
  );
}


export function applyConflictData(
  surgeries: Omit<
    CalendarSurgery,
    | "conflict"
    | "doctorConflict"
    | "roomConflict"
  >[],
): CalendarSurgery[] {
  return surgeries.map(
    (
      surgery,
      index,
    ) => {
      let doctorConflict =
        false;

      let roomConflict =
        false;

      surgeries.forEach(
        (
          other,
          otherIndex,
        ) => {
          if (
            index ===
            otherIndex
          ) {
            return;
          }

          if (
            !overlaps(
              surgery.start,
              surgery.end,
              other.start,
              other.end,
            )
          ) {
            return;
          }

          if (
            surgery.doctor ===
            other.doctor
          ) {
            doctorConflict =
              true;
          }

          if (
            surgery.displayRoom !==
              "Unassigned" &&
            surgery.displayRoom ===
              other.displayRoom
          ) {
            roomConflict =
              true;
          }
        },
      );

      return {
        ...surgery,
        doctorConflict,
        roomConflict,
        conflict:
          doctorConflict ||
          roomConflict,
      };
    },
  );
}


export function getDayHourRange(
  surgeries: CalendarSurgery[],
) {
  let startHour = 7;
  let endHour = 19;

  surgeries.forEach(
    (surgery) => {
      const start =
        surgery.start.getHours();

      const end =
        surgery.end.getHours() +
        (surgery.end.getMinutes() >
        0
          ? 1
          : 0);

      startHour =
        Math.min(
          startHour,
          start,
        );

      endHour =
        Math.max(
          endHour,
          end,
        );
    },
  );

  return {
    startHour,
    endHour,
  };
}


export function groupSurgeriesByStartTime(
  surgeries: CalendarSurgery[],
): SurgeryTimeGroup[] {
  const groups =
    new Map<
      string,
      CalendarSurgery[]
    >();

  surgeries.forEach(
    (surgery) => {
      const key =
        `${String(
          surgery.start.getHours(),
        ).padStart(2, "0")}:${String(
          surgery.start.getMinutes(),
        ).padStart(2, "0")}`;

      if (!groups.has(key)) {
        groups.set(
          key,
          [],
        );
      }

      groups
        .get(key)!
        .push(surgery);
    },
  );

  return Array.from(
    groups.entries(),
  ).map(
    ([key, items]) => ({
      key,
      time:
        formatTime(
          items[0].start,
        ),
      items,
    }),
  );
}


export function layoutDaySurgeries(
  surgeries: CalendarSurgery[],
) {
  const sorted =
    [...surgeries].sort(
      (a, b) =>
        a.start.getTime() -
        b.start.getTime(),
    );

  const result: {
    surgery: CalendarSurgery;
    laneIndex: number;
    laneCount: number;
  }[] = [];

  let index = 0;

  while (
    index < sorted.length
  ) {
    const cluster: CalendarSurgery[] =
      [sorted[index]];

    let clusterEnd =
      sorted[index].end;

    let cursor =
      index + 1;

    while (
      cursor <
        sorted.length &&
      sorted[cursor].start <
        clusterEnd
    ) {
      cluster.push(
        sorted[cursor],
      );

      if (
        sorted[cursor].end >
        clusterEnd
      ) {
        clusterEnd =
          sorted[cursor].end;
      }

      cursor++;
    }

    cluster.forEach(
      (surgery, laneIndex) =>
        result.push({
          surgery,
          laneIndex,
          laneCount:
            cluster.length,
        }),
    );

    index = cursor;
  }

  return result;
}

