import { useLocation, useNavigate, useSearchParams } from "react-router-dom";
import { useRef, useState, useMemo, useEffect } from "react";
import { useSurgeryStore } from "../store/surgeryStore";
import { type Period, type SortKey, type SortDirection, type ToastState } from "../features/workspaces/Accounting/types";
import { getPatientMrn, getSurgeryProcedures, isDateInPeriod, getSortValue, getInitials, getPatientAge, getPatientGender, formatDateShort } from "../features/workspaces/Accounting/utils";
import { MIN_PAGE_SIZE, ROW_HEIGHT } from "../features/workspaces/Accounting/config";
import { CashierCaseWorkspace } from "../features/accounting/CashierCaseWorkspace";
import { AccountingStatCard, FilterSection, FilterPill, ModernDatePicker, SortableHeader, PaymentStatus, PaymentActionButton, ReceiptActionButton } from "../features/workspaces/Accounting/components";
import { CheckCircle2, WalletCards, CreditCard, UserRound, Search, Filter, ChevronDown, CircleDollarSign, Stethoscope, ChevronLeft, ChevronRight, AlertCircle, X } from "lucide-react";


export default function Accounting() {
  const location = useLocation();
  const navigate = useNavigate();
  const [caseParams, setCaseParams] = useSearchParams();

  const incomingHighlightId = caseParams.get("case") ??
    (
      location.state as
        | { highlightSurgeryId?: string }
        | null
    )?.highlightSurgeryId ?? null;

  const highlightHandledRef = useRef<string | null>(null);

  const [highlightedRowId, setHighlightedRowId] =
    useState<string | null>(null);

  const surgeries = useSurgeryStore(
    (state) => state.surgeries,
  );

  const recordPayment = useSurgeryStore(
    (state) => state.recordPayment,
  );

  const [search, setSearch] = useState("");

  const directCase = surgeries.find((item) => item.id === incomingHighlightId);
  const selectedId = directCase && directCase.paymentStatus !== "Paid" ? directCase.id : null;
  const receiptId = directCase?.paymentStatus === "Paid" ? directCase.id : null;

  function selectCasePanel(id: string | null, panel?: string) {
    setCaseParams((previous) => {
      const next = new URLSearchParams(previous);
      if (id) next.set("case", id);
      if (panel) next.set("panel", panel); else next.delete("panel");
      return next;
    });
  }

  const [amountDraft, setAmountDraft] = useState({ caseId: selectedId, value: "" });
  const amount = amountDraft.caseId === selectedId ? amountDraft.value : "";
  function setAmount(value: string) {
    setAmountDraft({ caseId: selectedId, value });
  }

  const [filterOpen, setFilterOpen] =
    useState(false);

  const filterRef = useRef<HTMLDivElement | null>(null);

  const [selectedDoctors, setSelectedDoctors] =
    useState<string[]>([]);

  const [
    selectedPaymentStatuses,
    setSelectedPaymentStatuses,
  ] = useState<string[]>([]);

  const [period, setPeriod] =
    useState<Period>("Day");

  const [selectedDate, setSelectedDate] =
    useState("2026-09-03");

  const [sortKey, setSortKey] =
    useState<SortKey>("date");

  const [sortDirection, setSortDirection] =
    useState<SortDirection>("asc");

  const [page, setPage] = useState(0);

  const rowsContainerRef =
    useRef<HTMLDivElement | null>(null);

  const [pageSize, setPageSize] =
    useState(5);

  const [toast, setToast] =
    useState<ToastState>(null);

  const doctors = useMemo(
    () =>
      Array.from(
        new Set(
          surgeries.map(
            (surgery) => surgery.doctor,
          ),
        ),
      ),
    [surgeries],
  );

  const paymentStatuses = useMemo(
    () =>
      Array.from(
        new Set(
          surgeries.map(
            (surgery) =>
              surgery.paymentStatus,
          ),
        ),
      ),
    [surgeries],
  );

  const filtered = useMemo(() => {
    const query = search
      .trim()
      .toLowerCase();

    return surgeries.filter((surgery) => {
      const mrn =
        getPatientMrn(surgery);

      const procedures =
        getSurgeryProcedures(surgery);

      const matchesSearch =
        !query ||
        surgery.patientName
          .toLowerCase()
          .includes(query) ||
        mrn
          .toLowerCase()
          .includes(query) ||
        procedures.some((procedure) =>
          procedure
            .name
            .toLowerCase()
            .includes(query),
        );

      const matchesDoctor =
        selectedDoctors.length === 0 ||
        selectedDoctors.includes(
          surgery.doctor,
        );

      const matchesPaymentStatus =
        selectedPaymentStatuses.length ===
          0 ||
        selectedPaymentStatuses.includes(
          surgery.paymentStatus,
        );

      const matchesDate = isDateInPeriod(
        surgery.date,
        selectedDate,
        period,
      );

      return (
        matchesSearch &&
        matchesDoctor &&
        matchesPaymentStatus &&
        matchesDate
      );
    });
  }, [
    surgeries,
    search,
    selectedDoctors,
    selectedPaymentStatuses,
    selectedDate,
    period,
  ]);

  const sorted = useMemo(() => {
    const copy = [...filtered];

    copy.sort((a, b) => {
      const left =
        getSortValue(a, sortKey);

      const right =
        getSortValue(b, sortKey);

      let result = 0;

      if (
        typeof left === "number" &&
        typeof right === "number"
      ) {
        result = left - right;
      } else {
        result = String(left).localeCompare(
          String(right),
          undefined,
          {
            numeric: true,
            sensitivity: "base",
          },
        );
      }

      return sortDirection === "asc"
        ? result
        : -result;
    });

    return copy;
  }, [
    filtered,
    sortKey,
    sortDirection,
  ]);

  const totalPages = Math.max(
    1,
    Math.ceil(
      sorted.length / pageSize,
    ),
  );

  const visibleRows = useMemo(
    () =>
      sorted.slice(
        page * pageSize,
        page * pageSize + pageSize,
      ),
    [sorted, page, pageSize],
  );

  useEffect(() => {
    if (
      !incomingHighlightId ||
      highlightHandledRef.current === incomingHighlightId
    ) {
      return;
    }

    const target = surgeries.find(
      (surgery) => surgery.id === incomingHighlightId,
    );

    if (!target) return;

    highlightHandledRef.current = incomingHighlightId;

    /*
     * Make sure the transferred patient is visible even if the
     * Accounting page had filters left over from a previous visit.
     */
    setSearch("");
    setSelectedDoctors([]);
    setSelectedPaymentStatuses([]);
    setPeriod("Day");
    setSelectedDate(target.date);
    setHighlightedRowId(incomingHighlightId);

    const timeout = window.setTimeout(() => {
      setHighlightedRowId(null);
    }, 3500);

    return () => {
      window.clearTimeout(timeout);
    };
  }, [incomingHighlightId, surgeries]);

  useEffect(() => {
    if (!highlightedRowId) return;

    const rowIndex = sorted.findIndex(
      (surgery) => surgery.id === highlightedRowId,
    );

    if (rowIndex >= 0) {
      setPage(Math.floor(rowIndex / pageSize));
    }
  }, [highlightedRowId, sorted, pageSize]);

  const selected = surgeries.find(
    (surgery) =>
      surgery.id === selectedId,
  );


  const paidCount = surgeries.filter(
    (surgery) =>
      surgery.paymentStatus === "Paid",
  ).length;

  const pendingCount = surgeries.filter(
    (surgery) =>
      surgery.paymentStatus === "Pending",
  ).length;

  const partialCount = surgeries.filter(
    (surgery) =>
      surgery.paymentStatus ===
      "Partially Paid",
  ).length;

  const arrivedCount = surgeries.filter(
    (surgery) =>
      Boolean(surgery.arrivedAt),
  ).length;


  const activeFilterCount =
    selectedDoctors.length +
    selectedPaymentStatuses.length +
    (period !== "Day" ? 1 : 0);

  useEffect(() => {
    const element = rowsContainerRef.current;

    if (!element) return;

    const updatePageSize = () => {
      const availableHeight =
        element.getBoundingClientRect().height;

      const nextPageSize = Math.max(
        MIN_PAGE_SIZE,
        Math.floor(
          availableHeight / ROW_HEIGHT,
        ),
      );

      setPageSize((current) =>
        current === nextPageSize
          ? current
          : nextPageSize,
      );
    };

    updatePageSize();

    const observer = new ResizeObserver(
      updatePageSize,
    );

    observer.observe(element);

    window.addEventListener(
      "resize",
      updatePageSize,
    );

    return () => {
      observer.disconnect();
      window.removeEventListener(
        "resize",
        updatePageSize,
      );
    };
  }, []);

  useEffect(() => {
    setPage(0);
  }, [
    search,
    selectedDoctors,
    selectedPaymentStatuses,
    selectedDate,
    period,
  ]);

  useEffect(() => {
    if (page > totalPages - 1) {
      setPage(
        Math.max(
          0,
          totalPages - 1,
        ),
      );
    }
  }, [
    page,
    totalPages,
  ]);

  useEffect(() => {
    function handleKeyDown(
      event: KeyboardEvent,
    ) {
      if (event.key !== "Escape") {
        return;
      }

      if (selectedId) {
        closePanel();
      }

      if (receiptId) {
        closeReceipt();
      }
    }

    window.addEventListener(
      "keydown",
      handleKeyDown,
    );

    return () => {
      window.removeEventListener(
        "keydown",
        handleKeyDown,
      );
    };
  }, [selectedId, receiptId]);

  useEffect(() => {
    if (!filterOpen) return;

    function handleMouseDown(event: MouseEvent) {
      const target = event.target as Node | null;

      if (
        target &&
        filterRef.current &&
        !filterRef.current.contains(target)
      ) {
        setFilterOpen(false);
      }
    }

    document.addEventListener("mousedown", handleMouseDown);

    return () => {
      document.removeEventListener("mousedown", handleMouseDown);
    };
  }, [filterOpen]);

  useEffect(() => {
    if (!toast) return;

    const timer = window.setTimeout(
      () => setToast(null),
      3500,
    );

    return () =>
      window.clearTimeout(timer);
  }, [toast]);

  function showToast(
    type: "success" | "error",
    title: string,
    message: string,
  ) {
    setToast({
      type,
      title,
      message,
    });
  }

  function handleSort(
    key: SortKey,
  ) {
    if (sortKey === key) {
      setSortDirection((current) =>
        current === "asc"
          ? "desc"
          : "asc",
      );

      return;
    }

    setSortKey(key);
    setSortDirection("asc");
  }

  function toggleDoctor(
    doctor: string,
  ) {
    setSelectedDoctors((current) =>
      current.includes(doctor)
        ? current.filter(
            (item) =>
              item !== doctor,
          )
        : [
            ...current,
            doctor,
          ],
    );
  }

  function togglePaymentStatus(
    status: string,
  ) {
    setSelectedPaymentStatuses(
      (current) =>
        current.includes(status)
          ? current.filter(
              (item) =>
                item !== status,
            )
          : [
              ...current,
              status,
            ],
    );
  }

  function clearFilters() {
    setSelectedDoctors([]);
    setSelectedPaymentStatuses([]);
    setPeriod("Day");
    setSelectedDate(
      "2026-09-03",
    );
  }

  function openPayment(
    surgeryId: string,
  ) {
    selectCasePanel(surgeryId, "payment");
    setAmount("");
  }

  function openReceipt(
    surgeryId: string,
  ) {
    selectCasePanel(surgeryId, "receipt");
  }

  function closeReceipt() {
    selectCasePanel(null);
  }

  function closePanel() {
    selectCasePanel(null);
    setAmount("");
  }

  function submitPayment() {
    if (!selected) {
      showToast(
        "error",
        "Payment not processed",
        "No patient is selected.",
      );
      return;
    }

    const value = Number(amount);

    const remaining =
      selected.cost -
      selected.paidAmount;

    if (
      !amount ||
      Number.isNaN(value)
    ) {
      showToast(
        "error",
        "Invalid payment",
        "Enter a valid payment amount.",
      );
      return;
    }

    if (value <= 0) {
      showToast(
        "error",
        "Invalid payment",
        "Payment amount must be greater than zero.",
      );
      return;
    }

    if (value > remaining) {
      showToast(
        "error",
        "Payment exceeds balance",
        `Maximum allowed payment is $${remaining.toLocaleString()}.`,
      );
      return;
    }

    try {
      const patientName =
        selected.patientName;

      recordPayment(
        selected.id,
        value,
      );

      setAmount("");

      showToast(
        "success",
        "Payment completed",
        `$${value.toLocaleString()} was recorded successfully for ${patientName}.`,
      );
    } catch {
      showToast(
        "error",
        "Payment failed",
        "Something went wrong while recording the payment. Please try again.",
      );
    }
  }

  if (directCase)
  return (
    <>
      <CashierCaseWorkspace
        surgery={directCase}
        amount={amount}
        setAmount={setAmount}
        onPay={submitPayment}
        onBack={() => {
          navigate("/accounting", {
            replace: true,
            state: null,
          });
        }}
      />

      {toast && (
        <div className="fixed bottom-5 right-5 z-[200] w-[360px] max-w-[calc(100vw-40px)]">
          <div
            role="status"
            className={`relative overflow-hidden rounded-xl border bg-white shadow-[0_18px_45px_rgba(15,23,42,0.18)] ${
              toast.type === "success"
                ? "border-emerald-200"
                : "border-red-200"
            }`}
          >
            <span
              className={`absolute bottom-0 left-0 top-0 w-1 ${
                toast.type === "success"
                  ? "bg-emerald-500"
                  : "bg-red-500"
              }`}
            />

            <div className="flex items-start gap-3 py-3.5 pl-4 pr-3.5">
              <div
                className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${
                  toast.type === "success"
                    ? "bg-emerald-50 text-emerald-600"
                    : "bg-red-50 text-red-600"
                }`}
              >
                {toast.type === "success" ? (
                  <CheckCircle2 size={17} />
                ) : (
                  <AlertCircle size={17} />
                )}
              </div>

              <div className="min-w-0 flex-1">
                <p
                  className={`text-[12px] font-bold ${
                    toast.type === "success"
                      ? "text-emerald-700"
                      : "text-red-700"
                  }`}
                >
                  {toast.title}
                </p>

                <p className="mt-1 text-[10px] leading-4 text-slate-500">
                  {toast.message}
                </p>
              </div>

              <button
                type="button"
                aria-label="Close notification"
                onClick={() => setToast(null)}
                className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-slate-400 transition hover:bg-slate-100 hover:text-slate-600"
              >
                <X size={13} />
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );

  return (
    <div className="flex h-full min-h-0 flex-col bg-slate-50">
      {/* ================================================================ */}
      {/* SUMMARY CARDS                                                    */}
      {/* ================================================================ */}

      <div className="shrink-0 px-2 pt-2">
        <div data-responsive-grid="4" className="grid grid-cols-4 gap-2">
          <AccountingStatCard
            label="Paid"
            value={paidCount}
            icon={
              <CheckCircle2
                size={15}
              />
            }
            tone="indigo"
          />

          <AccountingStatCard
            label="Pending"
            value={pendingCount}
            icon={
              <WalletCards
                size={15}
              />
            }
            tone="amber"
          />

          <AccountingStatCard
            label="Partial"
            value={partialCount}
            icon={
              <CreditCard
                size={15}
              />
            }
            tone="violet"
          />

          <AccountingStatCard
            label="Arrived Patients"
            value={arrivedCount}
            icon={
              <UserRound
                size={15}
              />
            }
            tone="rose"
          />
        </div>
      </div>

      {/* ================================================================ */}
      {/* TABLE                                                            */}
      {/* ================================================================ */}

      <div className="flex min-h-0 flex-1 p-2">
        <section className="flex min-h-0 flex-1 flex-col overflow-visible rounded-xl border border-slate-200 bg-white">
          {/* TABLE HEADER */}

          <div className="flex min-h-[58px] shrink-0 items-center justify-between gap-3 border-b border-slate-100 px-4 py-2.5">
            <div>
              <h2 className="text-[12px] font-semibold text-slate-800">
                Surgery Payments
              </h2>

              <p className="mt-0.5 text-[9px] text-slate-400">
                Review balances and process patient payments
              </p>
            </div>

            <div className="flex items-center gap-2">
              {/* SEARCH */}

              <div className="relative w-[260px]">
                <Search
                  size={13}
                  className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400"
                />

                <input
                  value={search}
                  onChange={(event) =>
                    setSearch(
                      event.target.value,
                    )
                  }
                  placeholder="Search name, MRN or procedure..."
                  className="h-7 w-full rounded-lg border border-slate-200 bg-slate-50 pl-8 pr-3 !text-[11px] text-slate-600 outline-none transition placeholder:text-slate-400 focus:border-indigo-300 focus:bg-white focus:ring-2 focus:ring-indigo-50"
                />
              </div>

              {/* FILTER */}

              <div ref={filterRef} className="relative">
                <button
                  type="button"
                  onClick={() =>
                    setFilterOpen(
                      (current) =>
                        !current,
                    )
                  }
                  className={`inline-flex h-7 items-center gap-1.5 rounded-lg border px-2.5 !text-[11px] font-semibold transition ${
                    filterOpen ||
                    activeFilterCount > 0
                      ? "border-indigo-200 bg-indigo-50 text-indigo-700"
                      : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                  }`}
                >
                  <Filter
                    size={12}
                  />

                  Filters

                  {activeFilterCount >
                    0 && (
                    <span className="flex h-4 min-w-4 items-center justify-center rounded-full bg-indigo-600 px-1 text-[7px] font-bold text-white">
                      {
                        activeFilterCount
                      }
                    </span>
                  )}

                  <ChevronDown
                    size={11}
                  />
                </button>

                {filterOpen && (
                  <div className="absolute right-0 top-[calc(100%+6px)] z-30 w-[350px] rounded-xl border border-slate-200 bg-white p-3 shadow-[0_12px_32px_rgba(15,23,42,0.14)]">
                    <div className="mb-3 flex items-center justify-between">
                      <div>
                        <p className="!text-[12px] font-semibold text-slate-700">
                          Table Filters
                        </p>

                        <p className="mt-0.5 !text-[10px] text-slate-400">
                          Refine the cashier queue
                        </p>
                      </div>

                      <button
                        type="button"
                        onClick={
                          clearFilters
                        }
                        className="text-[8px] font-semibold text-indigo-600 hover:text-indigo-700"
                      >
                        Clear all
                      </button>
                    </div>

                    <FilterSection
                      label="Doctor"
                    >
                      <div className="flex flex-wrap gap-1.5">
                        {doctors.map(
                          (doctor) => (
                            <FilterPill
                              key={
                                doctor
                              }
                              label={
                                doctor
                              }
                              active={selectedDoctors.includes(
                                doctor,
                              )}
                              onClick={() =>
                                toggleDoctor(
                                  doctor,
                                )
                              }
                            />
                          ),
                        )}
                      </div>
                    </FilterSection>

                    <FilterSection
                      label="Payment Status"
                    >
                      <div className="flex flex-wrap gap-1.5">
                        {paymentStatuses.map(
                          (status) => (
                            <FilterPill
                              key={
                                status
                              }
                              label={
                                status
                              }
                              active={selectedPaymentStatuses.includes(
                                status,
                              )}
                              onClick={() =>
                                togglePaymentStatus(
                                  status,
                                )
                              }
                            />
                          ),
                        )}
                      </div>
                    </FilterSection>

                    <FilterSection
                      label="Surgery Date"
                    >
                      <div data-responsive-grid="2" className="grid grid-cols-[1fr_135px] gap-2">
                        <div className="flex h-7 items-center rounded-lg border border-slate-200 bg-slate-50 p-0.5">
                          {(
                            [
                              "Day",
                              "Week",
                              "Month",
                            ] as Period[]
                          ).map(
                            (item) => (
                              <button
                                key={
                                  item
                                }
                                type="button"
                                onClick={() =>
                                  setPeriod(
                                    item,
                                  )
                                }
                                className={`h-6 flex-1 rounded-md !text-[10px] font-semibold transition ${
                                  period ===
                                  item
                                    ? "bg-white text-indigo-600 shadow-sm"
                                    : "text-slate-400 hover:text-slate-600"
                                }`}
                              >
                                {
                                  item
                                }
                              </button>
                            ),
                          )}
                        </div>

                        <ModernDatePicker
                          value={selectedDate}
                          onChange={(value) => {
                            setSelectedDate(value);
                            setPage(0);
                          }}
                        />
                      </div>
                    </FilterSection>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* COLUMN HEADERS */}

          <div data-responsive-table-header="true" className="grid shrink-0 grid-cols-[minmax(145px,1.15fr)_84px_88px_minmax(140px,1fr)_125px_72px_78px_82px_94px_92px] items-center border-b border-slate-100 bg-slate-50/80 px-3 py-1.5">
            <SortableHeader
              label="Patient"
              sortKey="patient"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <SortableHeader
              label="Case #"
              sortKey="case"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <SortableHeader
              label="MRN"
              sortKey="mrn"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <SortableHeader
              label="Procedure"
              sortKey="procedures"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <SortableHeader
              label="Doctor"
              sortKey="doctor"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <SortableHeader
              label="Date"
              sortKey="date"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <SortableHeader
              label="Total"
              sortKey="total"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <SortableHeader
              label="Paid"
              sortKey="paid"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <SortableHeader
              label="Status"
              sortKey="payment"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <div className="!text-[10px] uppercase tracking-wide text-slate-400">
              Action
            </div>
          </div>

          {/* ROWS - Dashboard / Reception visual style */}

          <div
            ref={rowsContainerRef}
            className="min-h-0 flex-1 divide-y divide-slate-100 overflow-visible bg-white"
          >
            {visibleRows.length === 0 ? (
              <div className="flex h-full items-center justify-center">
                <div className="text-center">
                  <CircleDollarSign
                    size={21}
                    className="mx-auto text-slate-300"
                  />

                  <p className="mt-2 text-[10px] font-semibold text-slate-600">
                    No payment records found
                  </p>

                  <p className="mt-1 text-[8px] text-slate-400">
                    Try changing the search or filters.
                  </p>
                </div>
              </div>
            ) : (
              visibleRows.map((surgery, rowIndex) => {
                const remaining = Math.max(
                  0,
                  surgery.cost - surgery.paidAmount,
                );

                const hasArrived = Boolean(
                  surgery.arrivedAt,
                );

                const selectedRow =
                  surgery.id === selectedId;

                const highlightedRow =
                  surgery.id === highlightedRowId;

                const procedures =
                  getSurgeryProcedures(surgery);

                const primaryProcedure =
                  procedures[0] ?? {
                    name: "Procedure",
                    site: undefined,
                  };

                const extraProcedures = Math.max(
                  procedures.length - 1,
                  0,
                );

                return (
                  <div data-responsive-table-row="true"
                    key={surgery.id}
                    className={`group relative grid min-h-[48px] grid-cols-[minmax(145px,1.15fr)_84px_88px_minmax(140px,1fr)_125px_72px_78px_82px_94px_92px] items-center px-3 py-1.5 transition-all duration-500 ${
                      highlightedRow
                        ? "z-10 bg-indigo-100/80 shadow-[inset_0_0_0_1px_rgba(99,102,241,0.35),0_0_20px_rgba(99,102,241,0.24)]"
                        : selectedRow
                          ? "bg-indigo-50/45"
                          : "bg-white hover:bg-slate-50/70"
                    }`}
                  >
                    <span 
                      className={`absolute bottom-1.5 left-0 top-1.5 w-[3px] rounded-r-full ${
                        highlightedRow
                          ? "bg-indigo-600 shadow-[0_0_10px_rgba(79,70,229,0.75)]"
                          : "bg-indigo-500"
                      }`}
                    />

                    {highlightedRow && (
                      <span className="pointer-events-none absolute inset-0 animate-pulse ring-2 ring-inset ring-indigo-300/70" />
                    )}

                    {/* PATIENT */}

                    <div data-cell-label="Patient"  className="flex min-w-0 items-center gap-2">
                      <div
                        className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-[9px] font-bold ${
                          selectedRow || highlightedRow
                            ? "bg-indigo-600 text-white"
                            : "bg-indigo-50 text-indigo-600"
                        }`}
                      >
                        {getInitials(
                          surgery.patientName,
                        )}
                      </div>

                      <div className="min-w-0">
                        <div className="flex min-w-0 items-center gap-1.5">
                          <span className="truncate text-[10px] font-semibold text-slate-800">
                            {surgery.patientName}
                          </span>

                          {hasArrived && (
                            <span className="shrink-0 rounded-full bg-emerald-50 px-1.5 py-0.5 text-[7px] font-semibold text-emerald-600">
                              Arrived
                            </span>
                          )}
                        </div>

                        <p className="mt-0.5 truncate text-[8.5px] font-medium text-slate-400">
                          {getPatientAge(surgery)} yrs · {getPatientGender(surgery)}
                        </p>
                      </div>
                    </div>

                    {/* CASE # */}

                    <span data-cell-label="Case #"  className="truncate text-[10px] font-semibold text-indigo-700">
                      {surgery.id}
                    </span>

                    {/* MRN */}

                    <span data-cell-label="MRN"  className="truncate pr-2 text-[10px] font-medium text-slate-500">
                      {getPatientMrn(surgery)}
                    </span>

                    {/* PROCEDURE */}

                    <div data-cell-label="Procedure"  className="group/procedures relative flex min-w-0 items-center gap-2 pr-2">
                      <div className="flex min-w-0 items-center gap-1">
                        <span className="truncate text-[10px] font-semibold text-slate-700">
                          {primaryProcedure.name}
                        </span>

                        {primaryProcedure.site && (
                          <>
                            <span className="shrink-0 text-[10px] text-slate-300">
                              •
                            </span>

                            <span className="truncate text-[9px] font-medium text-slate-400">
                              {primaryProcedure.site}
                            </span>
                          </>
                        )}
                      </div>

                      {extraProcedures > 0 && (
                        <>
                          <span className="shrink-0 rounded-full bg-slate-100 px-2 py-0.5 text-[8px] font-bold text-slate-500 ring-1 ring-inset ring-slate-200">
                            +{extraProcedures}
                          </span>

                          <div
                            className={`pointer-events-none invisible absolute left-0 z-50 w-[290px] rounded-xl border border-slate-200 bg-white p-2.5 opacity-0 shadow-[0_12px_32px_rgba(15,23,42,0.16)] transition-all duration-150 group-hover/procedures:visible group-hover/procedures:translate-y-0 group-hover/procedures:opacity-100 ${
                              rowIndex >= visibleRows.length - 2
                                ? "bottom-[calc(100%+7px)] -translate-y-1"
                                : "top-[calc(100%+7px)] translate-y-1"
                            }`}
                          >
                            <div className="mb-2 flex items-center justify-between gap-2">
                              <div>
                                <p className="text-[9px] font-bold text-slate-700">
                                  All Procedures
                                </p>

                                <p className="mt-0.5 text-[8px] text-slate-400">
                                  Case {surgery.id}
                                </p>
                              </div>

                              <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[8px] font-bold text-slate-500">
                                {procedures.length}
                              </span>
                            </div>

                            <div className="space-y-1">
                              {procedures.map(
                                (procedure, index) => (
                                  <div
                                    key={`${surgery.id}-${procedure.name}-${procedure.site ?? index}`}
                                    className="flex items-center gap-2 rounded-lg bg-slate-50/80 px-2.5 py-1.5"
                                  >
                                    <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-slate-100 text-[7px] font-bold text-slate-500">
                                      {index + 1}
                                    </span>

                                    <div className="flex min-w-0 flex-1 items-center gap-1">
                                      <span className="truncate text-[9px] font-semibold text-slate-700">
                                        {procedure.name}
                                      </span>

                                      {procedure.site && (
                                        <>
                                          <span className="shrink-0 text-[9px] text-slate-300">
                                            •
                                          </span>

                                          <span className="truncate text-[9px] font-medium text-slate-400">
                                            {procedure.site}
                                          </span>
                                        </>
                                      )}
                                    </div>
                                  </div>
                                ),
                              )}
                            </div>
                          </div>
                        </>
                      )}
                    </div>

                    {/* DOCTOR */}

                    <div data-cell-label="Doctor" className="flex min-w-0 items-center gap-1.5 pr-3">
                      <Stethoscope
                        size={11}
                        className="shrink-0 text-slate-400"
                      />

                      <span className="truncate text-[10px] font-medium text-slate-600">
                        {surgery.doctor}
                      </span>
                    </div>

                    {/* DATE */}

                    <span data-cell-label="Date" className="text-[10px] font-medium text-slate-500">
                      {formatDateShort(
                        surgery.date,
                      )}
                    </span>

                    {/* TOTAL */}

                    <span data-cell-label="Total" className="text-[10px] font-semibold text-slate-700">
                      ${surgery.cost.toLocaleString()}
                    </span>

                    {/* PAID */}

                    <div data-cell-label="Paid">
                      <div className="text-[10px] font-semibold text-slate-700">
                        ${surgery.paidAmount.toLocaleString()}
                      </div>

                      {remaining > 0 && (
                        <div className="mt-0.5 text-[7px] text-slate-400">
                          ${remaining.toLocaleString()} left
                        </div>
                      )}
                    </div>

                    {/* PAYMENT */}

                    <PaymentStatus
                      status={
                        surgery.paymentStatus
                      }
                    />

                    {/* ACTION */}

                    <div data-cell-label="Action" className="relative z-10 flex items-center justify-start">
                      {surgery.paymentStatus !==
                      "Paid" ? (
                        <PaymentActionButton
                          partial={
                            surgery.paymentStatus ===
                            "Partially Paid"
                          }
                          onClick={() =>
                            openPayment(
                              surgery.id,
                            )
                          }
                        />
                      ) : (
                        <ReceiptActionButton
                          onClick={() =>
                            openReceipt(
                              surgery.id,
                            )
                          }
                        />
                      )}
                    </div>
                  </div>
                );
              })
            )}
          </div>

          {/* PAGINATION - Dashboard style */}

          {sorted.length > 0 && (
            <div className="flex h-10 shrink-0 items-center justify-between border-t border-slate-100 bg-slate-50/50 px-3">
              <p className="text-[9px] font-medium text-slate-400">
                Showing{" "}
                <span className="font-semibold text-slate-600">
                  {page * pageSize + 1}–{Math.min(
                    (page + 1) * pageSize,
                    sorted.length,
                  )}
                </span>{" "}
                of{" "}
                <span className="font-semibold text-slate-600">
                  {sorted.length}
                </span>
                <span className="ml-2 text-slate-300">•</span>
                <span className="ml-2 font-medium text-slate-400">
                  {pageSize} rows/page
                </span>
              </p>

              <div className="flex items-center gap-1.5">
                <button
                  type="button"
                  aria-label="Previous page"
                  disabled={page === 0}
                  onClick={() =>
                    setPage((current) =>
                      Math.max(0, current - 1),
                    )
                  }
                  className="flex h-7 w-7 items-center justify-center rounded-md border border-slate-200 bg-white text-slate-400 transition hover:border-indigo-200 hover:bg-indigo-50 hover:text-indigo-700 disabled:cursor-not-allowed disabled:opacity-35"
                >
                  <ChevronLeft size={11} />
                </button>

                {Array.from(
                  { length: totalPages },
                  (_, index) => index,
                )
                  .slice(
                    Math.max(
                      0,
                      Math.min(
                        page - 1,
                        totalPages - 4,
                      ),
                    ),
                    Math.max(
                      0,
                      Math.min(
                        page - 1,
                        totalPages - 4,
                      ),
                    ) + 4,
                  )
                  .map((pageIndex) => (
                    <button
                      key={pageIndex}
                      type="button"
                      onClick={() =>
                        setPage(pageIndex)
                      }
                      className={`flex h-7 min-w-7 items-center justify-center rounded-md border px-2 text-[10px] font-semibold transition ${
                        page === pageIndex
                          ? "border-indigo-600 bg-indigo-600 text-white shadow-sm"
                          : "border-slate-200 bg-white text-slate-600 hover:border-indigo-200 hover:bg-indigo-50 hover:text-indigo-700"
                      }`}
                    >
                      {pageIndex + 1}
                    </button>
                  ))}

                <button
                  type="button"
                  aria-label="Next page"
                  disabled={
                    page >= totalPages - 1
                  }
                  onClick={() =>
                    setPage((current) =>
                      Math.min(
                        totalPages - 1,
                        current + 1,
                      ),
                    )
                  }
                  className="flex h-7 w-7 items-center justify-center rounded-md border border-slate-200 bg-white text-slate-400 transition hover:border-indigo-200 hover:bg-indigo-50 hover:text-indigo-700 disabled:cursor-not-allowed disabled:opacity-35"
                >
                  <ChevronRight size={11} />
                </button>
              </div>
            </div>
          )}
        </section>
      </div>

      {toast && (
        <div className="fixed bottom-5 right-5 z-[100] w-[360px] max-w-[calc(100vw-40px)]">
          <div
            className={`relative overflow-hidden rounded-xl border bg-white shadow-[0_18px_45px_rgba(15,23,42,0.18)] ${
              toast.type === "success"
                ? "border-emerald-200"
                : "border-red-200"
            }`}
          >
            <span
              className={`absolute bottom-0 left-0 top-0 w-1 ${
                toast.type === "success"
                  ? "bg-emerald-500"
                  : "bg-red-500"
              }`}
            />

            <div className="flex items-start gap-3 py-3.5 pl-4 pr-3.5">
              <div
                className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${
                  toast.type === "success"
                    ? "bg-emerald-50 text-emerald-600"
                    : "bg-red-50 text-red-600"
                }`}
              >
                {toast.type === "success" ? (
                  <CheckCircle2 size={17} />
                ) : (
                  <AlertCircle size={17} />
                )}
              </div>

              <div className="min-w-0 flex-1">
                <p
                  className={`text-[12px] font-bold ${
                    toast.type === "success"
                      ? "text-emerald-700"
                      : "text-red-700"
                  }`}
                >
                  {toast.title}
                </p>

                <p className="mt-1 text-[10px] leading-4 text-slate-500">
                  {toast.message}
                </p>
              </div>

              <button
                type="button"
                aria-label="Close notification"
                onClick={() =>
                  setToast(null)
                }
                className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-slate-400 transition hover:bg-slate-100 hover:text-slate-600"
              >
                <X size={13} />
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

import { useNavigate } from "react-router-dom";
import { useSurgeryStore } from "../store/surgeryStore";
import { useState, useMemo } from "react";
import { type SortKey, type SortDirection, type OperatingFilter, type Period, type RoomItem } from "../features/workspaces/Dashboard/types";
import { TODAY, STATUS_STYLES } from "../features/workspaces/Dashboard/config";
import { isDateInPeriod } from "../features/workspaces/Dashboard/utils";
import { PatientStartGuide } from "../components/surgery/PatientStartGuide";
import { MetricCard, RoomBoardTile, DashboardDatePicker, ProcedureCell, StatusBadge, Pagination, PostOpStat, ReadinessRow } from "../features/workspaces/Dashboard/components";
import { Activity, CheckCircle2, AlertTriangle, Building2, ArrowRight, Search, Filter, ChevronDown, ArrowUp, ArrowDown, ArrowUpDown, Stethoscope, FileText, ShieldCheck, ChevronRight, CreditCard, UserCheck, HeartPulse } from "lucide-react";


/* ==========================================================================
   PAGE
   ========================================================================== */

export default function Dashboard() {
  const navigate = useNavigate();

  const surgeries = useSurgeryStore(
    (state) => state.surgeries,
  );

  const [sortKey, setSortKey] =
    useState<SortKey>("time");
  const [sortDirection, setSortDirection] =
    useState<SortDirection>("asc");
  const [page, setPage] = useState(1);
  const [searchQuery, setSearchQuery] =
    useState("");
  const [filterOpen, setFilterOpen] =
    useState(false);
  const [selectedDoctors, setSelectedDoctors] =
    useState<string[]>([]);
  const [selectedStatuses, setSelectedStatuses] =
    useState<OperatingFilter[]>([]);
  const [period, setPeriod] =
    useState<Period>("Month");
  const [selectedDate, setSelectedDate] =
    useState(TODAY);

  const PAGE_SIZE = 4;

  const todaySurgeries = useMemo(
    () =>
      surgeries
        .filter(
          (surgery) =>
            surgery.date === TODAY,
        )
        .sort(
          (a, b) =>
            a.time.localeCompare(b.time),
        ),
    [surgeries],
  );

  const counts = useMemo(
    () => ({
      ready: todaySurgeries.filter(
        (surgery) =>
          surgery.status === "Ready",
      ).length,

      inProgress: todaySurgeries.filter(
        (surgery) =>
          surgery.status === "In Progress",
      ).length,

      recovery: todaySurgeries.filter(
        (surgery) =>
          surgery.status === "Recovery",
      ).length,

      paid: todaySurgeries.filter(
        (surgery) =>
          surgery.paymentStatus === "Paid",
      ).length,

      preOpReady: todaySurgeries.filter(
        (surgery) =>
          surgery.preOpCompleted ||
          surgery.preOpStatus === "Ready",
      ).length,

      anesthesiaReady: todaySurgeries.filter(
        (surgery) =>
          surgery.anesthesiaCompleted,
      ).length,
    }),
    [todaySurgeries],
  );

  const postOpEligible = useMemo(
    () =>
      todaySurgeries.filter(
        (surgery) =>
          surgery.status === "Completed" ||
          surgery.status === "Recovery" ||
          surgery.status === "Discharged",
      ),
    [todaySurgeries],
  );

  const postOpBase = Math.max(
    postOpEligible.length,
    1,
  );

  const operativeReportRate =
    Math.round(
      (postOpEligible.filter(
        (surgery) =>
          Boolean(
            surgery.operativeReport?.trim?.(),
          ),
      ).length /
        postOpBase) *
        100,
    );

  const dischargeInstructionsRate =
    Math.round(
      (postOpEligible.filter(
        (surgery) =>
          Boolean(
            surgery.dischargeInstructions?.trim?.(),
          ),
      ).length /
        postOpBase) *
        100,
    );

  const dischargedRate =
    Math.round(
      (postOpEligible.filter(
        (surgery) =>
          surgery.status === "Discharged",
      ).length /
        postOpBase) *
        100,
    );

  const postOpAttentionCount =
    postOpEligible.filter(
      (surgery) =>
        !surgery.operativeReport?.trim?.() ||
        !surgery.dischargeInstructions?.trim?.() ||
        surgery.status !== "Discharged",
    ).length;

  const roomBoard = useMemo<RoomItem[]>(
    () => {
      const roomNames = Array.from(
        new Set(
          todaySurgeries
            .map((surgery) => surgery.room)
            .filter(Boolean),
        ),
      );

      return roomNames
        .map((room) => {
          const roomCases =
            todaySurgeries.filter(
              (surgery) =>
                surgery.room === room,
            );

          const current =
            roomCases.find(
              (surgery) =>
                surgery.status ===
                "In Progress",
            ) ??
            roomCases.find(
              (surgery) =>
                surgery.status === "Ready",
            );

          const next =
            roomCases.find(
              (surgery) =>
                surgery.id !== current?.id &&
                ![
                  "In Progress",
                  "Completed",
                  "Recovery",
                  "Discharged",
                ].includes(
                  surgery.status,
                ),
            );

          return {
            room,
            current,
            next,
          };
        })
        .slice(0, 4);
    },
    [todaySurgeries],
  );

  const doctorOptions = useMemo(
    () =>
      Array.from(
        new Set(
          surgeries
            .map((surgery) => surgery.doctor)
            .filter(Boolean),
        ),
      ).sort((a, b) =>
        a.localeCompare(b),
      ),
    [surgeries],
  );

  const availableStatuses: OperatingFilter[] = [
    "Ready",
    "In Progress",
    "Recovery",
  ];

  const filteredCases = useMemo(() => {
    const query =
      searchQuery.trim().toLowerCase();

    return surgeries.filter((surgery) => {
      const matchesSearch =
        !query ||
        [
          surgery.id,
          surgery.patientName,
          surgery.mrn,
          surgery.notes,
          surgery.surgeonNotes,
          surgery.procedure,
          surgery.doctor,
          surgery.room,
          surgery.status,
          surgery.time,
        ]
          .filter(Boolean)
          .some((value) =>
            String(value)
              .toLowerCase()
              .includes(query),
          );

      const matchesDoctor =
        selectedDoctors.length === 0 ||
        selectedDoctors.includes(
          surgery.doctor,
        );

      const matchesStatus =
        selectedStatuses.length === 0 ||
        selectedStatuses.includes(
          surgery.status as OperatingFilter,
        );

      const matchesDate = isDateInPeriod(
        surgery.date,
        selectedDate,
        period,
      );

      return (
        matchesSearch &&
        matchesDoctor &&
        matchesStatus &&
        matchesDate
      );
    });
  }, [
    surgeries,
    searchQuery,
    selectedDoctors,
    selectedStatuses,
    period,
    selectedDate,
  ]);

  const toggleDoctorFilter = (
    doctor: string,
  ) => {
    setSelectedDoctors((current) =>
      current.includes(doctor)
        ? current.filter(
            (item) => item !== doctor,
          )
        : [...current, doctor],
    );
    setPage(1);
  };

  const toggleStatusFilter = (
    status: OperatingFilter,
  ) => {
    setSelectedStatuses((current) =>
      current.includes(status)
        ? current.filter(
            (item) => item !== status,
          )
        : [...current, status],
    );
    setPage(1);
  };

  const clearTableFilters = () => {
    setSelectedDoctors([]);
    setSelectedStatuses([]);
    setPeriod("Month");
    setSelectedDate(TODAY);
    setPage(1);
  };

  const sortedCases = useMemo(() => {
    const valueFor = (
      surgery: any,
      key: SortKey,
    ) => {
      switch (key) {
        case "patient":
          return surgery.patientName ?? "";
        case "procedure":
          return surgery.procedure ?? "";
        case "notes":
          return surgery.notes || surgery.surgeonNotes || "";
        case "surgeon":
          return surgery.doctor ?? "";
        case "room":
          return surgery.room ?? "";
        case "status":
          return surgery.status ?? "";
        case "time":
        default:
          return surgery.time ?? "";
      }
    };

    return [...filteredCases].sort(
      (a, b) => {
        const first = String(
          valueFor(a, sortKey),
        ).toLowerCase();
        const second = String(
          valueFor(b, sortKey),
        ).toLowerCase();

        const result =
          first.localeCompare(
            second,
            undefined,
            {
              numeric: true,
              sensitivity: "base",
            },
          );

        return sortDirection === "asc"
          ? result
          : -result;
      },
    );
  }, [
    filteredCases,
    sortKey,
    sortDirection,
  ]);

  const totalPages = Math.max(
    1,
    Math.ceil(
      sortedCases.length / PAGE_SIZE,
    ),
  );

  const safePage = Math.min(
    page,
    totalPages,
  );

  const visibleCases = sortedCases.slice(
    (safePage - 1) * PAGE_SIZE,
    safePage * PAGE_SIZE,
  );

  const handleSort = (
    key: SortKey,
  ) => {
    setPage(1);

    if (sortKey === key) {
      setSortDirection((current) =>
        current === "asc"
          ? "desc"
          : "asc",
      );
      return;
    }

    setSortKey(key);
    setSortDirection("asc");
  };

  const readinessBase =
    Math.max(todaySurgeries.length, 1);

  const financialRate =
    Math.round(
      (counts.paid / readinessBase) *
        100,
    );

  const preOpRate =
    Math.round(
      (counts.preOpReady /
        readinessBase) *
        100,
    );

  const anesthesiaRate =
    Math.round(
      (counts.anesthesiaReady /
        readinessBase) *
        100,
    );

  return (
    <div className="flex h-[calc(100vh-58px)] min-h-0 flex-col gap-2 overflow-hidden bg-slate-50/60 p-2">
      <PatientStartGuide />
      {/* ============================================================ */}
      {/* KEY SURGICAL METRICS                                         */}
      {/* ============================================================ */}

      <section data-responsive-grid="4" className="grid shrink-0 grid-cols-4 gap-2">
        <MetricCard
          label="Today's Schedule"
          value={todaySurgeries.length}
          hint="Scheduled procedures"
          icon={<Activity size={14} />}
          tone="slate"
          onClick={() =>
            navigate("/schedule")
          }
        />

        <MetricCard
          label="Operating Now"
          value={counts.inProgress}
          hint="Live OR cases"
          icon={<Activity size={14} />}
          tone="violet"
          onClick={() =>
            navigate("/surgery")
          }
        />

        <MetricCard
          label="Ready for OR"
          value={counts.ready}
          hint="Cleared to proceed"
          icon={<CheckCircle2 size={14} />}
          tone="blue"
          onClick={() =>
            navigate("/surgery")
          }
        />

        <MetricCard
          label="Needs Attention"
          value={postOpAttentionCount}
          hint="Post-Op follow-through"
          icon={<AlertTriangle size={14} />}
          tone={
            postOpAttentionCount > 0
              ? "cyan"
              : "teal"
          }
          onClick={() =>
            navigate("/post-op")
          }
        />
      </section>

      {/* ============================================================ */}
      {/* OPERATING ROOM BOARD                                         */}
      {/* ============================================================ */}

      <section className="relative z-[140] shrink-0 overflow-visible rounded-2xl border border-slate-200/90 bg-white shadow-[0_2px_10px_rgba(15,23,42,0.04)]">
        <div className="flex h-[38px] items-center justify-between border-b border-slate-200 px-3.5">
          <div className="flex items-center gap-2">
            <Building2
              size={12}
              className="text-violet-500"
            />

            <div>
              <h2 className="text-[10.5px] font-bold text-slate-700">
                Operating Room Board
              </h2>
            </div>
          </div>

          <button
            type="button"
            onClick={() =>
              navigate("/schedule")
            }
            className="inline-flex items-center gap-1 text-[8px] font-semibold text-violet-600 transition hover:text-violet-700"
          >
            Open schedule
            <ArrowRight size={9} />
          </button>
        </div>

        <div data-responsive-grid="4" className="grid grid-cols-4 divide-x divide-slate-200">
          {roomBoard.map((room, index) => (
            <RoomBoardTile key={room.room} room={room} alignRight={index >= 2} onOpen={(id) => navigate(`/surgery/${id}`)} />
          ))}
          {roomBoard.length === 0 && <p className="col-span-4 py-6 text-center text-xs text-slate-400">No operating rooms assigned today</p>}
        </div>
      </section>

      {/* ============================================================ */}
      {/* MAIN DASHBOARD                                               */}
      {/* ============================================================ */}

      <div data-responsive-grid="2" className="grid min-h-0 flex-1 grid-cols-[minmax(0,1.9fr)_minmax(280px,0.72fr)] gap-2">
        {/* ---------------------------------------------------------- */}
        {/* TODAY'S OPERATING LIST                                     */}
        {/* ---------------------------------------------------------- */}

        <div className="flex min-h-0 min-w-0 flex-col gap-2">
          <section className="relative flex shrink-0 flex-col overflow-visible rounded-xl border border-slate-200 bg-white">
          <div className="relative z-[80] shrink-0 overflow-visible border-b border-slate-100 bg-white px-3 py-2.5">
            <div className="flex items-center justify-between gap-3">
              <div>
                <h2 className="text-[11px] font-semibold text-slate-700">
                  Today's Operation List
                </h2>
              </div>

              <div className="flex items-center gap-2">
                <div className="relative">
                  <Search
                    size={12}
                    className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400"
                  />

                  <input
                    value={searchQuery}
                    onChange={(event) => {
                      setSearchQuery(
                        event.target.value,
                      );
                      setPage(1);
                    }}
                    placeholder="Search patient, case or procedure..."
                    className="h-7 w-[clamp(130px,17vw,270px)] rounded-lg border border-slate-200 bg-slate-50 pl-8 pr-3 text-[10px] text-slate-600 outline-none transition placeholder:text-[10px] placeholder:text-slate-400 focus:border-violet-300 focus:bg-white"
                  />
                </div>

                <div className="relative z-[90]">
                  <button
                    type="button"
                    onClick={() =>
                      setFilterOpen(
                        (value) => !value,
                      )
                    }
                    className={`flex h-7 items-center gap-1.5 rounded-md border px-2.5 text-[10px] font-semibold transition ${
                      selectedDoctors.length > 0 ||
                      selectedStatuses.length > 0 ||
                      period !== "Month" ||
                      selectedDate !== TODAY
                        ? "border-violet-200 bg-violet-50 text-violet-600"
                        : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                    }`}
                  >
                    <Filter size={11} />
                    Filters
                    <ChevronDown size={10} />
                  </button>

                  {filterOpen && (
                    <div className="absolute right-0 top-[calc(100%+6px)] z-[120] w-[360px] overflow-visible rounded-xl border border-slate-200 bg-white p-3 shadow-[0_16px_40px_rgba(15,23,42,0.18)]">
                      <div className="mb-2.5 flex items-center justify-between">
                        <div>
                          <p className="text-[9px] font-semibold text-slate-700">
                            Operation List Filters
                          </p>

                          <p className="mt-0.5 text-[8px] text-slate-400">
                            Filter by doctor, status and date range
                          </p>
                        </div>

                        <button
                          type="button"
                          onClick={clearTableFilters}
                          className="text-[8px] font-semibold text-violet-600 hover:underline"
                        >
                          Clear all
                        </button>
                      </div>

                      <div>
                        <p className="mb-1.5 text-[8px] font-semibold uppercase tracking-wide text-slate-400">
                          Doctor
                        </p>

                        <div className="flex flex-wrap gap-1.5">
                          {doctorOptions.map(
                            (doctor) => {
                              const active =
                                selectedDoctors.includes(
                                  doctor,
                                );

                              return (
                                <button
                                  key={doctor}
                                  type="button"
                                  onClick={() =>
                                    toggleDoctorFilter(
                                      doctor,
                                    )
                                  }
                                  className={`rounded-md border px-2 py-1 !text-[10px] font-semibold transition ${
                                    active
                                      ? "border-violet-200 bg-violet-50 text-violet-700"
                                      : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                                  }`}
                                >
                                  {doctor}
                                </button>
                              );
                            },
                          )}
                        </div>
                      </div>

                      <div className="mt-2.5">
                        <p className="mb-1.5 text-[8px] font-semibold uppercase tracking-wide text-slate-400">
                          Status
                        </p>

                        <div className="flex flex-wrap gap-1.5">
                          {availableStatuses.map(
                            (status) => {
                              const active =
                                selectedStatuses.includes(
                                  status,
                                );

                              return (
                                <button
                                  key={status}
                                  type="button"
                                  onClick={() =>
                                    toggleStatusFilter(
                                      status,
                                    )
                                  }
                                  className={`rounded-md border px-2 py-1 !text-[10px] font-semibold transition ${
                                    active
                                      ? "border-violet-200 bg-violet-50 text-violet-700"
                                      : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                                  }`}
                                >
                                  {status ===
                                  "In Progress"
                                    ? "In Surgery"
                                    : status}
                                </button>
                              );
                            },
                          )}
                        </div>
                      </div>

                      <div className="mt-2.5">
                        <p className="mb-1.5 text-[8px] font-semibold uppercase tracking-wide text-slate-400">
                          Date
                        </p>

                        <div data-responsive-grid="2" className="grid grid-cols-[auto_minmax(0,1fr)] items-center gap-2">
                          <div className="flex h-8 items-center rounded-lg border border-slate-200 bg-slate-50 p-0.5">
                            {(
                              [
                                "Day",
                                "Week",
                                "Month",
                              ] as Period[]
                            ).map((item) => (
                              <button
                                key={item}
                                type="button"
                                onClick={() => {
                                  setPeriod(item);
                                  setPage(1);
                                }}
                                className={`h-7 rounded-[5px] px-2 !text-[10px] font-semibold transition ${
                                  period === item
                                    ? "bg-white text-violet-600 shadow-sm"
                                    : "text-slate-500"
                                }`}
                              >
                                {item}
                              </button>
                            ))}
                          </div>

                          <DashboardDatePicker
                            value={selectedDate}
                            onChange={(value) => {
                              setSelectedDate(value);
                              setPage(1);
                            }}
                          />
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          <div data-responsive-table-header="true" className="relative z-0 grid shrink-0 grid-cols-[52px_minmax(0,1.5fr)_minmax(0,1.2fr)_minmax(0,0.9fr)_minmax(0,1.05fr)_62px_92px] gap-x-3 items-center border-b border-slate-100 bg-slate-50/80 px-3.5 py-2.5">
            {(
              [
                ["time", "Time"],
                ["patient", "Patient"],
                ["procedure", "Procedure"],
                ["notes", "Notes"],
                ["surgeon", "Surgeon"],
                ["room", "Room"],
                ["status", "Status"],
              ] as Array<
                [SortKey, string]
              >
            ).map(([key, label]) => (
              <button
                key={key}
                type="button"
                onClick={() =>
                  handleSort(key)
                }
                className="group flex w-fit items-center gap-1 !text-[11px] font-semibold text-slate-500 transition hover:text-slate-800"
              >
                <span>{label}</span>

                {sortKey === key ? (
                  sortDirection ===
                  "asc" ? (
                    <ArrowUp
                      size={10}
                      className="text-violet-600"
                    />
                  ) : (
                    <ArrowDown
                      size={10}
                      className="text-violet-600"
                    />
                  )
                ) : (
                  <ArrowUpDown
                    size={9}
                    className="text-slate-300 transition group-hover:text-slate-400"
                  />
                )}
              </button>
            ))}
          </div>

          <div className="relative z-0 divide-y divide-slate-100/90">
            {visibleCases.length > 0 ? (
              visibleCases.map(
                (surgery) => {
                  const style =
                    STATUS_STYLES[
                      surgery.status
                    ] ??
                    STATUS_STYLES.Booked;

                  return (
                    <button data-responsive-table-row="true"
                      key={surgery.id}
                      type="button"
                      onClick={() =>
                        navigate(
                          `/surgery/${surgery.id}`,
                        )
                      }
                      className="group relative grid min-h-[64px] w-full grid-cols-[52px_minmax(0,1.5fr)_minmax(0,1.2fr)_minmax(0,0.9fr)_minmax(0,1.05fr)_62px_92px] gap-x-3 items-center px-3.5 py-2.5 text-left transition hover:bg-slate-50/80"
                    >
                      <span
                        className={`absolute bottom-2 left-0 top-2 w-[3px] rounded-r-full ${style.dot}`}
                      />

                      <div data-cell-label="Time">
                        <p className="text-[11px] font-bold text-slate-700">
                          {surgery.time}
                        </p>

                        <p className="mt-0.5 text-[9px] font-medium text-slate-400">
                          {surgery.priority}
                        </p>
                      </div>

                      <div data-cell-label="Patient" className="flex min-w-0 items-center gap-2">

                        <div className="min-w-0">
                          <p className="whitespace-normal break-words pr-2 text-[11px] font-semibold text-slate-700">
                            {surgery.patientName}
                          </p>

                          <p className="mt-0.5 truncate text-[9px] text-slate-400">
                            MRN: {surgery.mrn || "Not recorded"}
                          </p>
                        </div>
                      </div>

                      <ProcedureCell
                        surgery={surgery}
                      />

                      <p data-cell-label="Notes" className="line-clamp-2 break-words pr-2 text-[10.5px] leading-4 text-slate-500">
                        {surgery.notes || surgery.surgeonNotes || "No notes"}
                      </p>
                      <div data-cell-label="Surgeon" className="flex min-w-0 items-center gap-1.5">
                        <Stethoscope
                          size={9.5}
                          className="shrink-0 text-slate-400"
                        />

                        <span className="truncate text-[10.5px] font-medium text-slate-600">
                          {surgery.doctor}
                        </span>
                      </div>

                      <div data-cell-label="Room" className="flex items-center gap-1">
                        <Building2
                          size={9}
                          className="shrink-0 text-slate-400"
                        />

                        <span className="truncate text-[10px] font-medium text-slate-600">
                          {surgery.room}
                        </span>
                      </div>

                      <StatusBadge
                        status={surgery.status}
                      />
                    </button>
                  );
                },
              )
            ) : (
              <div className="flex min-h-[180px] items-center justify-center">
                <div className="text-center">
                  <CheckCircle2
                    size={18}
                    className="mx-auto text-slate-300"
                  />

                  <p className="mt-2 text-[10px] font-semibold text-slate-500">
                    {searchQuery ||
                    selectedDoctors.length > 0 ||
                    selectedStatuses.length > 0
                      ? "No matching cases"
                      : "No cases scheduled"}
                  </p>

                  {(searchQuery ||
                    selectedDoctors.length > 0 ||
                    selectedStatuses.length > 0) && (
                    <button
                      type="button"
                      onClick={() => {
                        setSearchQuery("");
                        clearTableFilters();
                      }}
                      className="mt-1.5 text-[9px] font-semibold text-violet-600 hover:text-violet-700"
                    >
                      Clear search & filters
                    </button>
                  )}
                </div>
              </div>
            )}
          </div>
        </section>

          {sortedCases.length > 0 && (
            <div className="flex h-10 shrink-0 items-center justify-between px-1">
              <p className="text-[10.5px] font-medium text-slate-400">
                Showing{" "}
                <span className="font-semibold text-slate-600">
                  {(safePage - 1) * PAGE_SIZE + 1}–{Math.min(
                    safePage * PAGE_SIZE,
                    sortedCases.length,
                  )}
                </span>{" "}
                of{" "}
                <span className="font-semibold text-slate-600">
                  {sortedCases.length}
                </span>
              </p>

              <Pagination
                page={safePage}
                totalPages={totalPages}
                onChange={setPage}
              />
            </div>
          )}
        </div>

        {/* ---------------------------------------------------------- */}
        {/* RIGHT SIDE                                                 */}
        {/* ---------------------------------------------------------- */}

        <div className="grid min-h-0 grid-rows-[minmax(0,1fr)_auto] gap-2">
          {/* POST-OP STATUS */}

          <section className="overflow-hidden rounded-xl border border-slate-200 bg-white">
            <div className="flex h-[34px] items-center justify-between border-b border-slate-100 px-3">
              <div className="flex items-center gap-2">
                <Stethoscope
                  size={11}
                  className="text-cyan-500"
                />

                <h2 className="text-[10.5px] font-bold text-slate-700">
                  Post-Op Status
                </h2>
              </div>

            </div>

            <div data-responsive-grid="3" className="grid grid-cols-3 divide-x divide-slate-100">
              <PostOpStat
                label="Reports"
                value={`${operativeReportRate}%`}
                hint="Completed"
                icon={<FileText size={11} />}
                tone="cyan"
                onClick={() =>
                  navigate("/post-op")
                }
              />

              <PostOpStat
                label="Instructions"
                value={`${dischargeInstructionsRate}%`}
                hint="Prepared"
                icon={<ShieldCheck size={11} />}
                tone="teal"
                onClick={() =>
                  navigate("/post-op")
                }
              />

              <PostOpStat
                label="Discharged"
                value={`${dischargedRate}%`}
                hint="Completed"
                icon={<CheckCircle2 size={11} />}
                tone="slate"
                onClick={() =>
                  navigate("/post-op")
                }
              />
            </div>

            <button
              type="button"
              onClick={() =>
                navigate("/post-op")
              }
              className="flex h-7 w-full items-center justify-between border-t border-slate-100 bg-slate-50/50 px-3 text-left transition hover:bg-cyan-50/40"
            >
              <div className="flex items-center gap-2">
                <span
                  className={`h-1.5 w-1.5 rounded-full ${
                    postOpAttentionCount > 0
                      ? "bg-amber-500"
                      : "bg-teal-500"
                  }`}
                />

                <span className="text-[8.5px] font-semibold text-slate-600">
                  {postOpAttentionCount > 0
                    ? `${postOpAttentionCount} case${
                        postOpAttentionCount === 1
                          ? ""
                          : "s"
                      } still need follow-up`
                    : "All Post-Op cases complete"}
                </span>
              </div>

              <ChevronRight
                size={9}
                className="text-slate-300"
              />
            </button>
          </section>

          {/* TODAY'S READINESS */}

          <section className="overflow-hidden rounded-xl border border-slate-200 bg-white">
            <div className="flex h-[38px] items-center justify-between border-b border-slate-100 px-3">
              <div className="flex items-center gap-2">
                <ShieldCheck
                  size={11}
                  className="text-blue-500"
                />

                <h2 className="text-[10px] font-bold text-slate-700">
                  Today's Readiness
                </h2>
              </div>

              <span className="text-[7.5px] font-medium text-slate-400">
                Required before OR
              </span>
            </div>

            <div className="space-y-2.5 px-3 py-2.5">
              <ReadinessRow
                label="Financial clearance"
                value={financialRate}
                icon={<CreditCard size={10} />}
                tone="indigo"
                onClick={() =>
                  navigate("/accounting")
                }
              />

              <ReadinessRow
                label="Pre-Op completed"
                value={preOpRate}
                icon={<UserCheck size={10} />}
                tone="blue"
                onClick={() =>
                  navigate("/pre-op")
                }
              />

              <ReadinessRow
                label="Anesthesia confirmed"
                value={anesthesiaRate}
                icon={<HeartPulse size={10} />}
                tone="violet"
                onClick={() =>
                  navigate("/pre-op")
                }
              />
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}

