import { useNavigate } from "react-router-dom";
import { useSurgeryStore } from "../store/surgeryStore";
import { useState, useRef, useEffect, useMemo } from "react";
import { type Period, type SortKey, type SortDirection } from "../features/workspaces/Patients/types";
import { patients } from "../data/patients";
import { isPatientDateInPeriod } from "../features/workspaces/Patients/utils";
import { PAGE_SIZE, statusOptions } from "../features/workspaces/Patients/config";
import { PatientStat, PatientFilterPill, ModernPatientDatePicker, PatientSortableHeader, PatientStatus } from "../features/workspaces/Patients/components";
import { Users, Activity, HeartPulse, UserRoundCheck, Search, Filter, ChevronDown, ChevronRight, ChevronLeft } from "lucide-react";


export default function Patients() {
  const navigate = useNavigate();
  const surgeries = useSurgeryStore((state) => state.surgeries);

  const [search, setSearch] = useState("");
  const [filterOpen, setFilterOpen] = useState(false);

  const [selectedDoctors, setSelectedDoctors] =
    useState<string[]>([]);

  const [selectedStatuses, setSelectedStatuses] =
    useState<string[]>([]);

  const [period, setPeriod] =
    useState<Period>("Day");

  const [selectedDate, setSelectedDate] =
    useState("");

  const [sortKey, setSortKey] =
    useState<SortKey>("date");

  const [sortDirection, setSortDirection] =
    useState<SortDirection>("asc");

  const [page, setPage] = useState(1);

  const filterRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleOutsideClick(event: MouseEvent) {
      if (
        filterRef.current &&
        !filterRef.current.contains(event.target as Node)
      ) {
        setFilterOpen(false);
      }
    }

    document.addEventListener("mousedown", handleOutsideClick);
    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, []);

  const enrichedPatients = useMemo(() => {
    return patients.map((patient) => {
      const surgery = surgeries.find(
        (item) =>
          item.id === patient.id ||
          item.patientId === patient.id,
      ) as
        | ((typeof surgeries)[number] & {
            mrn?: string;
            age?: number;
            gender?: string;
            phone?: string;
            patientPhone?: string;
            phoneNumber?: string;
            patientPhoneNumber?: string;
            mobile?: string;
            patientMobile?: string;
          })
        | undefined;

      const rawPatient = patient as typeof patient & {
        mrn?: string;
        age?: number;
        gender?: string;
        phone?: string;
        patientPhone?: string;
        phoneNumber?: string;
        patientPhoneNumber?: string;
        mobile?: string;
        patientMobile?: string;
      };

      return {
        ...patient,
        mrn: surgery?.mrn ?? rawPatient.mrn ?? "—",
        age: surgery?.age ?? rawPatient.age,
        gender: surgery?.gender ?? rawPatient.gender ?? "—",
        phone:
          surgery?.phone ??
          surgery?.patientPhone ??
          surgery?.phoneNumber ??
          surgery?.patientPhoneNumber ??
          surgery?.mobile ??
          surgery?.patientMobile ??
          rawPatient.phone ??
          rawPatient.patientPhone ??
          rawPatient.phoneNumber ??
          rawPatient.patientPhoneNumber ??
          rawPatient.mobile ??
          rawPatient.patientMobile ??
          "—",
      };
    });
  }, [surgeries]);

  const doctors = useMemo(
    () =>
      Array.from(
        new Set(
          enrichedPatients.map(
            (patient) =>
              patient.surgeon,
          ),
        ),
      ).filter(Boolean),
    [enrichedPatients],
  );

  const filteredPatients = useMemo(() => {
    const query = search
      .toLowerCase()
      .trim();

    return enrichedPatients.filter(
      (patient) => {
        const matchesSearch =
          !query ||
          patient.name
            .toLowerCase()
            .includes(query) ||
          patient.id
            .toLowerCase()
            .includes(query) ||
          patient.mrn
            .toLowerCase()
            .includes(query) ||
          patient.phone
            .toLowerCase()
            .includes(query) ||
          patient.procedure
            .toLowerCase()
            .includes(query) ||
          patient.surgeon
            .toLowerCase()
            .includes(query);

        const matchesDoctor =
          selectedDoctors.length === 0 ||
          selectedDoctors.includes(
            patient.surgeon,
          );

        const matchesStatus =
          selectedStatuses.length === 0 ||
          selectedStatuses.includes(
            patient.status,
          );

        const matchesDate =
          !selectedDate ||
          isPatientDateInPeriod(
            patient.surgeryDate,
            selectedDate,
            period,
          );

        return (
          matchesSearch &&
          matchesDoctor &&
          matchesStatus &&
          matchesDate
        );
      },
    );
  }, [
    enrichedPatients,
    search,
    selectedDoctors,
    selectedStatuses,
    selectedDate,
    period,
  ]);

  const sortedPatients = useMemo(() => {
    const copy = [
      ...filteredPatients,
    ];

    copy.sort((a, b) => {
      const getValue = (
        patient: (typeof copy)[number],
      ) => {
        switch (sortKey) {
          case "patient":
            return patient.name;

          case "case":
            return patient.id;

          case "mrn":
            return patient.mrn;

          case "phone":
            return patient.phone;

          case "procedure":
            return patient.procedure;

          case "doctor":
            return patient.surgeon;

          case "date":
            return patient.surgeryDate;

          case "status":
            return patient.status;

          default:
            return "";
        }
      };

      const result = String(
        getValue(a),
      ).localeCompare(
        String(getValue(b)),
        undefined,
        {
          numeric: true,
          sensitivity: "base",
        },
      );

      return sortDirection === "asc"
        ? result
        : -result;
    });

    return copy;
  }, [
    filteredPatients,
    sortKey,
    sortDirection,
  ]);

  useEffect(() => {
    setPage(1);
  }, [
    search,
    selectedDoctors,
    selectedStatuses,
    selectedDate,
    period,
  ]);

  const totalPatients = enrichedPatients.length;

  const activePatients = enrichedPatients.filter(
    (patient) =>
      patient.status === "In Surgery" ||
      patient.status === "Confirmed" ||
      patient.status === "Pre-Op",
  ).length;

  const waitingPatients = enrichedPatients.filter(
    (patient) =>
      patient.status === "Today",
  ).length;

  const dischargedPatients = enrichedPatients.filter(
    (patient) =>
      patient.status === "Discharged",
  ).length;

  const totalPages = Math.max(
    1,
    Math.ceil(
      sortedPatients.length /
        PAGE_SIZE,
    ),
  );

  useEffect(() => {
    if (page > totalPages) {
      setPage(totalPages);
    }
  }, [page, totalPages]);

  const visiblePatients = useMemo(() => {
    const start =
      (page - 1) * PAGE_SIZE;

    return sortedPatients.slice(
      start,
      start + PAGE_SIZE,
    );
  }, [sortedPatients, page]);

  const firstVisible =
    sortedPatients.length === 0
      ? 0
      : (page - 1) * PAGE_SIZE + 1;

  const lastVisible = Math.min(
    page * PAGE_SIZE,
    sortedPatients.length,
  );

  function handleSort(
    key: SortKey,
  ) {
    if (sortKey === key) {
      setSortDirection(
        (current) =>
          current === "asc"
            ? "desc"
            : "asc",
      );

      return;
    }

    setSortKey(key);
    setSortDirection("asc");
  }

  function toggleDoctor(
    doctor: string,
  ) {
    setSelectedDoctors(
      (current) =>
        current.includes(doctor)
          ? current.filter(
              (item) =>
                item !== doctor,
            )
          : [
              ...current,
              doctor,
            ],
    );
  }

  function toggleStatus(
    status: string,
  ) {
    setSelectedStatuses(
      (current) =>
        current.includes(status)
          ? current.filter(
              (item) =>
                item !== status,
            )
          : [
              ...current,
              status,
            ],
    );
  }

  function clearFilters() {
    setSelectedDoctors([]);
    setSelectedStatuses([]);
    setPeriod("Day");
    setSelectedDate("");
  }

  return (
    <div className="h-[calc(100vh-72px)] min-h-0 overflow-hidden bg-slate-50 p-2">
      <div className="flex h-full min-h-0 flex-col gap-2">
        <div data-responsive-grid="4" className="grid grid-cols-4 gap-2">
          <PatientStat
            label="Total Patients"
            value={totalPatients}
            icon={<Users size={15} />}
          />

          <PatientStat
            label="Active Cases"
            value={activePatients}
            icon={<Activity size={15} />}
          />

          <PatientStat
            label="Waiting"
            value={waitingPatients}
            icon={<HeartPulse size={15} />}
          />

          <PatientStat
            label="Discharged"
            value={dischargedPatients}
            icon={<UserRoundCheck size={15} />}
          />
        </div>

        <section className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-xl border border-fuchsia-100 bg-white shadow-[0_1px_2px_rgba(16,24,40,0.03)]">
          <div className="flex min-h-[58px] shrink-0 items-center justify-between gap-4 border-b border-slate-100 px-4 py-2.5">
            <div className="flex items-center gap-2">

              <div>
                <h2 className="text-[12px] font-semibold text-slate-800">
                  Patient Directory
                </h2>

                <p className="mt-0.5 text-[9px] text-slate-400">
                  Browse and manage registered patients
                </p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <div className="relative w-[270px]">
                <Search
                  size={13}
                  className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400"
                />

                <input
                  value={search}
                  onChange={(event) =>
                    setSearch(event.target.value)
                  }
                  placeholder="Search patient, case, MRN, phone or procedure..."
                  className="h-7 w-full rounded-lg border border-slate-200 bg-slate-50 pl-8 pr-3 !text-[11px] text-slate-700 outline-none transition placeholder:text-slate-400 focus:border-fuchsia-300 focus:bg-white focus:ring-2 focus:ring-fuchsia-50"
                />
              </div>

              <div
                ref={filterRef}
                className="relative"
              >
                <button
                  type="button"
                  onClick={() =>
                    setFilterOpen(
                      (current) =>
                        !current,
                    )
                  }
                  className={`inline-flex h-7 items-center gap-1.5 rounded-lg border px-2.5 !text-[11px] font-semibold transition ${
                    filterOpen ||
                    selectedDoctors.length >
                      0 ||
                    selectedStatuses.length >
                      0 ||
                    Boolean(
                      selectedDate,
                    ) ||
                    period !== "Day"
                      ? "border-fuchsia-200 bg-fuchsia-50 text-fuchsia-700"
                      : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                  }`}
                >
                  <Filter size={11} />
                  Filters

                  {(selectedDoctors.length +
                    selectedStatuses.length +
                    (selectedDate
                      ? 1
                      : 0) +
                    (period !== "Day"
                      ? 1
                      : 0)) >
                    0 && (
                    <span className="flex h-4 min-w-4 items-center justify-center rounded-full bg-fuchsia-600 px-1 text-[7px] font-bold text-white">
                      {selectedDoctors.length +
                        selectedStatuses.length +
                        (selectedDate
                          ? 1
                          : 0) +
                        (period !== "Day"
                          ? 1
                          : 0)}
                    </span>
                  )}

                  <ChevronDown
                    size={10}
                  />
                </button>

                {filterOpen && (
                  <div className="absolute right-0 top-[calc(100%+6px)] z-40 w-[360px] rounded-xl border border-slate-200 bg-white p-3 shadow-[0_12px_32px_rgba(15,23,42,0.14)]">
                    <div className="mb-3 flex items-center justify-between">
                      <div>
                        <p className="!text-[11px] font-semibold text-slate-700">
                          Table Filters
                        </p>

                        <p className="mt-0.5 text-[9px] text-slate-500">
                          Refine the patient directory
                        </p>
                      </div>

                      <button
                        type="button"
                        onClick={
                          clearFilters
                        }
                        className="text-[9px] font-semibold text-fuchsia-600 hover:text-fuchsia-700"
                      >
                        Clear all
                      </button>
                    </div>

                    <div className="mb-3">
                      <p className="mb-1.5 text-[9px] font-semibold uppercase tracking-wide text-slate-400">
                        Doctor
                      </p>

                      <div className="flex flex-wrap gap-1.5">
                        {doctors.map(
                          (doctor) => (
                            <PatientFilterPill
                              key={
                                doctor
                              }
                              label={
                                doctor
                              }
                              active={selectedDoctors.includes(
                                doctor,
                              )}
                              onClick={() =>
                                toggleDoctor(
                                  doctor,
                                )
                              }
                            />
                          ),
                        )}
                      </div>
                    </div>

                    <div className="mb-3">
                      <p className="mb-1.5 text-[9px] font-semibold uppercase tracking-wide text-slate-400">
                        Status
                      </p>

                      <div className="flex flex-wrap gap-1.5">
                        {statusOptions
                          .filter(
                            (item) =>
                              item !== "All",
                          )
                          .map(
                            (statusItem) => (
                              <PatientFilterPill
                                key={
                                  statusItem
                                }
                                label={
                                  statusItem
                                }
                                active={selectedStatuses.includes(
                                  statusItem,
                                )}
                                onClick={() =>
                                  toggleStatus(
                                    statusItem,
                                  )
                                }
                              />
                            ),
                          )}
                      </div>
                    </div>

                    <div>
                      <p className="mb-1.5 text-[9px] font-semibold uppercase tracking-wide text-slate-400">
                        Surgery Date
                      </p>

                      <div data-responsive-grid="2" className="grid grid-cols-[1fr_138px] gap-2">
                        <div className="flex h-7 items-center rounded-lg border border-slate-200 bg-slate-50 p-0.5">
                          {(
                            [
                              "Day",
                              "Week",
                              "Month",
                            ] as Period[]
                          ).map(
                            (item) => (
                              <button
                                key={
                                  item
                                }
                                type="button"
                                onClick={() =>
                                  setPeriod(
                                    item,
                                  )
                                }
                                className={`h-6 flex-1 rounded-md !text-[11px] font-semibold transition ${
                                  period ===
                                  item
                                    ? "bg-white text-fuchsia-600 shadow-sm"
                                    : "text-slate-400 hover:text-slate-600"
                                }`}
                              >
                                {item}
                              </button>
                            ),
                          )}
                        </div>

                        <ModernPatientDatePicker
                          value={selectedDate}
                          onChange={(value) => {
                            setSelectedDate(value);
                            setPage(1);
                          }}
                        />
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div data-responsive-table-header="true" className="grid shrink-0 grid-cols-[minmax(165px,1.25fr)_82px_95px_112px_minmax(150px,1.05fr)_130px_96px_76px_24px] items-center border-b border-slate-100 bg-slate-50/80 px-3 py-2.5">
            <PatientSortableHeader
              label="Patient"
              sortKey="patient"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <PatientSortableHeader
              label="Case #"
              sortKey="case"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <PatientSortableHeader
              label="MRN"
              sortKey="mrn"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <PatientSortableHeader
              label="Phone"
              sortKey="phone"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <PatientSortableHeader
              label="Procedure"
              sortKey="procedure"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <PatientSortableHeader
              label="Doctor"
              sortKey="doctor"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <PatientSortableHeader
              label="Date"
              sortKey="date"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <PatientSortableHeader
              label="Status"
              sortKey="status"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />

            <span />
          </div>

          <div className="min-h-0 flex-1 overflow-hidden">
            {visiblePatients.map((patient) => (
              <button data-responsive-table-row="true"
                key={patient.id}
                type="button"
                onClick={() => navigate(`/patients/${patient.id}`)}
                className="group relative grid min-h-[48px] w-full grid-cols-[minmax(165px,1.25fr)_82px_95px_112px_minmax(150px,1.05fr)_130px_96px_76px_24px] items-center border-b border-slate-100 bg-white px-3 py-1.5 text-left transition hover:bg-fuchsia-50/45"
              >
                <span  className="absolute bottom-1.5 left-0 top-1.5 w-[3px] rounded-r-full bg-fuchsia-500" />

                <div data-cell-label="Patient"  className="flex min-w-0 items-center gap-2.5">
                  <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-fuchsia-50 text-[10px] font-semibold text-fuchsia-700 ring-1 ring-fuchsia-100">
                    {patient.initials}
                  </div>

                  <div className="min-w-0">
                    <div className="truncate text-[11px] font-semibold text-slate-700">
                      {patient.name}
                    </div>

                    <div className="mt-0.5 flex items-center gap-1 text-[9px] text-slate-400">
                      <span>
                        {patient.age != null ? `${patient.age} yrs` : "—"}
                      </span>
                      <span className="text-slate-300">•</span>
                      <span>{patient.gender}</span>
                    </div>
                  </div>
                </div>

                <div data-cell-label="Case #"  className="truncate text-[10px] font-semibold text-fuchsia-600">
                  {patient.id}
                </div>

                <div data-cell-label="MRN"  className="truncate text-[10px] font-medium text-slate-500">
                  {patient.mrn}
                </div>

                <div data-cell-label="Phone"  className="truncate pr-2 text-[10px] font-medium text-slate-500">
                  {patient.phone}
                </div>

                <div data-cell-label="Procedure"  className="min-w-0 pr-2">
                  <div className="truncate text-[10px] font-medium text-slate-600">
                    {patient.procedure}
                  </div>
                </div>

                <div data-cell-label="Doctor"  className="truncate pr-2 text-[10px] text-slate-600">
                  {patient.surgeon}
                </div>

                <div data-cell-label="Date"  className="truncate text-[10px] text-slate-500">
                  {patient.surgeryDate}
                </div>

                <div data-cell-label="Status">
                  <PatientStatus status={patient.status} />
                </div>

                <ChevronRight
                  size={13}
                  className="text-slate-300 transition group-hover:translate-x-0.5 group-hover:text-fuchsia-500"
                />
              </button>
            ))}

            {visiblePatients.length === 0 && (
              <div className="flex h-full min-h-[160px] items-center justify-center">
                <div className="text-center">
                  <div className="text-[10px] font-semibold text-slate-600">
                    No patients found
                  </div>
                  <div className="mt-1 text-[8.5px] text-slate-400">
                    Try changing your search or filters.
                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="flex min-h-[48px] items-center justify-between border-t border-slate-100 bg-slate-50/30 px-3">
            <div className="flex items-center gap-2 text-[9px] text-slate-400">
              <span>
                Showing{" "}
                <span className="font-semibold text-slate-500">
                  {firstVisible}–{lastVisible}
                </span>{" "}
                of{" "}
                <span className="font-semibold text-slate-500">
                  {sortedPatients.length}
                </span>
              </span>
              <span className="text-slate-300">•</span>
              <span>{PAGE_SIZE} rows/page</span>
            </div>

            <div className="flex items-center gap-1.5">
              <button
                type="button"
                onClick={() =>
                  setPage((current) => Math.max(1, current - 1))
                }
                disabled={page === 1}
                className="flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40"
              >
                <ChevronLeft size={13} />
              </button>

              {Array.from(
                { length: totalPages },
                (_, index) => index + 1,
              ).map((pageNumber) => (
                <button
                  key={pageNumber}
                  type="button"
                  onClick={() => setPage(pageNumber)}
                  className={`flex h-8 min-w-8 items-center justify-center rounded-lg border px-2 text-[9px] font-semibold transition ${
                    page === pageNumber
                      ? "border-fuchsia-500 bg-fuchsia-500 text-white shadow-sm shadow-fuchsia-200"
                      : "border-slate-200 bg-white text-slate-600 hover:border-fuchsia-200 hover:text-fuchsia-600"
                  }`}
                >
                  {pageNumber}
                </button>
              ))}

              <button
                type="button"
                onClick={() =>
                  setPage((current) =>
                    Math.min(totalPages, current + 1),
                  )
                }
                disabled={page === totalPages}
                className="flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40"
              >
                <ChevronRight size={13} />
              </button>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}

import { useSurgeryStore } from "../store/surgeryStore";
import { useState, useRef, useEffect, useMemo } from "react";
import { localToday, toDateLabel, changeDay, monthTitle, calendarDays, formatDateValue, STATUS_COLUMNS } from "../features/workspaces/Planning2/config";
import { type PendingMove } from "../features/workspaces/Planning2/types";
import { type Surgery } from "../types/surgery";
import { orderedCases, isFinished, conflictsFor } from "../utils/planning";
import { isBoardStatus, getToneClasses } from "../features/workspaces/Planning2/utils";
import { SummaryCard, StatusCell, MoveConfirmation, PlanEditor } from "../features/workspaces/Planning2/components";
import { CalendarDays, Clock3, Route, AlertTriangle, ChevronLeft, ChevronRight, ChevronDown, Search, Filter, Building2, Minimize2, Maximize2 } from "lucide-react";


export default function Planning2() {
  const surgeries =
    useSurgeryStore(
      (state) =>
        state.surgeries,
    );

  const updateSurgery =
    useSurgeryStore(
      (state) =>
        state.updateSurgery,
    );

  const [date, setDate] =
    useState(localToday);

  const [calendarOpen, setCalendarOpen] =
    useState(false);

  const [calendarMonth, setCalendarMonth] =
    useState(() => {
      const value = new Date(`${localToday()}T00:00:00`);
      return new Date(value.getFullYear(), value.getMonth(), 1);
    });

  const [search, setSearch] =
    useState("");

  const [
    draggedSurgeryId,
    setDraggedSurgeryId,
  ] = useState<string | null>(
    null,
  );

  const [
    dragOverCell,
    setDragOverCell,
  ] = useState<string | null>(
    null,
  );

  const [
    pendingMove,
    setPendingMove,
  ] = useState<PendingMove>(
    null,
  );

  const [doctor, setDoctor] =
    useState("");

  const [
    doctorFilterOpen,
    setDoctorFilterOpen,
  ] = useState(false);

  const [editing, setEditing] =
    useState<Surgery | null>(
      null,
    );

  const [notice, setNotice] =
    useState("");

  const [
    boardExpanded,
    setBoardExpanded,
  ] = useState(false);

  const doctorFilterRef =
    useRef<HTMLDivElement | null>(
      null,
    );

  const calendarRef =
    useRef<HTMLDivElement | null>(
      null,
    );

  useEffect(() => {
    if (!notice) {
      return;
    }

    const timer =
      window.setTimeout(
        () => {
          setNotice("");
        },
        2800,
      );

    return () =>
      window.clearTimeout(
        timer,
      );
  }, [notice]);

  useEffect(() => {
    if (!doctorFilterOpen) {
      return;
    }

    const handleMouseDown = (
      event: MouseEvent,
    ) => {
      const target =
        event.target as
          | Node
          | null;

      if (
        target &&
        doctorFilterRef.current &&
        !doctorFilterRef.current.contains(
          target,
        )
      ) {
        setDoctorFilterOpen(
          false,
        );
      }
    };

    document.addEventListener(
      "mousedown",
      handleMouseDown,
    );

    return () =>
      document.removeEventListener(
        "mousedown",
        handleMouseDown,
      );
  }, [doctorFilterOpen]);

  useEffect(() => {
    if (!calendarOpen) {
      return;
    }

    const handleMouseDown = (event: MouseEvent) => {
      const target = event.target as Node | null;

      if (
        target &&
        calendarRef.current &&
        !calendarRef.current.contains(target)
      ) {
        setCalendarOpen(false);
      }
    };

    document.addEventListener("mousedown", handleMouseDown);

    return () =>
      document.removeEventListener("mousedown", handleMouseDown);
  }, [calendarOpen]);

  useEffect(() => {
    const selected = new Date(`${date}T00:00:00`);

    if (!Number.isNaN(selected.getTime())) {
      setCalendarMonth(
        new Date(selected.getFullYear(), selected.getMonth(), 1),
      );
    }
  }, [date]);

  useEffect(() => {
    if (!boardExpanded) {
      return;
    }

    const previousOverflow =
      document.body.style.overflow;

    document.body.style.overflow =
      "hidden";

    const handleKeyDown = (
      event: KeyboardEvent,
    ) => {
      if (event.key === "Escape") {
        setBoardExpanded(false);
      }
    };

    window.addEventListener(
      "keydown",
      handleKeyDown,
    );

    return () => {
      document.body.style.overflow =
        previousOverflow;

      window.removeEventListener(
        "keydown",
        handleKeyDown,
      );
    };
  }, [boardExpanded]);

  const rooms = useMemo(
    () =>
      [
        ...new Set(
          surgeries
            .map(
              (surgery) =>
                surgery.room,
            )
            .filter(Boolean),
        ),
      ].sort(),
    [surgeries],
  );

  const doctors =
    useMemo(
      () =>
        [
          ...new Set(
            surgeries.map(
              (surgery) =>
                surgery.doctor,
            ),
          ),
        ].sort(),
      [surgeries],
    );

  const scopedCases =
    useMemo(() => {
      const query =
        search
          .trim()
          .toLowerCase();

      return orderedCases(
        surgeries.filter(
          (surgery) => {
            const matchesDate =
              surgery.date === date;

            const matchesBoardStatus =
              isBoardStatus(
                surgery.status,
              );

            const matchesDoctor =
              !doctor ||
              surgery.doctor ===
                doctor;

            const matchesSearch =
              !query ||
              [
                surgery.patientName,
                surgery.mrn,
                surgery.procedure,
                surgery.doctor,
                surgery.room,
                surgery.id,
              ].some((value) =>
                String(
                  value || "",
                )
                  .toLowerCase()
                  .includes(query),
              );

            return (
              matchesDate &&
              matchesBoardStatus &&
              matchesDoctor &&
              matchesSearch
            );
          },
        ),
      );
    }, [
      surgeries,
      date,
      doctor,
      search,
    ]);

  const roomRows = useMemo(
    () =>
      rooms.filter(
        (room) =>
          scopedCases.some(
            (surgery) =>
              surgery.room ===
              room,
          ) ||
          !search,
      ),
    [
      rooms,
      scopedCases,
      search,
    ],
  );

  const scheduledCases =
    scopedCases.filter(
      (surgery) =>
        !isFinished(surgery),
    ).length;

  const upcomingReady =
    scopedCases.filter(
      (surgery) =>
        surgery.status ===
          "Pre-Op" ||
        surgery.status ===
          "Ready",
    ).length;

  const inProgress =
    scopedCases.filter(
      (surgery) =>
        surgery.status ===
        "In Progress",
    ).length;

  const conflictCases =
    scopedCases.filter(
      (surgery) =>
        conflictsFor(
          surgery,
          scopedCases,
        ).length > 0,
    );

  const rangeLabel =
    toDateLabel(date);

  const draggedSurgery =
    draggedSurgeryId
      ? surgeries.find(
          (surgery) =>
            surgery.id ===
            draggedSurgeryId,
        ) ?? null
      : null;

  return (
    <div className="flex h-[calc(100vh-58px)] min-h-0 flex-col gap-2.5 overflow-hidden bg-slate-50/65 p-2.5">
      {/* SUMMARY CARDS */}
      <section data-responsive-grid="4" className="grid shrink-0 grid-cols-4 gap-2">
        <SummaryCard
          label="Scheduled Cases"
          value={scheduledCases}
          helper="selected day"
          tone="blue"
          icon={
            <CalendarDays
              size={15}
            />
          }
        />

        <SummaryCard
          label="Upcoming / Ready"
          value={upcomingReady}
          helper="waiting to start"
          tone="violet"
          icon={
            <Clock3
              size={15}
            />
          }
        />

        <SummaryCard
          label="In Progress"
          value={inProgress}
          helper="currently active"
          tone="amber"
          icon={
            <Route
              size={15}
            />
          }
        />

        <SummaryCard
          label="Conflicts"
          value={
            conflictCases.length
          }
          helper="needs attention"
          tone="red"
          icon={
            <AlertTriangle
              size={15}
            />
          }
        />
      </section>

      {/* PAGE CONTROLS */}
      <header className="shrink-0 rounded-xl border border-slate-200 bg-white shadow-[0_1px_3px_rgba(15,23,42,0.035)]">
        <div className="flex items-center justify-between gap-3 border-b border-slate-100 px-3 py-2">
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() =>
                setDate(
                  localToday(),
                )
              }
              className="h-8 rounded-lg border border-slate-200 bg-white px-3 text-[9px] font-semibold text-slate-600 transition hover:bg-slate-50"
            >
              Today
            </button>

            <button
              type="button"
              onClick={() =>
                setDate(
                  changeDay(
                    date,
                    -1,
                  ),
                )
              }
              className="flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400 transition hover:bg-slate-50 hover:text-slate-700"
              aria-label="Previous day"
              title="Previous day"
            >
              <ChevronLeft
                size={13}
              />
            </button>

            <button
              type="button"
              onClick={() =>
                setDate(
                  changeDay(
                    date,
                    1,
                  ),
                )
              }
              className="flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400 transition hover:bg-slate-50 hover:text-slate-700"
              aria-label="Next day"
              title="Next day"
            >
              <ChevronRight
                size={13}
              />
            </button>

            <div ref={calendarRef} className="relative">
              <button
                type="button"
                onClick={() => setCalendarOpen((current) => !current)}
                className={`group flex h-8 items-center gap-2 rounded-lg border bg-white px-2.5 transition ${
                  calendarOpen
                    ? "border-violet-200 bg-violet-50/40 ring-2 ring-violet-100"
                    : "border-slate-200 hover:border-violet-200 hover:bg-violet-50/20"
                }`}
              >
                <CalendarDays
                  size={12}
                  className="shrink-0 text-violet-500"
                />

                <span className="min-w-[126px] text-left text-[9px] font-semibold text-slate-700">
                  {rangeLabel}
                </span>

                <ChevronDown
                  size={10}
                  className={`shrink-0 text-slate-300 transition ${
                    calendarOpen ? "rotate-180 text-violet-500" : "group-hover:text-violet-400"
                  }`}
                />
              </button>

              {calendarOpen && (
                <div className="absolute left-0 top-[calc(100%+7px)] z-[180] w-[292px] overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_20px_55px_rgba(15,23,42,0.18)]">
                  <div className="flex items-center justify-between border-b border-slate-100 bg-slate-50/65 px-3 py-2.5">
                    <div>
                      <p className="text-[10px] font-bold text-slate-800">
                        {monthTitle(calendarMonth)}
                      </p>
                      <p className="mt-0.5 text-[7.5px] text-slate-400">
                        Choose a day for the planning board
                      </p>
                    </div>

                    <div className="flex items-center gap-1">
                      <button
                        type="button"
                        onClick={() =>
                          setCalendarMonth(
                            (current) =>
                              new Date(
                                current.getFullYear(),
                                current.getMonth() - 1,
                                1,
                              ),
                          )
                        }
                        className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400 transition hover:border-violet-200 hover:bg-violet-50 hover:text-violet-700"
                        aria-label="Previous month"
                      >
                        <ChevronLeft size={12} />
                      </button>

                      <button
                        type="button"
                        onClick={() =>
                          setCalendarMonth(
                            (current) =>
                              new Date(
                                current.getFullYear(),
                                current.getMonth() + 1,
                                1,
                              ),
                          )
                        }
                        className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400 transition hover:border-violet-200 hover:bg-violet-50 hover:text-violet-700"
                        aria-label="Next month"
                      >
                        <ChevronRight size={12} />
                      </button>
                    </div>
                  </div>

                  <div className="p-3">
                    <div className="grid grid-cols-7 gap-1">
                      {["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map(
                        (day) => (
                          <div
                            key={day}
                            className="flex h-6 items-center justify-center text-[6.5px] font-bold uppercase tracking-wide text-slate-400"
                          >
                            {day}
                          </div>
                        ),
                      )}

                      {calendarDays(calendarMonth).map((dayValue) => {
                        const value = formatDateValue(dayValue);
                        const selected = value === date;
                        const today = value === localToday();
                        const inMonth =
                          dayValue.getMonth() === calendarMonth.getMonth();

                        const hasCases = surgeries.some(
                          (surgery) => surgery.date === value,
                        );

                        return (
                          <button
                            key={value}
                            type="button"
                            onClick={() => {
                              setDate(value);
                              setCalendarOpen(false);
                            }}
                            className={`relative flex h-8 items-center justify-center rounded-lg text-[8px] font-semibold transition ${
                              selected
                                ? "bg-violet-600 text-white shadow-sm"
                                : today
                                  ? "bg-violet-50 text-violet-700 ring-1 ring-violet-200"
                                  : inMonth
                                    ? "text-slate-600 hover:bg-violet-50 hover:text-violet-700"
                                    : "text-slate-300 hover:bg-slate-50"
                            }`}
                          >
                            {dayValue.getDate()}

                            {hasCases && !selected && (
                              <span className="absolute bottom-1 h-1 w-1 rounded-full bg-violet-400" />
                            )}
                          </button>
                        );
                      })}
                    </div>

                    <div className="mt-3 flex items-center justify-between border-t border-slate-100 pt-2.5">
                      <button
                        type="button"
                        onClick={() => {
                          const today = localToday();
                          setDate(today);
                          const parsed = new Date(`${today}T00:00:00`);
                          setCalendarMonth(
                            new Date(parsed.getFullYear(), parsed.getMonth(), 1),
                          );
                          setCalendarOpen(false);
                        }}
                        className="h-7 rounded-lg bg-violet-50 px-2.5 text-[8px] font-bold text-violet-700 transition hover:bg-violet-100"
                      >
                        Today
                      </button>

                      <span className="text-[7px] font-medium text-slate-400">
                        • = scheduled surgeries
                      </span>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="ml-1 hidden 2xl:block">
              <p className="text-[8px] font-semibold text-slate-400">
                Planning2 · Daily OR
                room and status schedule
              </p>
            </div>
          </div>

          <div className="flex min-w-0 items-center justify-end gap-2">
            <div className="relative w-[230px]">
              <Search
                size={12}
                className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400"
              />

              <input
                value={search}
                onChange={(
                  event,
                ) =>
                  setSearch(
                    event.target
                      .value,
                  )
                }
                placeholder="Search patient, case, procedure..."
                className="h-8 w-full rounded-lg border border-slate-200 bg-slate-50/60 pl-8 pr-2.5 text-[8.5px] font-medium text-slate-700 outline-none transition placeholder:text-slate-300 focus:border-violet-300 focus:bg-white focus:ring-2 focus:ring-violet-100"
              />
            </div>

            <div
              ref={
                doctorFilterRef
              }
              className="relative"
            >
              <button
                type="button"
                onClick={() =>
                  setDoctorFilterOpen(
                    (
                      current,
                    ) =>
                      !current,
                  )
                }
                className={`flex h-8 min-w-[132px] items-center justify-between gap-2 rounded-lg border px-2.5 text-[8.5px] font-semibold transition ${
                  doctor
                    ? "border-violet-200 bg-violet-50 text-violet-700"
                    : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                }`}
              >
                <div className="flex min-w-0 items-center gap-1.5">
                  <Filter
                    size={10}
                  />

                  <span className="truncate">
                    {doctor ||
                      "All Doctors"}
                  </span>
                </div>

                <ChevronDown
                  size={10}
                  className={`transition ${
                    doctorFilterOpen
                      ? "rotate-180"
                      : ""
                  }`}
                />
              </button>

              {doctorFilterOpen && (
                <div className="absolute right-0 top-[calc(100%+6px)] z-[120] w-[280px] rounded-xl border border-slate-200 bg-white p-3 shadow-[0_16px_36px_rgba(15,23,42,0.16)]">
                  <div className="mb-2 flex items-center justify-between">
                    <div>
                      <p className="text-[9px] font-semibold text-slate-700">
                        Doctor Filter
                      </p>

                      <p className="mt-0.5 text-[7.5px] text-slate-400">
                        Focus the
                        planning board.
                      </p>
                    </div>

                    {doctor && (
                      <button
                        type="button"
                        onClick={() => {
                          setDoctor("");
                          setDoctorFilterOpen(
                            false,
                          );
                        }}
                        className="text-[7.5px] font-semibold text-violet-600"
                      >
                        Clear
                      </button>
                    )}
                  </div>

                  <div className="flex max-h-[180px] flex-wrap gap-1.5 overflow-y-auto">
                    <button
                      type="button"
                      onClick={() => {
                        setDoctor("");
                        setDoctorFilterOpen(
                          false,
                        );
                      }}
                      className={`h-7 rounded-lg border px-2.5 text-[8px] font-semibold ${
                        !doctor
                          ? "border-violet-200 bg-violet-50 text-violet-700"
                          : "border-slate-200 bg-white text-slate-500"
                      }`}
                    >
                      All Doctors
                    </button>

                    {doctors.map(
                      (name) => (
                        <button
                          key={
                            name
                          }
                          type="button"
                          onClick={() => {
                            setDoctor(
                              name,
                            );

                            setDoctorFilterOpen(
                              false,
                            );
                          }}
                          className={`h-7 rounded-lg border px-2.5 text-[8px] font-semibold ${
                            doctor ===
                            name
                              ? "border-violet-200 bg-violet-50 text-violet-700"
                              : "border-slate-200 bg-white text-slate-500 hover:border-violet-200 hover:bg-violet-50/30"
                          }`}
                        >
                          {name}
                        </button>
                      ),
                    )}
                  </div>
                </div>
              )}
            </div>

          </div>
        </div>

        <div className="flex items-center justify-between px-3 py-1.5">
          <div className="flex items-center gap-3">
            <span className="text-[7px] font-bold uppercase tracking-wide text-slate-400">
              Legend
            </span>

            {STATUS_COLUMNS.map(
              (column) => {
                const tone =
                  getToneClasses(
                    column.tone,
                  );

                return (
                  <span
                    key={
                      column.key
                    }
                    className="flex items-center gap-1 text-[7.5px] font-semibold text-slate-500"
                  >
                    <span
                      className={`h-2 w-2 rounded-full ${tone.dot}`}
                    />

                    {
                      column.label
                    }
                  </span>
                );
              },
            )}
          </div>

          <div className="flex items-center gap-2 text-[8px] text-slate-400">
            <span>
              Drag editable cards to another room in the same state. Drop in the same room to change time.
            </span>
          </div>
        </div>
      </header>

      {notice && (
        <div
          role="status"
          className="shrink-0 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-[9px] font-medium text-emerald-700"
        >
          {notice}
        </div>
      )}

      {/* PLANNING BOARD */}
      <section
        className={`flex min-h-0 flex-col overflow-hidden border border-slate-200 bg-white ${
          boardExpanded
            ? "fixed inset-2 z-[150] rounded-2xl shadow-[0_28px_80px_rgba(15,23,42,0.24)]"
            : "flex-1 rounded-2xl shadow-[0_1px_3px_rgba(15,23,42,0.025)]"
        }`}
      >
        {/* BOARD TOOLBAR */}
        <div
          className={`flex shrink-0 items-center justify-between border-b border-slate-100 bg-white px-2.5 ${
            boardExpanded
              ? "h-8"
              : "h-9"
          }`}
        >
          <div className="flex min-w-0 items-center gap-2">
            <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-lg bg-violet-50 text-violet-600">
              <Building2 size={11} />
            </div>

            <div className="min-w-0">
              <p className="truncate text-[9px] font-bold text-slate-700">
                OR Planning Board
              </p>

              <p className="truncate text-[7px] text-slate-400">
                Drag editable cards between rooms · click a card for detailed editing
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={() =>
              setBoardExpanded(
                (current) => !current,
              )
            }
            className={`flex h-7 items-center gap-1.5 rounded-lg border px-2.5 text-[8px] font-semibold transition ${
              boardExpanded
                ? "border-violet-200 bg-violet-50 text-violet-700 hover:bg-violet-100"
                : "border-slate-200 bg-white text-slate-500 hover:border-violet-200 hover:bg-violet-50/50 hover:text-violet-700"
            }`}
            title={
              boardExpanded
                ? "Exit full table view"
                : "Expand table"
            }
          >
            {boardExpanded ? (
              <Minimize2 size={11} />
            ) : (
              <Maximize2 size={11} />
            )}

            {boardExpanded
              ? "Exit full view"
              : "Expand"}
          </button>
        </div>

        <div
          className={`min-h-0 flex-1 overflow-x-hidden ${
            boardExpanded
              ? "overflow-hidden"
              : "overflow-y-auto"
          }`}
        >
          <div
            className={`w-full min-w-0 ${
              boardExpanded
                ? "flex h-full min-h-0 flex-col"
                : ""
            }`}
          >
            {/* COLUMN HEADER */}
            <div data-responsive-grid="2"
              className={`sticky top-0 z-30 grid border-b border-slate-100 bg-slate-50/95 shadow-[0_4px_10px_rgba(15,23,42,0.025)] backdrop-blur ${
                boardExpanded
                  ? "grid-cols-[170px_repeat(4,minmax(0,1fr))]"
                  : "grid-cols-[136px_repeat(4,minmax(0,1fr))]"
              }`}
            >
              <div
                className={`sticky left-0 z-40 flex items-center border-r border-slate-100 bg-slate-50/95 backdrop-blur ${
                  boardExpanded
                    ? "h-[40px]"
                    : "h-[46px]"
                } ${
                  boardExpanded
                    ? "px-3"
                    : "px-2"
                }`}
              >
                <div>
                  <p className="text-[10px] font-bold text-slate-700">
                    Rooms
                  </p>

                  <p className="mt-0.5 text-[7.5px] text-slate-400">
                    OR sequence
                  </p>
                </div>
              </div>

              {STATUS_COLUMNS.map(
                (column) => {
                  const tone =
                    getToneClasses(
                      column.tone,
                    );

                  const count =
                    scopedCases.filter(
                      (surgery) =>
                        surgery.status ===
                        column.key,
                    ).length;

                  return (
                    <div
                      key={
                        column.key
                      }
                      className={`flex items-center border-r border-slate-100 last:border-r-0 ${
                        boardExpanded
                          ? "h-[40px]"
                          : "h-[46px]"
                      } ${
                        boardExpanded
                          ? "px-2"
                          : "px-1"
                      }`}
                    >
                      <div
                        className={`flex h-8 w-full items-center justify-between rounded-lg border ${
                          boardExpanded
                            ? "px-2.5"
                            : "px-2"
                        } ${tone.header}`}
                      >
                        <div className="flex items-center gap-1.5">
                          <span
                            className={`h-2 w-2 rounded-full ${tone.dot}`}
                          />

                          <span className="text-[8px] font-bold uppercase tracking-wide">
                            {
                              column.label
                            }
                          </span>
                        </div>

                        <span className="rounded-full bg-white/80 px-1.5 py-0.5 text-[7px] font-bold">
                          {count}
                        </span>
                      </div>
                    </div>
                  );
                },
              )}
            </div>

            {/* ROOM ROWS */}
            {roomRows.length >
            0 ? (
              <div
                className={
                  boardExpanded
                    ? "grid min-h-0 flex-1 divide-y divide-slate-100"
                    : "divide-y divide-slate-100"
                }
                style={
                  boardExpanded
                    ? {
                        gridTemplateRows: `repeat(${roomRows.length}, minmax(0, 1fr))`,
                      }
                    : undefined
                }
              >
                {roomRows.map(
                  (room) => {
                    const roomCases =
                      scopedCases.filter(
                        (surgery) =>
                          surgery.room ===
                          room,
                      );

                    const running =
                      roomCases.find(
                        (surgery) =>
                          surgery.status ===
                          "In Progress",
                      );

                    const next =
                      roomCases.find(
                        (surgery) =>
                          !isFinished(
                            surgery,
                          ) &&
                          surgery.id !==
                            running?.id,
                      );

                    return (
                      <div data-responsive-grid="2"
                        key={
                          room
                        }
                        className={`grid ${
                          boardExpanded
                            ? "h-full min-h-0 grid-cols-[170px_repeat(4,minmax(0,1fr))]"
                            : "min-h-[132px] grid-cols-[136px_repeat(4,minmax(0,1fr))]"
                        }`}
                      >
                        {/* ROOM */}
                        <div
                          className={`sticky left-0 z-20 border-r border-slate-200 bg-slate-50/95 shadow-[5px_0_12px_rgba(15,23,42,0.035)] backdrop-blur ${
                            boardExpanded
                              ? "h-full min-h-0 px-2.5 py-1.5"
                              : "min-h-[132px] px-2 py-2"
                          }`}
                        >
                          <div className="flex items-center gap-2">
                            <div
                              className={`flex items-center justify-center rounded-lg border border-violet-100 bg-white text-violet-600 shadow-sm ${
                                boardExpanded
                                  ? "h-6 w-6"
                                  : "h-7 w-7"
                              }`}
                            >
                              <Building2
                                size={
                                  boardExpanded
                                    ? 11
                                    : 13
                                }
                              />
                            </div>

                            <div className="min-w-0">
                              <p className="truncate text-[10.5px] font-bold text-slate-800">
                                {room}
                              </p>

                              <div className="mt-0.5 flex items-center gap-1">
                                <span
                                  className={`h-1.5 w-1.5 rounded-full ${
                                    running
                                      ? "bg-violet-500"
                                      : next
                                        ? "bg-emerald-500"
                                        : "bg-slate-300"
                                  }`}
                                />

                                <span className="text-[7.5px] font-semibold text-slate-400">
                                  {running
                                    ? "In use"
                                    : next
                                      ? "Scheduled"
                                      : "Available"}
                                </span>
                              </div>
                            </div>
                          </div>

                          <div
                            className={`${
                              boardExpanded
                                ? "mt-1 space-y-1"
                                : "mt-1.5 space-y-1.5"
                            }`}
                          >
                            <div
                              className={`rounded-lg border border-slate-100 bg-white px-2 ${
                                boardExpanded
                                  ? "py-1"
                                  : "py-1.5"
                              }`}
                            >
                              <p className="text-[6.5px] font-bold uppercase tracking-wide text-slate-400">
                                Current
                              </p>

                              <p className="mt-0.5 truncate text-[7.5px] font-semibold text-slate-600">
                                {running
                                  ? `${running.time} · ${running.patientName}`
                                  : "No active case"}
                              </p>
                            </div>

                            <div
                              className={`rounded-lg border border-slate-100 bg-white px-2 ${
                                boardExpanded
                                  ? "py-1"
                                  : "py-1.5"
                              }`}
                            >
                              <p className="text-[6.5px] font-bold uppercase tracking-wide text-slate-400">
                                Next
                              </p>

                              <p className="mt-0.5 truncate text-[7.5px] font-semibold text-slate-600">
                                {next
                                  ? `${next.time} · ${next.patientName}`
                                  : "No next case"}
                              </p>
                            </div>
                          </div>
                        </div>

                        {/* STATUS CELLS */}
                        {STATUS_COLUMNS.map(
                          (
                            column,
                          ) => {
                            const items =
                              roomCases.filter(
                                (
                                  surgery,
                                ) =>
                                  surgery.status ===
                                  column.key,
                              );

                            return (
                              <StatusCell
                                key={`${room}-${column.key}`}
                                items={
                                  items
                                }
                                tone={
                                  column.tone
                                }
                                room={
                                  room
                                }
                                status={
                                  column.key
                                }
                                scopedCases={
                                  scopedCases
                                }
                                draggedSurgery={
                                  draggedSurgery
                                }
                                isDragOver={
                                  dragOverCell ===
                                  `${room}:${column.key}`
                                }
                                onDragStart={(
                                  surgery,
                                ) => {
                                  setDraggedSurgeryId(
                                    surgery.id,
                                  );
                                }}
                                onDragEnd={() => {
                                  setDraggedSurgeryId(
                                    null,
                                  );
                                  setDragOverCell(
                                    null,
                                  );
                                }}
                                onDragOver={() =>
                                  setDragOverCell(
                                    `${room}:${column.key}`,
                                  )
                                }
                                onDragLeave={() =>
                                  setDragOverCell(
                                    null,
                                  )
                                }
                                onDrop={(
                                  surgery,
                                ) => {
                                  setDraggedSurgeryId(
                                    null,
                                  );
                                  setDragOverCell(
                                    null,
                                  );
                                  setPendingMove(
                                    {
                                      surgery,
                                      targetRoom:
                                        room,
                                    },
                                  );
                                }}
                                onEdit={
                                  setEditing
                                }
                                expanded={
                                  boardExpanded
                                }
                              />
                            );
                          },
                        )}
                      </div>
                    );
                  },
                )}
              </div>
            ) : (
              <div className="flex h-[280px] items-center justify-center">
                <div className="text-center">
                  <CalendarDays
                    size={20}
                    className="mx-auto text-slate-300"
                  />

                  <p className="mt-2 text-[10px] font-semibold text-slate-600">
                    No surgeries
                    found
                  </p>

                  <p className="mt-1 text-[8px] text-slate-400">
                    Change the
                    date, search or
                    doctor filter.
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>
      </section>

      {pendingMove && (
        <MoveConfirmation
          key={`${pendingMove.surgery.id}-${pendingMove.targetRoom}`}
          surgery={
            surgeries.find(
              (surgery) =>
                surgery.id ===
                pendingMove.surgery.id,
            ) ??
            pendingMove.surgery
          }
          targetRoom={
            pendingMove.targetRoom
          }
          surgeries={
            surgeries
          }
          onCancel={() =>
            setPendingMove(
              null,
            )
          }
          onConfirm={(
            updates,
          ) => {
            const current =
              surgeries.find(
                (surgery) =>
                  surgery.id ===
                  pendingMove.surgery
                    .id,
              ) ??
              pendingMove.surgery;

            const roomChanged =
              current.room !==
              updates.room;

            const timeChanged =
              current.time !==
              updates.time;

            updateSurgery(
              current.id,
              updates,
            );

            setNotice(
              roomChanged &&
                timeChanged
                ? `${current.patientName} moved from ${current.room} to ${updates.room} and rescheduled from ${current.time} to ${updates.time}.`
                : roomChanged
                  ? `${current.patientName} moved from ${current.room} to ${updates.room}.`
                  : `${current.patientName} rescheduled from ${current.time} to ${updates.time}.`,
            );

            setPendingMove(
              null,
            );
          }}
        />
      )}

      {editing && (
        <PlanEditor
          key={editing.id}
          surgery={
            surgeries.find(
              (surgery) =>
                surgery.id ===
                editing.id,
            ) || editing
          }
          surgeries={
            surgeries
          }
          rooms={rooms}
          onClose={() =>
            setEditing(null)
          }
          onSave={(
            updates,
          ) => {
            updateSurgery(
              editing.id,
              updates,
            );

            setNotice(
              `Plan updated for ${editing.patientName}. Planning2 refreshed.`,
            );

            setEditing(null);
          }}
        />
      )}
    </div>
  );
}

