source:
import { useNavigate, useParams } from "react-router-dom";
import { useSurgeryStore } from "../store/surgeryStore";
import { useState, useRef, useMemo, useEffect } from "react";
import { type PostOpState, type LifestyleHabitType, type ExpandedList, type ToastState, type PatientCondition, type Period, type SortKey, type SortDirection, type FollowUpOrder, type Medication, type MedicationStatus, type OrderStatus, type PostOpVisit, type VisitStatus, type LifestyleHabit } from "../features/workspaces/PostOpDetails/types";
import { EMPTY_STATE, MIN_PAGE_SIZE, ROW_HEIGHT, lifestyleHabitTypes } from "../features/workspaces/PostOpDetails/config";
import { getProcedureNames, loadPostOp, isPostOpDateInPeriod, getPostOpDateSortValue, isPostOpStateEmpty, createSarahDemoState, persistPostOp, createId, getDoctorAvailableVisitSlots, formatShortDate, getPatientPhoneForWhatsApp, openPostOpWhatsApp, buildPostOpVisitWhatsAppMessage, formatVisitTime, formatDischargeDateTime, hasRichTextContent, stripHtml, getNextVisitLabel, getLifestylePlaceholder } from "../features/workspaces/PostOpDetails/utils";
import { FileText, ArrowLeft, ClipboardCheck, CalendarDays, Pill, FlaskConical, Image, Leaf, X, Plus, ChevronDown, Footprints, HeartPulse, Check, Save, Minimize2, Maximize2, Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, List, ListOrdered, Highlighter } from "lucide-react";
import { PatientContextTools } from "../features/patient-context/PatientContextTools";
import { HeaderInfo, QuickFact, WorkspaceCard, SmallAddButton, MedicationForm, MedicationRow, EmptyState, ViewAllButton, OrderForm, FollowUpRow, LifestyleTypeIcon, LifestyleHabitRow, VisitForm, VisitRow, ReportToolbarButton } from "../features/workspaces/PostOpDetails/components";


export default function PostOpDetails() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();

  const surgeries = useSurgeryStore(
    (state) => state.surgeries,
  );

  const updateSurgery = useSurgeryStore(
    (state) => state.updateSurgery,
  );

  const [search] = useState("");
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(5);

  const rowsContainerRef =
    useRef<HTMLDivElement | null>(null);

  const selectedId = id ?? null;

  const setSelectedId = (
    nextId: string | null,
  ) => {
    navigate(
      nextId
        ? `/post-op/${nextId}`
        : "/post-op",
    );
  };

  const [postOp, setPostOp] =
    useState<PostOpState>(EMPTY_STATE);

  const [addingMedication, setAddingMedication] =
    useState(false);

  const [addingOrder, setAddingOrder] =
    useState(false);

  const [addingVisit, setAddingVisit] =
    useState(false);

  const [addingLifestyle, setAddingLifestyle] =
    useState(false);

  const [newLifestyleType, setNewLifestyleType] =
    useState<LifestyleHabitType>("Walking");

  const [newLifestyleInstruction, setNewLifestyleInstruction] =
    useState("");

  const [lifestyleTypePanelOpen, setLifestyleTypePanelOpen] =
    useState(false);

  const [expandedList, setExpandedList] =
    useState<ExpandedList>(null);

  const [reportOpen, setReportOpen] =
    useState(false);

  const [reportExpanded, setReportExpanded] =
    useState(false);

  const [surgeonReport, setSurgeonReport] =
    useState("");

  const reportEditorRef =
    useRef<HTMLDivElement | null>(null);

  const savedReportRangeRef =
    useRef<Range | null>(null);

  const [recoveryNotesOpen, setRecoveryNotesOpen] =
    useState(false);

  const [noteOpen, setNoteOpen] =
    useState(false);

  const [noteDraft, setNoteDraft] =
    useState("");

  const [toast, setToast] =
    useState<ToastState>(null);

  const [filterOpen, setFilterOpen] =
    useState(false);

  const [selectedDoctors] =
    useState<string[]>([]);

  const [selectedConditions] =
    useState<PatientCondition[]>([]);

  const [period] =
    useState<Period>("Day");

  const [selectedDate] =
    useState("");

  const [sortKey] =
    useState<SortKey>("date");

  const [sortDirection] =
    useState<SortDirection>("asc");

  const filterRef =
    useRef<HTMLDivElement | null>(null);

  const [medicationDraft, setMedicationDraft] =
    useState({
      name: "",
      dose: "",
      frequency: "",
      duration: "",
    });

  const [orderDraft, setOrderDraft] =
    useState({
      type: "Lab Test" as FollowUpOrder["type"],
      name: "",
      dueDate: "",
    });

  const [visitDraft, setVisitDraft] =
    useState({
      date: "",
      time: "",
      progress: "",
      notes: "",
    });

  const postOpCases = useMemo(
    () =>
      surgeries.filter((surgery) =>
        [
          "Completed",
          "Recovery",
          "Discharged",
        ].includes(surgery.status),
      ),
    [surgeries],
  );


  const filteredCases = useMemo(() => {
    const query = search
      .trim()
      .toLowerCase();

    return postOpCases.filter(
      (surgery) => {
        const procedures =
          getProcedureNames(
            surgery,
          )
            .join(" ")
            .toLowerCase();

        const stored =
          loadPostOp(
            surgery.id,
          );

        const matchesSearch =
          !query ||
          surgery.patientName
            .toLowerCase()
            .includes(query) ||
          surgery.id
            .toLowerCase()
            .includes(query) ||
          surgery.doctor
            .toLowerCase()
            .includes(query) ||
          procedures.includes(
            query,
          );

        const matchesDoctor =
          selectedDoctors.length === 0 ||
          selectedDoctors.includes(
            surgery.doctor,
          );

        const matchesCondition =
          selectedConditions.length === 0 ||
          selectedConditions.includes(
            stored.condition,
          );

        const matchesDate =
          !selectedDate ||
          isPostOpDateInPeriod(
            surgery,
            selectedDate,
            period,
          );


        return (
          matchesSearch &&
          matchesDoctor &&
          matchesCondition &&
          matchesDate
        );
      },
    );
  }, [
    postOpCases,
    search,
    selectedDoctors,
    selectedConditions,
    selectedDate,
    period,
  ]);

  const sortedCases = useMemo(() => {
    const copy = [
      ...filteredCases,
    ];

    copy.sort((a, b) => {
      const getValue = (
        surgery: (typeof copy)[number],
      ) => {
        const stored =
          loadPostOp(
            surgery.id,
          );

        switch (sortKey) {
          case "patient":
            return surgery.patientName;

          case "patientId":
            return surgery.id;

          case "procedures":
            return getProcedureNames(
              surgery,
            ).join(" ");

          case "surgeon":
            return surgery.doctor;

          case "date":
            return getPostOpDateSortValue(
              surgery,
            );

          case "condition":
            return stored.condition;

          case "followUp":
            return stored.followUps.filter(
              (item) =>
                item.status !==
                "Completed",
            ).length;

          default:
            return "";
        }
      };

      const aValue =
        getValue(a);

      const bValue =
        getValue(b);

      const result =
        typeof aValue === "number" &&
        typeof bValue === "number"
          ? aValue - bValue
          : String(
              aValue,
            ).localeCompare(
              String(bValue),
              undefined,
              {
                numeric: true,
                sensitivity: "base",
              },
            );

      return sortDirection ===
        "asc"
        ? result
        : -result;
    });

    return copy;
  }, [
    filteredCases,
    sortKey,
    sortDirection,
  ]);

  const totalPages = Math.max(
    1,
    Math.ceil(
      sortedCases.length / pageSize,
    ),
  );


  const selected = surgeries.find(
    (surgery) =>
      surgery.id === selectedId,
  );

  useEffect(() => {
    if (!selectedId || !selected) return;

    const stored =
      loadPostOp(selectedId);

    if (
      selectedId === "SRG-2048" &&
      isPostOpStateEmpty(stored)
    ) {
      setPostOp(
        createSarahDemoState(),
      );
    } else {
      setPostOp(stored);
    }

    const currentReport =
      stored.surgeonReport ||
      selected.operativeReport ||
      "";

    setSurgeonReport(currentReport);

    setPostOp((current) => ({
      ...current,
      surgeonReport: currentReport,
    }));
  }, [selectedId, selected?.operativeReport]);


  useEffect(() => {
    const element = rowsContainerRef.current;

    if (!element) return;

    const updatePageSize = () => {
      const availableHeight =
        element.getBoundingClientRect().height;

      const nextPageSize = Math.max(
        MIN_PAGE_SIZE,
        Math.floor(
          availableHeight / ROW_HEIGHT,
        ),
      );

      setPageSize((current) =>
        current === nextPageSize
          ? current
          : nextPageSize,
      );
    };

    updatePageSize();

    const observer =
      new ResizeObserver(updatePageSize);

    observer.observe(element);

    window.addEventListener(
      "resize",
      updatePageSize,
    );

    return () => {
      observer.disconnect();

      window.removeEventListener(
        "resize",
        updatePageSize,
      );
    };
  }, []);

  useEffect(() => {
    if (page > totalPages - 1) {
      setPage(
        Math.max(
          0,
          totalPages - 1,
        ),
      );
    }
  }, [page, totalPages]);

  useEffect(() => {
    /*
     * Post-Op always opens on the patient table.
     * Only close an already-open drawer if its patient is no longer
     * available after filtering; never auto-select the first record.
     */
    if (
      selectedId &&
      !filteredCases.some(
        (item) =>
          item.id === selectedId,
      )
    ) {
      setSelectedId(null);
      setPostOp(EMPTY_STATE);
    }
  }, [
    filteredCases,
    selectedId,
  ]);

  useEffect(() => {
    if (!selectedId) return;

    const timer =
      window.setTimeout(() => {
        persistPostOp(
          selectedId,
          postOp,
        );
      }, 250);

    return () =>
      window.clearTimeout(timer);
  }, [selectedId, postOp]);




  useEffect(() => {
    if (!toast) return;

    const timer = window.setTimeout(
      () => setToast(null),
      3800,
    );

    return () =>
      window.clearTimeout(timer);
  }, [toast]);

  function showToast(
    type: "success" | "error",
    title: string,
    message: string,
    items?: string[],
  ) {
    setToast({
      type,
      title,
      message,
      items,
    });
  }

  useEffect(() => {
    setPage(0);
  }, [
    search,
    selectedDoctors,
    selectedConditions,
    selectedDate,
    period,
  ]);

  useEffect(() => {
    if (!filterOpen) return;

    function handleOutsideClick(
      event: MouseEvent,
    ) {
      const target =
        event.target as Node | null;

      if (
        target &&
        filterRef.current &&
        !filterRef.current.contains(
          target,
        )
      ) {
        setFilterOpen(false);
      }
    }

    document.addEventListener(
      "mousedown",
      handleOutsideClick,
    );

    return () =>
      document.removeEventListener(
        "mousedown",
        handleOutsideClick,
      );
  }, [filterOpen]);






  function addMedication() {
    const missing: string[] = [];

    if (!medicationDraft.name.trim()) {
      missing.push(
        "Medication name is required",
      );
    }

    if (!medicationDraft.dose.trim()) {
      missing.push(
        "Dose is required",
      );
    }

    if (
      !medicationDraft.frequency.trim()
    ) {
      missing.push(
        "Frequency is required",
      );
    }

    if (
      !medicationDraft.duration.trim()
    ) {
      missing.push(
        "Duration is required",
      );
    }

    if (missing.length > 0) {
      showToast(
        "error",
        "Medication not added",
        "Please complete the following required fields:",
        missing,
      );

      return;
    }

    try {
      const item: Medication = {
        id: createId("med"),
        name:
          medicationDraft.name.trim(),
        dose:
          medicationDraft.dose.trim(),
        frequency:
          medicationDraft.frequency.trim(),
        duration:
          medicationDraft.duration.trim(),
        status: "Active",
        stopReason: "",
      };

      setPostOp((current) => ({
        ...current,
        medications: [
          ...current.medications,
          item,
        ],
      }));

      setMedicationDraft({
        name: "",
        dose: "",
        frequency: "",
        duration: "",
      });

      setAddingMedication(false);

      showToast(
        "success",
        "Medication added",
        `${item.name} was added successfully to the Post-Op medication plan.`,
      );
    } catch (error) {
      showToast(
        "error",
        "Medication not added",
        error instanceof Error
          ? error.message
          : "Something went wrong while adding the medication.",
      );
    }
  }

  function updateMedication(
    id: string,
    nextItem: Medication,
  ) {
    setPostOp((current) => ({
      ...current,
      medications:
        current.medications.map(
          (item) =>
            item.id === id
              ? nextItem
              : item,
        ),
    }));
  }

  function deleteMedication(
    id: string,
  ) {
    setPostOp((current) => ({
      ...current,
      medications:
        current.medications.filter(
          (item) =>
            item.id !== id,
        ),
    }));
  }

  function updateMedicationStatus(
    id: string,
    status: MedicationStatus,
    stopReason = "",
  ) {
    setPostOp((current) => ({
      ...current,
      medications:
        current.medications.map(
          (item) =>
            item.id === id
              ? {
                  ...item,
                  status,
                  stopReason:
                    status === "Stopped"
                      ? stopReason
                      : "",
                }
              : item,
        ),
    }));
  }

  function addFollowUpOrder() {
    const missing: string[] = [];

    if (!orderDraft.type) {
      missing.push(
        "Request type is required",
      );
    }

    if (!orderDraft.name.trim()) {
      missing.push(
        "Test or imaging name is required",
      );
    }

    if (!orderDraft.dueDate) {
      missing.push(
        "Due date is required",
      );
    }

    if (missing.length > 0) {
      showToast(
        "error",
        "Request not added",
        "Please complete the following required fields:",
        missing,
      );

      return;
    }

    try {
      const item: FollowUpOrder = {
        id: createId("order"),
        type: orderDraft.type,
        name:
          orderDraft.name.trim(),
        dueDate:
          orderDraft.dueDate,
        status: "Requested",
        result: "",
      };

      setPostOp((current) => ({
        ...current,
        followUps: [
          ...current.followUps,
          item,
        ],
      }));

      setOrderDraft({
        type: "Lab Test",
        name: "",
        dueDate: "",
      });

      setAddingOrder(false);

      showToast(
        "success",
        "Request added",
        `${item.name} was added successfully to Tests & Imaging.`,
      );
    } catch (error) {
      showToast(
        "error",
        "Request not added",
        error instanceof Error
          ? error.message
          : "Something went wrong while adding the request.",
      );
    }
  }

  function updateOrder(
    id: string,
    nextItem: FollowUpOrder,
  ) {
    setPostOp((current) => ({
      ...current,
      followUps:
        current.followUps.map(
          (item) =>
            item.id === id
              ? nextItem
              : item,
        ),
    }));
  }

  function deleteOrder(
    id: string,
  ) {
    setPostOp((current) => ({
      ...current,
      followUps:
        current.followUps.filter(
          (item) =>
            item.id !== id,
        ),
    }));
  }

  function updateOrderStatus(
    id: string,
    status: OrderStatus,
  ) {
    setPostOp((current) => ({
      ...current,
      followUps:
        current.followUps.map(
          (item) =>
            item.id === id
              ? {
                  ...item,
                  status,
                }
              : item,
        ),
    }));
  }


  function updateOrderResult(
    id: string,
    result: string,
  ) {
    setPostOp((current) => ({
      ...current,
      followUps:
        current.followUps.map(
          (item) =>
            item.id === id
              ? {
                  ...item,
                  result,
                }
              : item,
        ),
    }));
  }

  function addVisit() {
    if (!selected) {
      showToast(
        "error",
        "Visit not scheduled",
        "No patient is selected.",
      );

      return;
    }

    const missing: string[] = [];

    if (!visitDraft.date) {
      missing.push(
        "Visit date is required",
      );
    }

    if (!visitDraft.time) {
      missing.push(
        "Available time slot is required",
      );
    }

    if (!visitDraft.progress.trim()) {
      missing.push(
        "Visit purpose is required",
      );
    }

    if (missing.length > 0) {
      showToast(
        "error",
        "Visit not scheduled",
        "Please complete the following required fields:",
        missing,
      );

      return;
    }

    const availableSlots =
      getDoctorAvailableVisitSlots(
        selected.doctor,
        visitDraft.date,
        surgeries,
        postOp.visits,
      );

    if (
      availableSlots.length === 0
    ) {
      showToast(
        "error",
        "Date is not available",
        `${selected.doctor} has no available Post-Op visit slots on ${formatShortDate(
          visitDraft.date,
        )}. Please choose another date.`,
      );

      return;
    }

    try {
      const item: PostOpVisit = {
        id: createId("visit"),
        date: visitDraft.date,
        time: visitDraft.time,
        status: "Upcoming",
        condition:
          postOp.condition,
        progress:
          visitDraft.progress.trim(),
        notes:
          visitDraft.notes.trim(),
        result: "",
      };

      setPostOp((current) => ({
        ...current,
        visits: [
          ...current.visits,
          item,
        ],
      }));

      setVisitDraft({
        date: "",
        time: "",
        progress: "",
        notes: "",
      });

      setAddingVisit(false);

      const patientPhone =
        getPatientPhoneForWhatsApp(
          selected,
        );

      const medicationsForMessage = [
        ...postOp.medications,
      ];

      const followUpsForMessage = [
        ...postOp.followUps,
      ];

      openPostOpWhatsApp(
        patientPhone,
        buildPostOpVisitWhatsAppMessage({
          action: "booked",
          patientName:
            selected.patientName,
          doctor:
            selected.doctor,
          date: item.date,
          time: item.time,
          medications:
            medicationsForMessage,
          followUps:
            followUpsForMessage,
        }),
      );

      showToast(
        "success",
        "Post-Op visit scheduled",
        `${selected.patientName}'s visit with ${selected.doctor} was scheduled for ${formatShortDate(
          item.date,
        )} at ${formatVisitTime(
          item.time,
        )}.`,
      );
    } catch (error) {
      showToast(
        "error",
        "Visit not scheduled",
        error instanceof Error
          ? error.message
          : "Something went wrong while scheduling the Post-Op visit.",
      );
    }
  }

  function updateVisit(
    id: string,
    nextVisit: PostOpVisit,
  ) {
    if (!selected) return;

    const previous =
      postOp.visits.find(
        (visit) =>
          visit.id === id,
      );

    setPostOp((current) => ({
      ...current,
      visits:
        current.visits.map(
          (visit) =>
            visit.id === id
              ? nextVisit
              : visit,
        ),
    }));

    const patientPhone =
      getPatientPhoneForWhatsApp(
        selected,
      );

    openPostOpWhatsApp(
      patientPhone,
      buildPostOpVisitWhatsAppMessage({
