  function deleteVisit(
    id: string,
  ) {
    if (!selected) return;

    const removedVisit =
      postOp.visits.find(
        (visit) =>
          visit.id === id,
      );

    setPostOp((current) => ({
      ...current,
      visits:
        current.visits.filter(
          (visit) =>
            visit.id !== id,
        ),
    }));

    if (removedVisit) {
      const patientPhone =
        getPatientPhoneForWhatsApp(
          selected,
        );

      openPostOpWhatsApp(
        patientPhone,
        buildPostOpVisitWhatsAppMessage({
          action: "cancelled",
          patientName:
            selected.patientName,
          doctor:
            selected.doctor,
          date:
            removedVisit.date,
          time:
            removedVisit.time,
          medications: [
            ...postOp.medications,
          ],
          followUps: [
            ...postOp.followUps,
          ],
        }),
      );

      showToast(
        "success",
        "Post-Op visit cancelled",
        `${selected.patientName}'s visit on ${formatShortDate(
          removedVisit.date,
        )} at ${formatVisitTime(
          removedVisit.time,
        )} was cancelled.`,
      );
    }
