        "Post-Op plan not saved",
        "No patient is selected.",
      );
      return;
    }

    try {
      persistPostOp(
        selected.id,
        postOp,
      );

      updateSurgery(
        selected.id,
        {
          postOpCompleted: true,
          postOpCondition:
            postOp.condition,
          postOpInstructions:
            postOp.instructions,
          postOpMedications:
            postOp.medications,
          postOpFollowUps:
            postOp.followUps,
          postOpVisits:
            postOp.visits,
          postOpDischargeChecklist:
            postOp.dischargeChecklist,
          postOpDischarged:
            postOp.discharged,
          operativeReport:
            postOp.surgeonReport ||
            surgeonReport,
        } as any,
      );

      showToast(
        "success",
        "Post-Op plan saved",
        `${selected.patientName}'s medications, follow-ups and visits were saved successfully.`,
      );

      setAddingMedication(false);
      setAddingOrder(false);
      setAddingVisit(false);
      setAddingLifestyle(false);
      setLifestyleTypePanelOpen(false);
      setNewLifestyleType("Walking");
      setNewLifestyleInstruction("");
