    setSurgeonReport(currentReport);
    setReportOpen(true);

    window.requestAnimationFrame(() => {
      if (reportEditorRef.current) {
        reportEditorRef.current.innerHTML =
          currentReport;
      }
    });
  }

  function rememberReportSelection() {
    const editor =
      reportEditorRef.current;

    const selection =
      window.getSelection();

    if (
      !editor ||
      !selection ||
      selection.rangeCount === 0
    ) {
      return;
    }

    const range =
      selection.getRangeAt(0);

    if (
      editor.contains(
        range.commonAncestorContainer,
      )
    ) {
      savedReportRangeRef.current =
        range.cloneRange();
    }
  }

  function restoreReportSelection() {
    const range =
      savedReportRangeRef.current;

    if (!range) return;

    const selection =
      window.getSelection();

    if (!selection) return;

    selection.removeAllRanges();
    selection.addRange(range);
  }

  function applyReportCommand(
    command: string,
    value?: string,
  ) {
    const editor =
      reportEditorRef.current;

    if (!editor) return;

    editor.focus();
    restoreReportSelection();

    try {
      document.execCommand(
        "styleWithCSS",
        false,
        "true",
      );
    } catch {}

    if (command === "hiliteColor") {
      const applied =
        document.execCommand(
          "hiliteColor",
          false,
          value,
        );

      if (!applied) {
        document.execCommand(
          "backColor",
          false,
          value,
        );
      }
    } else {
      document.execCommand(
        command,
        false,
        value,
      );
    }

    rememberReportSelection();
    setSurgeonReport(
      editor.innerHTML,
    );
  }

