                  <div data-responsive-grid="2" className="grid max-h-[420px] grid-cols-2 content-start gap-2 overflow-y-auto overflow-x-visible p-3 [grid-auto-rows:52px]">
                    {expandedList ===
                      "medications" &&
                      postOp.medications.map(
                        (item) => (
                          <MedicationRow
                            key={item.id}
                            item={item}
                            showHoverDetails={false}
                            onStatusChange={(
                              status,
                              stopReason,
