import { useLocation, useNavigate } from "react-router-dom";
import { useRef, useState, useEffect, useMemo } from "react";
import { type ToastState, type Period, type SortKey, type SortDirection, type ReviewMap, type AnesthesiaExamState, type SafetyNote, type SupplyItem, type IntraNote } from "../features/workspaces/PreOp/types";
import { useSurgeryStore } from "../store/surgeryStore";
import { initialRequiredSupplies, initialAdditionalSupplies, MIN_PAGE_SIZE, ROW_HEIGHT } from "../features/workspaces/PreOp/config";
import { getDoctor, getPatientName, getPatientCode, getProcedures, isDateInPeriod, getDateSortValue, getSurgeryClock, getPreOpWorkflowStatus, getInitials, getPatientAge, getPatientGender, getSurgeryDate } from "../features/workspaces/PreOp/utils";
import { ModuleStatCard, FilterPill, ModernPreOpDatePicker, SortableHeader, PreOpStatusBadge } from "../features/workspaces/PreOp/components";
import { Activity, CheckCircle2, Receipt, Syringe, Search, Filter, ChevronDown, Stethoscope, Clock3, ChevronRight, ChevronLeft, UserCheck, X, AlertTriangle } from "lucide-react";


export default function PreOp() {
  const location = useLocation();
  const navigate = useNavigate();
  const workspaceHeadingRef = useRef<HTMLHeadingElement>(null);

  const routeState =
    location.state as
      | {
          highlightSurgeryId?: string;
          preOpToast?: Exclude<
            ToastState,
            null
          >;
        }
      | null;

  const incomingHighlightId =
    routeState?.highlightSurgeryId ?? null;

  const incomingPreOpToast =
    routeState?.preOpToast ?? null;

  const highlightHandledRef =
    useRef<string | null>(null);

  const [highlightedRowId, setHighlightedRowId] =
    useState<string | null>(null);

  const {
    surgeries,
    admitPatient,
    startPreOp,
  } = useSurgeryStore();

  const [selectedId] =
    useState<string | null>(null);

  useEffect(() => {
    if (selectedId) workspaceHeadingRef.current?.focus();
  }, [selectedId]);

  const [
    admitCandidateId,
    setAdmitCandidateId,
  ] = useState<string | null>(null);

  const [search, setSearch] =
    useState("");

  const [filterOpen, setFilterOpen] =
    useState(false);

  const [selectedDoctors, setSelectedDoctors] =
    useState<string[]>([]);

  const [selectedStatuses, setSelectedStatuses] =
    useState<string[]>([]);

  const [period, setPeriod] =
    useState<Period>("Day");

  const [selectedDate, setSelectedDate] =
    useState("2026-09-03");

  const [sortKey, setSortKey] =
    useState<SortKey>("date");

  const [sortDirection, setSortDirection] =
    useState<SortDirection>("asc");

  const [page, setPage] =
    useState(0);

  const rowsContainerRef =
    useRef<HTMLDivElement | null>(null);

  const filterRef =
    useRef<HTMLDivElement | null>(null);

  const [pageSize, setPageSize] =
    useState(5);

  const [toast, setToast] =
    useState<ToastState>(null);









  const [completedTests] =
    useState<string[]>([]);

  const [preOpReview] =
    useState<ReviewMap>({});

  const [anesthesiaReview] =
    useState<ReviewMap>({});

  const [anesthesiaExam] =
    useState<AnesthesiaExamState>({
      functionalCapacity: "",
      canLieFlat: "",
      smoking: "",
      recentUri: "",
      airway: "",
      dental: "",
      heart: "",
      lungs: "",
      height: "",
      weight: "",
      currentMedications: "",
      priorAnesthesiaHistory: "",
      familyAnesthesiaHistory: "",
      ekg: "",
      labs: "",
      other: "",
      npoConfirmed: "",
      asaClass: "",
    });



  const [anesthesia] =
    useState("");


  const [safety] =
    useState<SafetyNote>({
      exceptions: [],
      acknowledged: false,
    });





  const [requiredSupplies] = useState<SupplyItem[]>(
    initialRequiredSupplies,
  );

  const [additionalSupplies] = useState<SupplyItem[]>(
    initialAdditionalSupplies,
  );

  const [notes] =
    useState<IntraNote[]>([]);





  /*
   * Intra-op notes are session-only while working on this page.
   * They reset naturally after a browser refresh.
   */
  const transientWorkspaceRef =
    useRef<
      Record<
        string,
        {
          notes: IntraNote[];
        }
      >
    >({});



  const admitCandidate = useMemo(
    () =>
      surgeries.find(
        (surgery) =>
          surgery.id === admitCandidateId,
      ) ?? null,
    [surgeries, admitCandidateId],
  );

  /*
   * Keep every surgery/patient visible in the Pre-Op table.
   * The row no longer moves between module tables as status changes.
   */
  const preOpCases = useMemo(
    () => surgeries,
    [surgeries],
  );

  const doctors = useMemo(
    () =>
      Array.from(
        new Set(
          preOpCases.map((surgery) =>
            getDoctor(surgery),
          ),
        ),
      ),
    [preOpCases],
  );

  const statuses = useMemo(
    () =>
      Array.from(
        new Set(
          preOpCases.map(
            (surgery) =>
              surgery.status,
          ),
        ),
      ),
    [preOpCases],
  );

  const filteredCases = useMemo(() => {
    const query = search
      .trim()
      .toLowerCase();

    return preOpCases.filter(
      (surgery) => {
        const name =
          getPatientName(
            surgery,
          ).toLowerCase();

        const code =
          getPatientCode(
            surgery,
          ).toLowerCase();

        const procedure =
          getProcedures(surgery)
            .map(
              (item) => item.name,
            )
            .join(" ")
            .toLowerCase();

        const doctor =
          getDoctor(
            surgery,
          );

        const caseNumber =
          String(
            surgery.id ?? "",
          ).toLowerCase();

        const matchesSearch =
          !query ||
          name.includes(query) ||
          code.includes(query) ||
          caseNumber.includes(query) ||
          procedure.includes(query);

        const matchesDoctor =
          selectedDoctors.length === 0 ||
          selectedDoctors.includes(
            doctor,
          );

        const matchesStatus =
          selectedStatuses.length === 0 ||
          selectedStatuses.includes(
            surgery.status,
          );

        const matchesDate =
          isDateInPeriod(
            surgery,
            selectedDate,
            period,
          );

        return (
          matchesSearch &&
          matchesDoctor &&
          matchesStatus &&
          matchesDate
        );
      },
    );
  }, [
    preOpCases,
    search,
    selectedDoctors,
    selectedStatuses,
    selectedDate,
    period,
  ]);

  const sortedCases = useMemo(() => {
    const copy = [...filteredCases];

    copy.sort((a, b) => {
      const getValue = (
        surgery: (typeof copy)[number],
      ) => {
        switch (sortKey) {
          case "patient":
            return getPatientName(
              surgery,
            );

          case "case":
            return String(
              surgery.id ?? "",
            );

          case "procedures":
            return getProcedures(
              surgery,
            )
              .map(
                (item) =>
                  item.name,
              )
              .join(" ");

          case "surgeon":
            return getDoctor(
              surgery,
            );

          case "date":
            return getDateSortValue(
              surgery,
            );

          case "time":
            return getSurgeryClock(
              surgery,
            );

          case "preOpStatus":
            return getPreOpWorkflowStatus(
              surgery,
            );

          default:
            return "";
        }
      };

      const result = String(
        getValue(a),
      ).localeCompare(
        String(getValue(b)),
        undefined,
        {
          numeric: true,
          sensitivity: "base",
        },
      );

      return sortDirection === "asc"
        ? result
        : -result;
    });

    return copy;
  }, [
    filteredCases,
    sortKey,
    sortDirection,
  ]);

  const totalPages = Math.max(
    1,
    Math.ceil(
      sortedCases.length /
        pageSize,
    ),
  );

  const visibleCases = useMemo(
    () =>
      sortedCases.slice(
        page * pageSize,
        page * pageSize +
          pageSize,
      ),
    [
      sortedCases,
      page,
      pageSize,
    ],
  );

  useEffect(() => {
    const element =
      rowsContainerRef.current;

    if (!element) return;

    const updatePageSize = () => {
      const availableHeight =
        element.getBoundingClientRect()
          .height;

      // Keep pagination stable while the full-page workspace hides the queue.
      if (availableHeight === 0) return;

      const nextPageSize = Math.max(
        MIN_PAGE_SIZE,
        Math.floor(
          availableHeight /
            ROW_HEIGHT,
        ),
      );

      setPageSize((current) =>
        current === nextPageSize
          ? current
          : nextPageSize,
      );
    };

    updatePageSize();

    const observer =
      new ResizeObserver(
        updatePageSize,
      );

    observer.observe(element);

    window.addEventListener(
      "resize",
      updatePageSize,
    );

    return () => {
      observer.disconnect();

      window.removeEventListener(
        "resize",
        updatePageSize,
      );
    };
  }, []);

  useEffect(() => {
    if (!filterOpen) return;

    const handleMouseDown = (
      event: MouseEvent,
    ) => {
      const target =
        event.target as Node | null;

      if (
        target &&
        filterRef.current &&
        !filterRef.current.contains(
          target,
        )
      ) {
        setFilterOpen(false);
      }
    };

    document.addEventListener(
      "mousedown",
      handleMouseDown,
    );

    return () => {
      document.removeEventListener(
        "mousedown",
        handleMouseDown,
      );
    };
  }, [filterOpen]);

  useEffect(() => {
    if (
      !incomingHighlightId ||
      highlightHandledRef.current ===
        incomingHighlightId
    ) {
      return;
    }

    const target = preOpCases.find(
      (surgery) =>
        surgery.id ===
        incomingHighlightId,
    );

    if (!target) return;

    highlightHandledRef.current =
      incomingHighlightId;

    setSearch("");
    setSelectedDoctors([]);
    setSelectedStatuses([]);
    setPeriod("Day");

    const rawDate =
      getDateSortValue(target);

    if (rawDate) {
      const date = new Date(
        String(rawDate).length === 10
          ? `${rawDate}T00:00:00`
          : String(rawDate),
      );

      if (
        !Number.isNaN(
          date.getTime(),
        )
      ) {
        setSelectedDate(
          [
            date.getFullYear(),
            String(
              date.getMonth() + 1,
            ).padStart(2, "0"),
            String(
              date.getDate(),
            ).padStart(2, "0"),
          ].join("-"),
        );
      }
    }

    setHighlightedRowId(
      incomingHighlightId,
    );

    const timer =
      window.setTimeout(() => {
        setHighlightedRowId(null);
      }, 3500);

    return () =>
      window.clearTimeout(timer);
  }, [
    incomingHighlightId,
    preOpCases,
  ]);

  useEffect(() => {
    if (!highlightedRowId) return;

    const rowIndex =
      sortedCases.findIndex(
        (surgery) =>
          surgery.id ===
          highlightedRowId,
      );

    if (rowIndex >= 0) {
      setPage(
        Math.floor(
          rowIndex / pageSize,
        ),
      );
    }
  }, [
    highlightedRowId,
    sortedCases,
    pageSize,
  ]);

  useEffect(() => {
    surgeries.forEach(
      (surgery) => {
        const id = String(
          surgery.id ?? "",
        );

        if (!id) return;

        localStorage.removeItem(
          `intra-op-notes-${id}`,
        );

        const key =
          `pre-op-progress-${id}`;

        const raw =
          localStorage.getItem(key);

        if (!raw) return;

        try {
          const parsed =
            JSON.parse(raw);

          localStorage.setItem(
            key,
            JSON.stringify({
              completedTests:
                Array.isArray(
                  parsed.completedTests,
                )
                  ? parsed.completedTests
                  : [],
              completedAssessment:
                Array.isArray(
                  parsed.completedAssessment,
                )
                  ? parsed.completedAssessment
                  : [],
              anesthesia:
                typeof parsed.anesthesia ===
                "string"
                  ? parsed.anesthesia
                  : "",
            }),
          );
        } catch {
          localStorage.removeItem(key);
        }
      },
    );
  }, [surgeries]);

  useEffect(() => {
    setPage(0);
  }, [
    search,
    selectedDoctors,
    selectedStatuses,
    selectedDate,
    period,
  ]);

  useEffect(() => {
    if (
      page >
      totalPages - 1
    ) {
      setPage(
        Math.max(
          0,
          totalPages - 1,
        ),
      );
    }
  }, [
    page,
    totalPages,
  ]);

  useEffect(() => {
    if (!toast) return;

    const timer = window.setTimeout(
      () => setToast(null),
      3500,
    );

    return () =>
      window.clearTimeout(timer);
  }, [toast]);


  useEffect(() => {
    if (!incomingPreOpToast) return;

    setToast(incomingPreOpToast);

    // Consume the flash message so refreshing / revisiting the list
    // does not show the same success notification again.
    navigate(location.pathname, {
      replace: true,
      state: null,
    });
  }, [
    incomingPreOpToast,
    location.pathname,
    navigate,
  ]);

  function handleSort(
    key: SortKey,
  ) {
    if (sortKey === key) {
      setSortDirection(
        (current) =>
          current === "asc"
            ? "desc"
            : "asc",
      );

      return;
    }

    setSortKey(key);
    setSortDirection("asc");
  }

  function toggleDoctor(
    doctor: string,
  ) {
    setSelectedDoctors(
      (current) =>
        current.includes(
          doctor,
        )
          ? current.filter(
              (item) =>
                item !== doctor,
            )
          : [
              ...current,
              doctor,
            ],
    );
  }

  function toggleStatus(
    status: string,
  ) {
    setSelectedStatuses(
      (current) =>
        current.includes(
          status,
        )
          ? current.filter(
              (item) =>
                item !== status,
            )
          : [
              ...current,
              status,
            ],
    );
  }

  function clearFilters() {
    setSelectedDoctors([]);
    setSelectedStatuses([]);
    setPeriod("Day");
    setSelectedDate(
      "2026-09-03",
    );
  }













  function persistWorkspace() {
    if (!selectedId) return;

    localStorage.setItem(
      `pre-op-progress-${selectedId}`,
      JSON.stringify({
        completedTests,
        preOpReview,
        anesthesiaReview,
        anesthesiaExam,
        anesthesia,
      }),
    );

    /*
     * Keep intra-op notes for this browser-page session only.
     * They are not written to localStorage.
     */
    transientWorkspaceRef.current[
      selectedId
    ] = {
      notes,
    };

    localStorage.setItem(
      `pre-op-safety-${selectedId}`,
      JSON.stringify({
        ...safety,
        acknowledged: false,
      }),
    );

    localStorage.setItem(
      `pre-op-supplies-${selectedId}`,
      JSON.stringify({
        required: requiredSupplies,
        additional: additionalSupplies,
      }),
    );

    localStorage.removeItem(
      `intra-op-notes-${selectedId}`,
    );
  }

  function selectPatient(id: string) {
    const surgery = surgeries.find((item) => item.id === id);
    if (!surgery) return;

    if (
      surgery.status !== "Pre-Op" &&
      surgery.status !== "Ready"
    ) {
      return;
    }

    navigate(`/pre-op/${id}`);
  }

  function confirmAdmission() {
    if (!admitCandidate) return;

    admitPatient(admitCandidate.id);
    setAdmitCandidateId(null);

    setToast({
      type: "success",
      title: "Patient admitted",
      message: `${getPatientName(admitCandidate)} is now inside the OR section. Pre-Op can be started.`,
    });
  }

  function beginPreOp(id: string) {
    startPreOp(id);

    const latest = useSurgeryStore
      .getState()
      .surgeries.find((item) => item.id === id);

    if (latest?.status === "Pre-Op") {
      setToast({
        type: "success",
        title: "Pre-Op started",
        message: `${getPatientName(latest)} is ready for the Pre-Op assessment.`,
      });

      navigate(`/pre-op/${id}`);
    }
  }















  useEffect(() => {
    if (!selectedId) return;

    const timer =
      window.setTimeout(() => {
        persistWorkspace();
      }, 300);

    return () =>
      window.clearTimeout(timer);
  }, [
    selectedId,
    completedTests,
    preOpReview,
    anesthesiaReview,
    anesthesiaExam,
    anesthesia,
    safety,
    requiredSupplies,
    additionalSupplies,
    notes,
  ]);

  const readyCasesCount = preOpCases.filter((item) => item.status === "Ready").length;
  const activePreOpCount = preOpCases.filter((item) => item.status === "Pre-Op").length;
  const paidCasesCount = preOpCases.filter((item) => item.paymentStatus === "Paid").length;
  const anesthesiaRecordedCount = preOpCases.filter((item) =>
    Boolean(item.anesthesiaType),
  ).length;

  return (
    <div className="h-[calc(100vh-72px)] min-h-0 overflow-hidden bg-slate-50 p-2">
      <div className="flex h-full min-h-0 flex-col gap-2">
        <section data-responsive-grid="4" className="grid shrink-0 grid-cols-4 gap-2">
          <ModuleStatCard
            label="In Pre-Op"
            value={activePreOpCount}
            icon={<Activity size={15} />}
            tone="blue"
          />
          <ModuleStatCard
            label="Ready"
            value={readyCasesCount}
            icon={<CheckCircle2 size={15} />}
            tone="green"
          />
          <ModuleStatCard
            label="Payment Cleared"
            value={paidCasesCount}
            icon={<Receipt size={15} />}
            tone="indigo"
          />
          <ModuleStatCard
            label="Anesthesia Recorded"
            value={anesthesiaRecordedCount}
            icon={<Syringe size={15} />}
            tone="violet"
          />
        </section>
        {/* PATIENT LIST */}
        <div className="relative min-h-0 flex-1">
          <section className="flex h-full min-h-0 flex-col overflow-visible rounded-xl border border-slate-200 bg-white">
            {/* LIST HEADER */}
            <div className="flex min-h-[58px] shrink-0 items-center justify-between gap-4 border-b border-slate-100 px-4 py-2.5">
              <div>
                <h2 className="text-[12px] font-semibold text-slate-800">
                  Pre-Op Patients
                </h2>

                <p className="mt-0.5 text-[10px] text-slate-400">
                  All surgery patients remain visible; Pre-Op actions are enabled only when the workflow reaches this module
                </p>
              </div>

              <div className="flex items-center gap-2">
                <div className="relative w-[260px]">
                  <Search
                    size={14}
                    className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
                  />

                  <input
                    value={search}
                    onChange={(event) =>
                      setSearch(
                        event.target.value,
                      )
                    }
                    placeholder="Search patient, ID or procedure..."
                    className="h-7 w-full rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 !text-[11px] text-slate-700 outline-none transition placeholder:text-slate-400 focus:border-blue-300 focus:bg-white focus:ring-2 focus:ring-blue-50"
                  />
                </div>

                <div ref={filterRef} className="relative">
                  <button
                    type="button"
                    onClick={() =>
                      setFilterOpen(
                        (current) =>
                          !current,
                      )
                    }
                    className={`inline-flex h-7 items-center gap-1.5 rounded-lg border px-2.5 !text-[11px] font-semibold transition ${
                      filterOpen ||
                      selectedDoctors.length > 0 ||
                      selectedStatuses.length > 0 ||
                      period !== "Day"
                        ? "border-blue-200 bg-blue-50 text-blue-700"
                        : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                    }`}
                  >
                    <Filter size={12} />
                    Filters

                    {(selectedDoctors.length +
                      selectedStatuses.length +
                      (period !== "Day" ? 1 : 0)) >
                      0 && (
                      <span className="flex h-4 min-w-4 items-center justify-center rounded-full bg-blue-600 px-1 text-[7px] font-bold text-white">
                        {selectedDoctors.length +
                          selectedStatuses.length +
                          (period !== "Day"
                            ? 1
                            : 0)}
                      </span>
                    )}

                    <ChevronDown
                      size={11}
                    />
                  </button>

                  {filterOpen && (
                    <div className="absolute right-0 top-[calc(100%+6px)] z-30 w-[350px] rounded-xl border border-slate-200 bg-white p-3 shadow-[0_12px_32px_rgba(15,23,42,0.14)]">
                      <div className="mb-2.5 flex items-center justify-between">
                        <div>
                          <p className="text-[10px] font-semibold text-slate-700">
                            Table Filters
                          </p>

                          <p className="mt-0.5 text-[9px] text-slate-500">
                            Refine the Pre-Op patient list
                          </p>
                        </div>

                        <button
                          type="button"
                          onClick={
                            clearFilters
                          }
                          className="text-[8px] font-semibold text-blue-600 hover:text-blue-700"
                        >
                          Clear all
                        </button>
                      </div>

                      <div className="mb-3">
                        <p className="mb-1.5 text-[8px] font-semibold uppercase tracking-wide text-slate-400">
                          Doctor
                        </p>

                        <div className="flex flex-wrap gap-1.5">
                          {doctors.map(
                            (doctor) => (
                              <FilterPill
                                key={
                                  doctor
                                }
                                label={
                                  doctor
                                }
                                active={selectedDoctors.includes(
                                  doctor,
                                )}
                                onClick={() =>
                                  toggleDoctor(
                                    doctor,
                                  )
                                }
                              />
                            ),
                          )}
                        </div>
                      </div>

                      <div className="mb-3">
                        <p className="mb-1.5 text-[8px] font-semibold uppercase tracking-wide text-slate-400">
                          Status
                        </p>

                        <div className="flex flex-wrap gap-1.5">
                          {statuses.map(
                            (status) => (
                              <FilterPill
                                key={
                                  status
                                }
                                label={
                                  status
                                }
                                active={selectedStatuses.includes(
                                  status,
                                )}
                                onClick={() =>
                                  toggleStatus(
                                    status,
                                  )
                                }
                              />
                            ),
                          )}
                        </div>
                      </div>

                      <div>
                        <p className="mb-1.5 text-[8px] font-semibold uppercase tracking-wide text-slate-400">
                          Surgery Date
                        </p>

                        <div data-responsive-grid="2" className="grid grid-cols-[1fr_135px] gap-2">
                          <div className="flex h-7 items-center rounded-lg border text-[11px] border-slate-200 bg-slate-50 p-0.5">
                            {(
                              [
                                "Day",
                                "Week",
                                "Month",
                              ] as Period[]
                            ).map(
                              (item) => (
                                <button
                                  key={
                                    item
                                  }
                                  type="button"
                                  onClick={() =>
                                    setPeriod(
                                      item,
                                    )
                                  }
                                  className={`h-6 flex-1 rounded-md text-[8px] font-semibold transition ${
                                    period ===
                                    item
                                      ? "bg-white text-blue-600 shadow-sm"
                                      : "text-slate-400 hover:text-slate-600"
                                  }`}
                                >
                                  {
                                    item
                                  }
                                </button>
                              ),
                            )}
                          </div>

                          <ModernPreOpDatePicker
