                                  hour: "numeric",
                                  minute: "2-digit",
                                },
                              )}
                            </span>
                          </div>

                          <p className="mt-0.5 line-clamp-2 !text-[12px] leading-3.5 text-slate-600">
                            {note.text}
                          </p>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            )}

              </div>
            </div>
          </section>

        </div>

      )}

    </div>
                  </div>
                </div>

                {/* =====================================================
                    BOTTOM ACTION BAR — COMPACT
                ====================================================== */}

                <div
                  className={`col-start-2 row-start-2 flex h-[44px] min-w-0 items-center justify-between gap-3 rounded-xl border bg-white px-3 shadow-[0_1px_2px_rgba(15,23,42,0.03)] ${
                    activeTab === "anesthesia"
                      ? "border-purple-100"
