import { useNavigate, useLocation, useParams } from "react-router-dom";
import { useSurgeryStore } from "../store/surgeryStore";
import { useState, useMemo, useEffect, useRef } from "react";
import { type PatientStatus, type Patient, type ReceptionProcedure, type Period, type SortKey, type SortDirection, type ReceptionToastType, type ConsentFormDetails, type ReceptionConsentApproval, type AdmissionFormItem, type SignerRole } from "../features/workspaces/ReceptionDetails/types";
import { initialReceptionStatus, receptionDemographics, admissionFormItems, PAGE_SIZE, checklistItems } from "../features/workspaces/ReceptionDetails/config";
import { getSurgeryProcedures } from "../components/surgery/SurgeryPresentation";
import { getSharedReceptionStatus, showReceptionToast, createAdmissionFormsState, createConsentApproval, createConsentFormDetails, isConsentFormComplete, isDateInPeriod, getInitials, formatSurgeryDate } from "../features/workspaces/ReceptionDetails/utils";
import { IdCard, ArrowLeft, CalendarDays, UserCheck, CheckCircle2, AlertTriangle, Search, Filter, ChevronDown, Stethoscope, Clock3, ChevronRight, ChevronLeft, ShieldCheck, FileCheck2, Printer, X } from "lucide-react";
import { WorkflowStep, SummaryCard, ReceptionDatePicker, SortHeader, StatusBadge, ChecklistRow, ReceptionCompletedPanel } from "../features/workspaces/ReceptionDetails/components";
import { ReceptionPrintouts } from "../components/surgery/ReceptionPrintouts";


export default function ReceptionDetails() {
  const navigate = useNavigate();
  const location = useLocation();

  const surgeries = useSurgeryStore((state) => state.surgeries);
  const markArrivedInStore = useSurgeryStore((state) => state.markArrived);
  const sendToCashierInStore = useSurgeryStore(
    (state) => state.sendToCashier
  );

  // Reception-only workflow state (Expected / Arrived / Reception In
  // Progress / Reception Checked / On Hold) and arrival time/issues -
  // these don't live on the shared Surgery record, only the final
  // "sent to cashier" hand-off does (via sendToCashierInStore below).
  const [receptionStatus, setReceptionStatus] = useState<
    Record<string, PatientStatus>
  >(() => ({ ...initialReceptionStatus }));

  const [arrivalTimes, setArrivalTimes] = useState<Record<string, string>>(
    {}
  );

  const [issuesById, setIssuesById] = useState<Record<string, string[]>>({});

  const patients: Patient[] = useMemo(
    () =>
      surgeries.map((surgery) => {
        const demo = receptionDemographics[surgery.id] ?? {
          mrn: `MRN-${surgery.id}`,
          age: 0,
          gender: "Female" as const,
        };

        const surgeryMeta = surgery as any;
        const fallbackSitesRaw =
          surgeryMeta.procedureSites ??
          surgeryMeta.sites ??
          surgeryMeta.procedureSide;

        const fallbackSites: string[] = Array.isArray(fallbackSitesRaw)
          ? fallbackSitesRaw
              .map((value: unknown) =>
                typeof value === "string" ? value : "",
              )
              .filter(Boolean)
          : typeof fallbackSitesRaw === "string"
            ? fallbackSitesRaw
                .split(",")
                .map((value: string) => value.trim())
                .filter(Boolean)
            : [];

        const receptionProcedures: ReceptionProcedure[] =
          getSurgeryProcedures(surgery).map((item: any, index: number) => ({
            name: String(item?.name ?? "Procedure"),
            site:
              typeof item?.site === "string"
                ? item.site
                : typeof item?.side === "string"
                  ? item.side
                  : typeof item?.location === "string"
                    ? item.location
                    : typeof item?.bodySite === "string"
                      ? item.bodySite
                      : fallbackSites[index] ?? fallbackSites[0],
          }));

        return {
          id: surgery.id,
          mrn: surgery.mrn || demo.mrn,
          name: surgery.patientName,
          age: demo.age,
          gender: demo.gender,
          procedure: surgery.procedure,
          procedures: receptionProcedures,
          surgeon: surgery.doctor,
          date: surgery.date,
          time: surgery.time,
          status:
            getSharedReceptionStatus(surgery) ??
            receptionStatus[surgery.id] ??
            initialReceptionStatus[surgery.id] ??
            "Expected",
          arrivalTime:
            arrivalTimes[surgery.id],
          issues: issuesById[surgery.id],
        };
      }),
    [surgeries, receptionStatus, arrivalTimes, issuesById]
  );

  const { id } = useParams<{ id: string }>();
  const [selectedIdState, setSelectedId] = useState(id ?? "");
  const selectedId = id ?? selectedIdState;

  useEffect(() => {
    // Remove Reception progress saved by older versions of this page.
    // The current prototype intentionally resets ReceptionDetails on refresh.
    try {
      localStorage.removeItem("surgery-reception-status");

      if (selectedId) {
        localStorage.removeItem(
          `reception-details-${selectedId}`,
        );
      }
    } catch {
      // Ignore storage access errors.
    }
  }, [selectedId]);

  useEffect(() => {
    if (id) setSelectedId(id);
  }, [id]);
  const [search, setSearch] = useState("");
  const [highlightSurgeryId, setHighlightSurgeryId] =
    useState<string | null>(null);

  const handledIncomingSurgeryRef = useRef<string | null>(null);

  const [showOnlyArrived, setShowOnlyArrived] = useState(false);
  const [filterOpen, setFilterOpen] = useState(false);
  const [selectedDoctors, setSelectedDoctors] = useState<string[]>([]);
  const [selectedStatuses, setSelectedStatuses] = useState<PatientStatus[]>([]);
  const [period, setPeriod] = useState<Period>("Month");
  const [selectedDate, setSelectedDate] = useState("2026-09-03");
  const [sortKey, setSortKey] = useState<SortKey>("time");
  const [sortDirection, setSortDirection] = useState<SortDirection>("asc");
  const [page, setPage] = useState(0);
  const [showHoldModal, setShowHoldModal] = useState(false);
  const [holdReason, setHoldReason] = useState("");

  useEffect(() => {
    const routeState = location.state as
      | {
          highlightSurgeryId?: string;
          receptionToast?: {
            type?: ReceptionToastType;
            title?: string;
            message?: string;
          };
        }
      | null;

    const incomingId = routeState?.highlightSurgeryId;

    if (!incomingId) return;

    // React StrictMode / patient-store updates can cause this effect to run
    // more than once. Handle each incoming case only once so the toast is
    // never duplicated.
    if (handledIncomingSurgeryRef.current === incomingId) {
      return;
    }

    const patient = patients.find(
      (item) => item.id === incomingId,
    );

    if (!patient) return;

    handledIncomingSurgeryRef.current = incomingId;

    // Reset table controls so the transferred patient is guaranteed to be
    // visible, then pin it to the first row for the short hand-off highlight.
    setSearch("");
    setShowOnlyArrived(false);
    setSelectedDoctors([]);
    setSelectedStatuses([]);
    setPeriod("Month");
    setSelectedDate(patient.date);
    setSortKey("time");
    setSortDirection("asc");
    setPage(0);
    setHighlightSurgeryId(incomingId);

    if (routeState?.receptionToast) {
      showReceptionToast(
        routeState.receptionToast.type ?? "success",
        routeState.receptionToast.title ??
          "Surgery booked successfully",
        routeState.receptionToast.message ??
          "The patient was moved to Reception.",
      );
    } else {
      showReceptionToast(
        "success",
        "Surgery booked successfully",
        "The patient was moved to Reception.",
      );
    }

    const glowTimer = window.setTimeout(() => {
      setHighlightSurgeryId((current) =>
        current === incomingId ? null : current,
      );
    }, 2000);

    // Clear React Router navigation state immediately so refresh or later
    // renders cannot replay the transfer toast.
    navigate(
      location.pathname + location.search,
      {
        replace: true,
        state: null,
      },
    );

  return () => {
      window.clearTimeout(glowTimer);
    };
  }, [
    location.pathname,
    location.search,
    location.state,
    navigate,
    patients,
  ]);


  const [checkedItems, setCheckedItems] = useState<Record<string, boolean>>({
    identity: true,
    procedure: true,
    consent: false,
    fasting: true,
    belongings: false,
    contact: true,
    wristband: false,
  });

  const [admissionFormsById, setAdmissionFormsById] = useState<
    Record<string, Record<string, boolean>>
  >({});

  const [consentDetailsById, setConsentDetailsById] = useState<
    Record<
      string,
      Record<string, ConsentFormDetails>
    >
  >({});

  const [consentApprovalById, setConsentApprovalById] = useState<
    Record<string, ReceptionConsentApproval>
  >({});

  const [showPrintCenter, setShowPrintCenter] = useState(false);
  const [highlightedMissing, setHighlightedMissing] = useState<string[]>([]);
  const missingHighlightTimerRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (missingHighlightTimerRef.current !== null) {
        window.clearTimeout(missingHighlightTimerRef.current);
      }
    };
  }, []);

  const selectedSurgery = surgeries.find((surgery) => surgery.id === selectedId);

  const selectedPatient = patients.find(
    (patient) => patient.id === selectedId,
  );

  useEffect(() => {
    if (!selectedPatient) return;

    const originalStatus =
      initialReceptionStatus[
        selectedPatient.id
      ] ?? "Expected";

    // Always rebuild the ReceptionDetails workspace from the original
    // Reception state when this page mounts / the selected patient changes.
    if (
      originalStatus ===
        "Ready for Admission" ||
      originalStatus ===
        "Sent to Cashier"
    ) {
      setCheckedItems({
        identity: true,
        procedure: true,
        consent: true,
        fasting: true,
        belongings: true,
        contact: true,
        wristband: true,
      });

      setAdmissionFormsById((current) => ({
        ...current,
        [selectedPatient.id]:
          createAdmissionFormsState(true),
      }));
    } else {
      setCheckedItems({
        identity: false,
        procedure: false,
        consent: false,
        fasting: false,
        belongings: false,
        contact: false,
        wristband: false,
      });

      setAdmissionFormsById((current) => ({
        ...current,
        [selectedPatient.id]:
          createAdmissionFormsState(false),
      }));

      setConsentDetailsById((current) => ({
        ...current,
        [selectedPatient.id]: {},
      }));

      setConsentApprovalById((current) => ({
        ...current,
        [selectedPatient.id]:
          createConsentApproval(),
      }));
    }

    setArrivalTimes((current) => {
      const next = { ...current };
      delete next[selectedPatient.id];
      return next;
    });

    setIssuesById((current) => {
      const next = { ...current };
      delete next[selectedPatient.id];
      return next;
    });

    setShowPrintCenter(false);
    setShowHoldModal(false);
    setHoldReason("");
  }, [selectedPatient?.id]);


  const admissionForms = selectedPatient
    ? admissionFormsById[selectedPatient.id] ??
      createAdmissionFormsState(
        selectedPatient.status === "Ready for Admission" ||
          selectedPatient.status === "Sent to Cashier",
      )
    : createAdmissionFormsState(false);

  const requiredAdmissionForms = admissionFormItems.filter(
    (item) =>
      item.fields.some(
        (field) => field.required,
      ),
  );

  const completedAdmissionForms = requiredAdmissionForms.filter(
    (item) => admissionForms[item.id],
  ).length;

  const consentDetails = selectedPatient
    ? consentDetailsById[selectedPatient.id] ?? {}
    : {};

  const consentApproval = selectedPatient
    ? consentApprovalById[selectedPatient.id] ??
      createConsentApproval()
    : createConsentApproval();

  const approvalReady = Boolean(
    consentApproval.signerName.trim(),
  );


  const allAdmissionFormsComplete =
    completedAdmissionForms ===
    requiredAdmissionForms.length;

  const setConsentApprovalField = <
    Key extends keyof ReceptionConsentApproval,
  >(
    key: Key,
    value: ReceptionConsentApproval[Key],
  ) => {
    if (!selectedPatient) return;

    setConsentApprovalById((current) => ({
      ...current,
      [selectedPatient.id]: {
        ...(current[selectedPatient.id] ??
          createConsentApproval()),
        [key]: value,
      },
    }));
  };

  const getConsentDetails = (
    item: AdmissionFormItem,
  ) => {
    const base =
      createConsentFormDetails(item);

    const saved =
      consentDetails[item.id];

    if (!saved) return base;

    return {
      ...base,
      ...saved,
      values: {
        ...base.values,
        ...(saved.values ?? {}),
      },
      answers: {
        ...base.answers,
        ...(saved.answers ?? {}),
      },
    };
  };

  const updateConsentField = (
    item: AdmissionFormItem,
    fieldId: string,
    value: string,
  ) => {
    if (!selectedPatient) return;

    const currentDetails =
      getConsentDetails(item);

    const nextDetails: ConsentFormDetails = {
      ...currentDetails,
      values: {
        ...currentDetails.values,
        [fieldId]: value,
      },
    };

    const formComplete =
      isConsentFormComplete(
        item,
        nextDetails,
      );

    setConsentDetailsById((current) => ({
      ...current,
      [selectedPatient.id]: {
        ...(current[selectedPatient.id] ?? {}),
        [item.id]: {
          ...nextDetails,
          completedAt: formComplete
            ? new Date().toISOString()
            : undefined,
        },
      },
    }));

    setAdmissionFormsById((current) => ({
      ...current,
      [selectedPatient.id]: {
        ...(current[selectedPatient.id] ??
          createAdmissionFormsState(false)),
        [item.id]: formComplete,
      },
    }));
  };


  const availableDoctors = useMemo(
    () => Array.from(new Set(patients.map((patient) => patient.surgeon))),
    [patients],
  );

  const availableStatuses: PatientStatus[] = [
    "Expected",
    "Arrived",
    "Reception In Progress",
    "Ready for Admission",
    "Sent to Cashier",
    "On Hold",
  ];

  const filteredPatients = useMemo(() => {
    const query = search.trim().toLowerCase();

    const filtered = patients.filter((patient) => {
      const matchesSearch =
        !query ||
        patient.name.toLowerCase().includes(query) ||
        patient.mrn.toLowerCase().includes(query) ||
        patient.procedures.some(
          (procedure) =>
            procedure.name.toLowerCase().includes(query) ||
            (procedure.site ?? "").toLowerCase().includes(query),
        );

      const matchesArrived = showOnlyArrived
        ? patient.status !== "Expected"
        : true;

      const matchesDoctor =
        selectedDoctors.length === 0 ||
        selectedDoctors.includes(patient.surgeon);

      const matchesStatus =
        selectedStatuses.length === 0 ||
        selectedStatuses.includes(patient.status);

      const matchesDate = isDateInPeriod(
        patient.date,
        selectedDate,
        period,
      );

      return (
        matchesSearch &&
        matchesArrived &&
        matchesDoctor &&
        matchesStatus &&
        matchesDate
      );
    });

    const sorted = [...filtered].sort((a, b) => {
      const getValue = (patient: Patient) => {
        switch (sortKey) {
          case "name":
            return patient.name;
          case "case":
            return patient.id;
          case "mrn":
            return patient.mrn;
          case "procedures":
            return patient.procedures
              .map((procedure) =>
                `${procedure.name} ${procedure.site ?? ""}`.trim(),
              )
              .join(" ");
          case "surgeon":
            return patient.surgeon;
          case "date":
            return patient.date;
          case "time":
            return patient.time;
          case "status":
            return patient.status;
        }
      };

      const first = String(getValue(a)).toLowerCase();
      const second = String(getValue(b)).toLowerCase();
      const comparison = first.localeCompare(second, undefined, {
        numeric: true,
      });

      return sortDirection === "asc" ? comparison : -comparison;
    });

    if (!highlightSurgeryId) {
      return sorted;
    }

    return [
      ...sorted.filter(
        (patient) => patient.id === highlightSurgeryId,
      ),
      ...sorted.filter(
        (patient) => patient.id !== highlightSurgeryId,
      ),
    ];
  }, [
    patients,
    search,
    showOnlyArrived,
    selectedDoctors,
    selectedStatuses,
    period,
    selectedDate,
    sortKey,
    sortDirection,
    highlightSurgeryId,
  ]);

  const totalPages = Math.max(
    1,
    Math.ceil(filteredPatients.length / PAGE_SIZE),
  );

  const paginatedPatients = useMemo(
    () =>
      filteredPatients.slice(
        page * PAGE_SIZE,
        page * PAGE_SIZE + PAGE_SIZE,
      ),
    [filteredPatients, page],
  );

  const handleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortDirection((current) => (current === "asc" ? "desc" : "asc"));
    } else {
      setSortKey(key);
      setSortDirection("asc");
    }
    setPage(0);
  };

  const toggleDoctorFilter = (doctor: string) => {
    setSelectedDoctors((current) =>
      current.includes(doctor)
        ? current.filter((item) => item !== doctor)
        : [...current, doctor],
    );
    setPage(0);
  };

  const toggleStatusFilter = (status: PatientStatus) => {
    setSelectedStatuses((current) =>
      current.includes(status)
        ? current.filter((item) => item !== status)
        : [...current, status],
    );
    setPage(0);
  };

  const clearTableFilters = () => {
    setSelectedDoctors([]);
    setSelectedStatuses([]);
    setPeriod("Month");
    setSelectedDate("2026-09-03");
    setPage(0);
  };


  const completedCount = checklistItems.filter(
    (item) => checkedItems[item.id],
  ).length;

  const allChecked = completedCount === checklistItems.length;

  const receptionReady =
    allChecked &&
    allAdmissionFormsComplete &&
    approvalReady;

  const isMissingHighlighted = (key: string) =>
    highlightedMissing.includes(key);

  const expectedCount = patients.filter(
    (patient) => patient.status === "Expected",
  ).length;

  const arrivedCount = patients.filter(
    (patient) =>
      patient.status === "Arrived" ||
      patient.status === "Reception In Progress",
  ).length;

  const readyCount = patients.filter(
    (patient) => patient.status === "Ready for Admission",
  ).length;

  const holdCount = patients.filter(
    (patient) => patient.status === "On Hold",
  ).length;

  const selectPatient = (patient: Patient) => {
    setSelectedId(patient.id);
    setShowPrintCenter(false);

    setAdmissionFormsById((current) => {
      if (current[patient.id]) return current;

      const complete =
        patient.status === "Ready for Admission" ||
        patient.status === "Sent to Cashier";

      return {
        ...current,
        [patient.id]: createAdmissionFormsState(complete),
      };
    });

    if (
      patient.status === "Reception In Progress"
    ) {
      setCheckedItems({
        identity: true,
        procedure: true,
        consent: false,
        fasting: true,
        belongings: false,
        contact: true,
        wristband: false,
      });
    } else if (
      patient.status === "Ready for Admission" ||
      patient.status === "Sent to Cashier"
    ) {
      setCheckedItems({
        identity: true,
        procedure: true,
        consent: true,
        fasting: true,
        belongings: true,
        contact: true,
        wristband: true,
      });
    } else {
      setCheckedItems({
        identity: false,
        procedure: false,
        consent: false,
        fasting: false,
        belongings: false,
        contact: false,
        wristband: false,
      });
    }
  };

  const markPatientArrived = () => {
    if (!selectedPatient) return;

    const time = new Date().toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    });

    setReceptionStatus((current) => ({
      ...current,
      [selectedPatient.id]: "Reception In Progress",
    }));

    setArrivalTimes((current) => ({
      ...current,
      [selectedPatient.id]: time,
    }));

    // Timestamp the real surgery record so other pages (Cashier, etc.)
    // can show that the patient has physically arrived.
    markArrivedInStore(selectedPatient.id);

    setCheckedItems({
      identity: true,
      procedure: true,
      consent: false,
      fasting: true,
      belongings: false,
      contact: true,
      wristband: false,
    });
  };

  const completeReception = () => {
    if (!selectedPatient) return;

    const missingChecklistItems = checklistItems.filter(
      (item) => !checkedItems[item.id],
    );

    const missingChecklist = missingChecklistItems.map(
      (item) => item.label,
    );

    const missingConsentFields: string[] = [];
    const missingHighlightKeys: string[] = missingChecklistItems.map(
      (item) => `checklist:${item.id}`,
    );

    requiredAdmissionForms.forEach((item) => {
      const details = getConsentDetails(item);

      item.fields
        .filter((field) => field.required)
        .forEach((field) => {
          const value = details.values[field.id];

          if (!value?.trim()) {
            missingConsentFields.push(
              `${item.shortLabel}: ${field.label}`,
            );
            missingHighlightKeys.push(`field:${field.id}`);
          }
        });
    });

    const missingApproval: string[] = [];

    if (!consentApproval.signerName.trim()) {
      missingApproval.push("Signer name");
      missingHighlightKeys.push("approval:signerName");
    }

    const missingSections: string[] = [];

    if (missingChecklist.length > 0) {
      missingSections.push(
        `Eligibility: ${missingChecklist.join(", ")}`,
      );
    }

    if (missingConsentFields.length > 0) {
      missingSections.push(
        `Consent fields: ${missingConsentFields.join(", ")}`,
      );
    }

    if (missingApproval.length > 0) {
      missingSections.push(
        `Approval: ${missingApproval.join(", ")}`,
      );
    }

    if (missingSections.length > 0) {
      setHighlightedMissing(missingHighlightKeys);

      if (missingHighlightTimerRef.current !== null) {
        window.clearTimeout(missingHighlightTimerRef.current);
      }

      missingHighlightTimerRef.current = window.setTimeout(() => {
        setHighlightedMissing([]);
        missingHighlightTimerRef.current = null;
      }, 2400);

      showReceptionToast(
        "warning",
        "Reception is not complete",
        `Please complete the following before continuing:

${missingSections.join(
          "\n",
        )}`,
      );

      return;
    }

    setHighlightedMissing([]);

    setReceptionStatus((current) => ({
      ...current,
      [selectedPatient.id]: "Ready for Admission",
    }));
  };

  const sendToCashier = () => {
    if (!selectedPatient) {
      showReceptionToast(
        "error",
        "Patient not sent",
        "Unable to send the patient to Cashier.",
      );
      return;
    }

    const patientId = selectedPatient.id;
    const patientName = selectedPatient.name;

    try {
      // Update the shared surgery record first.
      sendToCashierInStore(patientId);

      // Verify that the hand-off really happened before changing
      // the Reception-only visual state.
      const updatedSurgery = useSurgeryStore
        .getState()
        .surgeries.find((item) => item.id === patientId);

      if (
        !updatedSurgery ||
        updatedSurgery.status !== "Payment Pending"
      ) {
        throw new Error(
          "The patient could not be moved to the Cashier queue.",
        );
      }

      setReceptionStatus((current) => ({
        ...current,
        [patientId]: "Sent to Cashier",
      }));

      showReceptionToast(
        "success",
        "Admitted & sent to Cashier",
        `${patientName} was admitted and sent to Cashier successfully.`,
      );

      // Stay in Reception after the shared Cashier hand-off.
    } catch (error) {
      console.error("Send to Cashier failed:", error);

      showReceptionToast(
        "error",
        "Patient not sent",
        error instanceof Error
          ? error.message
          : "Something went wrong while sending the patient to Cashier.",
      );
    }
  };

  const holdPatient = () => {
  if (!selectedPatient || !holdReason.trim()) return;

  setReceptionStatus((current) => ({
    ...current,
    [selectedPatient.id]: "On Hold",
  }));

  setIssuesById((current) => ({
    ...current,
    [selectedPatient.id]: [holdReason.trim()],
  }));

  setHoldReason("");
  setShowHoldModal(false);
};

  const workflowActiveStep =
    selectedPatient?.status === "Expected"
      ? 1
      : selectedPatient?.status === "Ready for Admission"
        ? 3
        : selectedPatient?.status === "Sent to Cashier"
          ? 0
          : selectedPatient
            ? 2
            : 0;

  const arrivalCompleted =
    selectedPatient !== undefined &&
    selectedPatient.status !== "Expected";

  const eligibilityCompleted =
    selectedPatient?.status === "Ready for Admission" ||
    selectedPatient?.status === "Sent to Cashier";

  const cashierCompleted =
    selectedPatient?.status === "Sent to Cashier";

  if (!selectedPatient) {
    return (
      <div className="flex h-[calc(100vh-58px)] items-center justify-center bg-slate-50/60 p-4">
        <div className="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-6 text-center shadow-sm">
          <div className="mx-auto flex h-11 w-11 items-center justify-center rounded-xl bg-amber-50 text-amber-600">
            <IdCard size={18} />
          </div>
          <h2 className="mt-3 text-[13px] font-bold text-slate-800">Reception case not found</h2>
          <p className="mt-1 text-[9px] text-slate-400">This patient is not available in the current Reception queue.</p>
          <button
            type="button"
            onClick={() => navigate("/reception")}
            className="mt-4 inline-flex h-8 items-center gap-1.5 rounded-lg bg-amber-500 px-3 text-[9px] font-bold text-white hover:bg-amber-600"
          >
            <ArrowLeft size={12} />
            Back to Reception
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-[calc(100vh-58px)] min-h-0 flex-col gap-2 overflow-hidden bg-slate-50/60 p-2">
      {/* Header */}
      <section className="hidden">
        {/* Workflow */}
        <div className="px-4 py-2.5">
          <div className="flex items-center justify-between gap-4">
            <div className="flex min-w-0 items-center">
              <WorkflowStep
                number={1}
                label="Confirm Arrival"
                active={workflowActiveStep === 1}
                completed={arrivalCompleted}
              />

              <div className={`mx-3 h-px w-12 ${arrivalCompleted ? "bg-amber-300" : "bg-slate-200"}`} />

              <WorkflowStep
                number={2}
                label="Eligibility & Documents"
                active={workflowActiveStep === 2}
                completed={eligibilityCompleted}
              />

              <div className={`mx-3 h-px w-12 ${eligibilityCompleted ? "bg-amber-300" : "bg-slate-200"}`} />

              <WorkflowStep
                number={3}
                label="Send to Cashier"
                active={workflowActiveStep === 3}
                completed={cashierCompleted}
              />
            </div>

            <div className="flex shrink-0 items-center gap-2 text-[9px] text-slate-400">
              <CalendarDays size={13} />
              <span>Monday, September 7, 2026</span>
            </div>
          </div>
        </div>
      </section>

      {/* Summary */}
      <div className="hidden">
        <div data-responsive-grid="4" className="grid grid-cols-4 gap-2">
          <SummaryCard
            label="Expected Today"
            value={expectedCount}
            icon={CalendarDays}
            tone="orange"
          />

          <SummaryCard
            label="Arrived"
            value={arrivedCount}
            icon={UserCheck}
            tone="orange"
          />

          <SummaryCard
            label="Ready for Admission"
            value={readyCount}
            icon={CheckCircle2}
            tone="orange"
          />

          <SummaryCard
            label="On Hold"
            value={holdCount}
            icon={AlertTriangle}
            tone="orange"
          />
        </div>
      </div>

      {/* Main */}
      <div className="flex min-h-0 flex-1">
        {/* Patient Queue lives on the Reception list page */}
        <div className="hidden">
          {/* Queue Header */}
          <div className="shrink-0 border-b border-slate-100 px-3 py-2.5">
            <div className="flex items-center justify-between gap-3">
              <div>
                <h2 className="text-[11px] font-semibold text-slate-700">
                  Surgery Reception Queue
                </h2>
                <p className="mt-0.5 text-[9px] text-slate-400">
                  Patients scheduled for surgery
                </p>
              </div>

              <div className="flex items-center gap-2">
                <div className="relative">
                  <Search
                    size={13}
                    className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400"
                  />

                  <input
                    value={search}
                    onChange={(event) => {
                      setSearch(event.target.value);
                      setPage(0);
                    }}
                    placeholder="Search name, MRN or procedure..."
                    className="h-7 w-[270px] rounded-lg border border-slate-200 bg-slate-50 pl-8 pr-3 !text-[11px] font-medium text-slate-600 outline-none transition placeholder:text-slate-400 focus:border-amber-300 focus:bg-white focus:ring-1 focus:ring-amber-100"
                  />
                </div>

                <div className="relative">
                  <button
                    type="button"
                    onClick={() => setFilterOpen((value) => !value)}
                    className={`flex h-7 items-center gap-1.5 rounded-md border px-2.5 !text-[11px] font-semibold transition ${
                      selectedDoctors.length > 0 || selectedStatuses.length > 0
                        ? "border-amber-200 bg-amber-50 text-amber-700"
                        : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                    }`}
                  >
                    <Filter size={12} />
                    Filters
                    <ChevronDown size={11} />
                  </button>

                  {filterOpen && (
                    <div className="absolute right-0 top-[calc(100%+6px)] z-30 w-[310px] rounded-xl border border-slate-200 bg-white p-3 shadow-[0_12px_32px_rgba(15,23,42,0.14)]">
                      <div className="mb-3 flex items-center justify-between">
                        <div>
                          <p className="text-[10px] font-semibold text-slate-700">
                            Reception Filters
                          </p>
                          <p className="mt-0.5 text-[8px] text-slate-400">
                            Filter by doctor, status and date range
                          </p>
                        </div>

                        <button
                          type="button"
                          onClick={clearTableFilters}
                          className="text-[8px] font-semibold text-amber-700 hover:underline"
                        >
                          Clear all
                        </button>
                      </div>

                      <div>
                        <p className="mb-1.5 text-[8px] font-semibold uppercase tracking-wide text-slate-400">
                          Doctor
                        </p>
                        <div className="flex flex-wrap gap-1.5">
                          {availableDoctors.map((doctor) => {
                            const active = selectedDoctors.includes(doctor);
                            return (
                              <button
                                key={doctor}
                                type="button"
                                onClick={() => toggleDoctorFilter(doctor)}
                                className={`rounded-md border px-2 py-1 !text-[10px] font-semibold transition ${
                                  active
                                    ? "border-amber-200 bg-amber-50 text-amber-700"
                                    : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                                }`}
                              >
                                {doctor}
                              </button>
                            );
                          })}
                        </div>
                      </div>

                      <div className="mt-3">
                        <p className="mb-1.5 text-[8px] font-semibold uppercase tracking-wide text-slate-400">
                          Status
                        </p>
                        <div className="flex flex-wrap gap-1.5">
                          {availableStatuses.map((status) => {
                            const active = selectedStatuses.includes(status);
                            return (
                              <button
                                key={status}
                                type="button"
                                onClick={() => toggleStatusFilter(status)}
                                className={`rounded-md border px-2 py-1 !text-[10px] font-semibold transition ${
                                  active
                                    ? "border-amber-200 bg-amber-50 text-amber-700"
                                    : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                                }`}
                              >
                                {status}
                              </button>
                            );
                          })}
                        </div>
                      </div>

                      <div className="mt-3">
                        <p className="mb-1.5 text-[8px] font-semibold uppercase tracking-wide text-slate-400">
                          Date
                        </p>

                        <div className="flex items-center gap-2">
                          <div className="flex h-8 items-center rounded-md border border-slate-200 bg-slate-50 p-0.5">
                            {(["Day", "Week", "Month"] as Period[]).map((item) => (
                              <button
                                key={item}
                                type="button"
                                onClick={() => {
                                  setPeriod(item);
                                  setPage(0);
                                }}
                                className={`h-7 rounded-[5px] px-2 !text-[10px] font-semibold transition ${
                                  period === item
                                    ? "bg-white text-amber-700 shadow-sm"
                                    : "text-slate-500"
                                }`}
                              >
                                {item}
                              </button>
                            ))}
                          </div>

                          <ReceptionDatePicker
                            value={selectedDate}
                            onChange={(date) => {
                              setSelectedDate(date);
                              setPage(0);
                            }}
                          />
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* Table Header - Dashboard style */}
          <div data-responsive-table-header="true" className="grid shrink-0 grid-cols-[minmax(150px,1.25fr)_86px_94px_minmax(170px,1.35fr)_135px_105px_76px_128px] items-center border-b border-slate-100 bg-slate-50/80 px-3 py-1.5">
            <SortHeader
              label="Patient"
              sortKey="name"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />
            <SortHeader
              label="Case #"
              sortKey="case"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />
            <SortHeader
              label="MRN"
              sortKey="mrn"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />
            <SortHeader
              label="Procedure"
              sortKey="procedures"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />
            <SortHeader
              label="Surgeon"
              sortKey="surgeon"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />
            <SortHeader
              label="Date"
              sortKey="date"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />
            <SortHeader
              label="Time"
              sortKey="time"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />
            <SortHeader
              label="Status"
              sortKey="status"
              activeKey={sortKey}
              direction={sortDirection}
              onSort={handleSort}
            />
          </div>

          {/* Table Rows - same visual language as Dashboard */}
          <div className="min-h-0 flex-1 divide-y divide-slate-100 bg-white">
            {paginatedPatients.length === 0 ? (
              <div className="flex h-full items-center justify-center text-center">
                <div>
                  <Search size={18} className="mx-auto text-slate-300" />
                  <p className="mt-2 text-[10px] font-semibold text-slate-600">
                    No reception patients found
                  </p>
                  <p className="mt-1 text-[8px] text-slate-400">
                    Try changing your search or filters.
                  </p>
                </div>
              </div>
            ) : (
              paginatedPatients.map((patient, rowIndex) => {
                const selected = patient.id === selectedId;
                const primaryProcedure =
                  patient.procedures[0] ?? {
                    name: patient.procedure,
                    site: undefined,
                  };
                const extraProcedures = Math.max(
                  patient.procedures.length - 1,
                  0,
                );

                return (
                  <button data-responsive-table-row="true"
                    key={patient.id}
                    type="button"
                    onClick={() => selectPatient(patient)}
                    className={`group relative grid min-h-[48px] w-full grid-cols-[minmax(150px,1.25fr)_86px_94px_minmax(170px,1.35fr)_135px_105px_76px_128px] items-center px-3 py-1.5 text-left transition-all duration-300 ${
                      patient.id === highlightSurgeryId
                        ? "z-10 bg-amber-50/70 ring-1 ring-inset ring-amber-300 shadow-[0_0_14px_rgba(245,158,11,0.18)]"
                        : selected
                          ? "bg-amber-50/45"
                          : "bg-white hover:bg-slate-50/70"
                    }`}
                  >
                    <span  className="absolute bottom-1.5 left-0 top-1.5 w-[3px] rounded-r-full bg-amber-500" />

                    {/* Patient */}
                    <div data-cell-label="Patient"  className="flex min-w-0 items-center gap-2">
                      <div
                        className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-[9px] font-bold ${
                          selected
                            ? "bg-amber-500 text-white"
                            : "bg-amber-50 text-amber-700"
                        }`}
                      >
                        {getInitials(patient.name)}
                      </div>

                      <div className="min-w-0">
                        <p className="truncate text-[10px] font-semibold text-slate-800">
                          {patient.name}
                        </p>
                        <p className="mt-0.5 truncate text-[8.5px] font-medium text-slate-400">
                          {patient.age} yrs · {patient.gender}
                        </p>
                      </div>
                    </div>

                    {/* Case Number */}
                    <span data-cell-label="Case #"  className="truncate text-[10px] font-semibold text-amber-700">
                      {patient.id}
                    </span>

                    {/* MRN */}
                    <span data-cell-label="MRN"  className="truncate text-[10px] font-medium text-slate-500">
                      {patient.mrn}
                    </span>

                    {/* Procedure */}
                    <div data-cell-label="Procedure" className="group/procedures relative flex min-w-0 items-center gap-2 pr-3">
                      <div className="flex min-w-0 items-center gap-1">
                        <span className="truncate text-[10px] font-semibold text-slate-700">
                          {primaryProcedure.name}
                        </span>

                        {primaryProcedure.site && (
                          <>
                            <span className="shrink-0 text-[10px] text-slate-300">
                              •
                            </span>
                            <span className="truncate text-[9px] font-medium text-slate-400">
                              {primaryProcedure.site}
                            </span>
                          </>
                        )}
                      </div>

                      {extraProcedures > 0 && (
                        <>
                          <span className="shrink-0 cursor-default rounded-full bg-slate-100 px-2 py-0.5 text-[8px] font-bold text-slate-500 ring-1 ring-inset ring-slate-200">
                            +{extraProcedures}
                          </span>

                          <div
                            className={`pointer-events-none invisible absolute left-0 z-50 w-[290px] rounded-xl border border-slate-200 bg-white p-2.5 opacity-0 shadow-[0_12px_32px_rgba(15,23,42,0.16)] transition-all duration-150 group-hover/procedures:visible group-hover/procedures:translate-y-0 group-hover/procedures:opacity-100 ${
                              rowIndex >= paginatedPatients.length - 2
                                ? "bottom-[calc(100%+7px)] -translate-y-1"
                                : "top-[calc(100%+7px)] translate-y-1"
                            }`}
                          >
                            <div className="mb-2 flex items-center justify-between gap-2">
                              <div>
                                <p className="text-[9px] font-bold text-slate-700">
                                  All Procedures
                                </p>
                                <p className="mt-0.5 text-[8px] text-slate-400">
                                  Case {patient.id}
                                </p>
                              </div>

                              <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[8px] font-bold text-slate-500">
                                {patient.procedures.length}
                              </span>
                            </div>

                            <div className="space-y-1">
                              {patient.procedures.map((procedure, index) => (
                                <div
                                  key={`${patient.id}-hover-${procedure.name}-${procedure.site ?? index}`}
                                  className="flex items-center gap-2 rounded-lg bg-slate-50/80 px-2.5 py-1.5"
                                >
                                  <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-slate-100 text-[7px] font-bold text-slate-500">
                                    {index + 1}
                                  </span>
                                  <div className="flex min-w-0 flex-1 items-center gap-1">
                                    <span className="truncate text-[9px] font-semibold text-slate-700">
                                      {procedure.name}
                                    </span>

                                    {procedure.site && (
                                      <>
                                        <span className="shrink-0 text-[9px] text-slate-300">
                                          •
                                        </span>
                                        <span className="truncate text-[9px] font-medium text-slate-400">
                                          {procedure.site}
                                        </span>
                                      </>
                                    )}
                                  </div>
                                </div>
                              ))}
                            </div>
                          </div>
                        </>
                      )}
                    </div>

                    {/* Surgeon */}
                    <div data-cell-label="Surgeon" className="flex min-w-0 items-center gap-1.5 pr-3">
                      <Stethoscope size={11} className="shrink-0 text-slate-400" />
                      <span className="truncate text-[10px] font-medium text-slate-700">
                        {patient.surgeon}
                      </span>
                    </div>

                    {/* Date */}
                    <div data-cell-label="Date" className="flex min-w-0 items-center gap-1.5">
                      <CalendarDays size={11} className="shrink-0 text-slate-400" />
                      <span className="truncate text-[10px] font-medium text-slate-600">
                        {formatSurgeryDate(patient.date)}
                      </span>
                    </div>

                    {/* Time */}
                    <div data-cell-label="Time" className="flex items-center gap-1.5">
                      <Clock3 size={11} className="shrink-0 text-slate-400" />
                      <span className="text-[10.5px] font-semibold text-slate-800">
                        {patient.time}
                      </span>
                    </div>

                    {/* Status */}
                    <div data-cell-label="Status" className="flex min-w-0 items-center justify-between gap-2">
                      <StatusBadge status={patient.status} />
                      <ChevronRight
                        size={12}
                        className={`shrink-0 transition group-hover:translate-x-0.5 ${
                          selected ? "text-amber-500" : "text-slate-300"
                        }`}
                      />
                    </div>
                  </button>
                );
              })
            )}
          </div>

          {/* Pagination - Dashboard style */}
          {filteredPatients.length > 0 && (
            <div className="flex h-10 shrink-0 items-center justify-between border-t border-slate-100 bg-slate-50/50 px-3">
              <p className="text-[9px] font-medium text-slate-400">
                Showing{" "}
                <span className="font-semibold text-slate-600">
                  {page * PAGE_SIZE + 1}–{Math.min(
                    (page + 1) * PAGE_SIZE,
                    filteredPatients.length,
                  )}
                </span>{" "}
                of{" "}
                <span className="font-semibold text-slate-600">
                  {filteredPatients.length}
                </span>
              </p>

              <div className="flex items-center gap-1.5">
                <button
                  type="button"
                  aria-label="Previous page"
                  disabled={page === 0}
                  onClick={() => setPage((current) => Math.max(0, current - 1))}
                  className="flex h-7 w-7 items-center justify-center rounded-md border border-slate-200 bg-white text-slate-400 transition hover:border-amber-200 hover:bg-amber-50 hover:text-amber-700 disabled:cursor-not-allowed disabled:opacity-35"
                >
                  <ChevronLeft size={11} />
                </button>

                {Array.from({ length: totalPages }, (_, index) => index)
                  .slice(
                    Math.max(0, Math.min(page - 1, totalPages - 4)),
                    Math.max(0, Math.min(page - 1, totalPages - 4)) + 4,
                  )
                  .map((pageIndex) => (
                    <button
                      key={pageIndex}
                      type="button"
                      onClick={() => setPage(pageIndex)}
                      className={`flex h-7 min-w-7 items-center justify-center rounded-md border px-2 text-[10px] font-semibold transition ${
                        page === pageIndex
                          ? "border-amber-500 bg-amber-500 text-white shadow-sm"
                          : "border-slate-200 bg-white text-slate-600 hover:border-amber-200 hover:bg-amber-50 hover:text-amber-700"
                      }`}
                    >
                      {pageIndex + 1}
                    </button>
                  ))}

                <button
                  type="button"
                  aria-label="Next page"
                  disabled={page >= totalPages - 1}
                  onClick={() =>
                    setPage((current) => Math.min(totalPages - 1, current + 1))
                  }
                  className="flex h-7 w-7 items-center justify-center rounded-md border border-slate-200 bg-white text-slate-400 transition hover:border-amber-200 hover:bg-amber-50 hover:text-amber-700 disabled:cursor-not-allowed disabled:opacity-35"
                >
                  <ChevronRight size={11} />
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Patient Reception Drawer */}
        {selectedPatient && (
          <>
            <div className="hidden" />

            <div className="flex h-full min-h-0 w-full flex-col overflow-hidden rounded-2xl border border-slate-200 bg-slate-50/45 shadow-[0_4px_18px_rgba(15,23,42,0.05)]">

              {/* STEP-SPECIFIC CONTENT — never scrolls */}
              <div className="min-h-0 flex-1 overflow-hidden p-2">
                {selectedPatient.status === "Expected" && (
                  <div className="flex h-full items-center justify-center">
                    <section className="w-full max-w-[610px] overflow-hidden rounded-2xl border border-amber-200 bg-white shadow-[0_8px_24px_rgba(15,23,42,0.06)]">
                      <div className="flex items-center gap-3 border-b border-amber-100 bg-gradient-to-r from-amber-50/85 to-white px-4 py-4">
                        <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-amber-100 text-amber-700">
                          <UserCheck size={19} />
                        </span>

                        <div className="min-w-0">
                          <p className="text-[12px] font-bold text-slate-800">
                            Confirm patient arrival
                          </p>

                          <p className="mt-1 text-[10px] leading-4 text-slate-500">
                            Arrival must be confirmed before Eligibility, Consents and Printouts can be completed.
                          </p>
                        </div>
                      </div>

                      <div className="p-4">
                        <div className="rounded-xl border border-amber-100 bg-amber-50/30 px-3 py-2.5">
                          <div className="flex items-center gap-2">
                            <ShieldCheck
                              size={13}
                              className="text-amber-600"
                            />

                            <p className="text-[11px] font-bold text-slate-700">
                              Next step
                            </p>
                          </div>

                          <p className="mt-1 text-[11px] leading-4 text-slate-500">
                            Complete the one-column Eligibility Checklist, collect required patient consents, then review printouts before handing the case to Cashier.
                          </p>
                        </div>

                        <button
                          type="button"
                          onClick={markPatientArrived}
                          className="mt-3 flex h-8 w-full items-center justify-center gap-2 rounded-lg bg-amber-500 !text-[12px] font-bold text-white transition hover:bg-amber-600"
                        >
                          <UserCheck size={14} />
                          Confirm Patient Arrival
                        </button>
                      </div>
                    </section>
                  </div>
                )}

                {(selectedPatient.status === "Arrived" ||
                  selectedPatient.status === "Reception In Progress") && (
                  <div data-responsive-grid="2" className="grid h-full min-h-0 grid-cols-[255px_minmax(0,1fr)] gap-2">
                    {/* ELIGIBILITY — ONE COLUMN */}
                    <section className="flex min-h-0 flex-col overflow-hidden rounded-xl border border-slate-200 bg-white shadow-[0_1px_2px_rgba(15,23,42,0.03)]">
                      <div className="flex h-9 shrink-0 items-center justify-between border-b border-slate-100 bg-amber-50/30 px-2.5">
                        <div className="flex min-w-0 items-center gap-2">
                          <span className="flex h-6 w-6 items-center justify-center rounded-md bg-amber-100 text-amber-700">
                            <ShieldCheck size={13} />
                          </span>
                          <div className="min-w-0">
                            <h3 className="text-[10px] font-bold text-slate-700">
                              Eligibility Checklist
                            </h3>
                            <p className="mt-0.5 text-[8px] text-slate-400">
                              Required reception checks.
                            </p>
                          </div>
                        </div>

                        <span className={`rounded-full px-2 py-1 text-[8px] font-bold ${allChecked ? "bg-emerald-50 text-emerald-700" : "bg-white text-slate-500 ring-1 ring-slate-200"}`}>
                          {completedCount}/{checklistItems.length}
                        </span>
                      </div>

                      <div className="grid min-h-0 flex-1 content-start grid-cols-1 auto-rows-[44px] gap-1.5 px-2 py-2">
                        {checklistItems.map((item) => (
                          <ChecklistRow
                            key={item.id}
                            item={item}
                            checked={Boolean(checkedItems[item.id])}
                            onChange={() =>
                              setCheckedItems((current) => ({
                                ...current,
                                [item.id]: !current[item.id],
                              }))
                            }
                            highlighted={isMissingHighlighted(`checklist:${item.id}`)}
                          />
                        ))}
                      </div>

                      {selectedPatient.issues && selectedPatient.issues.length > 0 && (
                        <div className="mx-2.5 mb-2 flex shrink-0 items-start gap-2 rounded-lg border border-red-200 bg-red-50/55 px-2 py-1.5">
                          <AlertTriangle size={11} className="mt-0.5 shrink-0 text-red-500" />
                          <p className="min-w-0 truncate text-[7px] font-medium text-red-600">
                            {selectedPatient.issues[0]}
                          </p>
                        </div>
                      )}
                    </section>

                    {/* CONSENTS + PRINTOUTS — ALL INLINE */}
                    <section className="flex min-h-0 flex-col overflow-hidden rounded-xl border border-amber-100 bg-white shadow-[0_1px_2px_rgba(15,23,42,0.03)]">
                      <div className="flex h-9 shrink-0 items-center justify-between border-b border-amber-100 bg-amber-50/45 px-2.5">
                        <div className="flex min-w-0 items-center gap-2">
                          <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md bg-amber-100 text-amber-700">
                            <FileCheck2 size={12} />
                          </span>

                          <div className="min-w-0">
                            <h3 className="text-[9px] font-bold text-slate-700">
                              Consents & Printouts
                            </h3>
                          </div>
                        </div>

                        <span
                          className={`shrink-0 rounded-full px-2 py-0.5 text-[7px] font-bold ${
                            allAdmissionFormsComplete
                              ? "bg-emerald-50 text-emerald-700"
                              : "bg-white text-amber-700 ring-1 ring-amber-200"
                          }`}
                        >
                          {completedAdmissionForms}/{requiredAdmissionForms.length} required
                        </span>
                      </div>

                      <div className="flex min-h-0 flex-1 flex-col gap-2 px-2.5 py-2">
                        {/* ORGANIZED FLAT FORM */}
                        <div className="grid grid-cols-6 gap-x-2.5 gap-y-2 rounded-lg border border-amber-100/80 bg-amber-50/20 p-2.5">
                          <label className="col-span-3 min-w-0">
                            <span className="block text-[9px] font-bold text-slate-600">
                              Emergency contact *
                            </span>
                            <input
                              value={
                                getConsentDetails(
                                  admissionFormItems[0],
                                ).values.emergencyContactName ?? ""
                              }
                              onChange={(event) =>
                                updateConsentField(
                                  admissionFormItems[0],
                                  "emergencyContactName",
                                  event.target.value,
                                )
                              }
                              placeholder="Full name"
                              className={`mt-1 h-7 w-full rounded-lg border bg-white px-2.5 !text-[11px] font-medium text-slate-700 outline-none placeholder:!text-[10px] placeholder:text-slate-300 transition-all duration-300 focus:border-amber-300 ${
                                isMissingHighlighted("field:emergencyContactName")
                                  ? "animate-pulse border-amber-300 bg-amber-50/40 shadow-[0_0_0_3px_rgba(251,191,36,0.10),0_0_16px_rgba(251,191,36,0.16)]"
                                  : "border-amber-200"
                              }`}
                            />
                          </label>

                          <label className="col-span-3 min-w-0">
                            <span className="block text-[9px] font-bold text-slate-600">
                              Emergency phone *
                            </span>
                            <input
                              value={
                                getConsentDetails(
                                  admissionFormItems[0],
                                ).values.emergencyPhone ?? ""
                              }
                              onChange={(event) =>
                                updateConsentField(
                                  admissionFormItems[0],
                                  "emergencyPhone",
                                  event.target.value,
                                )
                              }
                              placeholder="+961 ..."
                              inputMode="tel"
                              className={`mt-1 h-7 w-full rounded-lg border bg-white px-2.5 !text-[11px] font-medium text-slate-700 outline-none placeholder:!text-[10px] placeholder:text-slate-300 transition-all duration-300 focus:border-amber-300 ${
                                isMissingHighlighted("field:emergencyPhone")
                                  ? "animate-pulse border-amber-300 bg-amber-50/40 shadow-[0_0_0_3px_rgba(251,191,36,0.10),0_0_16px_rgba(251,191,36,0.16)]"
                                  : "border-slate-200"
                              }`}
                            />
                          </label>

                          <label className="col-span-3 min-w-0">
                            <span className="block text-[9px] font-bold text-slate-600">
                              Authorized person
                            </span>
                            <input
                              value={
                                getConsentDetails(
                                  admissionFormItems[1],
                                ).values.authorizedContactName ?? ""
                              }
                              onChange={(event) =>
                                updateConsentField(
                                  admissionFormItems[1],
                                  "authorizedContactName",
                                  event.target.value,
                                )
                              }
                              placeholder="Optional"
                              className="mt-1 h-7 w-full rounded-lg border border-slate-200 bg-white px-2.5 !text-[11px] font-medium text-slate-700 outline-none placeholder:!text-[10px] placeholder:text-slate-300 focus:border-amber-300"
                            />
                          </label>

                          <label className="col-span-3 min-w-0">
                            <span className="block text-[9px] font-bold text-slate-600">
                              Authorized phone
                            </span>
                            <input
                              value={
                                getConsentDetails(
                                  admissionFormItems[1],
                                ).values.authorizedPhone ?? ""
                              }
                              onChange={(event) =>
                                updateConsentField(
                                  admissionFormItems[1],
                                  "authorizedPhone",
                                  event.target.value,
                                )
                              }
                              placeholder="+961 ..."
                              inputMode="tel"
                              className="mt-1 h-7 w-full rounded-lg border border-slate-200 bg-white px-2.5 !text-[11px] font-medium text-slate-700 outline-none placeholder:!text-[10px] placeholder:text-slate-300 focus:border-amber-300"
                            />
                          </label>

                          <div className="col-span-3 min-w-0">
                            <p className="block text-[9px] font-bold text-slate-600">
                              Payment responsibility *
                            </p>
                            <div
                              className={`mt-1 flex h-7 overflow-hidden rounded-lg border bg-white transition-all duration-300 ${
                                isMissingHighlighted("field:paymentResponsibility")
                                  ? "animate-pulse border-amber-300 bg-amber-50/40 shadow-[0_0_0_3px_rgba(251,191,36,0.10),0_0_16px_rgba(251,191,36,0.16)]"
                                  : "border-slate-200"
                              }`}
                            >
                              {["Patient", "Insurance", "Guarantor"].map(
                                (option) => {
                                  const current =
                                    getConsentDetails(
                                      admissionFormItems[2],
                                    ).values.paymentResponsibility ?? "";

                                  return (
                                    <button
                                      key={option}
                                      type="button"
                                      onClick={() =>
                                        updateConsentField(
                                          admissionFormItems[2],
                                          "paymentResponsibility",
                                          option,
                                        )
                                      }
                                      className={`min-w-0 flex-1 border-r border-slate-200 px-2 !text-[10px] font-bold last:border-r-0 ${
                                        current === option
                                          ? "bg-amber-500 text-white"
                                          : "text-slate-500 hover:bg-amber-50"
                                      }`}
                                    >
                                      {option}
                                    </button>
                                  );
                                },
                              )}
                            </div>
                          </div>

                          <label className="col-span-3 min-w-0">
                            <span className="block text-[9px] font-bold text-slate-600">
                              Guarantor
                            </span>
                            <input
                              value={
                                getConsentDetails(
                                  admissionFormItems[2],
                                ).values.guarantorName ?? ""
                              }
                              onChange={(event) =>
                                updateConsentField(
                                  admissionFormItems[2],
                                  "guarantorName",
                                  event.target.value,
                                )
                              }
                              placeholder="Optional"
                              className="mt-1 h-7 w-full rounded-lg border border-slate-200 bg-white px-2.5 !text-[11px] font-medium text-slate-700 outline-none placeholder:!text-[10px] placeholder:text-slate-300 focus:border-amber-300"
                            />
                          </label>
                        </div>

                        {/* SHARED APPROVAL */}
                        <div className="grid grid-cols-6 gap-x-2.5 gap-y-2 rounded-lg border border-slate-200 bg-white p-2.5">
                          <label className="col-span-3 min-w-0">
                            <span className="block text-[9px] font-bold text-slate-600">
                              Signer name *
                            </span>

                            <input
                              value={consentApproval.signerName}
                              onChange={(event) =>
                                setConsentApprovalField(
                                  "signerName",
                                  event.target.value,
                                )
                              }
                              placeholder="Patient / representative"
                              className={`mt-1 h-7 w-full rounded-md border bg-white px-2.5 !text-[11px] font-medium leading-none text-slate-700 outline-none placeholder:!text-[10px] placeholder:text-slate-300 transition-all duration-300 focus:border-amber-300 ${
                                isMissingHighlighted("approval:signerName")
                                  ? "animate-pulse border-amber-300 bg-amber-50/40 shadow-[0_0_0_3px_rgba(251,191,36,0.10),0_0_16px_rgba(251,191,36,0.16)]"
                                  : "border-slate-200"
                              }`}
                            />
                          </label>

                          <div className="col-span-3 min-w-0">
                            <p className="block text-[9px] font-bold text-slate-600">
                              Signer role
                            </p>

                            <div className="mt-1 flex h-7 overflow-hidden rounded-md border border-slate-200 bg-white">
                              {(
                                [
                                  ["Patient", "Patient"],
                                  ["Parent / Guardian", "Guardian"],
                                  ["Authorized Representative", "Rep."],
                                ] as Array<[SignerRole, string]>
                              ).map(([role, label]) => (
                                <button
                                  key={role}
                                  type="button"
                                  onClick={() =>
                                    setConsentApprovalField(
                                      "signerRole",
                                      role,
                                    )
                                  }
                                  className={`min-w-0 flex-1 border-r border-slate-200 px-1 !text-[10px] font-bold leading-none last:border-r-0 ${
                                    consentApproval.signerRole === role
                                      ? "bg-amber-500 text-white"
                                      : "text-slate-500 hover:bg-amber-50"
                                  }`}
                                >
                                  {label}
                                </button>
                              ))}
                            </div>
                          </div>

                        </div>

                        {/* COMPACT PRINTOUT ROW */}
                        <div data-responsive-grid="2" className="grid min-w-0 grid-cols-[1fr_auto] items-center gap-2 rounded-lg border border-slate-200 bg-slate-50/45 px-2.5 py-2">
                          <div className="flex min-w-0 items-center gap-1.5">
                            <Printer size={13} className="shrink-0 text-amber-600" />
                            <span className="truncate text-[9px] font-semibold text-slate-500">
                              Printouts use auto-filled patient and operation details.
                            </span>
                          </div>

                          <button
                            type="button"
                            onClick={() => setShowPrintCenter(true)}
                            disabled={!selectedSurgery}
                            className="inline-flex h-7 items-center gap-1.5 rounded-lg border border-amber-200 bg-amber-100/50 px-3.5 !text-[11px] font-bold leading-none text-amber-700 shadow-[0_1px_2px_rgba(15,23,42,0.04)] transition hover:bg-amber-50 disabled:cursor-not-allowed disabled:opacity-50"
                          >
                            <Printer size={10} />
                            Preview & Print
                          </button>
                        </div>
                      </div>
                    </section>
                  </div>
                )}

                {selectedPatient.status === "Ready for Admission" && (
                  <ReceptionCompletedPanel
                    patient={selectedPatient}
                    surgery={selectedSurgery}
                    completedCount={completedCount}
                    totalChecks={checklistItems.length}
                    completedForms={completedAdmissionForms}
                    totalForms={requiredAdmissionForms.length}
                    onSend={sendToCashier}
                  />
                )}

                {selectedPatient.status === "Sent to Cashier" && (
                  <div className="flex h-full items-center justify-center">
                    <section className="w-full max-w-[620px] overflow-hidden rounded-2xl border border-emerald-200 bg-white shadow-[0_8px_24px_rgba(15,23,42,0.06)]">
                      <div className="flex flex-col items-center px-6 py-8 text-center">
                        <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-emerald-100 text-emerald-600">
                          <CheckCircle2 size={22} />
                        </div>
                        <h3 className="mt-3 text-[13px] font-bold text-emerald-800">
                          Sent to Cashier
                        </h3>
                        <p className="mt-1 max-w-[430px] text-[8.5px] leading-4 text-slate-500">
                          Reception is complete. The patient is now in the Cashier workflow for financial clearance.
                        </p>

                        <div data-responsive-grid="3" className="mt-4 grid w-full grid-cols-3 gap-2">
                          <div className="rounded-lg border border-slate-200 bg-slate-50/60 p-2.5">
                            <p className="text-[8px] font-bold uppercase tracking-wide text-slate-400">Arrival</p>
                            <p className="mt-1 text-[10px] font-semibold text-slate-700">Confirmed</p>
                          </div>
                          <div className="rounded-lg border border-slate-200 bg-slate-50/60 p-2.5">
                            <p className="text-[8px] font-bold uppercase tracking-wide text-slate-400">Eligibility</p>
                            <p className="mt-1 text-[10px] font-semibold text-slate-700">Completed</p>
                          </div>
                          <div className="rounded-lg border border-slate-200 bg-slate-50/60 p-2.5">
                            <p className="text-[8px] font-bold uppercase tracking-wide text-slate-400">Handoff</p>
                            <p className="mt-1 text-[10px] font-semibold text-emerald-700">Cashier</p>
                          </div>
                        </div>
                      </div>
                    </section>
                  </div>
                )}

                {selectedPatient.status === "On Hold" && (
                  <div className="flex h-full items-center justify-center">
                    <section className="w-full max-w-[620px] overflow-hidden rounded-2xl border border-red-200 bg-white shadow-[0_8px_24px_rgba(15,23,42,0.06)]">
                      <div className="flex items-start gap-3 border-b border-red-100 bg-red-50/55 px-4 py-3">
                        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-red-100 text-red-600">
                          <AlertTriangle size={17} />
                        </div>
                        <div className="min-w-0">
                          <h3 className="text-[11px] font-bold text-red-800">Patient On Hold</h3>
                          <p className="mt-0.5 text-[8px] text-red-500">Resolve the reception issue before continuing eligibility checks.</p>
                        </div>
                      </div>

                      <div className="p-4">
                        <p className="text-[7px] font-bold uppercase tracking-wide text-slate-400">Reason</p>
                        <p className="mt-1 rounded-lg border border-red-100 bg-red-50/35 px-3 py-2 text-[9px] font-medium text-slate-700">
                          {selectedPatient.issues?.[0] || "Reception issue requires review."}
                        </p>

                        <button
                          type="button"
                          onClick={() =>
                            setReceptionStatus((current) => ({
                              ...current,
                              [selectedPatient.id]: "Reception In Progress",
                            }))
                          }
                          className="mt-3 flex h-9 w-full items-center justify-center rounded-lg border border-amber-200 bg-amber-50 text-[9px] font-bold text-amber-700 transition hover:bg-amber-100/60"
                        >
                          Resume Eligibility & Documents
                        </button>
                      </div>
                    </section>
                  </div>
                )}
              </div>

              {/* Actions only for the eligibility/documents step */}
              {(selectedPatient.status === "Arrived" ||
                selectedPatient.status === "Reception In Progress") && (
                <div className="shrink-0 border-t border-slate-200 bg-white px-3 py-2.5">
                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={() => setShowHoldModal(true)}
                      className="flex h-6 w-[120px] shrink-0 items-center justify-center gap-1.5 rounded-lg border border-red-200 bg-red-50/60 !text-[11px] font-semibold text-red-600 transition hover:bg-red-50"
                    >
                      <AlertTriangle size={12} />
                      Put on Hold
                    </button>

                    <div className="min-w-0 flex-1">
                      {(!allChecked || !allAdmissionFormsComplete || !approvalReady) && (
                        <p className="truncate text-right text-[9px] font-medium text-slate-400">
                          Complete required eligibility items, required consent fields and signer approval.
                        </p>
                      )}
                    </div>

                    <button
                      type="button"
                      onClick={completeReception}
                      className={`flex h-7 w-[210px] shrink-0 items-center justify-center gap-1.5 rounded-lg !text-[12px] font-bold shadow-[0_1px_2px_rgba(15,23,42,0.05)] transition ${
                        receptionReady
                          ? "bg-emerald-500 text-white hover:bg-emerald-600"
                          : "bg-amber-500 text-white hover:bg-amber-600"
                      }`}
                    >
                      {receptionReady ? (
                        <CheckCircle2 size={13} />
                      ) : (
                        <AlertTriangle size={13} />
                      )}
                      Complete Reception
                    </button>
                  </div>
                </div>
              )}
            </div>
          </>
        )}
      </div>

      {/* Reception Print Center */}
      {showPrintCenter && selectedSurgery && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-900/20 p-4 backdrop-blur-[1px]">
          <div className="flex h-[78vh] max-h-[720px] w-[880px] max-w-[94vw] flex-col overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_22px_60px_rgba(15,23,42,0.18)]">
            <div className="flex h-12 shrink-0 items-center justify-between border-b border-blue-100 bg-gradient-to-r from-blue-50/65 to-white px-4">
              <div className="flex items-center gap-2.5">
                <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-blue-100 text-blue-700">
                  <Printer size={14} />
                </span>
                <div>
                  <h3 className="text-[11px] font-bold text-slate-800">
                    Reception Print Center
                  </h3>
                  <p className="mt-0.5 text-[7.5px] text-slate-400">
                    {selectedPatient?.name} · {selectedPatient?.id}
                  </p>
                </div>
              </div>

              <button
                type="button"
                onClick={() => setShowPrintCenter(false)}
                className="flex h-7 w-7 items-center justify-center rounded-md border border-slate-200 bg-white text-slate-400 transition hover:bg-slate-50 hover:text-slate-600"
                aria-label="Close print center"
              >
                <X size={12} />
              </button>
            </div>

            <div className="grid min-h-0 flex-1 grid-rows-[74px_minmax(0,1fr)] gap-2 p-3">
              {/* AUTO-FILLED PRINT DATA — intentionally visible only in preview */}
              <div data-responsive-grid="4" className="grid grid-cols-[1.1fr_0.9fr_1.35fr_0.9fr] divide-x divide-slate-100 overflow-hidden rounded-xl border border-blue-100 bg-blue-50/20">
                <div className="min-w-0 px-3 py-2">
                  <p className="text-[7px] font-bold uppercase tracking-wide text-slate-400">
                    Patient
                  </p>

                  <p className="mt-1 truncate text-[9px] font-bold text-slate-700">
                    {selectedPatient?.name}
                  </p>

                  <p className="mt-0.5 truncate text-[7.5px] text-slate-400">
                    {selectedPatient?.mrn} · {selectedPatient?.age} yrs · {selectedPatient?.gender}
                  </p>
                </div>

                <div className="min-w-0 px-3 py-2">
                  <p className="text-[7px] font-bold uppercase tracking-wide text-slate-400">
                    Case
                  </p>

                  <p className="mt-1 truncate text-[9px] font-bold text-slate-700">
                    {selectedPatient?.id}
                  </p>

                  <p className="mt-0.5 truncate text-[7.5px] text-slate-400">
                    {selectedPatient
                      ? `${formatSurgeryDate(selectedPatient.date)} · ${selectedPatient.time}`
                      : ""}
                  </p>
                </div>

                <div className="min-w-0 px-3 py-2">
                  <p className="text-[7px] font-bold uppercase tracking-wide text-slate-400">
                    Operation
                  </p>

                  <p className="mt-1 truncate text-[9px] font-bold text-slate-700">
                    {selectedPatient?.procedures
                      .map(
                        (procedure) =>
                          procedure.name,
                      )
                      .join(", ")}
                  </p>

                  <p className="mt-0.5 truncate text-[7.5px] text-slate-400">
                    Surgeon: {selectedPatient?.surgeon}
                  </p>
                </div>

                <div className="min-w-0 px-3 py-2">
                  <p className="text-[7px] font-bold uppercase tracking-wide text-slate-400">
                    Consents
                  </p>

                  <p className="mt-1 text-[9px] font-bold text-blue-700">
                    {completedAdmissionForms}/{requiredAdmissionForms.length} required complete
                  </p>

                  <p className="mt-0.5 text-[7.5px] text-slate-400">
                    Auto-filled preview
                  </p>
                </div>
              </div>

              <div className="min-h-0 overflow-auto rounded-xl border border-slate-100 bg-slate-50/25 p-2">
                <ReceptionPrintouts
                  key={selectedSurgery.id}
                  surgery={selectedSurgery}
                />
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Hold Modal */}
      {showHoldModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/20 p-4 backdrop-blur-[1px]">
          <div className="w-full max-w-sm overflow-hidden rounded-xl border border-slate-200 bg-white shadow-[0_18px_50px_rgba(15,23,42,0.16)]">
            <div className="flex items-start gap-3 border-b border-slate-100 p-4">
              <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-red-50 text-red-500">
                <AlertTriangle size={16} />
              </div>

              <div>
                <h3 className="text-[12px] font-semibold text-slate-800">
                  Put Patient on Hold?
                </h3>

                <p className="mt-1 text-[9px] leading-4 text-slate-400">
                  The patient will not be able to proceed to admission until
                  the reception issue is resolved.
                </p>
              </div>
            </div>

            <div className="p-4">
              <label className="text-[9px] font-semibold text-slate-600">
                Reason
              </label>

              <textarea
                value={holdReason}
                onChange={(event) => setHoldReason(event.target.value)}
                placeholder="Enter reason for putting the patient on hold..."
                className="mt-1.5 h-20 w-full resize-none rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-[9px] text-slate-600 outline-none placeholder:text-slate-400 focus:border-red-300 focus:bg-white"
                />

              <div className="mt-3 flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setShowHoldModal(false)}
                  className="h-8 rounded-md border border-slate-200 bg-white px-3 text-[9px] font-semibold text-slate-500 hover:bg-slate-50"
                >
                  Cancel
                </button>

                <button
                  type="button"
                  onClick={holdPatient}
                  className="h-8 rounded-md bg-red-500 px-3 text-[9px] font-semibold text-white hover:bg-red-600"
                >
                  Put on Hold
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

