import { useSurgeryStore } from "../store/surgeryStore";
import { useState, useRef, useMemo, useEffect } from "react";
import { type ToastState, type Period, type SortKey, type SortDirection, type RecoveryState, type Stability, type RecoveryStatus } from "../features/workspaces/Recovery/types";
import { emptyRecovery, recoveryAssessments, awakeningStages, MIN_PAGE_SIZE, ROW_HEIGHT } from "../features/workspaces/Recovery/config";
import { getSurgeryProcedures, isRecoveryDateInPeriod, getRecoveryDateSortValue, getSurgeryDurationSeconds, hasRichTextContent, getInitials, getPatientAge, getPatientGender, formatRecoverySurgeryDate, formatSurgeryDuration, formatClock } from "../features/workspaces/Recovery/utils";
import { SurgeryCopilotDrawer } from "../features/copilot/components/SurgeryCopilotDrawer";
import { RecoveryStatCard, RecoveryFilterPill, ModernRecoveryDatePicker, RecoverySortableHeader, PatientConditionBadge, RecoveryStatusBadge, SummaryItem, SectionTitle, ToolbarButton } from "../features/workspaces/Recovery/components";
import { CheckCircle2, HeartPulse, ShieldCheck, AlertTriangle, Search, Filter, ChevronDown, Stethoscope, ChevronRight, ChevronLeft, X, Scissors, Clock3, Activity, UserRound, Check, FileText, Minimize2, Maximize2, Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, List, ListOrdered, Highlighter, Save } from "lucide-react";


export default function Recovery() {
  const surgeries = useSurgeryStore(
    (state) => state.surgeries,
  );

  const updateSurgery = useSurgeryStore(
    (state) => state.updateSurgery,
  );

  const [search, setSearch] = useState("");
  const [selectedId, setSelectedId] =
    useState<string | null>(null);
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(5);

  const rowsContainerRef =
    useRef<HTMLDivElement | null>(null);

  const [toast, setToast] =
    useState<ToastState>(null);

  const [filterOpen, setFilterOpen] =
    useState(false);

  const [selectedDoctors, setSelectedDoctors] =
    useState<string[]>([]);

  const [selectedStatuses, setSelectedStatuses] =
    useState<string[]>([]);

  const [period, setPeriod] =
    useState<Period>("Day");

  const [selectedDate, setSelectedDate] =
    useState("");

  const [sortKey, setSortKey] =
    useState<SortKey>("date");

  const [sortDirection, setSortDirection] =
    useState<SortDirection>("asc");

  const filterRef =
    useRef<HTMLDivElement | null>(null);

  const [recovery, setRecovery] =
    useState<RecoveryState>(emptyRecovery);

  const [reportExpanded, setReportExpanded] =
    useState(false);

  const reportEditorRef =
    useRef<HTMLDivElement | null>(null);

  const savedReportRangeRef =
    useRef<Range | null>(null);

  /*
   * These Recovery fields are intentionally session-only:
   * - Patient Awakening
   * - Recovery Notes
   * - Surgeon Post-Operative Report
   *
   * They remain available while this Recovery page stays mounted,
   * including drawer close/reopen and patient switching, but reset
   * naturally after a browser refresh.
   */
  const transientRecoveryRef =
    useRef<
      Record<
        string,
        {
          awakeningStage: number;
          notes: string;
          surgeonReport: string;
        }
      >
    >({});

  /*
   * Recovery receives patients after surgery is finished.
   * We also keep "Recovery" and "Discharged" visible so a saved
   * recovery record can still be reviewed later.
   */
  const recoveryCases = useMemo(
    () =>
      surgeries.filter((surgery) =>
        [
          "Completed",
          "Recovery",
          "Discharged",
        ].includes(surgery.status),
      ),
    [surgeries],
  );

  const doctors = useMemo(
    () =>
      Array.from(
        new Set(
          recoveryCases.map(
            (surgery) => surgery.doctor,
          ),
        ),
      ).filter(Boolean),
    [recoveryCases],
  );

  const statuses = useMemo(
    () =>
      Array.from(
        new Set(
          recoveryCases.map(
            (surgery) =>
              loadRecovery(
                surgery.id,
              ).status,
          ),
        ),
      ),
    [recoveryCases],
  );

  const filteredCases = useMemo(() => {
    const query = search
      .trim()
      .toLowerCase();

    return recoveryCases.filter(
      (surgery) => {
        const procedures =
          getSurgeryProcedures(
            surgery,
          )
            .map(
              (item) => item.name,
            )
            .join(" ")
            .toLowerCase();

        const stored =
          loadRecovery(surgery.id);

        const matchesSearch =
          !query ||
          surgery.patientName
            .toLowerCase()
            .includes(query) ||
          surgery.id
            .toLowerCase()
            .includes(query) ||
          procedures.includes(query) ||
          surgery.doctor
            .toLowerCase()
            .includes(query);

        const matchesDoctor =
          selectedDoctors.length === 0 ||
          selectedDoctors.includes(
            surgery.doctor,
          );

        const matchesStatus =
          selectedStatuses.length === 0 ||
          selectedStatuses.includes(
            stored.status,
          );

        const matchesDate =
          !selectedDate ||
          isRecoveryDateInPeriod(
            surgery,
            selectedDate,
            period,
          );

        return (
          matchesSearch &&
          matchesDoctor &&
          matchesStatus &&
          matchesDate
        );
      },
    );
  }, [
    recoveryCases,
    search,
    selectedDoctors,
    selectedStatuses,
    selectedDate,
    period,
  ]);

  const sortedCases = useMemo(() => {
    const copy = [...filteredCases];

    copy.sort((a, b) => {
      const getValue = (
        surgery: (typeof copy)[number],
      ) => {
        const stored =
          loadRecovery(surgery.id);

        switch (sortKey) {
          case "patient":
            return surgery.patientName;

          case "patientId":
            return surgery.id;

          case "procedures":
            return getSurgeryProcedures(
              surgery,
            )
              .map(
                (item) => item.name,
              )
              .join(" ");

          case "surgeon":
            return surgery.doctor;

          case "date":
            return getRecoveryDateSortValue(
              surgery,
            );

          case "duration":
            return getSurgeryDurationSeconds(
              surgery,
            );

          case "condition":
            return stored.stability;

          case "recoveryStatus":
            return stored.status;

          default:
            return "";
        }
      };

      const aValue = getValue(a);
      const bValue = getValue(b);

      const result =
        typeof aValue === "number" &&
        typeof bValue === "number"
          ? aValue - bValue
          : String(aValue).localeCompare(
              String(bValue),
              undefined,
              {
                numeric: true,
                sensitivity: "base",
              },
            );

      return sortDirection === "asc"
        ? result
        : -result;
    });

    return copy;
  }, [
    filteredCases,
    sortKey,
    sortDirection,
  ]);

  const totalPages = Math.max(
    1,
    Math.ceil(
      sortedCases.length / pageSize,
    ),
  );

  const visibleCases = useMemo(
    () =>
      sortedCases.slice(
        page * pageSize,
        page * pageSize + pageSize,
      ),
    [sortedCases, page, pageSize],
  );

  const selected = useMemo(
    () =>
      surgeries.find(
        (surgery) =>
          surgery.id === selectedId,
      ),
    [surgeries, selectedId],
  );

  const assessmentProgress =
    recovery.assessments.length;

  const allAssessmentsComplete =
    recoveryAssessments.every((item) =>
      recovery.assessments.includes(item),
    );

  const readyForTransfer =
    recovery.started &&
    recovery.awakeningStage ===
      awakeningStages.length - 1 &&
    allAssessmentsComplete &&
    recovery.stability === "stable";

  /*
   * Remove transient fields saved by older Recovery versions.
   * This runs once for the current surgery list and prevents stale
   * awakening / notes / reports from coming back after refresh.
   */
  useEffect(() => {
    surgeries.forEach(
      (surgery) => {
        const id = String(
          surgery.id ?? "",
        );

        if (!id) return;

        const key =
          `recovery-${id}`;

        const raw =
          localStorage.getItem(
            key,
          );

        if (!raw) return;

        try {
          const parsed =
            JSON.parse(raw);

          localStorage.setItem(
            key,
            JSON.stringify({
              assessments:
                Array.isArray(
                  parsed.assessments,
                )
                  ? parsed.assessments.filter(
                      (
                        value: unknown,
                      ) =>
                        typeof value ===
                        "string",
                    )
                  : [],
              stability:
                parsed.stability ===
                "unstable"
                  ? "unstable"
                  : "stable",
            }),
          );
        } catch {
          localStorage.removeItem(
            key,
          );
        }
      },
    );
  }, [surgeries]);

  useEffect(() => {
    const element = rowsContainerRef.current;

    if (!element) return;

    const updatePageSize = () => {
      const availableHeight =
        element.getBoundingClientRect().height;

      const nextPageSize = Math.max(
        MIN_PAGE_SIZE,
        Math.floor(
          availableHeight / ROW_HEIGHT,
        ),
      );

      setPageSize((current) =>
        current === nextPageSize
          ? current
          : nextPageSize,
      );
    };

    updatePageSize();

    const observer =
      new ResizeObserver(updatePageSize);

    observer.observe(element);

    window.addEventListener(
      "resize",
      updatePageSize,
    );

    return () => {
      observer.disconnect();

      window.removeEventListener(
        "resize",
        updatePageSize,
      );
    };
  }, []);

  /*
   * Keep page position valid after a search.
   */
  useEffect(() => {
    if (page > totalPages - 1) {
      setPage(
        Math.max(0, totalPages - 1),
      );
    }
  }, [page, totalPages]);

  /*
   * Auto-save Recovery workspace without introducing another
   * scrolling/modal workflow.
   */
  useEffect(() => {
    if (!selectedId) return;

    const timer = window.setTimeout(
      () => {
        persistRecovery(
          selectedId,
          recovery,
        );
      },
      300,
    );

    return () =>
      window.clearTimeout(timer);
  }, [selectedId, recovery]);

  /*
   * Load the saved rich-text report into the editor when the selected
   * patient changes. Keeping the contentEditable element uncontrolled
   * avoids resetting the cursor while the doctor is typing.
   */
  useEffect(() => {
    if (!reportEditorRef.current) return;

    reportEditorRef.current.innerHTML =
      recovery.surgeonReport || "";
    // Only reload the document when switching patients.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedId]);

  useEffect(() => {
    setPage(0);
  }, [
    search,
    selectedDoctors,
    selectedStatuses,
    selectedDate,
    period,
  ]);

  useEffect(() => {
    if (!filterOpen) return;

    function handleOutsideClick(
      event: MouseEvent,
    ) {
      const target =
        event.target as Node | null;

      if (
        target &&
        filterRef.current &&
        !filterRef.current.contains(
          target,
        )
      ) {
        setFilterOpen(false);
      }
    }

    document.addEventListener(
      "mousedown",
      handleOutsideClick,
    );

    return () =>
      document.removeEventListener(
        "mousedown",
        handleOutsideClick,
      );
  }, [filterOpen]);

  useEffect(() => {
    if (!toast) return;

    const timer = window.setTimeout(
      () => setToast(null),
      4000,
    );

    return () =>
      window.clearTimeout(timer);
  }, [toast]);

  function showToast(
    type: "success" | "error",
    title: string,
    message: string,
    items?: string[],
  ) {
    setToast({
      type,
      title,
      message,
      items,
    });
  }

  function handleSort(
    key: SortKey,
  ) {
    if (sortKey === key) {
      setSortDirection(
        (current) =>
          current === "asc"
            ? "desc"
            : "asc",
      );

      return;
    }

    setSortKey(key);
    setSortDirection("asc");
  }

  function toggleDoctor(
    doctor: string,
  ) {
    setSelectedDoctors(
      (current) =>
        current.includes(doctor)
          ? current.filter(
              (item) =>
                item !== doctor,
            )
          : [...current, doctor],
    );
  }

  function toggleStatus(
    status: string,
  ) {
    setSelectedStatuses(
      (current) =>
        current.includes(status)
          ? current.filter(
              (item) =>
                item !== status,
            )
          : [...current, status],
    );
  }

  function clearFilters() {
    setSelectedDoctors([]);
    setSelectedStatuses([]);
    setPeriod("Day");
    setSelectedDate("");
  }

  function selectPatient(id: string) {
    setReportExpanded(false);

    if (selectedId) {
      persistRecovery(
        selectedId,
        recovery,
      );
    }

    const surgery = surgeries.find(
      (item) => item.id === id,
    );

    if (!surgery) return;

    setSelectedId(id);

    const stored =
      loadRecovery(id);

    setRecovery({
      ...stored,

      /*
       * Do not fall back to surgery.operativeReport / surgeonNotes here.
       * Those shared values would make the Recovery inputs reappear
       * after a browser refresh.
       */
      surgeonReport:
        stored.surgeonReport,

      stability:
        stored.stability ||
        (surgery.patientCondition ===
        "Unstable"
          ? "unstable"
          : "stable"),
    });
  }

  function persistRecovery(
    id: string,
    value: RecoveryState,
  ) {
    /*
     * Persist only the durable Recovery information.
     *
     * Awakening, Notes and Surgeon Report are intentionally omitted
     * so refreshing the browser opens them in their default state.
     */
    localStorage.setItem(
      `recovery-${id}`,
      JSON.stringify({
        assessments:
          value.assessments,
        stability:
          value.stability,
      }),
    );

    /*
     * Preserve the transient values only for this mounted page session.
     */
    transientRecoveryRef.current[id] = {
      awakeningStage:
        value.awakeningStage,
      notes:
        value.notes,
      surgeonReport:
        value.surgeonReport,
    };
  }

  function loadRecovery(
    id: string,
  ): RecoveryState {
    const raw =
      localStorage.getItem(
        `recovery-${id}`,
      );

    const transient =
      transientRecoveryRef.current[id];

    let assessments: string[] = [];
    let stability: Stability =
      "stable";

    if (raw) {
      try {
        const parsed =
          JSON.parse(raw);

        assessments =
          Array.isArray(
            parsed.assessments,
          )
            ? parsed.assessments.filter(
                (value: unknown) =>
                  typeof value ===
                  "string",
              )
            : [];

        stability =
          parsed.stability ===
          "unstable"
            ? "unstable"
            : "stable";
      } catch {
        /*
         * Ignore old/invalid Recovery localStorage and use defaults.
         */
      }
    }

    return {
      started: true,

      /*
       * On a browser refresh transientRecoveryRef is empty,
       * so Patient Awakening returns to:
       * "Anesthesia ongoing".
       */
      awakeningStage:
        transient?.awakeningStage ??
        0,

      assessments,

      /*
       * Notes and report are session-only and therefore empty
       * after refresh.
       */
      notes:
        transient?.notes ?? "",

      status:
        transient &&
        transient.awakeningStage >
          1
          ? transient.awakeningStage >=
            awakeningStages.length -
              1
            ? "Ready for Transfer"
            : "Progressing"
          : "Monitoring",

      stability,

      surgeonReport:
        transient?.surgeonReport ??
        "",
    };
  }

  function updateRecoveryStage(
    stage: number,
  ) {
    /*
     * Awakening is intentionally sequential.
     * The user can only move from the current stage to the next one.
     */
    if (
      stage !==
      recovery.awakeningStage + 1
    ) {
      return;
    }

    const status: RecoveryStatus =
      stage >=
      awakeningStages.length - 1
        ? "Ready for Transfer"
        : stage <= 1
          ? "Monitoring"
          : "Progressing";

    setRecovery((current) => {
      const next = {
        ...current,
        started: true,
        awakeningStage: stage,
        status,
      };

      if (selectedId) {
        transientRecoveryRef.current[
          selectedId
        ] = {
          awakeningStage:
            next.awakeningStage,
          notes:
            next.notes,
          surgeonReport:
            next.surgeonReport,
        };
      }

      return next;
    });
  }

  function toggleAssessment(
    item: string,
  ) {
    setRecovery((current) => ({
      ...current,
      assessments:
        current.assessments.includes(item)
          ? current.assessments.filter(
              (value) =>
                value !== item,
            )
          : [
              ...current.assessments,
              item,
            ],
    }));
  }

  function saveRecovery() {
    if (!selected) return;

    const savedState = {
      ...recovery,
      status: readyForTransfer
        ? ("Ready for Transfer" as const)
        : recovery.status,
    };

    setRecovery(savedState);

    persistRecovery(
      selected.id,
      savedState,
    );

    /*
     * Save the doctor report and recovery result on the shared
     * surgery record so Surgery Details / later workflow pages
     * can reuse the same information.
     */
    updateSurgery(
      selected.id,
      {
        status: "Recovery",
        operativeReport:
          savedState.surgeonReport,
        surgeonNotes:
          savedState.notes,
        patientCondition:
          savedState.stability ===
          "stable"
            ? "Stable"
            : "Unstable",

        // These additional properties are useful to later
        // Recovery / Admission / Discharge screens. Cast keeps
        // this page compatible even if your Surgery type has
        // not added them yet.
        recoveryStatus:
          savedState.status,
        recoveryCompleted:
          readyForTransfer,
        recoveryAssessments:
          savedState.assessments,
        awakeningStage:
          savedState.awakeningStage,
      } as any,
    );
  }

  function rememberReportSelection() {
    const editor =
      reportEditorRef.current;

    const selection =
      window.getSelection();

    if (
      !editor ||
      !selection ||
      selection.rangeCount === 0
    ) {
      return;
    }

    const range =
      selection.getRangeAt(0);

    if (
      editor.contains(
        range.commonAncestorContainer,
      )
    ) {
      savedReportRangeRef.current =
        range.cloneRange();
    }
  }

  function restoreReportSelection() {
    const range =
      savedReportRangeRef.current;

    if (!range) return;

    const selection =
      window.getSelection();

    if (!selection) return;

    selection.removeAllRanges();
    selection.addRange(range);
  }

  function applyReportCommand(
    command: string,
    value?: string,
  ) {
    const editor =
      reportEditorRef.current;

    if (!editor) return;

    editor.focus();
    restoreReportSelection();

    /*
     * styleWithCSS makes foreColor/highlight behave consistently
     * inside the contentEditable report.
     */
    try {
      document.execCommand(
        "styleWithCSS",
        false,
        "true",
      );
    } catch {
      // Browser can safely continue with normal execCommand.
    }

    if (
      command === "hiliteColor"
    ) {
      const applied =
        document.execCommand(
          "hiliteColor",
          false,
          value,
        );

      if (!applied) {
        document.execCommand(
          "backColor",
          false,
          value,
        );
      }
    } else {
      document.execCommand(
        command,
        false,
        value,
      );
    }

    rememberReportSelection();

    const html =
      editor.innerHTML;

    setRecovery((current) => ({
      ...current,
      surgeonReport: html,
    }));
  }

  function handleReportInput(
    event: React.FormEvent<HTMLDivElement>,
  ) {
    /*
     * IMPORTANT:
     * Capture the HTML immediately. Do not read event.currentTarget
     * from inside the state-updater callback because React may clear
     * currentTarget after the event handler finishes.
     */
    const html =
      event.currentTarget.innerHTML;

    setRecovery((current) => {
      const next = {
        ...current,
        surgeonReport: html,
      };

      if (selectedId) {
        transientRecoveryRef.current[
          selectedId
        ] = {
          awakeningStage:
            next.awakeningStage,
          notes:
            next.notes,
          surgeonReport:
            next.surgeonReport,
        };
      }

      return next;
    });
  }

  function toggleReportExpanded() {
    /*
     * Sync the current DOM document before changing layout mode so
     * expanding/collapsing never loses what the doctor has typed.
     */
    const html =
      reportEditorRef.current?.innerHTML ??
      recovery.surgeonReport;

    setRecovery((current) => ({
      ...current,
      surgeonReport: html,
    }));

    setReportExpanded(
      (current) => !current,
    );

    /*
     * The contentEditable node stays mounted, but its layout changes
     * from normal to fixed. Restore focus after the browser has applied
     * that layout change.
     */
    window.requestAnimationFrame(() => {
      reportEditorRef.current?.focus();
    });
  }

  function collapseReport() {
    const html =
      reportEditorRef.current?.innerHTML ??
      recovery.surgeonReport;

    setRecovery((current) => ({
      ...current,
      surgeonReport: html,
    }));

    setReportExpanded(false);
  }

  function confirmReadyForTransfer() {
    if (!selected) {
      showToast(
        "error",
        "Recovery not completed",
        "No patient is selected. Select a patient and try again.",
      );

      return;
    }

    const missing: string[] = [];

    if (
      recovery.awakeningStage !==
      awakeningStages.length - 1
    ) {
      missing.push(
        "Complete all Patient Awakening stages",
      );
    }

    if (!allAssessmentsComplete) {
      missing.push(
        "Complete all Recovery Assessment checks",
      );
    }

    if (
      recovery.stability !== "stable"
    ) {
      missing.push(
        "Confirm that the patient is Stable",
      );
    }

    if (
      !hasRichTextContent(
        recovery.surgeonReport,
      )
    ) {
      missing.push(
        "Complete the Surgeon Post-Operative Report",
      );
    }

    if (missing.length > 0) {
      showToast(
        "error",
        "Recovery needs attention",
        "Please complete the following requirements before marking the patient ready for transfer:",
        missing,
      );

      /*
       * Same behavior as Pre-Op:
       * keep the drawer open so the user can fix the missing items.
       */
      return;
    }

    try {
      const completedState: RecoveryState =
        {
          ...recovery,
          started: true,
          status:
            "Ready for Transfer",
        };

      setRecovery(
        completedState,
      );

      persistRecovery(
        selected.id,
        completedState,
      );

      updateSurgery(
        selected.id,
        {
          status: "Recovery",
          operativeReport:
            completedState.surgeonReport,
          surgeonNotes:
            completedState.notes,
          patientCondition:
            "Stable",
          recoveryStatus:
            "Ready for Transfer",
          recoveryCompleted: true,
          recoveryCompletedAt:
            new Date().toISOString(),
          recoveryAssessments:
            completedState.assessments,
          awakeningStage:
            completedState.awakeningStage,
        } as any,
      );

      showToast(
        "success",
        "Recovery completed",
        `${selected.patientName} has recovered successfully and is ready for transfer.`,
      );

      /*
       * Close only after a successful Recovery confirmation.
       */
      setReportExpanded(false);
      setSelectedId(null);
    } catch (error) {
      const message =
        error instanceof Error &&
        error.message
          ? error.message
          : "Something went wrong while completing Recovery. Please try again.";

      showToast(
        "error",
        "Recovery failed",
        message,
      );
    }
  }

  return (
    <div className="h-[calc(100vh-72px)] min-h-0 overflow-hidden bg-slate-50 p-2">
      <SurgeryCopilotDrawer surgery={selected} context={selected ? { recovery } : undefined}
        onDestination={(destination, surgeryId) => {
          if (destination.path !== "/recovery") return false;
          if (selectedId !== surgeryId) selectPatient(surgeryId);
          return true;
        }} />
      <div className="relative flex h-full min-h-0 flex-col gap-2">
        {/* ================================================================ */}
        {/* TOP STAT CARDS                                                   */}
        {/* ================================================================ */}

        <section data-responsive-grid="4" className="grid shrink-0 grid-cols-4 gap-2">
          <RecoveryStatCard
            label="Post-Op Patients"
            value={
              recoveryCases.filter(
                (item) =>
                  item.status === "Completed",
              ).length
            }
            icon={<CheckCircle2 size={15} />}
            tone="blue"
          />

          <RecoveryStatCard
            label="In Recovery"
            value={
              recoveryCases.filter(
                (item) =>
                  item.status === "Recovery",
              ).length
            }
            icon={<HeartPulse size={15} />}
            tone="teal"
          />

          <RecoveryStatCard
            label="Ready for Transfer"
            value={
              recoveryCases.filter((item) => {
                const saved = loadRecovery(
                  item.id,
                );

                return (
                  saved.status ===
                  "Ready for Transfer"
                );
              }).length
            }
            icon={<ShieldCheck size={15} />}
            tone="green"
          />

          <RecoveryStatCard
            label="Needs Monitoring"
            value={
              recoveryCases.filter((item) => {
                const saved = loadRecovery(
                  item.id,
                );

                return (
                  saved.stability ===
                    "unstable" ||
                  saved.status ===
                    "Monitoring" ||
                  saved.status ===
                    "Progressing"
                );
              }).length
            }
            icon={<AlertTriangle size={15} />}
            tone="orange"
          />
        </section>

        {/* ================================================================ */}
        {/* RECOVERY PATIENT TABLE — MATCHES PRE-OP TABLE                       */}
        {/* ================================================================ */}

        <div className="relative min-h-0 flex-1">
          <section className="flex h-full min-h-0 flex-col overflow-visible rounded-xl border border-slate-200 bg-white">
            {/* LIST HEADER */}
            <div className="flex min-h-[58px] shrink-0 items-center justify-between gap-4 border-b border-slate-100 px-4 py-2.5">
              <div>
                <h2 className="text-[12px] font-semibold text-slate-800">
                  Recovery Patients
                </h2>

                <p className="mt-0.5 text-[10px] text-slate-400">
                  Select a patient to open their recovery workspace
                </p>
              </div>

              <div className="flex items-center gap-2">
                <div className="relative w-[260px]">
                  <Search
                    size={14}
                    className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
                  />

                  <input
                    value={search}
                    onChange={(event) =>
                      setSearch(
                        event.target.value,
                      )
                    }
                    placeholder="Search patient, ID or procedure..."
                    className="h-7 w-full rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 !text-[11px] text-slate-700 outline-none transition placeholder:text-slate-400 focus:border-teal-300 focus:bg-white focus:ring-2 focus:ring-teal-50"
                  />
                </div>

                <div
                  ref={filterRef}
                  className="relative"
                >
                  <button
                    type="button"
                    onClick={() =>
                      setFilterOpen(
                        (current) =>
                          !current,
                      )
                    }
                    className={`inline-flex h-7 items-center gap-1.5 rounded-lg border px-2.5 !text-[11px] font-semibold transition ${
                      filterOpen ||
                      selectedDoctors.length > 0 ||
                      selectedStatuses.length > 0 ||
                      Boolean(selectedDate) ||
                      period !== "Day"
                        ? "border-teal-200 bg-teal-50 text-teal-700"
                        : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                    }`}
                  >
                    <Filter size={12} />
                    Filters

                    {(selectedDoctors.length +
                      selectedStatuses.length +
                      (selectedDate ? 1 : 0) +
                      (period !== "Day"
                        ? 1
                        : 0)) >
                      0 && (
                      <span className="flex h-4 min-w-4 items-center justify-center rounded-full bg-teal-600 px-1 text-[7px] font-bold text-white">
                        {selectedDoctors.length +
                          selectedStatuses.length +
                          (selectedDate
                            ? 1
                            : 0) +
                          (period !== "Day"
                            ? 1
                            : 0)}
                      </span>
                    )}

                    <ChevronDown size={11} />
                  </button>

                  {filterOpen && (
                    <div className="absolute right-0 top-[calc(100%+6px)] z-30 w-[350px] rounded-xl border border-slate-200 bg-white p-3 shadow-[0_12px_32px_rgba(15,23,42,0.14)]">
                      <div className="mb-3 flex items-center justify-between">
                        <div>
                          <p className="text-[10px] font-semibold text-slate-700">
                            Table Filters
                          </p>

                          <p className="mt-0.5 text-[9px] text-slate-500">
                            Refine the Recovery patient list
                          </p>
                        </div>

                        <button
                          type="button"
                          onClick={clearFilters}
                          className="text-[9px] font-semibold text-teal-600 hover:text-teal-700"
                        >
                          Clear all
                        </button>
                      </div>

                      <div className="mb-3">
                        <p className="mb-1.5 text-[9px] font-semibold uppercase tracking-wide text-slate-400">
                          Doctor
                        </p>

                        <div className="flex flex-wrap gap-1.5">
                          {doctors.map(
                            (doctor) => (
                              <RecoveryFilterPill
                                key={doctor}
                                label={doctor}
                                active={selectedDoctors.includes(
                                  doctor,
                                )}
                                onClick={() =>
                                  toggleDoctor(
                                    doctor,
                                  )
                                }
                              />
                            ),
                          )}
                        </div>
                      </div>

                      <div className="mb-3">
                        <p className="mb-1.5 text-[9px] font-semibold uppercase tracking-wide text-slate-400">
                          Recovery Status
                        </p>

                        <div className="flex flex-wrap gap-1.5">
                          {statuses.map(
                            (status) => (
                              <RecoveryFilterPill
                                key={status}
                                label={status}
                                active={selectedStatuses.includes(
                                  status,
                                )}
                                onClick={() =>
                                  toggleStatus(
                                    status,
                                  )
                                }
                              />
                            ),
                          )}
                        </div>
                      </div>

                      <div>
                        <p className="mb-1.5 text-[9px] font-semibold uppercase tracking-wide text-slate-400">
                          Surgery Date
                        </p>

                        <div data-responsive-grid="2" className="grid grid-cols-[1fr_135px] gap-2">
                          <div className="flex h-7 items-center rounded-lg border border-slate-200 bg-slate-50 p-0.5">
                            {(
                              [
                                "Day",
                                "Week",
                                "Month",
                              ] as Period[]
                            ).map(
                              (item) => (
                                <button
                                  key={item}
                                  type="button"
                                  onClick={() =>
                                    setPeriod(
                                      item,
                                    )
                                  }
                                  className={`h-6 flex-1 rounded-md !text-[11px] font-semibold transition ${
                                    period === item
                                      ? "bg-white text-teal-600 shadow-sm"
                                      : "text-slate-400 hover:text-slate-600"
                                  }`}
                                >
                                  {item}
                                </button>
                              ),
                            )}
                          </div>

                          <ModernRecoveryDatePicker
                              value={selectedDate}
                              onChange={(value) => {
                                setSelectedDate(value);
                                setPage(0);
                              }}
                            />
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* TABLE HEADER */}
            <div data-responsive-table-header="true" className="grid shrink-0 grid-cols-[minmax(165px,1.2fr)_100px_minmax(145px,1fr)_140px_105px_90px_95px_120px_24px] items-center border-b border-slate-100 bg-slate-50/80 px-3 py-2.5">
              <RecoverySortableHeader
                label="Patient"
                sortKey="patient"
                activeKey={sortKey}
                direction={sortDirection}
                onSort={handleSort}
              />

              <RecoverySortableHeader
                label="Case #"
                sortKey="patientId"
                activeKey={sortKey}
                direction={sortDirection}
                onSort={handleSort}
              />

              <RecoverySortableHeader
                label="Procedures"
                sortKey="procedures"
                activeKey={sortKey}
                direction={sortDirection}
                onSort={handleSort}
              />

              <RecoverySortableHeader
                label="Surgeon"
                sortKey="surgeon"
                activeKey={sortKey}
                direction={sortDirection}
                onSort={handleSort}
              />

              <RecoverySortableHeader
                label="Surgery Date"
                sortKey="date"
                activeKey={sortKey}
                direction={sortDirection}
                onSort={handleSort}
              />

              <RecoverySortableHeader
                label="Duration"
                sortKey="duration"
                activeKey={sortKey}
                direction={sortDirection}
                onSort={handleSort}
              />

              <RecoverySortableHeader
                label="Condition"
                sortKey="condition"
                activeKey={sortKey}
                direction={sortDirection}
                onSort={handleSort}
              />

              <RecoverySortableHeader
                label="Status"
                sortKey="recoveryStatus"
                activeKey={sortKey}
                direction={sortDirection}
                onSort={handleSort}
              />

              <span />
            </div>

            {/* TABLE ROWS */}
            <div
              ref={rowsContainerRef}
              className="min-h-0 flex-1 overflow-visible"
            >
              {visibleCases.length === 0 ? (
                <div className="flex h-full flex-col items-center justify-center text-center">
                  <div className="mb-3 flex h-10 w-10 items-center justify-center rounded-full bg-slate-100 text-slate-400">
                    <Search size={18} />
                  </div>

                  <p className="text-[12px] font-medium text-slate-600">
                    No recovery patients found
                  </p>

                  <p className="mt-1 max-w-[250px] text-[10px] leading-4 text-slate-400">
                    Try changing your search or filters.
                  </p>
                </div>
              ) : (
                visibleCases.map(
                  (surgery, rowIndex) => {
                    const active =
                      surgery.id ===
                      selectedId;

                    const stored =
                      loadRecovery(
                        surgery.id,
                      );

                    const procedures =
                      getSurgeryProcedures(
                        surgery,
                      );

                    return (
                      <button data-responsive-table-row="true"
                        key={surgery.id}
                        type="button"
                        onClick={() =>
                          selectPatient(
                            surgery.id,
                          )
                        }
                        className={`group relative grid min-h-[48px] w-full grid-cols-[minmax(165px,1.2fr)_100px_minmax(145px,1fr)_140px_105px_90px_95px_120px_24px] items-center border-b border-slate-100 px-3 py-1.5 text-left transition ${
                          active
                            ? "bg-teal-50/60"
                            : "bg-white hover:bg-slate-50"
                        }`}
                      >
                        <span 
                          className={`absolute bottom-1.5 left-0 top-1.5 w-[3px] rounded-r-full ${
                            active
                              ? "bg-teal-600"
                              : "bg-teal-500"
                          }`}
                        />

                        {/* PATIENT */}
                        <div data-cell-label="Patient"  className="flex min-w-0 items-center gap-2.5">
                          <div
                            className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-[9px] font-semibold ${
                              active
                                ? "bg-teal-600 text-white"
                                : "bg-teal-50 text-teal-600"
                            }`}
                          >
                            {getInitials(
                              surgery.patientName,
                            )}
                          </div>

                          <div className="min-w-0">
                            <span className="block truncate text-[10px] font-semibold text-slate-800">
                              {surgery.patientName}
                            </span>

                            <p className="mt-0.5 truncate text-[8.5px] font-medium text-slate-400">
                              {getPatientAge(
                                surgery,
                              )} yrs ·{" "}
                              {getPatientGender(
                                surgery,
                              )}
                            </p>
                          </div>
                        </div>

                        {/* CASE # */}
                        <span data-cell-label="Case #"  className="truncate pr-2 text-[10px] font-semibold text-teal-700">
                          {surgery.id}
                        </span>

                        {/* PROCEDURES */}
                        <div data-cell-label="Procedures"  className="group/procedures relative flex min-w-0 items-center gap-2 pr-2">
                          <div className="flex min-w-0 items-center gap-1">
                            <span className="truncate text-[10px] font-semibold text-slate-700">
                              {procedures[0]?.name ??
                                "Procedure"}
                            </span>

                            {procedures[0]?.site && (
                              <>
                                <span className="shrink-0 text-[10px] text-slate-300">
                                  •
                                </span>
                                <span className="truncate text-[9px] font-medium text-slate-400">
                                  {procedures[0].site}
                                </span>
                              </>
                            )}
                          </div>

                          {procedures.length > 1 && (
                            <>
                              <span className="shrink-0 rounded-full bg-slate-100 px-2 py-0.5 text-[8px] font-bold text-slate-500 ring-1 ring-inset ring-slate-200">
                                +{procedures.length - 1}
                              </span>

                              <div
                                className={`pointer-events-none invisible absolute left-0 z-50 w-[300px] rounded-xl border border-slate-200 bg-white p-2.5 opacity-0 shadow-[0_12px_32px_rgba(15,23,42,0.16)] transition-all duration-150 group-hover/procedures:visible group-hover/procedures:translate-y-0 group-hover/procedures:opacity-100 ${
                                  rowIndex >=
                                  visibleCases.length - 2
                                    ? "bottom-[calc(100%+7px)] -translate-y-1"
                                    : "top-[calc(100%+7px)] translate-y-1"
                                }`}
                              >
                                <div className="mb-2 flex items-center justify-between">
                                  <div>
                                    <p className="text-[9px] font-bold text-slate-700">
                                      All Procedures
                                    </p>
                                    <p className="mt-0.5 text-[8px] text-slate-400">
                                      {surgery.id}
                                    </p>
                                  </div>

                                  <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[8px] font-bold text-slate-500">
                                    {procedures.length}
                                  </span>
                                </div>

                                <div className="space-y-1">
                                  {procedures.map(
                                    (
                                      procedure,
                                      index,
                                    ) => (
                                      <div
                                        key={`${surgery.id}-${procedure.name}-${procedure.site ?? index}`}
                                        className="flex items-center gap-2 rounded-lg bg-slate-50/80 px-2.5 py-1.5"
                                      >
                                        <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-slate-100 text-[7px] font-bold text-slate-500">
                                          {index + 1}
                                        </span>

                                        <div className="flex min-w-0 flex-1 items-center gap-1">
                                          <span className="truncate text-[9px] font-semibold text-slate-700">
                                            {procedure.name}
                                          </span>

                                          {procedure.site && (
                                            <>
                                              <span className="shrink-0 text-[9px] text-slate-300">
                                                •
                                              </span>
                                              <span className="truncate text-[9px] font-medium text-slate-400">
                                                {procedure.site}
                                              </span>
                                            </>
                                          )}
                                        </div>
                                      </div>
                                    ),
                                  )}
                                </div>
                              </div>
                            </>
                          )}
                        </div>

                        {/* SURGEON */}
                        <div data-cell-label="Surgeon" className="flex min-w-0 items-center gap-1.5 pr-2">
                          <Stethoscope
                            size={11}
                            className="shrink-0 text-slate-400"
                          />

                          <span className="truncate text-[10px] font-medium text-slate-600">
                            {surgery.doctor}
                          </span>
                        </div>

                        {/* DATE */}
                        <span data-cell-label="Surgery Date" className="truncate text-[10px] font-medium text-slate-500">
                          {formatRecoverySurgeryDate(
                            surgery,
                          )}
                        </span>

                        {/* DURATION */}
                        <span data-cell-label="Duration" className="truncate text-[10px] font-semibold text-slate-600">
                          {formatSurgeryDuration(
                            surgery,
                          )}
                        </span>

                        {/* CONDITION */}
                        <PatientConditionBadge
                          stability={
                            stored.stability
                          }
                        />

                        {/* STATUS */}
                        <RecoveryStatusBadge
                          status={
                            stored.status
                          }
                        />

                        <ChevronRight
                          size={14}
                          className={`transition ${
                            active
                              ? "text-teal-500"
                              : "text-slate-300 group-hover:text-slate-500"
                          }`}
                        />
                      </button>
                    );
                  },
                )
              )}
            </div>

            {/* PAGINATION */}
            {sortedCases.length > 0 && (
              <div className="flex h-10 shrink-0 items-center justify-between border-t border-slate-100 bg-slate-50/50 px-3">
                <p className="text-[9px] font-medium text-slate-400">
                  Showing{" "}
                  <span className="font-semibold text-slate-600">
                    {page * pageSize + 1}–
                    {Math.min(
                      (page + 1) * pageSize,
                      sortedCases.length,
                    )}
                  </span>{" "}
                  of{" "}
                  <span className="font-semibold text-slate-600">
                    {sortedCases.length}
                  </span>

                  <span className="ml-2 text-slate-300">
                    •
                  </span>

                  <span className="ml-2 font-medium text-slate-400">
                    {pageSize} rows/page
                  </span>
                </p>

                <div className="flex items-center gap-1.5">
                  <button
                    type="button"
                    aria-label="Previous page"
                    disabled={page === 0}
                    onClick={() =>
                      setPage((current) =>
                        Math.max(
                          0,
                          current - 1,
                        ),
                      )
                    }
                    className="flex h-7 w-7 items-center justify-center rounded-md border border-slate-200 bg-white text-slate-400 transition hover:border-teal-200 hover:bg-teal-50 hover:text-teal-700 disabled:cursor-not-allowed disabled:opacity-35"
                  >
                    <ChevronLeft size={11} />
                  </button>

                  {Array.from(
                    { length: totalPages },
                    (_, index) => index,
                  )
                    .slice(
                      Math.max(
                        0,
                        Math.min(
                          page - 1,
                          totalPages - 4,
                        ),
                      ),
                      Math.max(
                        0,
                        Math.min(
                          page - 1,
                          totalPages - 4,
                        ),
                      ) + 4,
                    )
                    .map((pageIndex) => (
                      <button
                        key={pageIndex}
                        type="button"
                        onClick={() =>
                          setPage(pageIndex)
                        }
                        className={`flex h-7 min-w-7 items-center justify-center rounded-md border px-2 text-[10px] font-semibold transition ${
                          page === pageIndex
                            ? "border-teal-600 bg-teal-600 text-white shadow-sm"
                            : "border-slate-200 bg-white text-slate-600 hover:border-teal-200 hover:bg-teal-50 hover:text-teal-700"
                        }`}
                      >
                        {pageIndex + 1}
                      </button>
                    ))}

                  <button
                    type="button"
                    aria-label="Next page"
                    disabled={
                      page >= totalPages - 1
                    }
                    onClick={() =>
                      setPage((current) =>
                        Math.min(
                          totalPages - 1,
                          current + 1,
                        ),
                      )
                    }
                    className="flex h-7 w-7 items-center justify-center rounded-md border border-slate-200 bg-white text-slate-400 transition hover:border-teal-200 hover:bg-teal-50 hover:text-teal-700 disabled:cursor-not-allowed disabled:opacity-35"
                  >
                    <ChevronRight size={11} />
                  </button>
                </div>
              </div>
            )}
          </section>
        </div>

        {toast && (
          <div className="fixed bottom-5 right-5 z-[100] w-[440px] max-w-[calc(100vw-40px)]">
            <div
              className={`relative overflow-hidden rounded-xl border bg-white shadow-[0_18px_45px_rgba(15,23,42,0.18)] ${
                toast.type === "success"
                  ? "border-emerald-200"
                  : "border-red-200"
              }`}
            >
              <span
                className={`absolute bottom-0 left-0 top-0 w-1 ${
                  toast.type === "success"
                    ? "bg-emerald-500"
                    : "bg-red-500"
                }`}
              />

              <div className="flex items-start gap-3 py-3.5 pl-4 pr-3.5">
                <div
                  className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${
                    toast.type === "success"
                      ? "bg-emerald-50 text-emerald-600"
                      : "bg-red-50 text-red-600"
                  }`}
                >
                  {toast.type === "success" ? (
                    <CheckCircle2
                      size={17}
                    />
                  ) : (
                    <AlertTriangle
                      size={17}
                    />
                  )}
                </div>

                <div className="min-w-0 flex-1">
                  <p
                    className={`text-[12px] font-bold ${
                      toast.type === "success"
                        ? "text-emerald-700"
                        : "text-red-700"
                    }`}
                  >
                    {toast.title}
                  </p>

                  <p className="mt-1 text-[11px] leading-[18px] text-slate-600">
                    {toast.message}
                  </p>

                  {toast.items &&
                    toast.items.length >
                      0 && (
                    <ul className="mt-2 space-y-1.5">
                      {toast.items.map(
                        (
                          item,
                          index,
                        ) => (
                          <li
                            key={`${item}-${index}`}
                            className="flex items-start gap-2 text-[10px] leading-4 text-slate-600"
                          >
                            <span className="mt-[5px] h-1.5 w-1.5 shrink-0 rounded-full bg-red-500" />

                            <span className="min-w-0">
                              {item}
                            </span>
                          </li>
                        ),
                      )}
                    </ul>
                  )}
                </div>

                <button
                  type="button"
                  aria-label="Close notification"
                  onClick={() =>
                    setToast(null)
                  }
                  className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-slate-400 transition hover:bg-slate-100 hover:text-slate-600"
                >
                  <X size={13} />
                </button>
              </div>
            </div>
          </div>
        )}

        {/* ================================================================ */}
        {/* RECOVERY DRAWER                                                   */}
        {/* ================================================================ */}

        {selected && (
          <>
            {/* BACKDROP */}
            <button
              type="button"
              aria-label="Close recovery workspace"
              onClick={() => setSelectedId(null)}
              className="fixed inset-0 z-40 bg-slate-900/10"
            />

            {/* RIGHT DRAWER */}
            <section className="fixed inset-y-0 right-0 z-50 flex w-[980px] max-w-[94vw] flex-col overflow-hidden border-l border-slate-200 bg-white shadow-2xl">
              <div className="grid h-full min-h-0 grid-rows-[94px_58px_minmax(0,1fr)_54px]">
              {/* ============================================================ */}
              {/* PATIENT HEADER                                               */}
              {/* ============================================================ */}

              <header className="flex min-h-0 items-center justify-between gap-4 border-b border-slate-100 bg-white px-4">
                <div className="flex min-w-0 items-center gap-3">

                  <div className="flex h-13 w-13 shrink-0 items-center justify-center rounded-full bg-teal-50 text-[16px] font-bold text-teal-600">
                    {getInitials(
                      selected.patientName,
                    )}
                  </div>

                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <h2 className="truncate text-[15px] font-semibold text-slate-800">
                        {
                          selected.patientName
                        }
                      </h2>

                      <span className="rounded-full bg-teal-50 px-2 py-0.5 text-[9px] font-bold uppercase tracking-wide text-teal-600">
                        Recovery
                      </span>
                    </div>

                    <div className="mt-1 flex items-center gap-2 text-[12px] text-slate-500">
                      <span className="font-medium">
                        {selected.id}
                      </span>
                      <span>•</span>
                      <span className="font-medium text-slate-600">
                        {getPatientGender(selected)}
                      </span>
                      <span>•</span>
                      <span className="font-medium inline-flex items-center gap-1 truncate">
                        <Stethoscope
                          size={9}
                        />
                        {
                          selected.doctor
                        }
                      </span>
                    </div>

                    <div className="mt-2 flex min-w-0 items-center gap-2">
                      <div className="flex shrink-0 items-center gap-1 text-[9px] font-semibold uppercase tracking-wide text-slate-400">
                        <Scissors size={10} />
                        Procedures
                        <span className="rounded-full bg-emerald-100 px-1.5 py-0.5 text-[7px] font-bold text-emerald-700">
                          {getSurgeryProcedures(selected).length}
                        </span>
                      </div>

                      <div className="flex min-w-0 flex-wrap items-center gap-1">
                        {getSurgeryProcedures(selected).map(
                          (procedure, index) => (
                            <div
                              key={`${procedure.name}-${procedure.site ?? index}`}
                              className={`inline-flex max-w-[190px] items-center gap-1 rounded-md border px-2
                                  border-emerald-200 bg-emerald-50 text-emerald-700
                              }`}
                            >
                              <span className="truncate text-[10px] font-semibold">
                                {procedure.name}
                              </span>

                              {procedure.site && (
                                <>
                                  <span className="text-slate-300">•</span>
                                  <span className="truncate text-[10px] font-medium text-slate-400">
                                    {procedure.site}
                                  </span>
                                </>
                              )}
                            </div>
                          ),
                        )}
                      </div>
                    </div>
                  </div>
                </div>

                <div className="flex shrink-0 items-center gap-3">
                  {/* STABILITY TOGGLE */}

                  <div>
                    <p className="mb-1 text-right text-[9px] font-semibold uppercase tracking-wider text-slate-400">
                      Patient Condition
                    </p>

                    <div className="flex rounded-lg border border-slate-200 bg-slate-50 p-0.5">
                      <button
                        type="button"
                        onClick={() =>
                          setRecovery(
                            (current) => ({
                              ...current,
                              stability:
                                "stable",
                            }),
                          )
                        }
                        className={`flex h-7 items-center gap-1.5 rounded-md px-3 text-[9px] font-semibold transition ${
                          recovery.stability ===
                          "stable"
                            ? "bg-white text-emerald-600 shadow-sm ring-1 ring-emerald-100"
                            : "text-slate-400 hover:text-slate-600"
                        }`}
                      >
                        <ShieldCheck
                          size={11}
                        />
                        Stable
                      </button>

                      <button
                        type="button"
                        onClick={() =>
                          setRecovery(
                            (current) => ({
                              ...current,
                              stability:
                                "unstable",
                            }),
                          )
                        }
                        className={`flex h-7 items-center gap-1.5 rounded-md px-3 text-[9px] font-semibold transition ${
                          recovery.stability ===
                          "unstable"
                            ? "bg-white text-red-600 shadow-sm ring-1 ring-red-100"
                            : "text-slate-400 hover:text-slate-600"
                        }`}
                      >
                        <AlertTriangle
                          size={11}
                        />
                        Unstable
                      </button>
                    </div>
                  </div>

                  <button
                    type="button"
                    aria-label="Close recovery drawer"
                    onClick={() => setSelectedId(null)}
                    className="flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400 transition hover:bg-slate-50 hover:text-slate-600"
                  >
                    <ChevronRight size={14} />
                  </button>
                </div>
              </header>

              {/* ============================================================ */}
              {/* QUICK CLINICAL SUMMARY                                       */}
              {/* ============================================================ */}

              <section data-responsive-table-header="true" className="grid h-[58px] shrink-0 grid-cols-[1.1fr_1fr_1fr_1fr] border-b border-slate-100 bg-slate-50/40">
                <SummaryItem
                  icon={
                    <Clock3 size={12} />
                  }
                  label="Surgery End"
                  value={formatClock(
                    selected.surgeryCompletedAt,
                  )}
                />

                <SummaryItem
                  icon={
                    <Activity
                      size={12}
                    />
                  }
                  label="Recovery Status"
                  value={
                    recovery.status
                  }
                />

                <SummaryItem
                  icon={
                    <CheckCircle2
                      size={12}
                    />
                  }
                  label="Assessment"
                  value={`${assessmentProgress}/${recoveryAssessments.length} completed`}
                />

                <SummaryItem
                  icon={
                    <UserRound
                      size={12}
                    />
                  }
                  label="Operating Room"
                  value={
                    selected.room ||
                    "Not assigned"
                  }
                  last
                />
              </section>

              {/* ============================================================ */}
              {/* CONTENT — NO SCROLL                                          */}
              {/* ============================================================ */}

              <section data-responsive-grid="2" className="grid min-h-0 grid-cols-[.88fr_1.12fr] gap-2 bg-slate-50/40 p-2">
                {/* LEFT COLUMN */}

                <div className="grid min-h-0 grid-rows-[.9fr_1.1fr] gap-2">
                  {/* AWAKENING */}

                  <div className="min-h-0 overflow-hidden rounded-xl border border-slate-200 bg-white">
                    <SectionTitle
                      icon={
                        <HeartPulse
                          size={13}
                        />
                      }
                      title="Patient Awakening"
                      subtitle="Track emergence from anesthesia"
                      action={
                        <span className="rounded-md bg-teal-50 px-2 py-1 text-[9px] font-semibold text-teal-600">
                          {recovery.status}
                        </span>
                      }
                    />

                    <div className="flex h-[calc(100%-44px)] min-h-0 items-center px-3">
                      <div className="relative w-full">
                        <div className="absolute left-[9%] right-[9%] top-[11px] h-[2px] bg-slate-100" />

                        <div
                          className="absolute left-[9%] top-[11px] h-[2px] bg-teal-500 transition-all duration-300"
                          style={{
                            width: `${
                              (recovery.awakeningStage /
                                (awakeningStages.length -
                                  1)) *
                              82
                            }%`,
                          }}
                        />

                        <div className="relative grid grid-cols-5 gap-1">
                          {awakeningStages.map(
                            (
                              stage,
                              index,
                            ) => {
                              const complete =
                                index <
                                recovery.awakeningStage;

                              const current =
                                index ===
                                recovery.awakeningStage;

                              const next =
                                index ===
                                recovery.awakeningStage +
                                  1;

                              return (
                                <button
                                  key={stage}
                                  type="button"
                                  disabled={!next}
                                  onClick={() =>
                                    updateRecoveryStage(
                                      index,
                                    )
                                  }
                                  className={`group flex min-w-0 flex-col items-center text-center ${
                                    next
                                      ? "cursor-pointer"
                                      : "cursor-default"
                                  }`}
                                  title={
                                    next
                                      ? `Move to ${stage}`
                                      : current
                                        ? "Current awakening stage"
                                        : complete
                                          ? "Completed stage"
                                          : "Complete the previous stage first"
                                  }
                                >
                                  <span
                                    className={`relative z-10 flex h-[24px] w-[24px] items-center justify-center rounded-full border-2 text-[8px] font-bold transition ${
                                      complete
                                        ? "border-teal-500 bg-teal-500 text-white"
                                        : current
                                          ? "border-teal-500 bg-teal-50 text-teal-700 ring-4 ring-teal-50"
                                          : next
                                            ? "border-teal-300 bg-white text-teal-600 group-hover:border-teal-500 group-hover:bg-teal-50"
                                            : "border-slate-200 bg-white text-slate-300"
                                    }`}
                                  >
                                    {complete ? (
                                      <Check
                                        size={10}
                                        strokeWidth={3}
                                      />
                                    ) : (
                                      index + 1
                                    )}
                                  </span>

                                  <span
                                    className={`mt-1.5 max-w-[86px] text-[9px] leading-3 ${
                                      complete ||
                                      current
                                        ? "font-semibold text-teal-600"
                                        : next
                                          ? "font-semibold text-teal-500"
                                          : "text-slate-400"
                                    }`}
                                  >
                                    {stage}
                                  </span>
                                </button>
                              );
                            },
                          )}
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* ASSESSMENTS */}

                  <div className="min-h-0 overflow-hidden rounded-xl border border-slate-200 bg-white">
                    <SectionTitle
                      icon={
                        <CheckCircle2
                          size={13}
                        />
                      }
                      title="Recovery Assessment"
                      subtitle="Required post-operative checks"
                      action={
                        <span
                          className={`rounded-md px-2 py-1 text-[9px] font-semibold ${
                            allAssessmentsComplete
                              ? "bg-emerald-50 text-emerald-600"
                              : "bg-slate-100 text-slate-500"
                          }`}
                        >
                          {
                            assessmentProgress
                          }
                          /
                          {
                            recoveryAssessments.length
                          }
                        </span>
                      }
                    />

                    <div data-responsive-grid="2" className="grid h-[calc(100%-44px)] min-h-0 grid-cols-2 grid-rows-3 gap-1.5 p-2">
                      {recoveryAssessments.map(
                        (item) => {
                          const checked =
                            recovery.assessments.includes(
                              item,
                            );

                          return (
                            <button
                              key={item}
                              type="button"
                              onClick={() =>
                                toggleAssessment(
                                  item,
                                )
                              }
                              className={`flex min-h-0 items-center gap-2 rounded-lg border px-2.5 text-left transition ${
                                checked
                                  ? "border-emerald-200 bg-emerald-50/60"
                                  : "border-slate-200 bg-white hover:bg-slate-50"
                              }`}
                            >
                              <span
                                className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md border ${
                                  checked
                                    ? "border-emerald-500 bg-emerald-500 text-white"
                                    : "border-slate-300 bg-white text-transparent"
                                }`}
                              >
                                <Check
                                  size={
                                    11
                                  }
                                  strokeWidth={
                                    3
                                  }
                                />
                              </span>

                              <span
                                className={`text-[9px] font-semibold leading-4 ${
                                  checked
                                    ? "text-emerald-700"
                                    : "text-slate-600"
                                }`}
                              >
                                {item}
                              </span>
                            </button>
                          );
                        },
                      )}
                    </div>
                  </div>
                </div>

                {/* RIGHT COLUMN */}

                <div className="grid min-h-0 grid-rows-[.58fr_1.42fr] gap-2">
                  {/* RECOVERY NOTES */}

                  <div className="flex min-h-0 flex-col overflow-hidden rounded-xl border border-slate-200 bg-white">
                    <SectionTitle
                      icon={
                        <FileText
                          size={13}
                        />
                      }
                      title="Recovery Notes"
                      subtitle="Post-operative observations and instructions"
                    />

                    <div className="min-h-0 flex-1 p-2.5">
                      <textarea
                        value={
                          recovery.notes
                        }
                        onChange={(
                          event,
                        ) =>
                          setRecovery(
                            (
                              current,
                            ) => {
                              const next = {
                                ...current,
                                notes:
                                  event
                                    .target
                                    .value,
                              };

                              if (
                                selectedId
                              ) {
                                transientRecoveryRef.current[
                                  selectedId
                                ] = {
                                  awakeningStage:
                                    next.awakeningStage,
                                  notes:
                                    next.notes,
                                  surgeonReport:
                                    next.surgeonReport,
                                };
                              }

                              return next;
                            },
                          )
                        }
                        placeholder="Document pain, nausea, airway, medication response, complications, transfer instructions..."
                        className="h-full w-full resize-none overflow-hidden rounded-lg border border-slate-200 bg-slate-50/50 p-2 text-[10px] leading-4 text-slate-700 outline-none transition placeholder:text-slate-400 focus:border-teal-300 focus:bg-white focus:ring-2 focus:ring-teal-50"
                      />
                    </div>
                  </div>

                  {/* SURGEON REPORT */}

                  {reportExpanded && (
                    <button
                      type="button"
                      aria-label="Close expanded report"
                      onClick={collapseReport}
                      className="fixed inset-0 z-[65] bg-slate-900/20"
                    />
                  )}

                  <div
                    className={`flex min-h-0 flex-col overflow-hidden border border-emerald-200 bg-white shadow-sm ${
                      reportExpanded
                        ? "fixed bottom-4 left-4 right-4 top-4 z-[70] rounded-2xl shadow-2xl"
                        : "rounded-xl"
                    }`}
                  >
                    <div className="flex h-11 shrink-0 items-center justify-between gap-3 border-b border-emerald-100 bg-emerald-50/40 px-3">
                      <div className="flex min-w-0 items-center gap-2">
                        <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md bg-emerald-100 text-emerald-600">
                          <Stethoscope size={13} />
                        </div>

                        <div className="min-w-0">
                          <p className="text-[11px] font-semibold text-slate-800">
                            Surgeon Post-Operative Report
                          </p>
                          <p className="truncate !text-[10px] text-slate-400 font-medium">
                            Clinical report by {selected.doctor}
                          </p>
                        </div>
                      </div>

                      <div className="flex items-center gap-1.5">
                        <span className="rounded-md bg-white px-2 py-1 text-[9px] font-semibold text-emerald-600 ring-1 ring-emerald-100">
                          Rich Text
                        </span>

                        <button
                          type="button"
                          onClick={toggleReportExpanded}
                          className="flex h-7 items-center gap-1.5 rounded-md border border-emerald-200 bg-white px-2 text-[9px] font-semibold text-emerald-700 transition hover:bg-emerald-50"
                          title={reportExpanded ? "Collapse report" : "Expand report"}
                        >
                          {reportExpanded ? (
                            <Minimize2 size={11} />
                          ) : (
                            <Maximize2 size={11} />
                          )}
                          {reportExpanded ? "Collapse" : "Expand"}
                        </button>
                      </div>
                    </div>

                    <div className="flex min-h-0 flex-1 flex-col">
                      {/* DOCUMENT TOOLBAR */}
                      <div className="flex h-9 shrink-0 items-center gap-1 border-b border-emerald-100 bg-emerald-50/35 px-2">
                        <select
                          defaultValue="Arial"
                          onChange={(event) =>
                            applyReportCommand(
                              "fontName",
                              event.target.value,
                            )
                          }
                          className="h-6 rounded border border-slate-200 bg-white px-1.5 text-[9px] text-slate-600 outline-none"
                        >
                          <option>Arial</option>
                          <option>Georgia</option>
                          <option>Times New Roman</option>
                          <option>Courier New</option>
                        </select>

                        <select
                          defaultValue="3"
                          onChange={(event) =>
                            applyReportCommand(
                              "fontSize",
                              event.target.value,
                            )
                          }
                          className="h-6 w-12 rounded border border-slate-200 bg-white px-1 text-[9px] text-slate-600 outline-none"
                        >
                          <option value="1">10</option>
                          <option value="2">12</option>
                          <option value="3">14</option>
                          <option value="4">16</option>
                          <option value="5">18</option>
                        </select>

                        <div className="mx-0.5 h-4 w-px bg-slate-200" />

                        <ToolbarButton
                          title="Bold"
                          onClick={() =>
                            applyReportCommand("bold")
                          }
                        >
                          <Bold size={11} />
                        </ToolbarButton>

                        <ToolbarButton
                          title="Italic"
                          onClick={() =>
                            applyReportCommand("italic")
                          }
                        >
                          <Italic size={11} />
                        </ToolbarButton>

                        <ToolbarButton
                          title="Underline"
                          onClick={() =>
                            applyReportCommand("underline")
                          }
                        >
                          <Underline size={11} />
                        </ToolbarButton>

                        <div className="mx-0.5 h-4 w-px bg-slate-200" />

                        <ToolbarButton
                          title="Align left"
                          onClick={() =>
                            applyReportCommand("justifyLeft")
                          }
                        >
                          <AlignLeft size={11} />
                        </ToolbarButton>

                        <ToolbarButton
                          title="Align center"
                          onClick={() =>
                            applyReportCommand("justifyCenter")
                          }
                        >
                          <AlignCenter size={11} />
                        </ToolbarButton>

                        <ToolbarButton
                          title="Align right"
                          onClick={() =>
                            applyReportCommand("justifyRight")
                          }
                        >
                          <AlignRight size={11} />
                        </ToolbarButton>

                        <div className="mx-0.5 h-4 w-px bg-slate-200" />

                        <ToolbarButton
                          title="Bulleted list"
                          onClick={() =>
                            applyReportCommand("insertUnorderedList")
                          }
                        >
                          <List size={11} />
                        </ToolbarButton>

                        <ToolbarButton
                          title="Numbered list"
                          onClick={() =>
                            applyReportCommand("insertOrderedList")
                          }
                        >
                          <ListOrdered size={11} />
                        </ToolbarButton>

                        <div className="mx-0.5 h-4 w-px bg-slate-200" />

                        <label
                          title="Text color"
                          className="relative flex h-6 w-7 cursor-pointer items-center justify-center rounded border border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                        >
                          A
                          <input
                            type="color"
                            defaultValue="#334155"
                            onMouseDown={rememberReportSelection}
                            onInput={(event) =>
                              applyReportCommand(
                                "foreColor",
                                (
                                  event.target as HTMLInputElement
                                ).value,
                              )
                            }
                            className="absolute inset-0 cursor-pointer opacity-0"
                          />
                        </label>

                        <label
                          title="Highlight color"
                          className="relative flex h-6 w-7 cursor-pointer items-center justify-center rounded border border-slate-200 bg-white text-slate-500 hover:bg-slate-50"
                        >
                          <Highlighter size={11} />
                          <input
                            type="color"
                            defaultValue="#FEF3C7"
                            onMouseDown={rememberReportSelection}
                            onInput={(event) =>
                              applyReportCommand(
                                "hiliteColor",
                                (
                                  event.target as HTMLInputElement
                                ).value,
                              )
                            }
                            className="absolute inset-0 cursor-pointer opacity-0"
                          />
                        </label>
                      </div>

                      {/* DOCUMENT EDITOR — single report surface */}
                      <div
                        ref={reportEditorRef}
                        contentEditable
                        suppressContentEditableWarning
                        spellCheck
                        onInput={handleReportInput}
                        onMouseUp={rememberReportSelection}
                        onKeyUp={rememberReportSelection}
                        onBlur={rememberReportSelection}
                        data-placeholder="Document procedure outcome, operative findings, events during surgery, complications, interventions, blood loss, specimens, and immediate post-operative plan..."
                        className={`min-h-0 flex-1 overflow-auto bg-white px-5 py-4 text-[12px] leading-5 text-slate-700 outline-none empty:before:pointer-events-none empty:before:text-slate-400 empty:before:content-[attr(data-placeholder)] ${
                          reportExpanded
                            ? "text-[13px] leading-6"
                            : ""
                        }`}
                      />
                    </div>
                  </div>
                </div>
              </section>

              {/* ============================================================ */}
              {/* ACTION BAR                                                   */}
              {/* ============================================================ */}

              <footer className="flex min-h-0 items-center justify-between border-t border-slate-200 bg-white px-4 py-2">
                <div className="flex min-w-0 items-center gap-2">
                  <div
                    className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${
                      readyForTransfer
                        ? "bg-emerald-50 text-emerald-600"
                        : recovery.stability ===
                            "unstable"
                          ? "bg-red-50 text-red-500"
                          : "bg-slate-100 text-slate-400"
                    }`}
                  >
                    {readyForTransfer ? (
                      <CheckCircle2
                        size={12}
                      />
                    ) : recovery.stability ===
                      "unstable" ? (
                      <AlertTriangle
                        size={12}
                      />
                    ) : (
                      <Clock3
                        size={12}
                      />
                    )}
                  </div>

                  <div className="min-w-0">
                    <p className="!text-[11px] font-semibold text-slate-700">
                      {readyForTransfer
                        ? "Recovery criteria completed"
                        : recovery.stability ===
                            "unstable"
                          ? "Patient requires continued monitoring"
                          : "Recovery monitoring in progress"}
                    </p>

                    <p className="truncate !text-[10px] text-slate-400">
                      {readyForTransfer
                        ? "Patient is stable and ready for transfer."
                        : "Complete awakening, assessments, and confirm stability."}
                    </p>
                  </div>
                </div>

                <div className="flex shrink-0 items-center gap-2">
                  <button
                    type="button"
                    onClick={
                      saveRecovery
                    }
                    className="inline-flex h-7 items-center gap-1.5 rounded-md border border-slate-200 bg-slate-200 px-3 text-[9px] font-semibold text-slate-600 transition hover:bg-slate-50"
                  >
                    <Save
                      size={10}
                    />
                    Save
                  </button>

                  <button
                    type="button"
                    onClick={
                      confirmReadyForTransfer
                    }
                    className={`inline-flex h-7 items-center gap-1.5 rounded-md border px-3 text-[9px] font-semibold transition ${
                      readyForTransfer
                        ? "border-teal-600 bg-teal-600 text-white shadow-sm hover:bg-teal-700"
                        : "border-amber-200 bg-amber-50 text-amber-700 hover:border-amber-300 hover:bg-amber-100/70"
                    }`}
                  >
                    {readyForTransfer ? (
                      <CheckCircle2
                        size={10}
                      />
                    ) : (
                      <AlertTriangle
                        size={10}
                      />
                    )}

                    Confirm Ready for Transfer
                  </button>
                </div>
              </footer>
              </div>
            </section>
          </>
        )}
      </div>
    </div>
  );
}

